/* Tạo tự động bởi tools/build-vocab.js từ sheet "Merge" – đừng sửa tay */
Vocab.addDeck({"id":"merge","sets":[{"n":"Ưu tiên 1 · 1","c":[{"t":"Myriad","p":"(adj.)","d":"bao gồm một số lượng rất lớn","de":"consisting of a very great number","e":"It was difficult to decide what to do Friday night because the city presented us with myriad possibilities for fun.","ev":"Thật khó để quyết định phải làm gì vào tối thứ Sáu vì thành phố đã mang đến cho chúng tôi vô số cơ hội vui chơi.","k":"myriad"},{"t":"Unclassifiable","d":"Không thể được xếp vào danh mục nào","de":"Unable to be assigned to a category","e":"His art style was unclassifiable.","ev":"Phong cách nghệ thuật của ông không thể phân loại được.","k":"unclassifiable"},{"t":"Domestication","d":"Quá trình thuần hóa động vật hoặc trồng trọt cây dại.","de":"The process of taming an animal or cultivating a wild plant","e":"The domestication of wild animals has a long history.","ev":"Việc thuần hóa động vật hoang dã có một lịch sử lâu dài.","k":"domestication"},{"t":"Refute","p":"(v.)","d":"để chứng minh là sai","de":"to prove wrong","e":"Maria refuted the president’s argument as she yelled and gesticulated at the TV.","ev":"Maria bác bỏ lập luận của tổng thống khi cô ấy hét lên và khoa tay múa chân trước TV.","k":"refute"},{"t":"Capacity","d":"Khả năng","de":"Ability","e":"I was impressed by her capacity for hard work","ev":"Tôi rất ấn tượng bởi khả năng làm việc chăm chỉ của cô ấy","x":"Ví dụ 2: second meaning","k":"capacity"},{"t":"Embroider","d":"Để làm sai lệch thông tin, hãy bịa đặt những câu chuyện về...","de":"To falsify, make up stories about","e":"she embroidered her stories with colorful detail","ev":"cô ấy thêu dệt những câu chuyện của mình với những chi tiết đầy màu sắc","x":"Ví dụ 2: second meaning","k":"embroider"},{"t":"Illusory","d":"Không có thật; dựa trên ảo ảnh.","de":"Not real; based on an illusion","e":"The sense of security was illusory.","ev":"Cảm giác an toàn thật ảo tưởng.","k":"illusory"},{"t":"Static","d":"Không thay đổi (tức là ở trạng thái tĩnh)","de":"Unchanging (i.e., in a state of stasis)","e":"The image on the TV screen was static.","ev":"Hình ảnh trên màn hình TV tĩnh.","x":"Ví dụ 2: second meaning","k":"static"},{"t":"Hamper","d":"Gây cản trở hoặc làm chậm trễ","de":"To get in the way ot hinder","e":"The bad weather hampered our progress.","ev":"Thời tiết xấu đã cản trở sự tiến bộ của chúng tôi.","x":"Ví dụ 2: second meaning","k":"hamper"},{"t":"Foster","p":"(v.)","d":"để kích thích, thúc đẩy, khuyến khích","de":"to stimulate, promote, encourage","e":"To foster good health in the city, the mayor started a “Get out and exercise!” campaign.","ev":"Để tăng cường sức khỏe tốt cho thành phố, thị trưởng đã phát động chiến dịch “Hãy ra ngoài và tập thể dục!” chiến dịch.","k":"foster"},{"t":"Innocuous","p":"adj","d":"vô hại, không gây hại","de":"harmless, inoffensive","e":"The innocuous remark was taken out of context and caused unnecessary drama.","ev":"Nhận xét vô hại đã bị hiểu sai trong ngữ cảnh và gây ra những rắc rối không cần thiết.","k":"innocuous"},{"t":"Polar","d":"liên quan đến hoặc nằm ở một trong hai cực của Trái đất","de":"relating to or situated at one of the Earth's poles","e":"The polar regions are very cold.","ev":"Các vùng cực rất lạnh.","k":"polar"},{"t":"Heterogeneous","p":"(adj.)","d":"Đa dạng, phong phú về tính cách","de":"varied, diverse in character","e":"I hate having only one flavor so I always buy the swirled, or should I say heterogeneous, type of ice cream.","ev":"Tôi ghét chỉ có một hương vị nên tôi luôn mua loại kem xoáy, hay tôi nên nói là loại kem không đồng nhất.","k":"heterogeneous"},{"t":"Collaboration","d":"Hành động làm việc cùng với một người hoặc nhiều người khác.","de":"The act of working with another person or people","e":"Their collaboration produced outstanding results.","ev":"Sự hợp tác của họ đã tạo ra kết quả nổi bật.","k":"collaboration"},{"t":"Disperse","p":"(v.)","d":"làm cho phân tán, khiến phân tán","de":"to scatter, cause to scatter","e":"When the rain began to pour, the crowd at the baseball game quickly dispersed.","ev":"Khi trời bắt đầu đổ mưa, đám đông tại trận đấu bóng chày nhanh chóng giải tán.","k":"disperse"},{"t":"Prescient","p":"(adj.)","d":"có hiểu biết trước về các sự kiện","de":"to have foreknowledge of events","e":"Questioning the fortune cookie’s prediction, Ray went in search of the old hermit who was rumored to be prescient.","ev":"Đặt câu hỏi về dự đoán của chiếc bánh quy may mắn, Ray đi tìm vị ẩn sĩ già được đồn đại là có khả năng tiên tri.","k":"prescient"},{"t":"Prodigious","p":"verb","d":"Khổng lồ; to lớn đến kinh ngạc.","de":"Enormous; impressively large","e":"The prodigious talent of the young musician amazed everyone at the concert.","ev":"Tài năng phi thường của nhạc sĩ trẻ đã khiến mọi người kinh ngạc tại buổi hòa nhạc.","k":"prodigious"},{"t":"Confine","d":"Để hạn chế trong một khu vực giới hạn, giam hãm","de":"To restrict within a limited area, giam hãm","e":"He was confined to his room for the day.","ev":"Anh ta bị nhốt trong phòng cả ngày.","k":"confine"},{"t":"Sound","d":"Vững chắc, ổn định, đáng tin cậy, có giá trị (ví dụ: một lập luận hợp lý)","de":"Firm, stable, reliable, valid (e.g., a sound argument)","e":"The argument is sound and logical.","ev":"Lập luận có vẻ hợp lý và hợp lý.","x":"Ví dụ 2: second meaning","k":"sound"},{"t":"Superfluous","p":"adj","d":"vượt quá mức cần thiết","de":"exceeding what is necessary","e":"The report was full of superfluous information that was not necessary.","ev":"Báo cáo đầy rẫy thông tin thừa thãi mà không cần thiết.","k":"superfluous"},{"t":"Conjecture","d":"Một ý kiến ​​hoặc kết luận chưa được chứng minh, một phỏng đoán.","de":"an opinion or conclusion that is unproven, a guess","e":"His conjecture about the future was based on little evidence, making it speculative and uncertain.","ev":"Phỏng đoán của ông về tương lai dựa trên rất ít bằng chứng, khiến nó trở nên suy đoán và không chắc chắn.","k":"conjecture"},{"t":"Ruffled","d":"Bối rối, bối rối làm ai phục mình khó chịu","de":"Flustered, nonplussed làm ai bực mình khó chịu","e":"His feathers were ruffled by the criticism.","ev":"Lông của anh ta bị xù lên bởi những lời chỉ trích.","x":"Ví dụ 2: second meaning","k":"ruffled"},{"t":"Laconic","p":"adjective","d":"Ngắn gọn trong lời nói hoặc văn viết","de":"terse in speech or writing","e":"The speaker was laconic, delivering his message in just a few words.","ev":"Người phát biểu rất ngắn gọn, truyền đạt thông điệp của mình chỉ trong vài từ.","k":"laconic"},{"t":"Bolster","p":"verb","d":"v. hỗ trợ, củng cố hoặc tăng cường","de":"v. to support, strengthen, or fortify","e":"They implemented changes to bolster their defenses.","ev":"Họ đã thực hiện các thay đổi để củng cố phòng thủ.","k":"bolster"},{"t":"Grill","d":"Đặt câu hỏi một cách gay gắt và liên tục.","de":"To question intensely and repeatedly","e":"(e.g., the police officers grilled the suspect thoroughly)","ev":"(ví dụ: cảnh sát tra tấn nghi phạm một cách kỹ lưỡng)","x":"Ví dụ 2: second meaning","k":"grill"}]},{"n":"Ưu tiên 1 · 2","c":[{"t":"Discernible","d":"Có thể nhìn thấy; có thể phát hiện được","de":"Visible; detectable","e":"There was no discernible change in his condition.","ev":"Không có sự thay đổi rõ rệt nào trong tình trạng của anh ấy.","k":"discernible"},{"t":"Deplete","d":"Sử dụng hết nguồn cung hoặc tài nguyên","de":"to use up the supply or resources of","e":"The drought depleted the water supply.","ev":"Hạn hán làm cạn kiệt nguồn cung cấp nước.","k":"deplete"},{"t":"Appraise","p":"verb","d":"đánh giá giá trị của","de":"assess the value of","e":"A realtor will come over tonight to appraise our house.","ev":"Một nhân viên bất động sản sẽ đến tối nay để định giá ngôi nhà của chúng tôi.","k":"appraise"},{"t":"Hinder","d":"Ngăn chặn, phòng ngừa; từ đồng nghĩa với \"cản trở\".","de":"To block, prevent; synonym for \"impede\"","e":"The heavy rain hindered their progress.","ev":"Cơn mưa lớn đã cản trở bước tiến của họ.","k":"hinder"},{"t":"Galvanize","d":"Để tiếp thêm sinh lực; thúc đẩy hành động, kích hoạt","de":"To energize; spur into action, kích động","e":"The speech galvanized the community to take action.","ev":"Bài phát biểu đã thúc đẩy cộng đồng hành động.","k":"galvanize"},{"t":"Vacillate","p":"(v.)","d":"dao động, do dự","de":"to fluctuate, hesitate","e":"I prefer a definite answer, but my boss kept vacillating between the distinct options available to us.","ev":"Tôi thích một câu trả lời rõ ràng hơn, nhưng sếp của tôi cứ lưỡng lự giữa các lựa chọn riêng biệt có sẵn cho chúng tôi.","k":"vacillate"},{"t":"Ingenious","p":"(adj.)","d":"thông minh, tháo vát","de":"clever, resourceful","e":"Her ingenious use of walnuts instead of the peanuts called for by the recipe was lauded by the other garden club members who found her cake delicious.","ev":"Việc cô sử dụng quả óc chó một cách khéo léo thay vì đậu phộng theo công thức đã được các thành viên câu lạc bộ làm vườn khác khen ngợi vì thấy chiếc bánh của cô rất ngon.","k":"ingenious"},{"t":"Realize","d":"Để đạt được (một mục tiêu)","de":"To achieve (a goal)","e":"realize one's dreams","ev":"thực hiện ước mơ của một người","x":"Ví dụ 2: second meaning","k":"realize"},{"t":"Coalesce","p":"noun/verb","d":"để hợp nhất thành một thể thống nhất","de":"to fuse into a whole","e":"The two rivers coalesce into one larger river at the valley.","ev":"Hai con sông hợp nhất thành một con sông lớn hơn tại thung lũng.","k":"coalesce"},{"t":"Verisimilitude","d":"Tính chất của việc có vẻ như là sự thật","de":"The quality of seeming to be true","e":"The novel’s characters have a sense of verisimilitude.","ev":"Các nhân vật của cuốn tiểu thuyết có cảm giác chân thực.","k":"verisimilitude"},{"t":"Execute","d":"Để thực hiện","de":"To carry out","e":"The plan was executed flawlessly.","ev":"Kế hoạch đã được thực hiện một cách hoàn hảo.","x":"Ví dụ 2: second meaning","k":"execute"},{"t":"Dexterous","d":"Khéo léo về thể chất, đặc biệt là khéo léo với đôi tay.","de":"Physically skilled, especially with one’s hands","e":"The dexterous artist crafted an intricate sculpture.","ev":"Người nghệ sĩ khéo léo đã tạo ra một tác phẩm điêu khắc phức tạp.","k":"dexterous"},{"t":"Unequivocal","d":"Không còn nghi ngờ gì nữa; chắc chắn","de":"Leaving no doubt; certain","e":"She gave an unequivocal answer to the question.","ev":"Cô ấy đã đưa ra một câu trả lời rõ ràng cho câu hỏi.","k":"unequivocal"},{"t":"Explicit","d":"Được trình bày trực tiếp và rõ ràng tuyệt đối.","de":"Stated directly and with complete clarity","e":"The rules were made explicit to avoid confusion.","ev":"Các quy tắc đã được thực hiện rõ ràng để tránh nhầm lẫn.","k":"explicit"},{"t":"Mitigate","p":"(v.)","d":"để làm cho bớt bạo lực, giảm bớt","de":"to make less violent, alleviate","e":"When I had an awful sore throat, only warm tea would mitigate the pain.","ev":"Khi tôi bị đau họng khủng khiếp, chỉ có trà ấm mới có thể làm dịu cơn đau.","k":"mitigate"},{"t":"Scrutinize","d":"kiểm tra ai đó hoặc điều gì đó một cách rất kỹ lưỡng.","de":"to examine someone or something very carefully","e":"The police scrutinized the crime scene, looking for clues and evidence.","ev":"Cảnh sát đã khám nghiệm hiện trường vụ án, tìm kiếm manh mối và bằng chứng.","k":"scrutinize"},{"t":"Entice","p":"(v.) /ɪnˈtaɪs/","d":"dụ, cám dỗ, bị thu hút để thuyết phục ai đó làm điều gì đó bằng cách đưa ra cho họ một điều gì đó dễ chịu","de":"dụ dỗ, cám dỗ, being drawn to persuade someone to do something by offering them something pleasant","e":"entice someone into something: The adverts entice the customer into buying things they don't really want.be enticed away from: People are being enticed away from the profession by higher salaries elsewhere.","ev":"lôi kéo ai đó vào thứ gì đó: Quảng cáo lôi kéo khách hàng mua những thứ họ không thực sự muốn. bị lôi kéo khỏi: Mọi người đang bị lôi kéo rời bỏ nghề bởi mức lương cao hơn ở nơi khác.","k":"entice"},{"t":"Prolific","p":"adj","d":"Rất hiệu quả","de":"Very productive","e":"He is a prolific writer, publishing several books each year.","ev":"Anh là một nhà văn phong phú, xuất bản nhiều cuốn sách mỗi năm.","k":"prolific"},{"t":"Prioritize","d":"Liệt kê hoặc xếp hạng theo thứ tự quan trọng","de":"To list or rate in order of importance","e":"You need to prioritize your tasks for the day.","ev":"Bạn cần ưu tiên các nhiệm vụ trong ngày.","k":"prioritize"},{"t":"Façade","p":"(n.)","d":"bức tường của một tòa nhà","de":"the wall of a building","e":"Meet me in front of the museum’s main façade.","ev":"Gặp tôi trước mặt tiền chính của bảo tàng.","x":"Nghĩa 2: a deceptive appearance or attitude\nVí dụ 2: Despite my smiling façade, I am feeling melancholy.","k":"façade"},{"t":"Precipitate","p":"verb","d":"Làm cho điều gì đó xảy ra một cách đặc biệt đột ngột và bất ngờ.","de":"To cause to happen especially suddenly and unexpectedly","e":"Heavy rains can precipitate landslides in hilly areas.","ev":"Mưa lớn có thể gây ra lở đất ở các khu vực đồi núi.","k":"precipitate"},{"t":"Imminent","d":"Sắp xảy ra","de":"About to happen","e":"A storm is imminent in the region.","ev":"Một cơn bão sắp xảy ra trong khu vực.","k":"imminent"},{"t":"Irreproachable","d":"Vượt ngoài mọi lời chỉ trích; hoàn hảo không tì vết","de":"Beyond criticism; faultless","e":"His conduct was irreproachable.","ev":"Hành vi của anh ta không thể chê trách được.","k":"irreproachable"},{"t":"Couch","d":"Để che giấu","de":"To hide","e":"He couched his criticism in polite terms.","ev":"Anh ấy diễn đạt những lời chỉ trích của mình bằng những lời lẽ lịch sự.","x":"Ví dụ 2: second meaning","k":"couch"},{"t":"Scrupulous","p":"adj","d":"tỉ mỉ, trung thực","de":"painstaking, honest","e":"She was scrupulous in her research, ensuring all data was accurate and reliable.","ev":"Cô rất cẩn trọng trong nghiên cứu của mình, đảm bảo tất cả dữ liệu đều chính xác và đáng tin cậy.","k":"scrupulous"}]},{"n":"Ưu tiên 1 · 3","c":[{"t":"Substantiate","p":"verb","d":"để chứng minh là đúng","de":"to show to be true","e":"They need evidence to substantiate their claims.","ev":"Họ cần bằng chứng để chứng minh các tuyên bố của mình.","k":"substantiate"},{"t":"Cease","d":"Dừng lại; tạm dừng","de":"To stop; halt","e":"Production will cease immediately.","ev":"Việc sản xuất sẽ ngừng ngay lập tức.","k":"cease"},{"t":"Ambiguous","p":"adjective","d":"không chắc chắn, có thể được hiểu theo nhiều cách khác nhau","de":"uncertain, variably interpretable","e":"Some believe Caesar married Cleopatra for her power; others think it was her beauty. His actual reasons are ambiguous.","ev":"Một số người cho rằng Caesar kết hôn với Cleopatra vì quyền lực của cô; những người khác nghĩ rằng đó là vì sắc đẹp của cô.","k":"ambiguous"},{"t":"Exploit","d":"Tận dụng tối đa (một nguồn lực), sử dụng (một người) một cách không công bằng hoặc ích kỷ.","de":"to make full use of (a resource), to use (a person) in an unfair or selfish way","e":"The company exploited its workers, paying them low wages and forcing them to work long hours.","ev":"Công ty bóc lột công nhân của mình, trả lương thấp cho họ và buộc họ phải làm việc nhiều giờ.","k":"exploit"},{"t":"Irrevocable","p":"(adj.)","d":"không thể thu hồi lại","de":"incapable of being taken back","e":"The Bill of Rights is an irrevocable part of American law.","ev":"Tuyên ngôn Nhân quyền là một phần không thể hủy bỏ của luật pháp Hoa Kỳ.","k":"irrevocable"},{"t":"Intriguing","d":"Khơi gợi sự tò mò hoặc hứng thú","de":"Arousing curiosity or interest","e":"Her story was intriguing and captured everyone’s attention.","ev":"Câu chuyện của cô rất hấp dẫn và thu hút sự chú ý của mọi người.","k":"intriguing"},{"t":"Scrap","d":"Loại bỏ, vứt bỏ thứ gì đó không còn hữu ích hoặc không còn cần thiết nữa.","de":"To eliminate, to get rid of something that is no longer useful or wanted","e":"Hundreds of nuclear weapons have been scrapped.","ev":"Hàng trăm vũ khí hạt nhân đã bị loại bỏ.","x":"Ví dụ 2: second meaning","k":"scrap"},{"t":"Detractor","d":"Người chỉ trích một tuyên bố hoặc một hành động nào đó.","de":"Person who criticizes a claim or course of action","e":"Detractors argue that the policy will have negative side effects.","ev":"Những người gièm pha cho rằng chính sách này sẽ có tác dụng phụ tiêu cực.","k":"detractor"},{"t":"Animosity","d":"Cảm xúc ghét bỏ hoặc căm thù mạnh mẽ","de":"Strong feelings of dislike or hatred","e":"There was evident animosity between the two rivals.","ev":"Có sự thù địch rõ ràng giữa hai đối thủ.","k":"animosity"},{"t":"Momentous","d":"rất quan trọng (liên quan đến một quyết định hoặc sự kiện)","de":"very important (in reference to a decision or event)","e":"The decision was momentous, having a profound impact on the future of the country.","ev":"Quyết định này rất quan trọng, có tác động sâu sắc đến tương lai của đất nước.","k":"momentous"},{"t":"Shelve/Table","d":"Từ chối hoặc bác bỏ (ví dụ: một ý tưởng hoặc đề xuất)","de":"To reject or discard (e.g., an idea or proposal)","e":"The proposal was shelved for further consideration.","ev":"Đề xuất này đã được gác lại để xem xét thêm.","x":"Ví dụ 2: second meaning","k":"shelve/table"},{"t":"Synopsis","d":"Tóm tắt ngắn gọn","de":"A brief summary","e":"The book’s synopsis gave an overview of the plot.","ev":"Bản tóm tắt của cuốn sách đã đưa ra một cái nhìn tổng quan về cốt truyện.","k":"synopsis"},{"t":"Consensus","p":"noun","d":"sự đồng thuận về quan điểm","de":"an agreement of opinion","e":"The jury was able to reach a consensus only after days of deliberation.","ev":"Bồi thẩm đoàn cuối cùng đã đồng ý sau nhiều cuộc thảo luận.","k":"consensus"},{"t":"Reserve","d":"Để trì hoãn","de":"To hold off on","e":"(e.g., to reserve judgment)","ev":"(ví dụ: để bảo lưu phán quyết)","x":"Ví dụ 2: second meaning","k":"reserve"},{"t":"Analogy","d":"sự so sánh giữa hai thứ","de":"a comparison between two things","e":"He used an analogy to explain the complex concept, comparing it to something more familiar and easier to understand.","ev":"Ông đã sử dụng một phép loại suy để giải thích khái niệm phức tạp, so sánh nó với một thứ gì đó quen thuộc và dễ hiểu hơn.","k":"analogy"},{"t":"Migration","d":"Sự di chuyển của một người hoặc một nhóm người từ khu vực này sang khu vực khác.","de":"The movement of a person or group from one area to another","e":"Seasonal migration of birds is fascinating to observe.","ev":"Sự di cư theo mùa của các loài chim rất thú vị để quan sát.","k":"migration"},{"t":"Despondent","p":"adjective","d":"Cảm thấy chán nản, tuyệt vọng, vô vọng","de":"feeling depressed, discouraged, hopeless","e":"After losing his job, he felt despondent and lost.","ev":"Sau khi mất việc, anh cảm thấy tuyệt vọng và lạc lõng.","k":"despondent"},{"t":"Anomaly","p":"noun","d":"một thứ gì đó không phù hợp với trật tự thông thường.","de":"something that does not fit into the normal order","e":"That rip in the space-time continuum is certainly a spatial anomaly.","ev":"Vết rách trong không-thời gian đó chắc chắn là một bất thường không gian.","k":"anomaly"},{"t":"Abrupt","d":"Đột ngột, bất ngờ, không báo trước","de":"sudden, unexpected, without warning","e":"The conversation came to an abrupt end when the phone rang, startling everyone present.","ev":"Cuộc trò chuyện kết thúc đột ngột khi điện thoại reo lên khiến tất cả những người có mặt đều giật mình.","k":"abrupt"},{"t":"Assert","d":"khẳng định một cách chắc chắn và mạnh mẽ về một sự thật hoặc niềm tin nào đó.","de":"to state a fact or belief confidently and forcefully, khẳng định","e":"She asserted her authority as the leader, demanding respect and obedience.","ev":"Cô khẳng định quyền lực của mình với tư cách là người lãnh đạo, đòi hỏi sự tôn trọng và phục tùng.","k":"assert"},{"t":"Subjective","d":"Bị ảnh hưởng bởi sở thích, quan điểm hoặc cảm xúc cá nhân.","de":"Influenced by personal tastes, opinions, or feelings","e":"The review was highly subjective.","ev":"Việc đánh giá mang tính chủ quan cao.","k":"subjective"},{"t":"Spare, Severe","d":"Không trang trí, rất đơn giản","de":"Unadorned, very plain","e":"a very severe style of architecture","ev":"một phong cách kiến ​​trúc rất nghiêm túc","x":"Ví dụ 2: second meaning","k":"spare, severe"},{"t":"discount (verb)","p":"verb","d":"coi nhẹ, xem nhẹ","de":"coi nhẹ, xem nhẹ","e":"Don’t discount his opinion just because he is young; he may have valuable insights.","ev":"Đừng xem nhẹ ý kiến của anh chỉ vì anh còn trẻ; anh có thể có những hiểu biết quý giá.","k":"discount (verb)"},{"t":"Prohibitive","d":"Khó khăn hoặc giá cả quá cao đến mức ngăn cản việc gì đó xảy ra.","de":"So high (a difficulty or price) that it prevents something from occurring","e":"The cost of the trip was prohibitive.","ev":"Chi phí của chuyến đi rất cao.","k":"prohibitive"},{"t":"Satiate","p":"verb","d":"thỏa mãn quá mức","de":"to satisfy excessively","e":"The dessert was rich enough to satiate even the sweetest tooth.","ev":"Món tráng miệng đủ phong phú để làm thỏa mãn cả những người thích ngọt nhất.","k":"satiate"}]},{"n":"Ưu tiên 1 · 4","c":[{"t":"Offhand","d":"Làm một cách tùy tiện, không suy nghĩ trước.","de":"Done casually, without prior thought","e":"He gave an offhand remark that surprised everyone.","ev":"Anh ấy đưa ra một nhận xét thẳng thắn khiến mọi người ngạc nhiên.","k":"offhand"},{"t":"Vindicate","p":"(v.)","d":"trả thù; giải thoát khỏi lời buộc tội; phóng thích, minh oan","de":"to avenge; to free from allegation; to set free, minh oan","e":"The attorney had no chance of vindicating the defendant with all of the strong evidence presented by the state.","ev":"Luật sư không có cơ hội bào chữa cho bị cáo với tất cả những bằng chứng thuyết phục mà nhà nước đưa ra.","k":"vindicate"},{"t":"Coarseness","d":"Sự thô ráp, sự cứng rắn","de":"Roughness, harshness","e":"The fabric’s coarseness made it uncomfortable to wear.","ev":"Độ thô của vải khiến người mặc cảm thấy khó chịu.","k":"coarseness"},{"t":"Profound","d":"1) dữ dội, cực độ 2) đòi hỏi sự suy nghĩ sâu sắc","de":"1) intense, extreme 2) requiring deep thought","e":"The book had a profound impact on me.","ev":"Cuốn sách đã có tác động sâu sắc đến tôi.","k":"profound"},{"t":"Indulgent","p":"adj","d":"Quá hào phóng; quá dễ dãi","de":"Overly generous; too lenient","e":"The indulgent parents often spoiled their children with extravagant gifts.","ev":"Các bậc phụ huynh nuông chiều thường làm hư con cái mình bằng những món quà xa xỉ.","k":"indulgent"},{"t":"Enhance","d":"Để cải thiện hoặc tăng cường","de":"To improve or intensify","e":"She took a course to enhance her skills.","ev":"Cô đã tham gia một khóa học để nâng cao kỹ năng của mình.","k":"enhance"},{"t":"Sabotage","d":"Cố ý phá hủy hoặc làm hư hại","de":"To deliberately destroy or damage","e":"The enemy attempted to sabotage the mission.","ev":"Kẻ thù cố gắng phá hoại nhiệm vụ.","k":"sabotage"},{"t":"Disparate","p":"(adj.)","d":"khác biệt rõ rệt, chứa các yếu tố tương phản rõ rệt","de":"sharply differing, containing sharply contrasting elements","e":"Having widely varying interests, the students had disparate responses toward the novel.","ev":"Với những sở thích rất khác nhau, học sinh có những phản ứng khác nhau đối với cuốn tiểu thuyết.","k":"disparate"},{"t":"Tenuous","p":"adj","d":"yếu, nhỏ","de":"weak, slight","e":"The connection between the two theories is quite tenuous and needs further investigation.","ev":"Mối liên hệ giữa hai lý thuyết này khá mong manh và cần được điều tra thêm.","k":"tenuous"},{"t":"Fabricate","p":"(v.)","d":"bịa đặt, sáng tạo","de":"to make up, invent","e":"When I arrived an hour late to class, I fabricated some excuse about my car breaking down on the way to school.","ev":"Khi đến lớp muộn một tiếng, tôi bịa ra một số lý do về việc xe của tôi bị hỏng trên đường đến trường.","k":"fabricate"},{"t":"Constitution","d":"Xây dựng","de":"Build","e":"a football player has a solid constitution.","ev":"một cầu thủ bóng đá có thể chất vững chắc.","x":"Ví dụ 2: second meaning","k":"constitution"},{"t":"Reconcile","p":"(v.)","d":"để trở lại trạng thái hài hòa","de":"to return to harmony","e":"The feuding neighbors finally reconciled when one brought the other a delicious tuna noodle casserole.","ev":"Những người hàng xóm thù địch cuối cùng đã hòa giải khi người này mang cho người kia món mì cá ngừ hầm thơm ngon.","x":"Nghĩa 2: to make consistent with existing ideas\nVí dụ 2: Alou had to reconcile his skepticism about the existence of aliens with the fact that he was looking at a flying saucer.","k":"reconcile"},{"t":"Imposing","d":"Có kích thước rất lớn và vẻ ngoài ấn tượng.","de":"Very large and impressive in appearance","e":"The castle was imposing against the skyline.","ev":"Lâu đài sừng sững trên nền trời.","k":"imposing"},{"t":"Unqualified","d":"Tuyệt đối","de":"Absolute","e":"She gave him her unqualified support.","ev":"Cô đã dành cho anh sự hỗ trợ tuyệt vời của mình.","x":"Ví dụ 2: not negative / second meaning","k":"unqualified"},{"t":"Retrospect","d":"Nhìn lại quá khứ;","de":"Hindsight; looking back","e":"In retrospect, the decision made sense.","ev":"Nhìn lại, quyết định này có ý nghĩa.","k":"retrospect"},{"t":"Insight","d":"Hiểu biết sâu sắc","de":"Deep understanding","e":"He offered valuable insight during the discussion.","ev":"Ông đã đưa ra cái nhìn sâu sắc có giá trị trong cuộc thảo luận.","k":"insight"},{"t":"Unresolvable","d":"Không thể giải quyết hoặc dàn xếp","de":"Unable to be resolved or settled","e":"The conflict seemed unresolvable.","ev":"Cuộc xung đột dường như không thể giải quyết được.","k":"unresolvable"},{"t":"Surpass","d":"Vượt quá; đi xa hơn","de":"To exceed; go beyond","e":"She aimed to surpass her previous achievements.","ev":"Cô đặt mục tiêu vượt qua những thành tích trước đây của mình.","k":"surpass"},{"t":"Impeccable","p":"(adj.)","d":"xuất sắc, hoàn hảo","de":"exemplary, flawless","e":"If your grades were as impeccable as your sister’s, then you too would receive a car for a graduation present.","ev":"Nếu điểm số của bạn cũng hoàn hảo như chị gái bạn thì bạn cũng sẽ nhận được một chiếc ô tô làm quà tốt nghiệp.","k":"impeccable"},{"t":"Replenish","d":"Nạp lại; bổ sung","de":"To refill; resupply","e":"They needed to replenish their water supply.","ev":"Họ cần phải bổ sung nguồn cung cấp nước.","k":"replenish"},{"t":"Profusion","d":"Số lượng lớn; từ đồng nghĩa với \"vô số\"; từ trái nghĩa với \"ít ỏi\"","de":"Large amount; synonym for \"myriad\"; antonym for \"paucity\"","e":"There was a profusion of flowers in the garden.","ev":"Trong vườn có rất nhiều hoa.","x":"Ví dụ 2: Large Amount","k":"profusion"},{"t":"Catastrophic","d":"gây ra hoặc là kết quả của thảm họa hoàn toàn","de":"causing or resulting from complete disaster","e":"The earthquake was a catastrophic event.","ev":"Trận động đất là một sự kiện thảm khốc.","k":"catastrophic"},{"t":"Infallible","d":"Không có khả năng mắc sai lầm","de":"Incapable of making mistakes","e":"He believed his judgment to be infallible.","ev":"Anh tin rằng phán đoán của mình là không thể sai lầm.","x":"Ví dụ 2: not negative","k":"infallible"},{"t":"Indoctrinate","d":"Dạy một người/những người chấp nhận niềm tin một cách không phê phán, truyền bá, ném sọ","de":"To teach a person/people to uncritically accept beliefs, truyền bá, nhồi sọ","e":"The regime tried to indoctrinate citizens with its ideology.","ev":"Chế độ đã cố gắng truyền bá hệ tư tưởng của nó cho người dân.","k":"indoctrinate"},{"t":"Nefarious","p":"adj","d":"cực kỳ hung ác, độc ác","de":"heinously villainous, độc ác","e":"The villain's nefarious plans were finally revealed.","ev":"Kế hoạch tội ác của kẻ phản diện cuối cùng đã bị lộ.","k":"nefarious"}]},{"n":"Ưu tiên 1 · 5","c":[{"t":"Impenetrable","d":"Không thể đi qua","de":"Impossible to pass through","e":"The thick forest was impenetrable.","ev":"Rừng rậm không thể xuyên thủng.","k":"impenetrable"},{"t":"Commonplace","d":"Phổ biến, bình thường","de":"Common, ordinary","e":"Cell phones are now commonplace in society.","ev":"Điện thoại di động hiện nay đã trở nên phổ biến trong xã hội.","k":"commonplace"},{"t":"Surmise","p":"(v.)","d":"Suy luận dựa trên bằng chứng ít ỏi","de":"to infer with little evidence","e":"After speaking to only one of the students, the teacher was able to surmise what had caused the fight.","ev":"Sau khi chỉ nói chuyện với một học sinh, giáo viên đã có thể phỏng đoán nguyên nhân gây ra vụ đánh nhau.","k":"surmise"},{"t":"Irate","p":"adjective","d":"tức giận, phẫn nộ","de":"angry, furious","e":"He became irate when he found out his car had been towed.","ev":"Anh trở nên tức giận khi phát hiện ra xe của mình đã bị kéo đi.","k":"irate"},{"t":"Paucity","p":"noun","d":"số lượng nhỏ","de":"small in quantity","e":"The paucity of information made it challenging to draw any conclusions.","ev":"Sự thiếu hụt thông tin đã khiến việc rút ra bất kỳ kết luận nào trở nên khó khăn.","k":"paucity"},{"t":"Insurmountable","d":"Quá mạnh để vượt qua","de":"Too great to overcome","e":"The challenges seemed insurmountable.","ev":"Những thử thách dường như không thể vượt qua.","k":"insurmountable"},{"t":"Sway","d":"Thuyết phục ai đó làm theo một hướng hành động.","de":"To persuade to follow a course of action","e":"He tried to sway the jury with his arguments.","ev":"Anh ta cố gắng thuyết phục bồi thẩm đoàn bằng những lập luận của mình.","k":"sway"},{"t":"Nebulous","p":"adjective","d":"không rõ ràng, nhiều mây","de":"vaguely defined, cloudy","e":"The directions were nebulous, making it hard to find the location.","ev":"Các chỉ dẫn rất mơ hồ, khiến việc tìm kiếm địa điểm trở nên khó khăn.","k":"nebulous"},{"t":"Advantageous","d":"có tác động tích cực","de":"having a positive effect","e":"This is a very advantageous situation.","ev":"Đây là một tình huống rất thuận lợi.","k":"advantageous"},{"t":"Uncanny","p":"adj","d":"có tính chất hoặc nguồn gốc siêu nhiên","de":"of supernatural character or origin","e":"There was an uncanny resemblance between the two sisters, almost as if they were twins.","ev":"Có một sự tương đồng kỳ lạ giữa hai chị em, gần như họ là sinh đôi.","k":"uncanny"},{"t":"Legacy","d":"Tác động lâu dài","de":"A long-lasting impact","e":"He left a legacy of kindness and generosity.","ev":"Ông đã để lại một di sản về lòng tốt và sự hào phóng.","k":"legacy"},{"t":"Advance","d":"Đưa ra một yêu sách","de":"To put forward a claim","e":"She decided to advance her argument during the debate.","ev":"Cô quyết định đưa ra lập luận của mình trong cuộc tranh luận.","k":"advance"},{"t":"Buttress","p":"verb","d":"để hỗ trợ, giữ vững","de":"to support, hold up","e":"The new law will buttress existing regulations.","ev":"Luật mới sẽ củng cố các quy định hiện có.","k":"buttress"},{"t":"Compromise","d":"Làm cho người đó gặp nguy hiểm hoặc dễ bị tổn thương (ví dụ: làm tổn hại đến niềm tin của họ).","de":"To endanger or make vulnerable (e.g., to compromise one's beliefs)","e":"We were not prepared to compromise on safety","ev":"Chúng tôi không sẵn sàng thỏa hiệp về vấn đề an toàn","x":"Ví dụ 2: second meaning","k":"compromise"},{"t":"Untenable","d":"Không thể bào chữa hoặc hỗ trợ","de":"Unable to be defended or supported","e":"His position in the argument was untenable.","ev":"Vị trí của ông trong cuộc tranh luận là không thể đứng vững được.","k":"untenable"},{"t":"Idealize","d":"Tưởng tượng một điều gì đó tốt đẹp hơn thực tế.","de":"To imagine something as better than it is in reality","e":"It is easy to idealize life in a big city.","ev":"Thật dễ dàng để lý tưởng hóa cuộc sống ở một thành phố lớn.","k":"idealize"},{"t":"Corroborate","p":"verb","d":"để hỗ trợ bằng chứng","de":"to support with evidence","e":"The witness was called to corroborate the evidence presented in court.","ev":"Nhân chứng đã được mời đến để xác nhận bằng chứng được trình bày tại tòa.","k":"corroborate"},{"t":"Contingent","d":"Phụ thuộc vào; tùy thuộc vào","de":"Dependent upon; subject to","e":"The success of the project is contingent on the budget approval.","ev":"Sự thành công của dự án phụ thuộc vào việc phê duyệt ngân sách.","x":"Ví dụ 2: general","k":"contingent"},{"t":"Debacle","p":"noun","d":"một thất bại thảm hại, sự gián đoạn","de":"a disastrous failure, disruption","e":"The debacle at the event led to a lot of negative publicity for the organization.","ev":"Cuộc khủng hoảng tại sự kiện đã dẫn đến nhiều tin tức tiêu cực cho tổ chức.","k":"debacle"},{"t":"Impoverished","d":"Rất kém","de":"Very poor","e":"The impoverished community needs support.","ev":"Cộng đồng nghèo khó cần được hỗ trợ.","k":"impoverished"},{"t":"Misconstrue","d":"Hiểu lầm","de":"To misunderstand","e":"His words were easily misconstrued by the audience.","ev":"Lời nói của anh dễ bị khán giả hiểu sai.","k":"misconstrue"},{"t":"Precursor","d":"Người hoặc vật đi trước; người tiên phong","de":"A person or thing that precedes; a forerunner","e":"The typewriter was a precursor to modern computers.","ev":"Máy đánh chữ là tiền thân của máy tính hiện đại.","k":"precursor"},{"t":"Overshadow","d":"Để áp đảo; làm cho ai đó hoặc điều gì đó trở nên không quan trọng.","de":"To dominate; make someone or something seem unimportant","e":"Her achievements were overshadowed by her brother’s success.","ev":"Thành tích của cô bị lu mờ bởi thành công của anh trai cô.","k":"overshadow"},{"t":"Ominous","p":"(adj.)","d":"điềm gở, báo trước điều ác, xa gở","de":"foreboding or foreshadowing evil, điềm gở","e":"The fortuneteller’s ominous words flashed through my mind as the hooded figure approached me in the alley.","ev":"Những lời đáng ngại của thầy bói thoáng qua tâm trí tôi khi bóng người trùm đầu tiến đến gần tôi trong con hẻm.","k":"ominous"},{"t":"Conviction","d":"Sự chắc chắn, quyết tâm. Niềm tin vững vàng.","de":"Certainty, determination. Firm belief","e":"she takes pride in stating her political convictions.","ev":"cô ấy tự hào khi nêu quan điểm chính trị của mình.","x":"Ví dụ 2: second meaning","k":"conviction"}]},{"n":"Ưu tiên 1 · 6","c":[{"t":"Assume","d":"Nhận trách nhiệm, đảm nhiệm (ví dụ: đảm nhận một vị trí mới)","de":"To take on responsibility for, acquire (e.g., to assume a new position)","e":"The new CEO assumed her role on January 1st.","ev":"Giám đốc điều hành mới đảm nhận vai trò của mình vào ngày 1 tháng 1.","x":"Ví dụ 2: second meaning","k":"assume"},{"t":"Acknowledge","d":"Chấp nhận hoặc thừa nhận tính hợp lệ của một yêu cầu.","de":"To accept or admit the validity of a claim","e":"She acknowledged the challenges posed by the project.","ev":"Cô thừa nhận những thách thức mà dự án đặt ra.","k":"acknowledge"},{"t":"Waive","d":"Tự nguyện từ bỏ quyền làm điều gì đó","de":"To voluntarily give up the right to do something","e":"He decided to waive his right to a trial.","ev":"Anh quyết định từ bỏ quyền được xét xử.","k":"waive"},{"t":"Acclaim","p":"verb","d":"lời khen ngợi cao","de":"high praise","e":"Greg’s poem won the acclaim of his friends.","ev":"Bài thơ của Greg đã nhận được sự khen ngợi từ bạn bè.","k":"acclaim"},{"t":"Infer","d":"Suy luận hoặc kết luận dựa trên bằng chứng và lý lẽ.","de":"To deduce or conclude from evidence and reasoning","e":"From the clues, she was able to infer what had happened.","ev":"Từ những manh mối đó, cô có thể suy ra chuyện gì đã xảy ra.","k":"infer"},{"t":"Approximate","d":"Gần đúng nhưng chưa hoàn toàn chính xác.","de":"Close but not completely accurate","e":"The approximate cost of the project is $5,000.","ev":"Chi phí ước tính của dự án là 5.000 USD.","k":"approximate"},{"t":"Overload","d":"Gánh nặng hoặc căng thẳng quá mức","de":"Excessive burden or stress","e":"The workload caused him to feel overloaded.","ev":"Khối lượng công việc khiến anh cảm thấy quá tải.","k":"overload"},{"t":"Resurgence","d":"Hành động hồi sinh trở lại hoặc hoạt động","de":"The act of rising again into life or activity","e":"There was a resurgence of interest in classic films.","ev":"Sự quan tâm trở lại đối với các bộ phim cổ điển đã xuất hiện.","k":"resurgence"},{"t":"Discriminating","d":"Có khả năng phân biệt tinh tế (ví dụ: vị giác tinh tế)","de":"Able to make fine distinctions (e.g., a discriminating palate)","e":"Sáng suốt She has a discriminating taste in music.","ev":"Sáng suốt Cô ấy có gu âm nhạc rất tinh tế.","x":"Ví dụ 2: second meaning","k":"discriminating"},{"t":"Imperative","p":"(adj.)","d":"cần thiết, cấp bách","de":"necessary, pressing","e":"It is imperative that you have these folders organized by midday.","ev":"Điều bắt buộc là bạn phải sắp xếp các thư mục này trước giữa trưa.","x":"Loại từ 2: (n.)\nNghĩa 2: a rule, command, or order\nVí dụ 2: Her imperative to have the folders organized by midday was perceived as ridiculous by the others.","k":"imperative"},{"t":"Waver","d":"Phân vân giữa hai lựa chọn; từ đồng nghĩa với \"dao động\".","de":"To go back and forth between two options; synonym for \"vacillate\"","e":"She wavered between taking the job offer and staying.","ev":"Cô ấy lưỡng lự giữa việc nhận lời mời làm việc và ở lại.","k":"waver"},{"t":"Meticulous","p":"(adj.)","d":"Cực kỳ cẩn thận đến từng chi tiết","de":"extremely careful with details","e":"The ornate needlework in the bride’s gown was a product of meticulous handiwork.","ev":"Những đường thêu trang trí công phu trên váy cô dâu là sản phẩm của sự thủ công tỉ mỉ.","k":"meticulous"},{"t":"Appease","p":"verb","d":"để làm dịu, thỏa mãn, dành riêng","de":"to calm, satisfy, dỗ dành","e":"The mother gave her child candy to appease him when he cried.","ev":"Người mẹ đã cho đứa trẻ kẹo để làm dịu nó khi nó khóc.","k":"appease"},{"t":"Juxtaposition","p":"(n.)","d":"Hành động đặt hai vật cạnh nhau để so sánh ngầm.","de":"the act of placing two things next to each other for implicit comparison","e":"The interior designer admired my juxtaposition of the yellow couch and green table.","ev":"Nhà thiết kế nội thất ngưỡng mộ sự sắp xếp cạnh nhau của chiếc ghế dài màu vàng và chiếc bàn màu xanh lá cây.","k":"juxtaposition"},{"t":"Amorphous","p":"adjective","d":"không có hình dạng hoặc loại xác định","de":"without definite shape or type","e":"The effort was doomed from the start because the reasons behind it were amorphous.","ev":"Nỗ lực đã bị thất bại ngay từ đầu vì lý do phía sau nó không rõ ràng.","k":"amorphous"},{"t":"Speculate","d":"Phỏng đoán, đưa ra giả thuyết mà không có bằng chứng chắc chắn.","de":"to guess, to form a theory without firm evidence","e":"The police speculated about the motive for the crime, considering various possibilities but ultimately unable to determine the truth.","ev":"Cảnh sát suy đoán về động cơ gây án, xem xét nhiều khả năng khác nhau nhưng cuối cùng không thể xác định được sự thật.","k":"speculate"},{"t":"Revelation","d":"Một điều gì đó được tiết lộ và do đó được biết đến.","de":"Something that is revealed and thus made known","e":"The revelation shocked everyone present.","ev":"Tiết lộ này đã gây sốc cho tất cả những người có mặt.","k":"revelation"},{"t":"Latent","p":"(adj.)","d":"Ẩn giấu, nhưng có thể bị phát hiện.","de":"hidden, but capable of being exposed","e":"Sigmund’s dream represented his latent paranoid obsession with other people’s shoes.","ev":"Giấc mơ của Sigmund thể hiện nỗi ám ảnh hoang tưởng tiềm ẩn của anh về đôi giày của người khác.","k":"latent"},{"t":"Pretentious","d":"Tự cho mình tầm quan trọng lớn hơn thực tế","de":"Affecting greater importance than one actually has","e":"His pretentious speech annoyed many of the guests.","ev":"Lời nói kiêu căng của anh ta khiến nhiều quan khách khó chịu.","k":"pretentious"},{"t":"Harbor","d":"Sở hữu, nắm giữ","de":"To possess, hold","e":"e.g., to harbor a belief","ev":"ví dụ, để nuôi dưỡng một niềm tin","x":"Ví dụ 2: second meaning","k":"harbor"},{"t":"Exorbitant","p":"adj","d":"quá mức","de":"excessive","e":"The exorbitant prices of luxury goods can deter many consumers.","ev":"Giá cả quá cao của hàng hóa xa xỉ có thể làm nhiều người tiêu dùng chùn bước.","k":"exorbitant"},{"t":"Evade","d":"Trốn thoát hoặc tránh né","de":"To escape or avoid","e":"He managed to evade capture for years.","ev":"Anh ta đã trốn tránh bị bắt trong nhiều năm.","k":"evade"},{"t":"Reciprocate","p":"(v.)","d":"để đáp lại","de":"to give in return","e":"When Steve gave Samantha a sweater for Christmas, she reciprocated by giving him a kiss.","ev":"Khi Steve tặng Samantha một chiếc áo len nhân dịp Giáng sinh, cô ấy đã đáp lại bằng một nụ hôn.","k":"reciprocate"},{"t":"Rebut","d":"Đưa ra lập luận phản bác một tuyên bố được cho là sai.","de":"To offer an argument against a claim believed to be false","e":"The lawyer rebutted the accusations with strong evidence.","ev":"Luật sư bác bỏ lời cáo buộc bằng bằng chứng thuyết phục.","x":"Ví dụ 2: Question a Claim","k":"rebut"},{"t":"Credulous","d":"Dễ bị lừa, cả thiếc","de":"Easily fooled, cả tin","e":"He was too credulous to see through the scam.","ev":"Anh ta quá cả tin để có thể nhìn thấu được trò lừa đảo.","k":"credulous"}]},{"n":"Ưu tiên 1 · 7","c":[{"t":"Annotate","d":"Ghi chú để giúp giải thích hoặc làm rõ hơn.","de":"To make notes to help explain or clarify","e":"The teacher asked us to annotate the text.","ev":"Giáo viên yêu cầu chúng tôi chú thích văn bản.","k":"annotate"},{"t":"Replicate","d":"Để sao chép","de":"To copy","e":"Scientists were able to replicate the experiment’s results.","ev":"Các nhà khoa học đã có thể tái tạo kết quả của thí nghiệm.","k":"replicate"},{"t":"Upset","d":"Can thiệp vào kết quả dự kiến.","de":"To interfere with an expected outcome","e":"Any mechanical problems would upset our plans of driving across the desert.","ev":"Bất kỳ sự cố máy móc nào cũng có thể làm đảo lộn kế hoạch lái xe băng qua sa mạc của chúng tôi.","x":"Ví dụ 2: second meaning","k":"upset"},{"t":"Comprise","d":"bao gồm hoặc được cấu thành từ","de":"to consist of or to be made up of","e":"The team was comprised of players from different countries.","ev":"Đội bao gồm các cầu thủ đến từ các quốc gia khác nhau.","k":"comprise"},{"t":"Augment","p":"verb","d":"bổ sung, mở rộng","de":"to add to, expand","e":"The student seeks to augment his knowledge of French by reading literature.","ev":"Sinh viên đó muốn mở rộng kiến thức tiếng Pháp bằng cách đọc văn học.","k":"augment"},{"t":"Fruitful/Fruitless","d":"Hiệu quả/không hiệu quả","de":"Productive/unproductive","e":"Their discussion was fruitful, resulting in a new plan.","ev":"Cuộc thảo luận của họ đã có kết quả, dẫn đến một kế hoạch mới.","k":"fruitful/fruitless"},{"t":"Prescribe","p":"(v.)","d":"để đặt ra một quy tắc","de":"to lay down a rule","e":"The duke prescribed that from this point further all of the peasants living on his lands would have to pay higher taxes.","ev":"Công tước quy định rằng kể từ thời điểm này trở đi, tất cả nông dân sống trên đất của ông sẽ phải nộp thuế cao hơn.","k":"prescribe"},{"t":"Accentuate","p":"verb","d":"nhấn mạnh, làm nổi bật","de":"to stress, highlight","e":"Psychologists say happy people accentuate the positive in life.","ev":"Các nhà tâm lý học nói rằng những người hạnh phúc làm nổi bật điều tích cực trong cuộc sống.","k":"accentuate"},{"t":"Pretext","p":"noun","d":"Lời bào chữa sai trái được đưa ra để biện minh cho một hành động.","de":"False excuse given to justify a course of action","e":"He used a pretext to avoid the meeting.","ev":"Anh ta đã dùng lý do giả để tránh cuộc họp.","k":"pretext"},{"t":"Diverge","d":"Đi theo những hướng khác nhau từ cùng một điểm, trở nên khác biệt.","de":"to go in different directions from the same point, to become different","e":"The roads diverged at the intersection.","ev":"Các con đường phân nhánh ở ngã tư.","k":"diverge"},{"t":"Mobilize","d":"Chuẩn bị cho một cá nhân hoặc một nhóm người hành động.","de":"To prepare a person or group for action","e":"The army was mobilized in response to the threat.","ev":"Quân đội đã được huy động để đối phó với mối đe dọa.","k":"mobilize"},{"t":"Skeptic","d":"Người đặt câu hỏi hoặc nghi ngờ về một tuyên bố.","de":"Person who questions or doubts a claim","e":"As a skeptic, she demanded more proof before agreeing.","ev":"Là một người hoài nghi, cô yêu cầu thêm bằng chứng trước khi đồng ý.","k":"skeptic"},{"t":"Induce","p":"verb","d":"để tạo ra, kích thích","de":"to bring about, stimulate","e":"The medication may induce drowsiness, so be cautious when driving.","ev":"Thuốc có thể gây buồn ngủ, vì vậy hãy cẩn thận khi lái xe.","k":"induce"},{"t":"Spurious","p":"adj","d":"sai nhưng được thiết kế để có vẻ hợp lý. Giả sử sai","de":"false but designed to seem plausible. Giả mạo, sai","e":"The claims turned out to be spurious.","ev":"Các tuyên bố hóa ra là giả mạo.","k":"spurious"},{"t":"Resilient","p":"(adj.)","d":"Có khả năng phục hồi sau bất hạnh; có khả năng chịu đựng nghịch cảnh.","de":"able to recover from misfortune; able to withstand adversity","e":"The resilient ballplayer quickly recovered from his wrist injury.","ev":"Cầu thủ chơi bóng kiên cường đã nhanh chóng bình phục chấn thương cổ tay.","k":"resilient"},{"t":"Aesthetic","p":"adjective","d":"thuộc về nghệ thuật, liên quan đến sự cảm thụ cái đẹp.","de":"artistic, related to the appreciation of beauty","e":"We hired Susan for her excellent aesthetic sense in decorating.","ev":"Chúng tôi đã thuê Susan vì khả năng thẩm mỹ tuyệt vời của cô trong việc trang trí.","k":"aesthetic"},{"t":"Intricate","d":"Rất phức tạp","de":"Very complex","e":"The design is intricate and beautiful.","ev":"Thiết kế rất phức tạp và đẹp.","k":"intricate"},{"t":"Grave/ Gravity","d":"Mức độ nghiêm trọng","de":"Serious(ness)","e":"The situation was grave.","ev":"Tình hình thật nghiêm trọng.","x":"Ví dụ 2: second meaning","k":"grave/ gravity"},{"t":"Orthodox","p":"adj","d":"thông thường, tuân theo quy trình đã thiết lập.","de":"conventional, conforming to established protocol","e":"His orthodox views on education often clashed with innovative teaching methods.","ev":"Quan điểm chính thống của ông về giáo dục thường mâu thuẫn với các phương pháp giảng dạy sáng tạo.","k":"orthodox"},{"t":"Draconian","d":"Các luật lệ, quy tắc và hình phạt quá hà khắc","de":"Excessively harsh laws, rules, and punishments","e":"The new regulations were considered draconian by many.","ev":"Nhiều quy định mới được nhiều người coi là hà khắc.","k":"draconian"},{"t":"Bent","d":"Sự yêu thích. Từ đồng nghĩa với sở thích, khuynh hướng, thiên hướng.","de":"Liking for. Synonym for penchant, predilection, proclivity","e":"He has a bent for mathematics.","ev":"Anh ấy có năng khiếu về toán học.","x":"Ví dụ 2: second meaning","k":"bent"},{"t":"Idiosyncratic","p":"(adj.)","d":"Đặc trưng riêng của một người; mang tính cá nhân cao.","de":"peculiar to one person; highly individualized","e":"I know you had trouble with the last test, but because your mistakes were highly idiosyncratic, I’m going to deny your request that the class be given a new test.","ev":"Tôi biết bạn đã gặp khó khăn với bài kiểm tra vừa rồi, nhưng vì những lỗi của bạn rất đặc trưng nên tôi sẽ từ chối yêu cầu của bạn về việc cho cả lớp làm một bài kiểm tra mới.","k":"idiosyncratic"},{"t":"Chance","d":"Để thử","de":"To attempt","e":"She waited a few seconds and chanced another look","ev":"Cô đợi vài giây và có cơ hội nhìn lại","x":"Ví dụ 2: second meaning","k":"chance"},{"t":"Prevail","d":"Để vượt qua những khó khăn lớn lao","de":"To triumph over great odds","e":"She hoped that good would ultimately prevail.","ev":"Cô hy vọng rằng điều tốt đẹp cuối cùng sẽ thắng thế.","x":"Ví dụ 2: general","k":"prevail"},{"t":"(Pre)Supposition","d":"Một ý niệm được giả định trước về một chủ đề.","de":"An idea assumed beforehand about a subject","e":"The study was based on the presupposition that people act rationally.","ev":"Nghiên cứu này dựa trên giả định rằng mọi người hành động một cách hợp lý.","k":"(pre)supposition"}]},{"n":"Ưu tiên 1 · 8","c":[{"t":"Infinitesimal","d":"Cực kỳ nhỏ; gần bằng không.","de":"Extremely small; approaching zero","e":"The risk of error was infinitesimal.","ev":"Nguy cơ xảy ra lỗi là vô cùng nhỏ.","k":"infinitesimal"},{"t":"Pragmatic","p":"(adj.)","d":"thực tế","de":"practical","e":"The politician argued that while increased security measures might not fit with the lofty ideals of the nation, they were a pragmatic necessity to ensure everyone’s safety.","ev":"Chính trị gia này lập luận rằng mặc dù các biện pháp an ninh được tăng cường có thể không phù hợp với lý tưởng cao cả của quốc gia, nhưng chúng là một điều cần thiết thực tế để đảm bảo an toàn cho mọi người.","k":"pragmatic"},{"t":"Austere","p":"adj.","d":"rất trần trụi, ảm đạm, đơn sơ mộc mạc","de":"very bare, bleak, đơn sơ mộc mạc","e":"The austere furniture in the abandoned house made it feel haunted.","ev":"Đồ nội thất đơn giản trong ngôi nhà bị bỏ hoang khiến nó cảm thấy ám ảnh.","k":"austere"},{"t":"Renounce","p":"verb","d":"Từ bỏ, phủ nhận hoặc nhượng bộ điều gì đó","de":"to give up, deny, or surrender something","e":"He chose to renounce his previous lifestyle and start anew.","ev":"Anh quyết định từ bỏ lối sống trước đây và bắt đầu lại.","k":"renounce"},{"t":"Ameliorate","p":"verb","d":"để cải thiện","de":"to improve","e":"The tense situation was ameliorated when Sam proposed a solution everyone could agree upon.","ev":"Tình huống căng thẳng đã được cải thiện khi Sam đề xuất một giải pháp mà mọi người có thể đồng ý.","k":"ameliorate"},{"t":"Intuition","d":"bản năng, khả năng hiểu ngay lập tức một điều gì đó.","de":"instinct, the ability to understand something immediately","e":"She had a strong intuition that something was wrong, even though there was no concrete evidence to support her suspicion.","ev":"Cô có trực giác mạnh mẽ rằng có điều gì đó không ổn, mặc dù không có bằng chứng cụ thể nào chứng minh cho sự nghi ngờ của cô.","k":"intuition"},{"t":"Unattainable","d":"Không thể đạt được hoặc không thể đạt tới.","de":"Cannot be reached or achieved","e":"Perfection is often considered unattainable.","ev":"Sự hoàn hảo thường được coi là không thể đạt được.","k":"unattainable"},{"t":"Invasive","d":"Lan rộng một cách có hại (dạng danh từ của \"xâm lược\")","de":"Spreading in a harmful manner (noun form of \"invade\")","e":"The invasive species threatened the native plants.","ev":"Các loài xâm lấn đe dọa thực vật bản địa.","k":"invasive"},{"t":"Discord","d":"sự bất đồng giữa mọi người","de":"disagreement between people","e":"The discord between the two factions led to a civil war.","ev":"Sự bất hòa giữa hai phe đã dẫn đến một cuộc nội chiến.","k":"discord"},{"t":"Moribund","d":"Đang đến gần cái chết; sắp trở nên lỗi thời.","de":"Approaching death; on the verge of becoming obsolete","e":"The technology was considered moribund.","ev":"Công nghệ này được coi là hấp hối.","k":"moribund"},{"t":"Rudimentary","d":"Giới hạn ở các nguyên tắc cơ bản; cơ bản","de":"Limited to basic principles; elementary","e":"He had a rudimentary understanding of the language.","ev":"Anh ấy có sự hiểu biết sơ bộ về ngôn ngữ.","x":"Ví dụ 2: general","k":"rudimentary"},{"t":"Substantial","p":"adj.","d":"Có tầm quan trọng, quy mô hoặc giá trị đáng kể.","de":"of considerable importance, size, or worth.","e":"a substantial amount of cash","ev":"một lượng tiền mặt đáng kể","k":"substantial"},{"t":"Outsized","d":"Quá lớn một cách không cân xứng","de":"Disproportionately large","e":"The house was outsized compared to its surroundings.","ev":"Ngôi nhà có kích thước quá lớn so với xung quanh.","k":"outsized"},{"t":"Erratic","d":"không thể đoán trước, không nhất quán, bất thường","de":"unpredictable, inconsistent, irregular","e":"The erratic weather made it difficult to plan outdoor activities.","ev":"Thời tiết thất thường khiến việc lên kế hoạch cho các hoạt động ngoài trời trở nên khó khăn.","k":"erratic"},{"t":"Relay","d":"Truyền đạt lại cho người khác (ví dụ: chuyển tiếp thông tin)","de":"To pass on to someone else (e.g., to relay information)","e":"The message was relayed to the troops.","ev":"Thông điệp đã được chuyển đến quân đội.","x":"Ví dụ 2: second meaning","k":"relay"},{"t":"Ruminate About","d":"Suy nghĩ sâu sắc về một điều gì đó","de":"To think deeply about something","e":"The writer ruminated about the meaning of life while sitting by the lake.","ev":"Nhà văn ngẫm nghĩ về ý nghĩa cuộc sống khi ngồi bên hồ.","x":"Ví dụ 2: Think about","k":"ruminate about"},{"t":"Exacerbate","p":"(v.)","d":"để làm cho bạo lực, dữ dội hơn","de":"to make more violent, intense","e":"The gruesome and scary movie I saw last night exacerbated my fears of the dark.","ev":"Bộ phim khủng khiếp và đáng sợ mà tôi xem tối qua càng làm tăng thêm nỗi sợ bóng tối của tôi.","k":"exacerbate"},{"t":"Ambivalence","d":"n. trạng thái không chắc chắn hoặc lưỡng lự giữa hai hoặc nhiều lựa chọn","de":"n. the state of being uncertain or stuck between two or more options","e":"n. the state of being uncertain or stuck between two or more options","ev":"N. tình trạng không chắc chắn hoặc bị mắc kẹt giữa hai hoặc nhiều lựa chọn","k":"ambivalence"},{"t":"Strenuous","p":"(adj.)","d":"đòi hỏi năng lượng hoặc sức bền rất lớn.","de":"requiring tremendous energy or stamina","e":"Running a marathon is quite a strenuous task. So is watching an entire Star Trek marathon.","ev":"Chạy marathon là một công việc khá vất vả. Việc xem toàn bộ cuộc thi marathon Star Trek cũng vậy.","k":"strenuous"},{"t":"Indifferent","d":"Không quan tâm, không để tâm; thờ ơ.","de":"Without interest or concern; apathetic","e":"He was indifferent to the outcome of the game.","ev":"Anh ấy thờ ơ với kết quả của trận đấu.","k":"indifferent"},{"t":"Deviation","d":"Khác biệt so với những gì được coi là bình thường","de":"Departure from what is normal","e":"There was a slight deviation from the original plan.","ev":"Có một chút sai lệch so với kế hoạch ban đầu.","k":"deviation"},{"t":"Lucrative","p":"noun","d":"Rất có lợi nhuận","de":"Very profitable","e":"The new startup proved to be a lucrative venture for its founders.","ev":"Công ty khởi nghiệp mới đã chứng tỏ là một dự án sinh lời cho các nhà sáng lập.","k":"lucrative"},{"t":"Engulf","d":"bao vây và che phủ hoàn toàn","de":"to surround and cover completely","e":"The flames engulfed the house, destroying it completely.","ev":"Ngọn lửa bao trùm ngôi nhà, thiêu rụi hoàn toàn.","k":"engulf"},{"t":"Insuperable","d":"Không thể bị đánh bại","de":"Incapable of being overcome","e":"They faced insuperable obstacles.","ev":"Họ phải đối mặt với những trở ngại không thể vượt qua.","k":"insuperable"},{"t":"Indecipherable","d":"Không thể đọc hoặc hiểu được.","de":"Unable to be read or understood","e":"The old manuscript was indecipherable.","ev":"Bản thảo cũ không thể giải mã được.","k":"indecipherable"}]},{"n":"Ưu tiên 1 · 9","c":[{"t":"Badger","d":"Làm phiền hoặc quấy rầy (ví dụ: các phóng viên liên tục quấy rầy ứng cử viên sau khi vụ bê bối vỡ lở)","de":"To pester or annoy (e.g., reporters repeatedly badgered the candidate after the scandal broke)","e":"She badgered him until he agreed to help.","ev":"Cô nài nỉ anh cho đến khi anh đồng ý giúp đỡ.","x":"Ví dụ 2: second meaning","k":"badger"},{"t":"Affinity","p":"noun","d":"một cảm giác gần gũi tự nhiên","de":"a spontaneous feeling of closeness","e":"Jerry didn’t know why, but he felt an incredible affinity for Kramer the first time they met.","ev":"Jerry không biết tại sao, nhưng anh cảm thấy một mối liên hệ đặc biệt với Kramer lần đầu họ gặp nhau.","k":"affinity"},{"t":"Cite","d":"Trích dẫn hoặc tham khảo một tác phẩm để củng cố luận điểm.","de":"To quote or reference from a work to support an argument","e":"Please cite your sources in the essay.","ev":"Hãy trích dẫn nguồn của bạn trong bài luận.","k":"cite"},{"t":"Economy","d":"Tiết kiệm (ví dụ: một nhà văn có phong cách viết ngắn gọn là người sử dụng ít từ ngữ)","de":"Thrift (e.g., a writer who has an economical style is one who uses few words)","e":"We must learn to practice economy.","ev":"Chúng ta phải học cách thực hành kinh tế.","x":"Ví dụ 2: second meaning","k":"economy"},{"t":"Catalyze","p":"(v.)","d":"để nạp năng lượng, truyền cảm hứng","de":"to charge, inspire","e":"The president’s speech catalyzed the nation and resuscitated the economy.","ev":"Bài phát biểu của tổng thống đã xúc tác đất nước và vực dậy nền kinh tế.","k":"catalyze"},{"t":"Indigenous","p":"adj","d":"có nguồn gốc từ một vùng","de":"originating in a region","e":"The indigenous people of the region have a rich cultural heritage.","ev":"Người bản địa của khu vực này có một di sản văn hóa phong phú.","k":"indigenous"},{"t":"Pervasive","p":"(adj.)","d":"có xu hướng lan rộng khắp nơi, tràn lan","de":"having the tendency to spread throughout, tràn khắp","e":"Stepping off the plane in Havana, I recognized the pervasive odor of sugar cane fields on fire.","ev":"Bước xuống máy bay ở Havana, tôi ngửi thấy mùi hôi nồng nặc của cánh đồng mía cháy.","k":"pervasive"},{"t":"Imperceptible","d":"Không thể nhìn thấy hoặc cảm nhận được","de":"Cannot be seen or perceived","e":"The changes in his behavior were almost imperceptible.","ev":"Những thay đổi trong hành vi của anh ấy gần như không thể nhận ra.","k":"imperceptible"},{"t":"Unconventional","d":"không tuân theo các quy tắc truyền thống hoặc được chấp nhận.","de":"not following traditional or accepted rules","e":"He had an unconventional approach to teaching.","ev":"Ông có một cách tiếp cận giảng dạy độc đáo.","k":"unconventional"},{"t":"Mercurial","p":"adjective","d":"Đặc trưng bởi sự thay đổi nhanh chóng hoặc tính khí thất thường","de":"characterized by rapid change or temperamentality","e":"His mercurial temperament made it hard for people to know how he would react.","ev":"Tính cách thất thường của anh khiến mọi người khó đoán được anh sẽ phản ứng như thế nào.","k":"mercurial"},{"t":"Plastic","d":"Có thể thay đổi, dễ uốn nắn (ví dụ: tính dẻo dai của não bộ)","de":"Able to be changed, malleable (e.g., brain plasticity)","e":"brain plasticity","ev":"độ dẻo của não","x":"Ví dụ 2: second meaning","k":"plastic"},{"t":"Haphazard","d":"không có kế hoạch nào cả, một cách ngẫu nhiên","de":"not having any plan, randomly","e":"The books were arranged in a haphazard manner, making it hard to find anything.","ev":"Các cuốn sách được sắp xếp lộn xộn, khó tìm được thứ gì.","k":"haphazard"},{"t":"Elicit","p":"verb","d":"để khơi gợi, lôi ra, gợi lên","de":"to bring forth, draw out, evoke","e":"The teacher aimed to elicit responses from all the students during the discussion.","ev":"Giáo viên nhằm mục đích thu hút phản hồi từ tất cả học sinh trong cuộc thảo luận.","k":"elicit"},{"t":"Channel","d":"Hướng một thứ gì đó (ví dụ: năng lượng, tiền bạc) đến một mục đích cụ thể.","de":"To direct something (e.g., energy, money) toward a specific purpose","e":"A lot of money has been channeled into cancer research.","ev":"Rất nhiều tiền đã được chuyển vào nghiên cứu ung thư.","x":"Ví dụ 2: second meaning","k":"channel"},{"t":"Ubiquitous","p":"adj","d":"tồn tại ở khắp mọi nơi, phổ biến rộng rãi","de":"existing everywhere, widespread","e":"Smartphones have become ubiquitous in modern society.","ev":"Điện thoại thông minh đã trở nên phổ biến trong xã hội hiện đại.","k":"ubiquitous"},{"t":"Credible","d":"Đáng tin cậy","de":"Believable","e":"The witness provided a credible testimony.","ev":"Nhân chứng đã đưa ra lời khai đáng tin cậy.","k":"credible"},{"t":"Abundant","d":"dồi dào","de":"plentiful","e":"The resources were abundant in the region, providing a rich and plentiful supply for the people.","ev":"Nguồn tài nguyên trong vùng dồi dào, cung cấp nguồn cung dồi dào và dồi dào cho người dân.","k":"abundant"},{"t":"Relate","d":"Kể lại (một câu chuyện)","de":"To tell give an account of (a story)","e":"He related the events of his childhood.","ev":"Anh kể lại những sự kiện thời thơ ấu của mình.","x":"Ví dụ 2: second meaning","k":"relate"},{"t":"Eclipse","d":"Làm lu mờ hoặc ngăn chặn","de":"To overshadow or block","e":"Her success eclipsed all other achievements.","ev":"Thành công của cô làm lu mờ tất cả những thành tựu khác.","k":"eclipse"},{"t":"Affecting","d":"Chạm đến cảm xúc; lay động lòng người","de":"Touching the emotions; moving","e":"The movie’s ending was deeply affecting.","ev":"Cái kết của bộ phim gây ấn tượng sâu sắc.","k":"affecting"},{"t":"Unobtrusive","d":"Không gây chú ý; không thu hút sự chú ý","de":"Inconspicuous; not attracting attention","e":"He tried to be unobtrusive at the event.","ev":"Anh cố gắng tỏ ra kín đáo tại sự kiện.","k":"unobtrusive"},{"t":"Equitable","p":"adj","d":"Hội chợ","de":"Fair","e":"The judge aimed to ensure an equitable distribution of resources among the community.","ev":"Thẩm phán nhắm đến việc đảm bảo phân phối công bằng tài nguyên giữa các thành viên trong cộng đồng.","k":"equitable"},{"t":"Evince","p":"(v.)","d":"để thể hiện, tiết lộ","de":"to show, reveal","e":"Christopher’s hand-wringing and nail-biting evince how nervous he is about the upcoming English test.","ev":"Việc Christopher vặn tay và cắn móng tay cho thấy anh ấy lo lắng như thế nào về bài kiểm tra tiếng Anh sắp tới.","k":"evince"},{"t":"Thwart","d":"Ngăn chặn hoặc cản trở điều gì đó tiêu cực.","de":"To block or get in the way of something negative","e":"They worked to thwart the enemy’s plans.","ev":"Họ làm việc để ngăn chặn kế hoạch của kẻ thù.","k":"thwart"},{"t":"Sap","d":"Làm cạn kiệt (ví dụ: năng lượng)","de":"To drain (e.g., of energy)","e":"our energy is being sapped by bureaucrats and politicians","ev":"năng lượng của chúng ta đang bị các quan chức và chính trị gia làm hao mòn","x":"Ví dụ 2: second meaning","k":"sap"}]},{"n":"Ưu tiên 1 · 10","c":[{"t":"Obscure","p":"(adj.)","d":"không rõ ràng, bị che khuất một phần","de":"unclear, partially hidden","e":"Because he was standing in the shadows, his features were obscure.","ev":"Vì đứng trong bóng tối nên đường nét của anh ta bị che khuất.","k":"obscure"},{"t":"Superficial","d":"nông, trên bề mặt","de":"shallow, on the surface","e":"Their relationship was superficial, lacking depth and emotional connection.","ev":"Mối quan hệ của họ rất hời hợt, thiếu chiều sâu và sự kết nối tình cảm.","k":"superficial"},{"t":"Adaptation","d":"Sự thay đổi này được thực hiện để phù hợp với hoàn cảnh mới.","de":"A change made to accommodate new circumstances","e":"His adaptation to the new environment was impressive.","ev":"Sự thích nghi của anh ấy với môi trường mới thật ấn tượng.","k":"adaptation"},{"t":"Trivial","d":"Không quan trọng","de":"Unimportant","e":"He dismissed the issue as trivial.","ev":"Ông coi vấn đề này là tầm thường.","k":"trivial"},{"t":"Lineage","d":"Xuất thân từ một tổ tiên chung hoặc tiền bối.","de":"Descent from a common ancestor or predecessor","e":"Her royal lineage dates back centuries.","ev":"Dòng dõi hoàng gia của cô có từ nhiều thế kỷ trước.","k":"lineage"},{"t":"Indelible","d":"Đáng nhớ; không thể nào quên.","de":"Memorable; impossible to forget","e":"The trip left an indelible mark on her.","ev":"Chuyến đi đã để lại dấu ấn khó phai mờ trong cô.","k":"indelible"},{"t":"Check","d":"Kiềm chế, kiểm soát hoặc giảm thiểu (ví dụ: vắc-xin đã ngăn chặn sự lây lan của dịch bệnh)","de":"To restrain, control, or reduce (e.g., the vaccine checked the spread of the disease)","e":"They have begun to vaccinate children in an attempt to check the spread of the disease.","ev":"Họ đã bắt đầu tiêm chủng cho trẻ em nhằm kiểm soát sự lây lan của căn bệnh này.","x":"Ví dụ 2: second meaning","k":"check"},{"t":"Conspicuous","d":"Có thể nhìn thấy rõ ràng; dễ nhận thấy","de":"Clearly visible; noticeable","e":"The error was conspicuous in the final report.","ev":"Lỗi này rất dễ thấy trong báo cáo cuối cùng.","x":"Ví dụ 2: Noticeable, Striking","k":"conspicuous"},{"t":"Impede","d":"Gây khó khăn cho ai đó hoặc điều gì đó, dẫn đến sự chậm trễ.","de":"to create difficulties for someone or something, resulting in delay","e":"The heavy traffic impeded their progress, delaying their arrival.","ev":"Giao thông đông đúc đã cản trở bước tiến của họ, khiến việc đến nơi của họ bị trì hoãn.","k":"impede"},{"t":"Recant","p":"verb","d":"Lấy lại; rút lại; từ bỏ","de":"To take back; withdraw; renounce","e":"After much consideration, he decided to recant his earlier statement.","ev":"Sau nhiều cân nhắc, anh đã quyết định thu hồi tuyên bố trước đó của mình.","k":"recant"},{"t":"Innovative","d":"mới và khác biệt","de":"new and different","e":"The company's innovative products were a success, setting new standards for the industry and attracting a loyal customer base.","ev":"Các sản phẩm đổi mới của công ty đã thành công, đặt ra các tiêu chuẩn mới cho ngành và thu hút lượng khách hàng trung thành.","k":"innovative"},{"t":"Excavation","d":"Quá trình khai quật, thường là một địa điểm lịch sử.","de":"The process of digging up, usually a historic site","e":"The excavation revealed ancient artifacts.","ev":"Cuộc khai quật đã tiết lộ những hiện vật cổ xưa.","k":"excavation"},{"t":"Palpable","d":"Theo nghĩa đen, có thể chạm vào được; thường được sử dụng để mô tả một cảm giác rất mãnh liệt. Rõ ràng, hiển nhiên","de":"Literally, touchable; often used to describe a very intense feeling. Rõ ràng, hiển nhiên","e":"There was a palpable sense of excitement in the room.","ev":"Trong phòng tràn ngập cảm giác hưng phấn.","k":"palpable"},{"t":"Multifaceted","d":"Có nhiều khía cạnh","de":"Having many aspects","e":"He is a multifaceted individual with many talents.","ev":"Anh ấy là một cá nhân đa diện và có nhiều tài năng.","k":"multifaceted"},{"t":"Undermine","d":"Làm tổn hại hoặc làm suy yếu dần dần ai đó hoặc điều gì đó.","de":"to gradually damage or weaken someone or something","e":"The scandal undermined his reputation, making it difficult for him to regain the public's trust.","ev":"Vụ bê bối đã làm suy yếu danh tiếng của anh, khiến anh khó lấy lại được lòng tin của công chúng.","k":"undermine"},{"t":"Proponent","p":"noun","d":"Người ủng hộ một ý tưởng, kế hoạch hoặc lý tưởng nào đó.","de":"a person who supports an idea, plan, or cause","e":"She is a strong proponent of environmental protection and sustainability.","ev":"Cô ấy là một người ủng hộ mạnh mẽ cho việc bảo vệ môi trường và sự bền vững.","k":"proponent"},{"t":"Monetize","d":"Để kiếm tiền từ","de":"To make money from","e":"She found a way to monetize her hobby.","ev":"Cô đã tìm ra cách kiếm tiền từ sở thích của mình.","k":"monetize"},{"t":"Installation","d":"Triển lãm nghệ thuật bao gồm các vật thể lớn được đặt trong không gian công cộng.","de":"Art exhibit consisting of large objects placed in a public space","e":"The installation drew crowds at the gallery.","ev":"Việc sắp đặt đã thu hút đám đông tại phòng trưng bày.","k":"installation"},{"t":"Validate","p":"(v.)","d":"Xác nhận, ủng hộ, chứng thực","de":"to confirm, support, corroborate","e":"Yoko’s chemistry lab partner was asleep during the experiment and could not validate the accuracy of her methods.","ev":"Đối tác trong phòng thí nghiệm hóa học của Yoko đã ngủ trong suốt cuộc thí nghiệm và không thể xác nhận tính chính xác của phương pháp của cô ấy.","k":"validate"},{"t":"Engender","p":"(v.)","d":"Tạo ra, hình thành, phát sinh","de":"to bring about, create, generate","e":"During the Olympics, the victories of U.S. athletes engender a patriotic spirit among Americans.","ev":"Trong Thế vận hội, chiến thắng của các vận động viên Hoa Kỳ đã khơi dậy tinh thần yêu nước của người Mỹ.","k":"engender"},{"t":"Underscore","d":"để nhấn mạnh tầm quan trọng của điều gì đó","de":"to emphasize the importance something","e":"He underscored the importance of education.","ev":"Ông nhấn mạnh tầm quan trọng của giáo dục.","k":"underscore"},{"t":"Tedious","p":"(adj.)","d":"buồn tẻ, nhàm chán","de":"dull, boring","e":"As time passed and the history professor continued to drone on and on, the lecture became increasingly tedious.","ev":"Thời gian trôi qua và giáo sư lịch sử tiếp tục lải nhải liên tục, bài giảng ngày càng trở nên tẻ nhạt.","k":"tedious"},{"t":"Confound","p":"verb","d":"làm cho bực bội, gây nhầm lẫn","de":"to frustrate, confuse","e":"MacGuyver confounded the policemen pursuing him by covering his tracks.","ev":"Anh đã làm cho cảnh sát bối rối và trốn thoát.","k":"confound"},{"t":"Outmoded","d":"Không còn hợp thời; lỗi mốt.","de":"No longer fashionable; out of date","e":"The design is considered outmoded by today's standards.","ev":"Thiết kế này được coi là lỗi thời so với tiêu chuẩn ngày nay.","k":"outmoded"},{"t":"Adamant","p":"adj","d":"không thể xuyên thủng, bất động, không lay chuyển","de":"impervious, immovable, unyielding","e":"She remained adamant about her decision to move forward with the project.","ev":"Cô kiên quyết về quyết định tiếp tục thực hiện dự án.","k":"adamant"}]},{"n":"Ưu tiên 1 · 11","c":[{"t":"Arrest","d":"Ngăn chặn (không chỉ đơn thuần là còng tay tội phạm)","de":"To stop (not just put handcuffs on a criminal)","e":"The police arrested the spread of the disease with strict quarantine measures.","ev":"Cảnh sát đã ngăn chặn sự lây lan của dịch bệnh bằng các biện pháp cách ly nghiêm ngặt.","x":"Ví dụ 2: second meaning","k":"arrest"},{"t":"Tally","d":"(n.) Một bản ghi chép; tổng số; (v.) Đếm","de":"(n.) A recorded account; a total; (v.) To count","e":"She kept a tally of all the expenses.","ev":"Cô ấy giữ một bản kiểm kê tất cả các chi phí.","k":"tally"},{"t":"Circumvent","p":"verb","d":"để di chuyển,","de":"to get around, lách","e":"She tried to circumvent the rules.","ev":"Cô ấy cố gắng lách luật.","k":"circumvent"},{"t":"Nuance","p":"noun","d":"một chút khác biệt về ý nghĩa, giọng điệu, cách diễn đạt","de":"a slight variation in meaning, tone, expression","e":"The nuances of her expression revealed her true feelings about the situation.","ev":"Những sắc thái trong biểu cảm của cô ấy tiết lộ cảm xúc thật sự của cô về tình huống.","k":"nuance"},{"t":"Stipulate","d":"Yêu cầu hoặc chỉ định như một phần của thỏa thuận.","de":"To demand or specify as part of an agreement","e":"The contract stipulated that payments must be made on time.","ev":"Hợp đồng quy định rằng việc thanh toán phải được thực hiện đúng thời hạn.","k":"stipulate"},{"t":"Facility","d":"Khả năng thực hiện một việc gì đó một cách dễ dàng (ví dụ: khả năng học ngoại ngữ)","de":"Ability to do something easily (e.g., a facility for learning languages)","e":"The new sports facility is state-of-the-art.","ev":"Cơ sở thể thao mới là hiện đại.","x":"Ví dụ 2: second meaning","k":"facility"},{"t":"Copious","p":"adj","d":"dồi dào, phong phú","de":"profuse, abundant","e":"The researcher took copious notes during the lecture to ensure she didn't miss any details.","ev":"Nhà nghiên cứu đã ghi chép rất nhiều trong suốt bài giảng để đảm bảo không bỏ lỡ chi tiết nào.","k":"copious"},{"t":"Peripheral","p":"noun","d":"Ít quan trọng hơn","de":"Less important","e":"The peripheral devices were not functioning correctly with the computer.","ev":"Các thiết bị ngoại vi đã không hoạt động chính xác với máy tính.","k":"peripheral"},{"t":"Provocative","d":"Gây ra phản ứng, thường là sự khó chịu hoặc tức giận.","de":"Causing a reaction, often annoyance or anger","e":"His provocative remarks sparked a heated debate.","ev":"Lời nhận xét đầy khiêu khích của ông đã làm dấy lên một cuộc tranh luận sôi nổi.","k":"provocative"},{"t":"Scheme","d":"Một kế hoạch khéo léo và thường đầy mưu mẹo.","de":"A clever and often devious plan","e":"He devised a scheme to win the contest.","ev":"Anh ta nghĩ ra một kế hoạch để giành chiến thắng trong cuộc thi.","k":"scheme"},{"t":"Preclude","p":"verb","d":"để ngăn chặn","de":"to prevent","e":"His lack of experience does not preclude him from applying for the job.","ev":"Thiếu kinh nghiệm của anh không ngăn cản anh nộp đơn xin việc.","k":"preclude"},{"t":"Synchronize","d":"Gây ra nhiều sự kiện xảy ra cùng một lúc","de":"To cause multiple events to occur at the same time","e":"The dancers synchronized their movements perfectly.","ev":"Các vũ công đã đồng bộ hóa các động tác của họ một cách hoàn hảo.","k":"synchronize"},{"t":"Register","d":"Để ghi lại, thể hiện hoặc diễn đạt điều gì đó","de":"to record, show, or express something","e":"Her face registered disapproval","ev":"Vẻ mặt cô tỏ vẻ không hài lòng","k":"register"},{"t":"Nurture","p":"(v.)","d":"để hỗ trợ sự phát triển của","de":"to assist the development of","e":"Although Serena had never watered the plant, which was about to die, Javier was able to nurture it back to life.","ev":"Mặc dù Serena chưa bao giờ tưới nước cho cái cây sắp chết nhưng Javier vẫn có thể nuôi dưỡng nó sống lại.","k":"nurture"},{"t":"Hobble","d":"Ngăn chặn cản trở","de":"Prevent impede","e":"A long list of amendments have hobbled the new legislation.","ev":"Một danh sách dài các sửa đổi đã cản trở luật mới.","x":"Ví dụ 2: second meaning","k":"hobble"},{"t":"Incongruous","d":"Không phù hợp; điều gì đó trái ngược với môi trường xung quanh.","de":"Out of place; something that contrasts with its surroundings","e":"His casual attire was incongruous with the formal event.","ev":"Trang phục giản dị của anh ấy không phù hợp với sự kiện trang trọng.","k":"incongruous"},{"t":"Transcend","d":"Vượt lên trên những giới hạn thông thường","de":"To rise above normal limitations","e":"Her work transcends traditional boundaries.","ev":"Công việc của cô vượt qua ranh giới truyền thống.","k":"transcend"},{"t":"Mundane","p":"(adj.)","d":"quan tâm đến thế gian hơn là thiên đường, tầm thường.","de":"concerned with the world rather than with heaven, commonplace","e":"He is more concerned with the mundane issues of day-to-day life than with spiritual topics.","ev":"Ông quan tâm đến những vấn đề trần tục của cuộc sống hàng ngày hơn là những chủ đề tâm linh.","k":"mundane"},{"t":"Grapple With","d":"Khó khăn trong việc giải quyết hoặc hiểu một điều gì đó","de":"To struggle to deal with or understand something","e":"The philosopher grappled with the complex ethical implications of artificial intelligence.","ev":"Nhà triết học vật lộn với những tác động đạo đức phức tạp của trí tuệ nhân tạo.","x":"Ví dụ 2: Think about","k":"grapple with"},{"t":"Disposition","d":"Tính cách hoặc đặc điểm bẩm sinh","de":"Inherent personality or character trait","e":"She has a sunny disposition that brightens everyone's day.","ev":"Cô ấy có tính cách vui vẻ, có thể làm bừng sáng cả ngày của mọi người.","x":"Ví dụ 2: general","k":"disposition"},{"t":"Predatory","d":"Lợi dụng người khác","de":"Preying upon others","e":"The predatory animal stalked its prey.","ev":"Động vật săn mồi rình rập con mồi.","k":"predatory"},{"t":"Contrive","d":"Nghĩ ra, xoay xở, trù tính","de":"To think up, xoay xở, trù tính","e":"The prisoners contrived a way to escape.","ev":"Các tù nhân tìm cách trốn thoát.","k":"contrive"},{"t":"Intermediate","d":"Đứng giữa hai thứ","de":"Coming between two things","e":"This course is for intermediate learners.","ev":"Khóa học này dành cho người học ở trình độ trung cấp.","k":"intermediate"},{"t":"Manifestation","d":"Hình thức bên ngoài có thể nhìn thấy của một vật thể, xu hướng hoặc ý tưởng.","de":"Visible appearance of an object, trend, or idea","e":"The sculpture was a manifestation of his creativity.","ev":"Tác phẩm điêu khắc là sự thể hiện sự sáng tạo của ông.","k":"manifestation"},{"t":"Orientation","d":"Sự ưa thích hoặc thiên hướng","de":"A preference or liking for","e":"She has an orientation towards creative work.","ev":"Cô ấy có định hướng về công việc sáng tạo.","k":"orientation"}]},{"n":"Ưu tiên 1 · 12","c":[{"t":"Elusive","p":"adj","d":"Khó tìm, bắt hoặc khó đạt được, khó nắm bắt","de":"Difficult to find, catch, or achieve, khó nắm bắt","e":"Her thoughts were elusive, hard to pin down.","ev":"Những suy nghĩ của cô ấy rất khó nắm bắt.","k":"elusive"},{"t":"Watershed","d":"Một bước ngoặt","de":"A turning point","e":"The new policy marked a watershed moment in their history.","ev":"Chính sách mới đã đánh dấu một bước ngoặt trong lịch sử của họ.","k":"watershed"},{"t":"Eccentric","d":"không phổ biến, lạ lùng","de":"uncommon, strange","e":"His eccentric behavior often made him the center of attention, but also made it difficult to maintain friendships.","ev":"Hành vi lập dị của anh thường khiến anh trở thành trung tâm của sự chú ý nhưng cũng gây khó khăn cho việc duy trì tình bạn.","k":"eccentric"},{"t":"Consumption","p":"noun","d":"hành động tiêu thụ","de":"the act of consuming","e":"Consumption of intoxicating beverages is not permitted on these premises.","ev":"Việc uống rượu bị cấm trong khu vực này.","k":"consumption"},{"t":"Coin","d":"Sáng tạo ra (ví dụ: đặt ra một cụm từ mới)","de":"To invent (e.g., coin a phrase)","e":"He coined the term \"user interface.\"","ev":"Ông đặt ra thuật ngữ \"giao diện người dùng\".","x":"Ví dụ 2: second meaning","k":"coin"},{"t":"Antithetical","d":"Đặc trưng bởi sự tương phản cực độ,","de":"Characterized by extreme contrast,","e":"Their views are antithetical to each other.","ev":"Quan điểm của họ trái ngược nhau.","k":"antithetical"},{"t":"Exposure","d":"Tiếp xúc với ai đó hoặc điều gì đó (dạng danh từ của \"expose\")","de":"Contact with someone or something (noun form of \"expose\")","e":"The media exposure helped the company gain recognition.","ev":"Việc xuất hiện trên các phương tiện truyền thông đã giúp công ty được công nhận.","k":"exposure"},{"t":"Doctor","d":"Để can thiệp vào","de":"To tamper with","e":"The hacker doctored the data to support their theory.","ev":"Hacker đã chỉnh sửa dữ liệu để hỗ trợ lý thuyết của họ.","x":"Ví dụ 2: second meaning","k":"doctor"},{"t":"Supplement","d":"(n.) Sự bổ sung hoặc củng cố; (v.) Thêm vào","de":"(n.) An addition or reinforcement; (v.) To add on","e":"He took a vitamin supplement daily.","ev":"Anh ấy uống bổ sung vitamin hàng ngày.","k":"supplement"},{"t":"Supplant","p":"verb","d":"Thay thế; vượt trội hơn","de":"To replace; supersede","e":"They hoped to supplant the old technology with something more efficient.","ev":"Họ hy vọng thay thế công nghệ cũ bằng một cái gì đó hiệu quả hơn.","k":"supplant"},{"t":"Ineluctable","d":"Không thể tránh khỏi; không thể tránh khỏi","de":"Inescapable; inevitable","e":"The passage of time is ineluctable.","ev":"Thời gian trôi qua là điều không thể tránh khỏi.","k":"ineluctable"},{"t":"Relevant/Irrelevant","d":"Có liên quan/không liên quan đến chủ đề đang thảo luận","de":"Connected/unconnected to the topic at hand","e":"The example was relevant to the discussion.","ev":"Ví dụ có liên quan đến cuộc thảo luận.","k":"relevant/irrelevant"},{"t":"Uniform","d":"Hằng số, không thay đổi","de":"Constant, unvarying","e":"The laws for adopting a child are not uniform among the states.","ev":"Luật nhận con nuôi không thống nhất giữa các bang.","x":"Ví dụ 2: second meaning","k":"uniform"},{"t":"Afford","d":"Cấp (ví dụ: một cơ hội)","de":"Grant (e.g., an opportunity)","e":"The new law will afford protection to employees.","ev":"Luật mới sẽ đủ khả năng bảo vệ người lao động.","x":"Ví dụ 2: second meaning","k":"afford"},{"t":"Concede","p":"(v.)","d":"chấp nhận là hợp lệ, thừa nhận","de":"to accept as valid, thừa nhận","e":"Andrew had to concede that what his mother said about Diana made sense.","ev":"Andrew phải thừa nhận rằng những gì mẹ anh nói về Diana đều có lý.","k":"concede"},{"t":"Ephemeral","p":"adj","d":"Ngắn ngủi, thoáng qua","de":"short-lived, fleeting","e":"The beauty of the sunset was ephemeral.","ev":"Vẻ đẹp của hoàng hôn thật ngắn ngủi.","k":"ephemeral"},{"t":"Reservations","d":"Sự nghi ngờ = lo ngại","de":"Misgivings = doubt","e":"I have some reservations about the plan.","ev":"Tôi có một số bảo lưu về kế hoạch này.","x":"Ví dụ 2: second meaning","k":"reservations"}]},{"n":"Ưu tiên 2 · 1","c":[{"t":"Delusional","d":"Có những niềm tin hoặc quan điểm sai lầm hoặc không thực tế.","de":"Having false or unrealistic beliefs or opinions.","e":"He was delusional in thinking he could win the lottery without buying a ticket.","ev":"Anh ta bị ảo tưởng khi nghĩ rằng mình có thể trúng số mà không cần mua vé.","k":"delusional"},{"t":"incredulous, \nincredulity","p":"noun","d":"không tin,\nsự hoài nghi","de":"không tin, \nsự hoài nghi","e":"He was incredulous when he heard the news.","ev":"Anh ta tỏ ra hoài nghi khi nghe tin tức.","k":"incredulous, incredulity"},{"t":"Venerate","p":"(v.)","d":"tôn trọng, tôn kính, sùng kính","de":"to regard with respect or to honor, tôn kính, sùng kính","e":"The tribute to John Lennon sought to venerate his music, his words, and his legend.","ev":"Việc tưởng nhớ John Lennon nhằm tôn vinh âm nhạc, lời nói và huyền thoại của ông.","k":"venerate"},{"t":"Denounce","p":"(v.)","d":"chỉ trích công khai","de":"to criticize publicly","e":"The senator denounced her opponent as a greedy politician.","ev":"Thượng nghị sĩ tố cáo đối thủ của bà là một chính trị gia tham lam.","k":"denounce"},{"t":"Skeptically","d":"Với sự nghi ngờ hoặc do dự.","de":"With doubt or hesitation.","e":"He looked at the proposal skeptically, unsure of its feasibility.","ev":"Anh ta nhìn đề xuất này một cách hoài nghi, không chắc chắn về tính khả thi của nó.","k":"skeptically"},{"t":"melancholy","p":"adjective/noun","d":"u","de":"u sầu","e":"A sense of melancholy hung over the town after the festival ended.","ev":"Một cảm giác u buồn bao trùm thị trấn sau khi lễ hội kết thúc.","k":"melancholy"},{"t":"Discount","d":"Quyết định rằng điều gì đó hoặc ai đó không đáng để xem xét hoặc chú ý. Không để ý, coi nhẹ","de":"To decide that something or someone is not worth considering or giving attention. Không để ý, coi nhẹ","e":"She discounted his opinion because of his lack of experience.","ev":"Cô ấy bác bỏ ý kiến ​​​​của anh ấy vì anh ấy thiếu kinh nghiệm.","k":"discount"},{"t":"divergent","p":"adj","d":"khác nhau","de":"khác nhau","e":"Their divergent opinions led to a heated discussion.","ev":"Ý kiến khác nhau của họ đã dẫn đến một cuộc thảo luận sôi nổi.","k":"divergent"},{"t":"Contrivance","p":"/kənˈtraɪ.vəns/","d":"Một thứ được tạo ra một cách khéo léo và sáng tạo để phục vụ một mục đích cụ thể; việc sử dụng kỹ năng để tạo ra một thứ gì đó hoặc mang lại một kết quả. 1. Dụng cụ thông minh 2. Sự sắp đặt, trù tính","de":"A thing that is created skillfully and inventively to serve a particular purpose; the use of skill to create something or bring about an outcome. 1. Dụng cụ thông minh 2. Sự sắp đặt, trù tính","e":"The story was full of plot contrivances that strained credibility.","ev":"Câu chuyện chứa đầy những tình tiết phức tạp làm giảm uy tín.","k":"contrivance"},{"t":"unwarranted","d":"Thiếu lý do chính đáng; không cần thiết","de":"lacking a good reason; unnecessary","e":"They denounced the investigation as an unwarranted interference with their business.","ev":"Họ tố cáo cuộc điều tra là sự can thiệp không chính đáng vào hoạt động kinh doanh của họ.","k":"unwarranted"},{"t":"Equivocal","p":"adjective","d":"không rõ ràng, không chắc chắn, chưa quyết định","de":"ambiguous, uncertain, undecided","e":"His equivocal response left everyone unsure about his true intentions.","ev":"Phản ứng không rõ ràng của anh ấy khiến mọi người không chắc chắn về ý định thực sự của anh.","k":"equivocal"},{"t":"empiric(al)","p":"adjective","d":"thực nghiệm(al)","de":"thực nghiệm(al)","e":"The research is based on empirical evidence gathered from experiments.","ev":"Nghiên cứu này dựa trên bằng chứng thực nghiệm thu thập từ các cuộc thí nghiệm.","k":"empiric(al)"},{"t":"Supersede","d":"Thay thế (người hoặc vật trước đây có thẩm quyền hoặc được sử dụng); thế chỗ.","de":"To take the place of (a person or thing previously in authority or use); supplant.","e":"The new policy will supersede the old one starting next month.","ev":"Chính sách mới sẽ thay thế chính sách cũ bắt đầu từ tháng tới.","k":"supersede"},{"t":"profound, \nprofundity","p":"adjective/noun","d":"sâu, \n(kỳ tích)","de":"sâu, \nsự sâu sắc","e":"Her profound insights into human nature were well-received by the audience.","ev":"Những hiểu biết sâu sắc của cô về bản chất con người đã được khán giả đón nhận nồng nhiệt.","k":"profound, profundity"},{"t":"Contemptuously","d":"Một cách khinh miệt thể hiện sự khinh thường.","de":"In a scornful way that shows disdain. khinh khỉnh","e":"She glanced contemptuously at the messy room.","ev":"Cô khinh thường liếc nhìn căn phòng bừa bộn.","k":"contemptuously"},{"t":"Capitalize On","d":"Tận dụng một tình huống hoặc cơ hội cụ thể.","de":"To take advantage of a particular situation or opportunity.","e":"The company capitalized on the growing demand for electric cars.","ev":"Công ty tận dụng nhu cầu ngày càng tăng về ô tô điện.","k":"capitalize on"},{"t":"Intimate","d":"Quen biết thân thiết; quen thuộc, gần gũi; riêng tư và cá nhân.","de":"Closely acquainted; familiar, close; private and personal.","e":"They shared an intimate conversation about their future plans.","ev":"Họ đã trò chuyện thân mật về kế hoạch tương lai của mình.","k":"intimate"},{"t":"Pivotal","d":"Điều này vô cùng quan trọng đối với sự phát triển hoặc thành công của một điều gì đó khác.","de":"Of crucial importance in relation to the development or success of something else.","e":"The invention of the internet was a pivotal moment in human history.","ev":"Việc phát minh ra Internet là một thời điểm quan trọng trong lịch sử loài người.","k":"pivotal"},{"t":"Amplify","d":"Làm cho âm thanh to hơn hoặc mạnh hơn; tăng kích thước hoặc tác động của một चीज nào đó.","de":"To make something louder or stronger; to increase the size or effect of something.","e":"The musician used a microphone to amplify his voice during the concert.","ev":"Nhạc sĩ đã sử dụng micro để khuếch đại giọng hát của mình trong buổi hòa nhạc.","k":"amplify"},{"t":"Extraneous","p":"(adj.)","d":"không liên quan, thừa thãi, không cần thiết","de":"irrelevant, extra, not necessary","e":"Personal political ambitions should always remain extraneous to legislative policy, but, unfortunately, they rarely are.","ev":"Tham vọng chính trị cá nhân luôn luôn không liên quan đến chính sách lập pháp, nhưng thật không may, chúng hiếm khi như vậy.","k":"extraneous"},{"t":"Contingent On","d":"Tùy thuộc vào yếu tố ngẫu nhiên; chỉ xảy ra hoặc tồn tại nếu (những điều kiện nhất định) xảy ra; phụ thuộc vào.","de":"Subject to chance; occurring or existing only if (certain circumstances) are the case; dependent on.","e":"The success of the project is contingent on securing adequate funding.","ev":"Sự thành công của dự án phụ thuộc vào việc đảm bảo đủ nguồn vốn.","k":"contingent on"},{"t":"Heterotrophic","d":"(Sinh học) Sinh vật lấy chất dinh dưỡng từ các hợp chất hữu cơ phức tạp.","de":"(Biology) An organism deriving its nutritional requirements from complex organic substances. Dị dưỡng","e":"Humans are heterotrophic organisms, relying on other organisms for food.","ev":"Con người là sinh vật dị dưỡng, sống dựa vào sinh vật khác để có thức ăn.","k":"heterotrophic"},{"t":"Unyielding","d":"Không khuất phục trước áp lực; cứng rắn hoặc vững chắc; khó bị lay chuyển; kiên quyết.","de":"Not giving way to pressure; hard or solid; unlikely to be swayed; resolute.","e":"She remained unyielding in her opposition to the plan.","ev":"Cô vẫn kiên quyết phản đối kế hoạch này.","k":"unyielding"},{"t":"Inexplicable","d":"Không thể giải thích hay lý giải được.","de":"Unable to be explained or accounted for.","e":"The sudden disappearance of the files was inexplicable.","ev":"Sự biến mất đột ngột của các tập tin là không thể giải thích được.","k":"inexplicable"},{"t":"Pugnacious","p":"(adj.)","d":"hay gây gổ","de":"quarrelsome, hay gây gổ","e":"Aaron’s pugnacious nature led him to start several barroom brawls each month.","ev":"Bản tính hiếu chiến của Aaron đã khiến anh ta bắt đầu nhiều cuộc ẩu đả trong quán bar mỗi tháng.","k":"pugnacious"}]},{"n":"Ưu tiên 2 · 2","c":[{"t":"Inadvertent","d":"Không phải kết quả hoặc đạt được thông qua kế hoạch có chủ đích; không cố ý.","de":"Not resulting from or achieved through deliberate planning; unintentional.","e":"An inadvertent error caused the data loss.","ev":"Một lỗi vô ý gây ra mất dữ liệu.","k":"inadvertent"},{"t":"Propagate","p":"(v.)","d":"nhân lên, lan rộng","de":"to multiply, spread out","e":"Rumors of Paul McCartney’s demise propagated like wildfire throughout the world.","ev":"Tin đồn về cái chết của Paul McCartney lan truyền như cháy rừng khắp thế giới.","k":"propagate"},{"t":"Corollary","d":"một điều gì đó phát sinh từ một điều khác.","de":"something that results from something else","e":"Unfortunately, violence is the inevitable corollary of such a revolutionary change in society.","ev":"Thật không may, bạo lực là hệ quả tất yếu của một sự thay đổi mang tính cách mạng như vậy trong xã hội.","x":"Ví dụ 2: general","k":"corollary"},{"t":"Elide","d":"Bỏ qua âm thanh của một phần từ khi phát âm.","de":"To leave out the sound of part of a word when you are pronouncing it.","e":"In casual speech, people often elide the 't' in 'often'.","ev":"Trong cách nói thông thường, người ta thường bỏ chữ 't' trong 'thường'.","x":"Nghĩa 2: to ignore a difference between things\nVí dụ 2: By eliding the distinction, you are being sloppy and weakening your argument.","k":"elide"},{"t":"Reverential","d":"Có bản chất, do, hoặc đặc trưng bởi sự tôn kính.","de":"Of the nature of, due to, or characterized by reverence.","e":"He spoke in a reverential tone about his mentor.","ev":"Anh ấy nói với giọng tôn kính về người thầy của mình.","k":"reverential"},{"t":"Notional","d":"(Tính từ) Chỉ tồn tại trên lý thuyết hoặc dưới dạng gợi ý hay ý tưởng; tưởng tượng.","de":"(adjective) Existing only in theory or as a suggestion or idea; imaginary.","e":"The notional value of the company's assets was much higher than their actual market value.","ev":"Giá trị danh nghĩa của tài sản công ty cao hơn nhiều so với giá trị thị trường thực tế của chúng.","k":"notional"},{"t":"Restive","p":"(adj.)","d":"chống cự, bướng bỉnh, thiếu kiên nhẫn, không yên, khó bảo","de":"resistant, stubborn, impatient, không yên, khó bảo","e":"The restive audience pelted the band with mud and yelled nasty comments.","ev":"Những khán giả phản kháng đã ném bùn vào ban nhạc và hét lên những bình luận khó chịu.","k":"restive"},{"t":"Vacillating","d":"Dao động giữa các ý kiến ​​hoặc hành động khác nhau; thiếu quyết đoán.","de":"Wavering between different opinions or actions; irresolute.","e":"His vacillating stance on the issue confused his supporters.","ev":"Lập trường bỏ trống của ông về vấn đề này khiến những người ủng hộ ông bối rối.","k":"vacillating"},{"t":"Tentative","d":"Chưa được xác nhận, có thể thay đổi.","de":"unconfirmed, subject to change","e":"The agreement was tentative and could be changed, as both parties were still negotiating the terms.","ev":"Thỏa thuận này chỉ là dự kiến ​​và có thể thay đổi vì cả hai bên vẫn đang đàm phán các điều khoản.","k":"tentative"},{"t":"Disinterested","d":"Không bị ảnh hưởng bởi những cân nhắc về lợi ích cá nhân; không có hoặc không cảm thấy quan tâm đến điều gì đó. Không vụ lợi","de":"Not influenced by considerations of personal advantage; having or feeling no interest in something. Không vụ lợi","e":"A disinterested third party mediated the dispute.","ev":"Một bên thứ ba không có lợi ích đã đứng ra hòa giải tranh chấp.","k":"disinterested"},{"t":"Longitudinal Study","d":"Thiết kế nghiên cứu bao gồm việc quan sát lặp đi lặp lại cùng một biến số trong thời gian dài.","de":"A research design that involves repeated observations of the same variables over long periods of time.","e":"The longitudinal study tracked participants' health over two decades.","ev":"Nghiên cứu theo chiều dọc theo dõi sức khỏe của người tham gia trong hơn hai thập kỷ.","k":"longitudinal study"},{"t":"stately","d":"Có phong thái trang trọng, điềm đạm và oai phong; oai vệ trong cử chỉ và diện mạo.","de":"having a dignified, unhurried, and grand manner; majestic in manner and appearance.","e":"a stately sight to behold","ev":"một cảnh tượng trang nghiêm để chiêm ngưỡng","k":"stately"},{"t":"Irrefutable","d":"Không thể phủ nhận hay bác bỏ.","de":"Impossible to deny or disprove.","e":"The evidence presented in court was irrefutable.","ev":"Những bằng chứng được đưa ra trước tòa là không thể chối cãi.","k":"irrefutable"},{"t":"Misanthropic","d":"(Tính từ) Ghét bỏ loài người và tránh giao tiếp với xã hội loài người.","de":"(adjective) Disliking humankind and avoiding human society.","e":"His misanthropic views made it difficult for him to maintain friendships.","ev":"Quan điểm lệch lạc của anh ấy khiến anh ấy khó duy trì tình bạn.","k":"misanthropic"},{"t":"Demarcated","d":"(động từ) Đặt ra ranh giới hoặc giới hạn của; tách biệt hoặc phân biệt khỏi. Phân ranh giới","de":"(verb) Set the boundaries or limits of; separated or distinguished from. Phân ranh giới","e":"The property was demarcated by a white fence.","ev":"Khu đất được phân giới bằng hàng rào màu trắng.","k":"demarcated"},{"t":"Precede","d":"Có trước (một चीज) về thời gian; có trước về thứ tự hoặc vị trí.","de":"To come before (something) in time; to come before in order or position.","e":"A brief introduction preceded the main presentation.","ev":"Phần giới thiệu ngắn gọn trước phần trình bày chính.","k":"precede"},{"t":"Meager","p":"(adj.)","d":"thiếu về kích thước hoặc chất lượng","de":"deficient in size or quality","e":"My meager portion of food did nothing to satisfy my appetite.","ev":"Phần thức ăn ít ỏi của tôi không làm thỏa mãn cơn thèm ăn của tôi.","k":"meager"},{"t":"Outlier","d":"Một người hoặc một vật khác biệt so với tất cả các thành viên khác trong một nhóm hoặc tập hợp cụ thể.","de":"A person or thing differing from all other members of a particular group or set.","e":"In the data set, there was one outlier that skewed the results.","ev":"Trong tập dữ liệu, có một ngoại lệ làm sai lệch kết quả.","k":"outlier"},{"t":"Regard","d":"Xem xét hoặc nghĩ về (ai đó hoặc điều gì đó) theo một cách cụ thể; chú ý hoặc quan tâm đến điều gì đó.","de":"To consider or think of (someone or something) in a specified way; attention to or concern for something.","e":"He is highly regarded by his colleagues.","ev":"Anh được đồng nghiệp đánh giá cao.","k":"regard"},{"t":"Placate","p":"verb","d":"để xoa dịu cơn giận, làm dịu đi","de":"to ease the anger of, soothe","e":"She offered a small gift to placate her friend after their argument.","ev":"Cô đã tặng một món quà nhỏ để xoa dịu người bạn của mình sau cuộc tranh cãi.","k":"placate"},{"t":"Malign","d":"nói xấu vu vu","de":"say bad things about, vu khống","e":"She was known to malign her enemies, spreading rumors and lies about them to ruin their reputations.","ev":"Cô nổi tiếng là hay nói xấu kẻ thù của mình, tung tin đồn và dối trá về họ để hủy hoại danh tiếng của họ.","k":"malign"},{"t":"Nonsensical","d":"Không có ý nghĩa; vô nghĩa.","de":"Having no meaning; making no sense.","e":"The explanation was nonsensical and confused everyone.","ev":"Lời giải thích thật vô lý và khiến mọi người bối rối.","k":"nonsensical"},{"t":"Intercede In","d":"Can thiệp thay mặt người khác.","de":"To intervene on behalf of another.","e":"She interceded in the argument to help resolve it.","ev":"Cô ấy đã can thiệp vào cuộc tranh luận để giúp giải quyết nó.","k":"intercede in"},{"t":"Invaluable","d":"Không tìm thấy định nghĩa nào.","de":"No def found","e":"No example found","ev":"Không tìm thấy ví dụ nào","x":"Ví dụ 2: not negative","k":"invaluable"},{"t":"In Turn","d":"Liên tiếp nhau; lần lượt từng cái một; là kết quả của một chuỗi sự kiện nào đó.","de":"In succession; one after the other; as a result of something in a series of events.","e":"She spoke to each of the guests in turn.","ev":"Cô lần lượt nói chuyện với từng vị khách.","k":"in turn"}]},{"n":"Ưu tiên 2 · 3","c":[{"t":"Promulgate","p":"(v.)","d":"tuyên bố, phổ biến, ban hành, truyền bá","de":"to proclaim, make known, ban hành, truyền bá","e":"The film professor promulgated that both in terms of sex appeal and political intrigue, Sean Connery’s James Bond was superior to Roger Moore’s.","ev":"Giáo sư điện ảnh tuyên bố rằng cả về độ hấp dẫn giới tính lẫn mưu đồ chính trị, James Bond của Sean Connery đều vượt trội hơn của Roger Moore.","k":"promulgate"},{"t":"immaterial","d":"không liên quan","de":"irrelevant","e":"the source of a claim is immaterial: it has no direct bearing on whether the claim is true.","ev":"nguồn của một tuyên bố là không quan trọng: nó không ảnh hưởng trực tiếp đến việc tuyên bố đó có đúng hay không.","k":"immaterial"},{"t":"Protractor","d":"Một dụng cụ dùng để đo góc, thường có dạng một nửa hình tròn phẳng được đánh dấu bằng độ.","de":"An instrument for measuring angles, typically in the form of a flat semicircle marked with degrees.","e":"In geometry class, we used a protractor to measure angles.","ev":"Trong lớp hình học, chúng em dùng thước đo góc để đo góc.","k":"protractor"},{"t":"Deferential","p":"(adj.)","d":"thể hiện sự tôn trọng đối với quyền lực của người khác, tôn kính","de":"showing respect for another’s authority, tôn kính","e":"His deferential attitude toward her made her more confident in her ability to run the company.","ev":"Thái độ tôn trọng của anh đối với cô khiến cô tự tin hơn vào khả năng điều hành công ty của mình.","k":"deferential"},{"t":"Impugn","d":"Thể hiện sự nghi ngờ về tính trung thực, lòng dũng cảm, khả năng, v.v. của ai đó.","de":"To express doubts about someone's honesty, courage, ability, etc. nghi ngờ, công kích","e":"The lawyer impugned the witness's credibility during cross-examination.","ev":"Luật sư đã nghi ngờ độ tin cậy của nhân chứng trong quá trình thẩm vấn chéo.","k":"impugn"},{"t":"Tangible","d":"có thật và có thể được trưng bày hoặc chạm vào, hữu hình","de":"real and able to be shown or touched, hữu hình","e":"The benefits of the program were tangible and measurable, improving the lives of countless people.","ev":"Lợi ích của chương trình là hữu hình và có thể đo lường được, giúp cải thiện cuộc sống của vô số người.","k":"tangible"},{"t":"Apprise","d":"thông báo","de":"inform","e":"Please apprise me of any updates to the project timeline.","ev":"Vui lòng thông báo cho tôi về bất kỳ cập nhật nào về dòng thời gian của dự án.","k":"apprise"},{"t":"Proclivity","p":"(n.)","d":"một khuynh hướng mạnh mẽ đối với điều gì đó","de":"a strong inclination toward something","e":"In a sick twist of fate, Harold’s childhood proclivity for torturing small animals grew into a desire to become a surgeon.","ev":"Trong một vòng xoay bệnh hoạn của số phận, thiên hướng tra tấn động vật nhỏ thời thơ ấu của Harold đã phát triển thành mong muốn trở thành bác sĩ phẫu thuật.","k":"proclivity"},{"t":"Uncompromising","d":"Thể hiện sự không sẵn lòng nhượng bộ người khác, đặc biệt là bằng cách thay đổi cách làm hoặc quan điểm của bản thân.","de":"Showing an unwillingness to make concessions to others, especially by changing one's ways or opinions.","e":"His uncompromising stance made negotiations difficult.","ev":"Lập trường không khoan nhượng của ông khiến các cuộc đàm phán trở nên khó khăn.","k":"uncompromising"},{"t":"Forestall","p":"(v.)","d":"ngăn chặn, cản trở, trì hoãn, ngăn chặn trước đó","de":"to prevent, thwart, delay, chặn trước","e":"I forestalled the cold I was getting by taking plenty of vitamin C pills and wearing a scarf.","ev":"Tôi đã ngăn ngừa cảm lạnh bằng cách uống nhiều viên vitamin C và quàng khăn quàng cổ.","k":"forestall"},{"t":"Attrition","d":"(danh từ) Quá trình làm suy yếu dần sức mạnh hoặc hiệu quả của ai đó hoặc điều gì đó thông qua sự tấn công hoặc áp lực liên tục. Tiêu hao,","de":"(noun) The process of gradually reducing the strength or effectiveness of someone or something through sustained attack or pressure. Tiêu hao,","e":"Attrition War","ev":"Chiến tranh tiêu hao","x":"Nghĩa 2: a reduction in the number of people who work for an organization that is achieved by not replacing those people who leave, or ppl leave course before it finishes.","k":"attrition"},{"t":"Disseminate","p":"verb","d":"lan rộng","de":"to spread widely","e":"The organization aims to disseminate information about health and wellness.","ev":"Tổ chức này nhằm mục đích truyền bá thông tin về sức khỏe và sự lành mạnh.","k":"disseminate"},{"t":"Mandatory","d":"(Tính từ) Được yêu cầu bởi luật pháp hoặc quy định; bắt buộc.","de":"(adjective) Required by law or rules; compulsory.","e":"Attendance at the meeting is mandatory for all staff members.","ev":"Việc tham dự cuộc họp là bắt buộc đối với tất cả nhân viên.","k":"mandatory"},{"t":"Jettison","d":"Ném hoặc thả (một vật gì đó) từ máy bay hoặc tàu thủy; bỏ rơi hoặc vứt bỏ (ai đó hoặc vật gì đó không còn cần thiết nữa).","de":"To throw or drop (something) from an aircraft or ship; to abandon or discard (someone or something that is no longer wanted).","e":"The crew had to jettison excess cargo to lighten the ship.","ev":"Thủy thủ đoàn đã phải vứt bớt hàng hóa dư thừa để làm nhẹ tàu.","k":"jettison"},{"t":"Behold","d":"Nhìn thấy hoặc quan sát (một vật hoặc người, đặc biệt là một vật hoặc người đáng chú ý hoặc gây ấn tượng).","de":"To see or observe (a thing or person, especially a remarkable or impressive one).","e":"The sunset was a sight to behold.","ev":"Hoàng hôn là một cảnh tượng đáng chú ý.","k":"behold"},{"t":"Litany","d":"(danh từ) Một loạt các lời thỉnh cầu dùng trong các buổi lễ nhà thờ; một bài tụng dài dòng hoặc một chuỗi lặp đi lặp lại nhàm chán.","de":"(noun) A series of petitions for use in church services; a tedious recital or repetitive series.","e":"She recited a litany of complaints about the service.","ev":"Cô kể lại một loạt lời phàn nàn về dịch vụ.","k":"litany"},{"t":"Repository","p":"/rɪˈpɑːzətɔːri/","d":"Nơi hoặc vật chứa dùng để lưu trữ hoặc có thể lưu trữ đồ vật.","de":"A place where or receptacle in which things are or may be stored.","e":"The library serves as a repository of historical documents.","ev":"Thư viện phục vụ như một kho lưu trữ các tài liệu lịch sử.","k":"repository"},{"t":"Exclusive To","d":"Chỉ áp dụng cho một cá nhân, nhóm hoặc khu vực cụ thể.","de":"Limited to a particular person, group, or area.","e":"This offer is exclusive to our premium members.","ev":"Ưu đãi này chỉ dành riêng cho các thành viên cao cấp của chúng tôi.","k":"exclusive to"},{"t":"Comprehensive","p":"(adj.)","d":"bao gồm tất cả mọi thứ","de":"including everything","e":"She sent me a comprehensive list of the ingredients needed to cook rabbit soufflé.","ev":"Cô ấy gửi cho tôi một danh sách đầy đủ các nguyên liệu cần thiết để nấu món soufflé thỏ.","k":"comprehensive"},{"t":"Endure","d":"tiếp tục tồn tại trong thời gian dài","de":"to continue to exist for a long time","e":"The political system established in 1400 endured until about 1650.","ev":"Hệ thống chính trị được thành lập năm 1400 tồn tại cho đến khoảng năm 1650.","k":"endure"},{"t":"A Profusion Of","d":"Sự dư dả hoặc số lượng lớn của một thứ gì đó.","de":"An abundance or large quantity of something.","e":"The garden boasts a profusion of flowers in spring.","ev":"Khu vườn có rất nhiều hoa vào mùa xuân.","k":"a profusion of"},{"t":"Dismiss","d":"Quyết định rằng điều gì đó hoặc ai đó không quan trọng và không đáng để xem xét.","de":"To decide that something or someone is not important and not worth considering.","e":"The manager dismissed the proposal as impractical.","ev":"Người quản lý bác bỏ đề xuất này vì cho rằng nó không thực tế.","k":"dismiss"},{"t":"Compound","p":"(v.)","d":"Làm cho vấn đề hoặc tình huống khó khăn trở nên tồi tệ hơn.","de":"to make a problem or difficult situation worse","e":"His financial problems were compounded when he unexpectedly lost his job.","ev":"Vấn đề tài chính của anh càng trở nên phức tạp khi anh bất ngờ bị mất việc.","x":"Loại từ 2: (n.)\nNghĩa 2: a combination of different parts\nVí dụ 2: My attraction to Donna was a compound of curiosity about the unknown, physical desire, and intellectual admiration.\nLoại từ 3: (n.)\nNghĩa 3: a walled area containing a group of buildings\nVí dụ 3: When the fighting started, Joseph rushed into the family compound because it was safe and well defended.","k":"compound"},{"t":"Ongoing","d":"Đang tiếp diễn; vẫn đang trong quá trình thực hiện.","de":"Continuing; still in progress.","e":"The investigation is ongoing and no conclusions have been reached yet.","ev":"Cuộc điều tra đang diễn ra và chưa có kết luận nào được đưa ra.","k":"ongoing"},{"t":"Salient","p":"(adj.)","d":"đáng kể, nổi bật","de":"significant, conspicuous","e":"One of the salient differences between Alison and Nancy is that Alison is a foot taller.","ev":"Một trong những điểm khác biệt nổi bật giữa Alison và Nancy là Alison cao hơn một foot.","k":"salient"}]},{"n":"Ưu tiên 2 · 4","c":[{"t":"Recollect","d":"Nhớ lại (điều gì đó); gợi nhớ.","de":"To remember (something); call to mind.","e":"I can still recollect the day we first met.","ev":"Tôi vẫn có thể nhớ lại ngày đầu tiên chúng tôi gặp nhau.","k":"recollect"},{"t":"Propitiate","d":"Làm sao để ngăn ai đó nổi giận bằng cách cố gắng làm hài lòng họ.","de":"To stop somebody from being angry by trying to please them. Làm nguôi","e":"They offered sacrifices to propitiate the gods.","ev":"Họ dâng lễ vật để cầu xin các vị thần.","k":"propitiate"},{"t":"Unnerved","d":"(Tính từ) Làm cho cảm thấy lo lắng hoặc khó chịu.","de":"(adjective) Made to feel nervous or upset.","e":"He was unnerved by the sudden change in plans.","ev":"Anh ấy cảm thấy lo lắng trước sự thay đổi đột ngột trong kế hoạch.","k":"unnerved"},{"t":"Mediocre","d":"Chất lượng chỉ ở mức trung bình; không tốt lắm.","de":"Of only average quality; not very good.","e":"The movie received mediocre reviews from critics.","ev":"Bộ phim nhận được đánh giá tầm thường từ các nhà phê bình.","k":"mediocre"},{"t":"Equalize","d":"Làm cho số lượng, kích thước hoặc mức độ giống nhau ở khắp một địa điểm hoặc nhóm.","de":"To make the same in quantity, size, or degree throughout a place or group.","e":"The new law aims to equalize opportunities for all citizens.","ev":"Luật mới nhằm mục đích bình đẳng hóa cơ hội cho mọi công dân.","k":"equalize"},{"t":"Assent","d":"(danh từ) Sự bày tỏ sự tán thành hoặc đồng ý; (động từ) Bày tỏ sự tán thành hoặc đồng ý.","de":"(noun) The expression of approval or agreement; (verb) To express approval or agreement.","e":"The board gave its assent to the proposed changes.","ev":"Hội đồng đã đồng ý với những thay đổi được đề xuất.","k":"assent"},{"t":"Penchant","p":"noun","d":"khuynh hướng, thiên vị, sự ưu tiên","de":"a tendency, partiality, preference","e":"He had a penchant for collecting rare coins from around the world.","ev":"Anh có sở thích sưu tầm những đồng tiền hiếm từ khắp nơi trên thế giới.","k":"penchant"},{"t":"Counteract","p":"verb","d":"vô hiệu hóa, làm cho không hiệu quả, trung hòa","de":"to neutralize, make ineffective, trung hòa","e":"The antidote counteracted the effect of the poison.","ev":"Thuốc giải độc đã làm mất tác dụng của chất độc.","k":"counteract"},{"t":"Sanction","d":"(danh từ) Hình phạt đe dọa đối với hành vi vi phạm luật hoặc quy tắc; (động từ) Cho phép hoặc chấp thuận chính thức (một hành động).","de":"(noun) A threatened penalty for disobeying a law or rule; (verb) To give official permission or approval for (an action).","e":"The government imposed sanctions on the country for its actions.","ev":"Chính phủ đã áp đặt các biện pháp trừng phạt đối với đất nước vì hành động của mình.","k":"sanction"},{"t":"Magnify","d":"Làm cho vật gì đó trông lớn hơn kích thước thật của nó, đặc biệt là khi nhìn qua ống kính.","de":"To make something look larger than it is, especially by looking at it through a lens.","e":"The scientist used a microscope to magnify the cells for closer examination.","ev":"Nhà khoa học đã sử dụng kính hiển vi để phóng to các tế bào để kiểm tra kỹ hơn.","k":"magnify"},{"t":"Integrate","d":"Kết hợp (một thứ) với thứ khác để tạo thành một chỉnh thể; đưa (những người hoặc nhóm người có đặc điểm hoặc nhu cầu riêng) vào sự tham gia bình đẳng hoặc trở thành thành viên của một nhóm xã hội hoặc tổ chức.","de":"To combine (one thing) with another to form a whole; to bring (people or groups with particular characteristics or needs) into equal participation in or membership of a social group or institution.","e":"The new policy aims to integrate immigrants into the community.","ev":"Chính sách mới nhằm mục đích hòa nhập người nhập cư vào cộng đồng.","k":"integrate"},{"t":"Omit","d":"Không bao gồm hoặc không thực hiện điều gì đó.","de":"To fail to include or do something.","e":"She omitted to inform the authorities of their visit. He modestly omits to mention that he was pole-vault champion","ev":"Cô ấy đã bỏ qua việc thông báo cho chính quyền về chuyến thăm của họ. Anh khiêm tốn không đề cập đến việc mình là nhà vô địch nhảy sào","k":"omit"},{"t":"A Paucity Of","d":"Sự khan hiếm hoặc thiếu hụt một thứ gì đó.","de":"A scarcity or lack of something.","e":"There is a paucity of information on the subject.","ev":"Có rất ít thông tin về chủ đề này.","k":"a paucity of"},{"t":"Circumscribe","p":"verb","d":"Hạn chế quyền lực, quyền lợi hoặc hoạt động của ai đó hoặc điều gì đó.","de":"to limit the power, rights, or activities of someone or something","e":"The regulations circumscribe the activities of the organization to ensure compliance.","ev":"Các quy định giới hạn hoạt động của tổ chức để đảm bảo tuân thủ.","k":"circumscribe"},{"t":"Discretion","p":"(n.)","d":"phẩm chất dè dặt trong lời nói hoặc hành động; dè dặt","de":"the quality of being reserved in speech or action; thận trọng","e":"Not wanting her patient to get overly anxious, the doctor used discretion in deciding how much to tell the patient about his condition.","ev":"Không muốn bệnh nhân của mình lo lắng quá mức, bác sĩ đã thận trọng quyết định nên nói với bệnh nhân bao nhiêu về tình trạng của mình.","k":"discretion"},{"t":"Constrict","d":"Làm cho thứ gì đó trở nên hẹp hơn hoặc chặt hơn, hoặc trở nên hẹp hơn hoặc chặt hơn.","de":"To make something narrower or tighter, or to become narrower or tighter.","e":"The snake constricted its prey before swallowing it.","ev":"Con rắn siết chặt con mồi trước khi nuốt chửng.","k":"constrict"},{"t":"Yield","d":"1) tạo ra hoặc sinh ra (một kết quả) 2) đầu hàng","de":"1) to produce or generate (a result) 2) to surrender","e":"She refused to yield to his demands, standing her ground and refusing to compromise.","ev":"Cô không chịu khuất phục trước những yêu cầu của anh, giữ vững lập trường và không chịu thỏa hiệp.","k":"yield"},{"t":"Recurrent","d":"Xảy ra thường xuyên hoặc lặp đi lặp lại.","de":"Occurring often or repeatedly.","e":"She suffered from recurrent headaches.","ev":"Cô bị chứng đau đầu tái phát.","k":"recurrent"},{"t":"That Said","d":"Dùng để đưa ra một ý kiến ​​làm giảm bớt sức thuyết phục của những gì bạn vừa nói. Mặc dù vậy, điều đó không thể phủ nhận những gì người kia vừa nói.","de":"Used to introduce an opinion that makes what you have just said seem less strong. Despite what one just said.","e":"The job is challenging. That said, I enjoy the work.","ev":"Công việc đầy thử thách. Điều đó nói rằng, tôi thích công việc.","k":"that said"},{"t":"Palliate","p":"(v.)","d":"để giảm mức độ nghiêm trọng của","de":"to reduce the severity of","e":"The doctor trusted that the new medication would palliate her patient’s discomfort.","ev":"Bác sĩ tin tưởng rằng loại thuốc mới sẽ làm giảm bớt sự khó chịu của bệnh nhân.","k":"palliate"},{"t":"Intransigent","p":"(adj.)","d":"Từ chối thỏa hiệp, thường là về một quan điểm cực đoan.","de":"refusing to compromise, often on an extreme opinion","e":"The intransigent child said he would have 12 scoops of ice cream, or he would bang his head against the wall until his mother fainted from fear.","ev":"Đứa trẻ không khoan nhượng cho biết sẽ ăn 12 muỗng kem hoặc sẽ đập đầu vào tường cho đến khi mẹ ngất đi vì sợ hãi.","k":"intransigent"},{"t":"Pristine","d":"Nguyên bản và tinh khiết; không bị hư hỏng hay hao mòn do sử dụng, ban sơ","de":"original and pure; not spoiled or worn from use, ban sơ","e":"The beach was pristine, with white sand and crystal-clear water.","ev":"Bãi biển còn hoang sơ với cát trắng và nước trong vắt.","k":"pristine"},{"t":"Daunting","p":"adjective","d":"Đáng sợ, khiến người ta mất can đảm.","de":"intimidating, causing one to lose courage","e":"He kept delaying the daunting act of asking for a promotion.","ev":"Anh cứ trì hoãn việc đáng sợ là yêu cầu thăng chức.","k":"daunting"},{"t":"Incongruous With","d":"Không hài hòa hoặc không phù hợp với môi trường xung quanh hoặc các khía cạnh khác của sự vật.","de":"Not in harmony or keeping with the surroundings or other aspects of something.","e":"His casual attire was incongruous with the formal event.","ev":"Trang phục giản dị của anh ấy không phù hợp với sự kiện trang trọng.","k":"incongruous with"},{"t":"Homogeneous","d":"Cùng loại; tương tự; bao gồm các bộ phận đều cùng loại.","de":"Of the same kind; alike; consisting of parts all of the same kind.","e":"The population of the small town was fairly homogeneous.","ev":"Dân số của thị trấn nhỏ khá đồng nhất.","k":"homogeneous"}]},{"n":"Ưu tiên 2 · 5","c":[{"t":"Banal","p":"verb","d":"buồn tẻ, tầm thường","de":"dull, commonplace","e":"The movie was criticized for its banal dialogue and predictable plot.","ev":"Bộ phim bị chỉ trích vì lời thoại tầm thường và cốt truyện dễ đoán.","k":"banal"},{"t":"Counterfactual","d":"(danh từ) Một tuyên bố hoặc giả thuyết trái ngược với các sự kiện hoặc sự thật đã biết; (tính từ) liên quan đến hoặc diễn tả những gì chưa xảy ra hoặc không đúng sự thật.","de":"(noun) A statement or hypothesis that contradicts known facts or events; (adjective) relating to or expressing what has not happened or is not the case.","e":"The historian presented a counterfactual scenario where the war had never occurred. Counterfactual thinking: tư duy phản thực tế (what if...)","ev":"Nhà sử học đã đưa ra một kịch bản phản thực tế trong đó chiến tranh chưa bao giờ xảy ra. Tư duy phản thực tế: tư duy phản thực tế (nếu...)","k":"counterfactual"},{"t":"Spectacle","d":"Một màn trình diễn hoặc trưng bày gây ấn tượng mạnh về mặt thị giác; một sự kiện hoặc cảnh tượng được đánh giá dựa trên tác động trực quan của nó.","de":"A visually striking performance or display; an event or scene regarded in terms of its visual impact.","e":"The fireworks were a magnificent spectacle.","ev":"Pháo hoa là một cảnh tượng tuyệt vời.","k":"spectacle"},{"t":"belie","p":"verb","d":"tạo ra ấn tượng sai lệch về","de":"to give a false impression of","e":"His calm demeanor belies the chaos within.","ev":"Vẻ điềm tĩnh của anh ta che giấu sự hỗn loạn bên trong.","k":"belie"},{"t":"Expostulate","d":"(verb) Diễn tả sự không tán thành hoặc không đồng tình mạnh mẽ, phản đối đừng làm","de":"(verb) To express strong disapproval or disagreement, phản đối đừng làm","e":"He expostulated with his friend about the risks of the plan.","ev":"Anh ấy đã giải thích với bạn mình về những rủi ro của kế hoạch.","k":"expostulate"},{"t":"Inconsequential","d":"Không quan trọng hoặc không đáng kể.","de":"Not important or significant.","e":"The error was inconsequential and did not affect the outcome.","ev":"Lỗi này không nghiêm trọng và không ảnh hưởng đến kết quả.","k":"inconsequential"},{"t":"Repudiate","p":"verb","d":"từ chối","de":"reject","e":"The politician chose to repudiate the rumors about his involvement in the scandal.","ev":"Chính trị gia đã chọn bác bỏ những tin đồn về sự tham gia của mình vào vụ bê bối.","k":"repudiate"},{"t":"Unscrupulous","d":"Không có hoặc không thể hiện nguyên tắc đạo đức; không trung thực hoặc không công bằng.","de":"Having or showing no moral principles; not honest or fair.","e":"The unscrupulous salesman lied about the car's history.","ev":"Người bán hàng vô đạo đức đã nói dối về lịch sử của chiếc xe.","k":"unscrupulous"},{"t":"Propriety","p":"(n.)","d":"phẩm chất hoặc trạng thái đúng đắn, đoan trang, lịch sự","de":"the quality or state of being proper, decent, khuôn phép","e":"Erma’s old-fashioned parents believed that her mini-skirt lacked the propriety expected of a “nice” girl.","ev":"Cha mẹ cổ hủ của Erma tin rằng chiếc váy ngắn của cô thiếu sự đứng đắn như mong đợi của một cô gái “ngoan”.","k":"propriety"},{"t":"Unflattering","d":"Không hay ho; không thuận lợi.","de":"Not flattering; not favorable.","e":"The article gave an unflattering portrayal of the politician.","ev":"Bài báo đã miêu tả không mấy hay ho về chính trị gia này.","k":"unflattering"},{"t":"Ostentatious","p":"(adj.)","d":"phô trương quá mức, tài khoản","de":"excessively showy, phô trương","e":"On the palace tour, the guide focused on the ostentatious decorations and spoke little of the royal family’s history.","ev":"Trong chuyến tham quan cung điện, hướng dẫn viên tập trung vào cách trang trí phô trương và nói rất ít về lịch sử của gia đình hoàng gia.","k":"ostentatious"},{"t":"Discrepancy","p":"(n.)","d":"sự khác biệt, sự không tương ứng","de":"difference, failure of things to correspond","e":"He was troubled by the discrepancy between what he remembered paying for the appliance and what his receipt showed he paid for it.","ev":"Anh ấy gặp rắc rối vì sự khác biệt giữa số tiền anh ấy nhớ đã trả cho thiết bị và số tiền trên biên lai cho thấy anh ấy đã trả tiền cho nó.","k":"discrepancy"},{"t":"Recalcitrant","p":"adj","d":"thách thức, không hối lỗi, cứng đầu","de":"defiant, unapologetic, cứng đầu","e":"The recalcitrant student refused to comply with the school rules.","ev":"Học sinh cứng đầu đã từ chối tuân thủ các quy định của trường.","k":"recalcitrant"},{"t":"To That End","d":"Như một cách để giải quyết hoặc thực hiện điều gì đó; vì lý do đó. Nguyên nhân - kết quả","de":"As a way of dealing with or doing something; for that reason. Cause effect","e":"We need to cut costs; to that end, we are implementing a hiring freeze.","ev":"Chúng ta cần cắt giảm chi phí; vì mục đích đó, chúng tôi đang thực hiện việc đình chỉ tuyển dụng.","k":"to that end"},{"t":"Disingenuous","p":"adj","d":"Không thẳng thắn hay chân thành, thường bằng cách giả vờ rằng mình biết ít hơn về một vấn đề nào đó so với thực tế.","de":"Not candid or sincere, typically by pretending that one knows less about something than one really does.","e":"Her disingenuous smile made me suspicious.","ev":"Nụ cười không chân thật của cô ấy khiến tôi nghi ngờ.","k":"disingenuous"},{"t":"Intractable","p":"(adj.)","d":"khó thao tác, khó kiểm soát","de":"difficult to manipulate, unmanageable","e":"There was no end in sight to the intractable conflict between the warring countries.","ev":"Cuộc xung đột dai dẳng giữa các quốc gia tham chiến chưa có hồi kết.","k":"intractable"},{"t":"Presage","p":"(n.)","d":"một điềm báo","de":"an omen","e":"When my uncle’s old war injury ached, he interpreted it as a presage of bad weather approaching.","ev":"Khi vết thương chiến tranh cũ của chú tôi nhức nhối, ông giải thích đó là điềm báo thời tiết xấu đang đến gần.","k":"presage"},{"t":"Desultory","d":"(tính từ) Thiếu kế hoạch, mục đích hoặc nhiệt huyết; xảy ra một cách ngẫu nhiên hoặc thỉnh thoảng. Lung tung, rời khỏi cuộc đua","de":"(adjective) Lacking a plan, purpose, or enthusiasm; occurring randomly or occasionally. Lung tung, rời rạc","e":"Their desultory conversation wandered from topic to topic.","ev":"Cuộc trò chuyện rời rạc của họ lang thang từ chủ đề này sang chủ đề khác.","k":"desultory"},{"t":"Disparage","p":"verb","d":"chỉ trích hoặc nói xấu, chê bai","de":"to criticize or speak ill of, chê bai","e":"She disparaged his work, claiming it lacked originality.","ev":"Cô đã coi thường công việc của anh, cho rằng nó thiếu tính sáng tạo.","k":"disparage"},{"t":"Solicit","d":"Xin hoặc cố gắng lấy (thứ gì đó) từ ai đó.","de":"To ask for or try to obtain (something) from someone.","e":"They solicited donations for the charity event.","ev":"Họ kêu gọi quyên góp cho sự kiện từ thiện.","k":"solicit"},{"t":"Unanimous","d":"Hoàn toàn nhất trí; đồng lòng.","de":"Fully in agreement; of one mind.","e":"The committee reached a unanimous decision on the proposal.","ev":"Ủy ban đã đạt được quyết định nhất trí về đề xuất này.","k":"unanimous"},{"t":"Supposition","d":"một ý tưởng mà bạn tin rằng có thể đúng, giả thiết","de":"an idea that you believe might be true, giả thiết","e":"His supposition was correct.","ev":"Giả định của ông đã đúng.","k":"supposition"},{"t":"Brood Over","d":"Suy nghĩ sâu sắc về điều gì đó khiến mình không vui.","de":"To think deeply about something that makes one unhappy.","e":"He brooded over the mistakes he had made.","ev":"Anh trăn trở về những lỗi lầm mình đã mắc phải.","k":"brood over"},{"t":"Subvert","d":"Làm tổn hại hoặc làm suy yếu quyền lực của một hệ thống đã được thiết lập.","de":"to damage or weaken the authority of an established system","e":"The rebels attempted to subvert the government, overthrowing the existing regime.","ev":"Phiến quân âm mưu lật đổ chính quyền, lật đổ chế độ hiện tại.","k":"subvert"},{"t":"Absurd","d":"vô lý hoặc hoàn toàn không hợp lý","de":"ridiculous or completely unreasonable","e":"The idea of flying cars was absurd, seeming impossible and ridiculous.","ev":"Ý tưởng về ô tô bay thật vô lý, dường như không thể thực hiện được và buồn cười.","k":"absurd"}]},{"n":"Ưu tiên 2 · 6","c":[{"t":"Ascribe","p":"verb","d":"chỉ định, ghi công, quy cho","de":"to assign, credit, attribute to","e":"Many ascribe the invention of dynamite to Alfred Nobel.","ev":"Nhiều người cho rằng việc phát minh ra thuốc nổ là của Alfred Nobel.","k":"ascribe"},{"t":"Deficient","d":"Không có đủ thứ gì đó, đặc biệt là thứ thiết yếu.","de":"not having enough of something, especially something that is essential","e":"a diet that is deficient in vitamin A","ev":"chế độ ăn thiếu vitamin A","k":"deficient"},{"t":"Benign","p":"adj.","d":"Thuận lợi, không đe dọa, nhẹ nhàng","de":"favorable, not threatening, mild","e":"The tests determined her tumor was benign.","ev":"Các xét nghiệm đã xác định rằng khối u của cô là lành tính.","k":"benign"},{"t":"Permeate","p":"(v.) /ˈpɜːrmieɪt/","d":"lan rộng khắp nơi, bão hòa","de":"to spread throughout, saturate","e":"Mrs. Huxtable was annoyed that the wet dog’s odor had permeated the furniture’s upholstery.","ev":"Bà Huxtable khó chịu vì mùi chó ướt đã thấm vào vải bọc đồ nội thất.","k":"permeate"},{"t":"Possess","d":"Sở hữu; có (khả năng, phẩm chất hoặc đặc điểm).","de":"To have as belonging to one; own; to have (an ability, quality, or characteristic).","e":"She possesses a rare talent for music.","ev":"Cô sở hữu năng khiếu âm nhạc hiếm có.","k":"possess"},{"t":"Consequential","d":"Do đó, có tác động hoặc ảnh hưởng; quan trọng; đáng kể.","de":"Following as a result or effect; important; significant.","e":"The court's decision had consequential implications for the law.","ev":"Quyết định của tòa án có ý nghĩa quan trọng đối với pháp luật.","k":"consequential"},{"t":"Specious","p":"/ˈspiːʃəs/","d":"Bề ngoài thì có vẻ hợp lý nhưng thực ra lại sai; gây hiểu lầm về ngoại hình. Mã tốt, chỉ có bề ngoài.","de":"Superficially plausible, but actually wrong; misleading in appearance. Tốt mã, chỉ có bề ngoài.","e":"The argument was specious and lacked real evidence.","ev":"Lập luận này mang tính suy đoán và thiếu bằng chứng xác thực.","k":"specious"},{"t":"Concurrently","d":"(trạng từ) Đồng thời; cùng lúc.","de":"(adverb) At the same time; simultaneously.","e":"The two events will be held concurrently on different floors of the building.","ev":"Hai sự kiện sẽ được tổ chức đồng thời ở các tầng khác nhau của tòa nhà.","k":"concurrently"},{"t":"Unassuming","d":"khiêm tốn, giản dị","de":"humble, low-key","e":"She was an unassuming person who never boasted about her accomplishments, preferring to let her actions speak for themselves.","ev":"Cô ấy là một người khiêm tốn, không bao giờ khoe khoang về thành tích của mình, thích để hành động của mình tự nói lên điều đó.","k":"unassuming"},{"t":"Stymie","d":"Ngăn chặn hoặc cản trở sự tiến triển của...","de":"To prevent or hinder the progress of.","e":"The lack of funding stymied the research project.","ev":"Việc thiếu kinh phí đã cản trở dự án nghiên cứu.","k":"stymie"},{"t":"Profane","p":"(adj.)","d":"dâm dục, tục tĩu, báng bổ","de":"lewd, indecent, báng bổ","e":"Jacob’s profane act of dumping frogs in the holy water in the chapel at his boarding school resulted in his dismissal.","ev":"Hành động tục tĩu của Jacob là thả ếch vào nước thánh trong nhà nguyện ở trường nội trú của anh đã khiến anh bị đuổi việc.","k":"profane"},{"t":"Serenely","d":"Một cách bình tĩnh, ôn hòa và không hề lo lắng.","de":"In a calm, peaceful, and untroubled manner.","e":"She smiled serenely as she accepted the award.","ev":"Cô mỉm cười thanh thản khi nhận giải thưởng.","k":"serenely"},{"t":"Fallacy","p":"noun","d":"Một niềm tin sai lầm, đặc biệt là niềm tin dựa trên những lập luận không vững chắc.","de":"A mistaken belief, especially one based on unsound arguments.","e":"The fallacy of that statement is clear.","ev":"Sự sai lầm trong phát biểu đó là rõ ràng.","k":"fallacy"},{"t":"Obligate","d":"Khiến ai đó cảm thấy bị ép buộc về mặt đạo đức hoặc pháp lý phải làm điều gì đó.","de":"To make someone feel morally or legally forced to do something.","e":"The contract obligates the company to pay for all damages.","ev":"Hợp đồng bắt buộc công ty phải bồi thường mọi thiệt hại.","k":"obligate"},{"t":"Epitomize","d":"Để trở thành một ví dụ hoàn hảo.","de":"To be a perfect example of.","e":"She epitomizes elegance and grace.","ev":"Cô ấy là hình ảnh thu nhỏ của sự thanh lịch và duyên dáng.","k":"epitomize"},{"t":"Convoluted","p":"adjective","d":"phức tạp, rắc rối","de":"intricate, complicated","e":"Grace’s story was so convoluted that I couldn’t follow it.","ev":"Câu chuyện của Grace phức tạp đến mức tôi không thể theo kịp.","k":"convoluted"},{"t":"Oversee","d":"Giám sát (một người hoặc một công việc), đặc biệt là với tư cách chính thức.","de":"To supervise (a person or work), especially in an official capacity.","e":"She was appointed to oversee the project's development.","ev":"Cô được bổ nhiệm để giám sát sự phát triển của dự án.","k":"oversee"},{"t":"Analog","d":"Một người hoặc vật được xem là tương đồng với người hoặc vật khác; (trong lĩnh vực điện tử) một tín hiệu hoặc dữ liệu liên tục.","de":"A person or thing seen as comparable to another; (in electronics) a continuous signal or data.","e":"The human eye is an analog to a camera lens.","ev":"Mắt người là một cơ quan tương tự như ống kính máy ảnh.","k":"analog"},{"t":"Sanguine","p":"adjective","d":"lạc quan, vui vẻ","de":"optimistic, cheery","e":"Despite the challenges ahead, she remained sanguine about the future.","ev":"Dù đối mặt với những thử thách phía trước, cô vẫn lạc quan về tương lai.","k":"sanguine"},{"t":"Retroactive","d":"(Tính từ) Có hiệu lực từ một ngày trong quá khứ.","de":"(adjective) Taking effect from a date in the past.","e":"The new tax law is retroactive to January 1st, affecting all income earned since then.","ev":"Luật thuế mới có hiệu lực từ ngày 1 tháng 1, ảnh hưởng đến tất cả thu nhập kiếm được kể từ đó.","k":"retroactive"},{"t":"Indulgently","d":"Một cách quá rộng lượng hoặc khoan dung, bao dung, nuông chiều","de":"In a manner that is overly generous or lenient, bao dung, nuông chiều","e":"The grandparents treated their grandchildren indulgently.","ev":"Ông bà đối xử với cháu rất mực ân cần.","k":"indulgently"},{"t":"Propensity","p":"noun","d":"khuynh hướng, sở thích","de":"an inclination, preference","e":"He has a propensity for taking risks that often leads to unexpected outcomes.","ev":"Anh có xu hướng mạo hiểm, điều này thường dẫn đến những kết quả bất ngờ.","k":"propensity"},{"t":"Discern","p":"(v.)","d":"nhận thức, phát hiện","de":"to perceive, detect","e":"Though he hid his emotions, she discerned from his body language that he was angry.","ev":"Mặc dù anh che giấu cảm xúc của mình nhưng cô nhận ra từ ngôn ngữ cơ thể của anh rằng anh đang tức giận.","k":"discern"},{"t":"Harbinger","d":"Một người hoặc một vật nào đó báo hiệu điều gì đó sắp xảy ra, đặc biệt là điều xấu.","de":"A person or thing that shows that something is going to happen soon, especially something bad.","e":"The sudden drop in temperature was a harbinger of the approaching storm.","ev":"Nhiệt độ giảm đột ngột là điềm báo cơn bão đang đến gần.","k":"harbinger"},{"t":"Ruminate On","d":"Suy nghĩ sâu sắc về một vấn đề nào đó.","de":"To think deeply about something.","e":"He ruminated on the implications of the decision.","ev":"Anh ngẫm nghĩ về ý nghĩa của quyết định này.","k":"ruminate on"}]},{"n":"Ưu tiên 2 · 7","c":[{"t":"Extricate","p":"verb","d":"để gỡ rối","de":"to disentangle","e":"She managed to extricate herself from the difficult situation with grace.","ev":"Cô đã thành công trong việc thoát khỏi tình huống khó khăn một cách duyên dáng.","k":"extricate"},{"t":"Breadth","d":"Khoảng cách hoặc phép đo từ bên này sang bên kia; chiều rộng; phạm vi hoặc mức độ rộng lớn.","de":"The distance or measurement from side to side; width; wide range or extent.","e":"The breadth of his knowledge is impressive.","ev":"Bề rộng kiến ​​​​thức của anh ấy thật ấn tượng.","k":"breadth"},{"t":"Protract","d":"Làm cho thứ gì đó tồn tại lâu dài hoặc tồn tại lâu hơn mức cần thiết.","de":"To make something last for a long time or last longer than necessary.","e":"They protracted the negotiations to gain more time.","ev":"Họ kéo dài cuộc đàm phán để có thêm thời gian.","k":"protract"},{"t":"Installment","d":"(danh từ) Một trong nhiều phần mà khoản nợ hoặc khoản tiền phải trả được chia thành, để thanh toán vào các thời điểm cố định liên tiếp.","de":"(noun) One of several parts into which a debt or other sum payable is divided, to be paid at successive fixed times.","e":"She paid for the car in monthly installments over two years.","ev":"Cô trả góp chiếc xe hàng tháng trong vòng hai năm.","k":"installment"},{"t":"Reverberate","d":"để tiếp tục được lắng nghe; để vang vọng nhiều lần","de":"to continue to be heard; to echo repeatedly","e":"The sound of the explosion reverberated through the valley.","ev":"Âm thanh của vụ nổ vang vọng khắp thung lũng.","k":"reverberate"},{"t":"Invalidate","d":"Làm cho (một lập luận, tuyên bố hoặc lý thuyết) trở nên không hợp lý hoặc sai lầm; tước bỏ hiệu lực pháp lý của (một văn bản hoặc thủ tục chính thức) do vi phạm quy định hoặc luật pháp.","de":"To make (an argument, statement, or theory) unsound or erroneous; to deprive (an official document or procedure) of legal efficacy because of contravention of a regulation or law.","e":"The discovery of new evidence invalidated the previous theory.","ev":"Việc phát hiện ra bằng chứng mới đã vô hiệu hóa lý thuyết trước đó.","k":"invalidate"},{"t":"Have No Bearing On","d":"Không có liên quan hoặc ảnh hưởng gì đến điều gì đó.","de":"To have no relevance or influence on something.","e":"His past mistakes have no bearing on his current performance.","ev":"Những sai lầm trong quá khứ không ảnh hưởng gì đến phong độ hiện tại của anh ấy.","k":"have no bearing on"},{"t":"Wreak Havoc On","d":"Gây ra thiệt hại hoặc tổn thương lớn.","de":"To cause a large amount of damage or harm.","e":"The storm wreaked havoc on the coastal towns.","ev":"Cơn bão tàn phá các thị trấn ven biển.","k":"wreak havoc on"},{"t":"Rectify","d":"Sửa chữa (điều gì đó); cho đúng.","de":"To put (something) right; correct.","e":"The technician rectified the problem with the computer.","ev":"Kỹ thuật viên đã khắc phục sự cố với máy tính.","k":"rectify"},{"t":"Imperfect","d":"Không hoàn hảo; có lỗi hoặc không đầy đủ.","de":"Not perfect; faulty or incomplete.","e":"The system is still imperfect and requires further testing.","ev":"Hệ thống vẫn chưa hoàn hảo và cần được thử nghiệm thêm.","k":"imperfect"},{"t":"Intrinsic To","d":"Thuộc về một cách tự nhiên; thiết yếu.","de":"Belonging naturally; essential.","e":"Creativity is intrinsic to the artistic process.","ev":"Sáng tạo là bản chất của quá trình nghệ thuật.","k":"intrinsic to"},{"t":"Convene","p":"verb","d":"triệu tập","de":"to call together","e":"Jason convened his entire extended family for a discussion.","ev":"Jason đã triệu tập cả gia đình để thảo luận.","k":"convene"},{"t":"Dictate","d":"Nói hoặc đọc to điều gì đó để người khác ghi chép lại hoặc máy ghi âm; tuyên bố hoặc ra lệnh một cách có thẩm quyền.","de":"To say or read aloud something to be written down by a person or recorded by a machine; to state or order authoritatively.","e":"The general dictated a letter to his secretary.","ev":"Vị tướng viết một lá thư cho thư ký của mình.","k":"dictate"},{"t":"Candor","p":"(n.)","d":"sự trung thực, thẳng thắn","de":"honesty, frankness","e":"We were surprised by the candor of the mayor’s speech because he is usually rather evasive.","ev":"Chúng tôi rất ngạc nhiên trước sự thẳng thắn trong bài phát biểu của thị trưởng vì ông ấy thường khá lảng tránh.","k":"candor"},{"t":"Denigrate","p":"noun","d":"Làm giảm nhẹ, hạ thấp ý kiến ​​của ai đó","de":"to belittle, diminish the opinion of","e":"It's unfair to denigrate someone's work without understanding their effort.","ev":"Thật không công bằng khi hạ thấp công việc của ai đó mà không hiểu được nỗ lực của họ.","k":"denigrate"},{"t":"Irresolvable","d":"Không thể giải quyết hoặc dàn xếp.","de":"Impossible to resolve or settle.","e":"The conflict between the two parties seemed irresolvable.","ev":"Mâu thuẫn giữa hai bên tưởng chừng như không thể giải quyết được.","k":"irresolvable"},{"t":"Unpalatable","d":"Vị không ngon; khó dung nạp hoặc chấp nhận.","de":"Not pleasant to taste; difficult to tolerate or accept.","e":"The truth can sometimes be unpalatable.","ev":"Sự thật đôi khi có thể khó chấp nhận.","k":"unpalatable"},{"t":"Dogmatic","p":"adj","d":"Tự tin một cách hung hăng và kiêu ngạo về những nguyên tắc chưa được chứng minh.","de":"aggressively and arrogantly certain about unproved principles","e":"His dogmatic beliefs often led to heated arguments with others.","ev":"Những niềm tin giáo điều của anh thường dẫn đến những cuộc tranh cãi gay gắt với người khác.","k":"dogmatic"},{"t":"Palatable","p":"(adj.)","d":"phù hợp với khẩu vị hoặc cảm nhận, ngon","de":"agreeable to the taste or sensibilities, ngon","e":"Despite the unpleasant smell, the exotic cheese was quite palatable.","ev":"Mặc dù có mùi khó chịu nhưng loại pho mát lạ này khá ngon miệng.","k":"palatable"},{"t":"Counter","d":"(động từ) Nói hoặc hành động trái ngược với; (danh từ) Một vật dụng dài, mặt phẳng ở phía trên, thường được đặt trong cửa hàng hoặc ngân hàng, nơi diễn ra các giao dịch với khách hàng.","de":"(verb) To speak or act in opposition to; (noun) A long flat-topped fixture in a store or bank across which business is conducted with customers.","e":"She countered his argument with solid evidence.","ev":"Cô phản bác lại lập luận của anh bằng bằng chứng chắc chắn.","k":"counter"},{"t":"Obviate The Need","d":"Loại bỏ nhu cầu hoặc khó khăn; làm cho điều gì đó trở nên không cần thiết.","de":"To remove a need or difficulty; to make something unnecessary.","e":"The new treatment obviates the need for surgery.","ev":"Phương pháp điều trị mới loại bỏ sự cần thiết phải phẫu thuật.","k":"obviate the need"},{"t":"Contemporaneous","p":"adjective","d":"tồn tại trong cùng một thời điểm","de":"existing during the same time","e":"Though her novels do not feature the themes of Romanticism, Jane Austen’s work was contemporaneous with that of Wordsworth and Byron.","ev":"Tác phẩm của Austen diễn ra trong cùng một thời kỳ văn học với các tác giả này.","k":"contemporaneous"},{"t":"Summation","d":"(danh từ) Quá trình cộng gộp các sự vật lại với nhau; bản tóm tắt các điểm hoặc sự kiện.","de":"(noun) The process of adding things together; a summary of points or facts.","e":"The lawyer's summation highlighted the key evidence presented during the trial.","ev":"Phần tóm tắt của luật sư nêu bật những bằng chứng quan trọng được đưa ra trong phiên tòa.","k":"summation"},{"t":"Earnest","d":"chân thành và nghiêm túc","de":"sincere and serious","e":"She was an earnest student who was always eager to learn.","ev":"Cô là một học sinh nghiêm túc và luôn ham học hỏi.","k":"earnest"},{"t":"Cliched","d":"Thể hiện sự thiếu sáng tạo; dựa trên việc lặp đi lặp lại các cụm từ hoặc ý kiến.","de":"Showing a lack of originality; based on frequently repeated phrases or opinions.","e":"He made some clichéd remark.","ev":"Anh ấy đã đưa ra một số nhận xét sáo rỗng.","k":"cliched"}]},{"n":"Ưu tiên 2 · 8","c":[{"t":"Inducement","d":"Một thứ thuyết phục hoặc tác động đến ai đó để họ làm điều gì đó.","de":"A thing that persuades or influences someone to do something. Khuyến khích.","e":"The company offered financial inducements to attract new employees.","ev":"Công ty đưa ra các khuyến khích tài chính để thu hút nhân viên mới.","k":"inducement"},{"t":"Divulge","p":"verb","d":"tiết lộ điều gì đó bí mật","de":"to reveal something secret","e":"He refused to divulge any details.","ev":"Anh ta từ chối tiết lộ bất kỳ chi tiết nào.","k":"divulge"},{"t":"Inextricable","p":"(adj.)","d":"rối rắm hoặc vướng víu không lối thoát","de":"hopelessly tangled or entangled","e":"Unless I look at the solution manual, I have no way of solving this inextricable problem.","ev":"Trừ khi tôi nhìn vào hướng dẫn giải pháp, tôi không có cách nào giải quyết vấn đề khó hiểu này.","k":"inextricable"},{"t":"Exhaustive","d":"Bao gồm hoặc xem xét tất cả các yếu tố hoặc khía cạnh; toàn diện đầy đủ.","de":"Including or considering all elements or aspects; fully comprehensive.","e":"The report provided an exhaustive analysis of the issue.","ev":"Báo cáo đã cung cấp một phân tích toàn diện về vấn đề này.","k":"exhaustive"},{"t":"Defunct","p":"(adj.)","d":"không còn được sử dụng hoặc tồn tại","de":"no longer used or existing","e":"They planned to turn the defunct schoolhouse into a community center.","ev":"Họ lên kế hoạch biến ngôi trường không còn tồn tại thành một trung tâm cộng đồng.","k":"defunct"},{"t":"Postulate","d":"để gợi ý hoặc đề xuất điều gì đó là đúng (đưa ra làm đề)","de":"to suggest or propose something to be true (đưa ra làm định đề)","e":"The theory postulated that the universe began with a Big Bang, a hypothesis that has been widely accepted by scientists.","ev":"Lý thuyết này cho rằng vũ trụ bắt đầu từ Vụ nổ lớn, một giả thuyết đã được các nhà khoa học chấp nhận rộng rãi.","k":"postulate"},{"t":"Austerity","d":"Điều kiện kinh tế khó khăn do các chính sách của chính phủ nhằm cắt giảm chi tiêu công gây ra.","de":"difficult economic conditions created by government policies aimed at cutting public spending.","e":"War was followed by many years of austerity.","ev":"Tiếp theo chiến tranh là nhiều năm thắt lưng buộc bụng.","x":"Nghĩa 2: the quality of being simple and plain\nVí dụ 2: the pleasing austerity of the design","k":"austerity"},{"t":"Initiator","d":"Người khởi xướng một sự việc nào đó.","de":"A person who causes something to begin.","e":"She was the initiator of the community outreach program.","ev":"Cô là người khởi xướng chương trình tiếp cận cộng đồng.","k":"initiator"},{"t":"Qualify","d":"Được hưởng một quyền lợi hoặc đặc quyền cụ thể bằng cách đáp ứng một điều kiện cần thiết; làm cho (một tuyên bố hoặc khẳng định) bớt tuyệt đối hơn; thêm các điều kiện bảo lưu.","de":"To be entitled to a particular benefit or privilege by fulfilling a necessary condition; to make (a statement or assertion) less absolute; add reservations to.","e":"She qualified for the scholarship based on her academic achievements.","ev":"Cô đủ điều kiện nhận học bổng dựa trên thành tích học tập của mình.","k":"qualify"},{"t":"Incongruity","d":"Trạng thái không phù hợp; không tương thích.","de":"The state of being incongruous; incompatibility.","e":"The incongruity between his words and actions was evident.","ev":"Sự mâu thuẫn giữa lời nói và hành động của anh đã lộ rõ.","k":"incongruity"},{"t":"Trait","d":"Một phẩm chất hoặc đặc điểm nổi bật, thường là đặc điểm thuộc về một người.","de":"A distinguishing quality or characteristic, typically one belonging to a person.","e":"Patience is an essential trait for a teacher.","ev":"Kiên nhẫn là một đức tính cần thiết của một giáo viên.","k":"trait"},{"t":"Assuage","p":"verb","d":"làm dịu, xoa dịu","de":"to ease, pacify","e":"She tried to assuage his fears about the upcoming exam.","ev":"Cô cố gắng làm dịu nỗi lo lắng của anh về kỳ thi sắp tới.","k":"assuage"},{"t":"Putatively","d":"(trạng từ) Nói chung được coi là hoặc được cho là.","de":"(adverb) Generally considered or reputed to be.","e":"The putative father of the child was called in for questioning.","ev":"Người cha giả định của đứa trẻ đã được gọi đến để thẩm vấn.","k":"putatively"},{"t":"Conflate","d":"(động từ) Kết hợp (hai hoặc nhiều văn bản, ý tưởng, v.v.) thành một.","de":"(verb) To combine (two or more texts, ideas, etc.) into one.","e":"The editor conflated the two stories into a single narrative.","ev":"Người biên tập đã gộp hai câu chuyện thành một câu chuyện duy nhất.","k":"conflate"},{"t":"Rehabilitation","p":"n.","d":"Quá trình khôi phục lại trạng thái tốt (của một người, một tòa nhà)","de":"the process of returning to a good condition (a person, building)","e":"the rehabilitation of derelict buildings","ev":"việc phục hồi các tòa nhà bỏ hoang","k":"rehabilitation"},{"t":"Transpose","d":"Làm cho (hai hoặc nhiều vật) đổi chỗ cho nhau; chuyển đến một vị trí hoặc bối cảnh khác.","de":"To cause (two or more things) to change places with each other; to transfer to a different place or context.","e":"The editor transposed the paragraphs to improve the flow of the article.","ev":"Người biên tập đã chuyển đổi các đoạn văn để cải thiện tính trôi chảy của bài viết.","k":"transpose"},{"t":"Insular","p":"(adj.)","d":"chỉ quan tâm đến đất nước, ý tưởng, v.v. của riêng bạn và không quan tâm đến những thứ từ bên ngoài,","de":"only interested in your own country, ideas, etc. and not in those from outside, hẹp hòi thiển cận","e":"The British are often accused of being insular.","ev":"Người Anh thường bị buộc tội là thiển cận.","x":"Nghĩa 2: having little contact with other people\nVí dụ 2: people living restricted and sometimes insular existences","k":"insular"},{"t":"Subside","d":"(động từ) Trở nên bớt dữ dội, bạo lực hoặc nghiêm trọng; giảm bớt.","de":"(verb) To become less intense, violent, or severe; to abate.","e":"After the storm, the winds subsided, and the sea became calm.","ev":"Sau cơn bão, gió dịu dần và biển trở nên yên tĩnh.","k":"subside"},{"t":"Reverentially","d":"Với lòng kính trọng sâu sắc hoặc sự ngưỡng mộ.","de":"With deep respect or awe.","e":"The students listened reverentially to the professor's lecture.","ev":"Các sinh viên chăm chú lắng nghe bài giảng của giáo sư.","k":"reverentially"},{"t":"Verify","d":"Để đảm bảo hoặc chứng minh rằng (điều gì đó) là đúng, chính xác hoặc có căn cứ.","de":"To make sure or demonstrate that (something) is true, accurate, or justified.","e":"The results were verified by independent experts.","ev":"Kết quả đã được xác nhận bởi các chuyên gia độc lập.","k":"verify"},{"t":"Nullify","d":"Làm cho vô hiệu về mặt pháp lý; hủy bỏ.","de":"To make legally null and void; invalidate.","e":"The court's decision nullified the previous ruling.","ev":"Quyết định của tòa án đã vô hiệu hóa phán quyết trước đó.","k":"nullify"},{"t":"Nonplus","p":"v.","d":"Làm cho (ai đó) ngạc nhiên và bối rối đến mức họ không biết phải phản ứng như thế nào.","de":"surprise and confuse (someone) so much that they are unsure how to react.","e":"Diane was nonplussed by such an odd question","ev":"Diane bối rối trước một câu hỏi kỳ lạ như vậy","k":"nonplus"},{"t":"Counterbalance","d":"Một trọng lượng cân bằng với một trọng lượng khác; một lực hoặc tác động làm giảm bớt hoặc kiềm chế một lực đối lập.","de":"A weight that balances another weight; a force or influence that offsets or checks an opposing force.","e":"The benefits of the policy counterbalance its costs.","ev":"Lợi ích của chính sách sẽ cân bằng chi phí của nó.","k":"counterbalance"},{"t":"Reprehensible","p":"adj","d":"đáng khiển trách, đáng quở trách","de":"deserving rebuke, đáng quở trách","e":"His reprehensible actions during the crisis drew widespread condemnation.","ev":"Hành động đáng lên án của anh trong cuộc khủng hoảng đã bị chỉ trích rộng rãi.","k":"reprehensible"},{"t":"Extirpate","d":"(động từ) Nhổ tận gốc và tiêu diệt hoàn toàn.","de":"(verb) To root out and destroy completely.","e":"The invasive species was extirpated from the region to protect native wildlife.","ev":"Các loài xâm lấn đã bị tuyệt chủng khỏi khu vực để bảo vệ động vật hoang dã bản địa.","k":"extirpate"}]},{"n":"Ưu tiên 2 · 9","c":[{"t":"Alleviate","p":"verb","d":"để giảm bớt, làm cho dễ chịu hơn","de":"to relieve, make more bearable","e":"This drug will alleviate the symptoms of the terrible disease, but only for a while.","ev":"Thuốc này sẽ làm giảm triệu chứng của căn bệnh khủng khiếp, nhưng chỉ trong một thời gian ngắn.","k":"alleviate"},{"t":"Dispassionate","p":"adjective","d":"Không bị chi phối bởi cảm xúc mạnh, công bằng.","de":"not influenced by strong emotion, fair-minded","e":"He approached the situation with a dispassionate view, analyzing the facts without emotion.","ev":"Anh tiếp cận tình huống với cái nhìn lạnh lùng, phân tích các sự kiện mà không có cảm xúc.","k":"dispassionate"},{"t":"Undergo","d":"Trải nghiệm hoặc phải chịu đựng (một điều gì đó, thường là điều gì đó khó chịu hoặc vất vả).","de":"To experience or be subjected to (something, typically something unpleasant or arduous).","e":"He had to undergo surgery to repair the damage.","ev":"Anh ấy đã phải trải qua cuộc phẫu thuật để sửa chữa những tổn thương.","k":"undergo"},{"t":"Deserving","d":"Xứng đáng được đối xử theo một cách đặc biệt, thường là được giúp đỡ.","de":"Worthy of being treated in a particular way, typically of being given assistance.","e":"She is deserving of all the accolades she has received.","ev":"Cô ấy xứng đáng với tất cả những lời khen ngợi mà cô ấy đã nhận được.","k":"deserving"},{"t":"Circumspect","p":"(adj.)","d":"thận trọng, Cẩn trọng","de":"cautious, cẩn trọng","e":"Though I promised Rachel’s father I would bring her home promptly by midnight, it would have been more circumspect not to have specified a time.","ev":"Mặc dù tôi đã hứa với cha của Rachel là sẽ đưa cô ấy về nhà ngay trước nửa đêm, nhưng sẽ thận trọng hơn nếu không xác định thời gian cụ thể.","k":"circumspect"},{"t":"Hesitant","d":"Thiếu tự tin hoặc chậm chạp trong hành động hay lời nói.","de":"Unsure or slow in acting or speaking.","e":"She was hesitant to make a decision without more information.","ev":"Cô do dự khi đưa ra quyết định mà không có thêm thông tin.","k":"hesitant"},{"t":"Impart","d":"truyền đạt, kể cho hay, phổ biến","de":"truyền đạt, kể cho hay, phổ biến","e":"to impart news","ev":"để truyền đạt tin tức","k":"impart"},{"t":"Shrewd","p":"adj","d":"Có hoặc thể hiện khả năng phán đoán sắc bén; tinh tường. Sắc","de":"Having or showing sharp powers of judgment; astute. Sắc sảo","e":"His shrewd investment decisions greatly increased his wealth.","ev":"Các quyết định đầu tư khôn ngoan của anh đã làm gia tăng đáng kể sự giàu có của mình.","k":"shrewd"},{"t":"Subdued","p":"adj.","d":"Yên tĩnh bất thường, và có thể không vui; (về màu sắc hoặc ánh sáng) nhẹ nhàng và dịu dàng. Trầm","de":"unusually quiet, and possibly unhappy; (of color or lighting) soft and restrained. Trầm","e":"The room was painted in subdued tones of blue and gray.","ev":"Căn phòng được sơn với tông màu nhẹ nhàng như xanh lam và xám.","k":"subdued"}]},{"n":"Ưu tiên 3 · 1","c":[{"t":"pundit","p":"noun","d":"học","de":"học giả","e":"The pundit offered insightful commentary on the political situation.","ev":"Chuyên gia đã đưa ra những nhận xét sâu sắc về tình hình chính trị.","k":"pundit"},{"t":"unfathomable","p":"adj","d":"không thể được","de":"không thể hiểu được","e":"The depths of the ocean remain largely unfathomable to scientists.","ev":"Độ sâu của đại dương vẫn chủ yếu không thể hiểu được đối với các nhà khoa học.","k":"unfathomable"},{"t":"flippant, flippancy","p":"adj/noun","d":"sự lố bịch, sự lấp lánh","de":"sự lố bịch, sự lố bịch","e":"His flippant remarks during the serious discussion annoyed everyone.","ev":"Những lời nói hời hợt của anh trong cuộc thảo luận nghiêm túc đã khiến mọi người khó chịu.","k":"flippant, flippancy"},{"t":"effervesce","p":"noun","d":"bao phủ","de":"sủi bọt","e":"The soda began to effervesce as soon as the cap was removed.","ev":"Nước ngọt bắt đầu sủi bọt ngay khi nắp được mở.","k":"effervesce"},{"t":"jaded","p":"adjective","d":"mệt mỏi","de":"mệt mỏi","e":"After years in the industry, she felt jaded and disillusioned.","ev":"Sau nhiều năm trong ngành, cô cảm thấy mệt mỏi và thất vọng.","k":"jaded"},{"t":"compliant, \ncompliance","p":"adj/noun","d":"Tuân thủ, Tuân thủ","de":"tuân thủ, \nTuân thủ","e":"Her compliant nature made her easy to work with, as she was always agreeable.","ev":"Tính cách dễ bảo của cô khiến việc làm việc cùng cô trở nên dễ dàng, vì cô luôn đồng thuận.","k":"compliant, compliance"},{"t":"ramshackle","p":"adj","d":"xiêu","de":"xiêu vẹo","e":"The ramshackle house was falling apart.","ev":"Ngôi nhà tồi tàn đang bị sụp đổ.","k":"ramshackle"},{"t":"rouse, rousing","p":"verb/adjective","d":"đánh thức, đánh thức","de":"đánh thức, đánh thức","e":"The coach's speech was meant to rouse the team's spirit before the big game.","ev":"Bài phát biểu của huấn luyện viên nhằm khơi dậy tinh thần của đội trước trận đấu lớn.","k":"rouse, rousing"},{"t":"idyllic","p":"adjective","d":"bình dị","de":"bình dị","e":"They spent their vacation in an idyllic village surrounded by mountains and rivers.","ev":"Họ đã dành kỳ nghỉ của mình ở một ngôi làng idylic được bao quanh bởi núi và sông.","k":"idyllic"},{"t":"gallant(ry)","p":"adj/n","d":"Khúc cảm (ry)","de":"dũng cảm (ry)","e":"The gallant rescue of the trapped hikers was reported in the news.","ev":"Hành động dũng cảm cứu hộ những người leo núi bị mắc kẹt đã được đưa tin trên báo.","k":"gallant(ry)"},{"t":"spartan","p":"adj","d":"Người Spartan","de":"người Spartan","e":"He lived a spartan lifestyle, free of excess.","ev":"Anh ta sống một cuộc sống khắc khổ, không có sự dư thừa.","k":"spartan"},{"t":"exhibitionist, \nexhibitionistic","p":"adj","d":"nhà phát triển triển lãm, \nthích tài khoản","de":"nhà triển lãm, \nthích phô trương","e":"His exhibitionist tendencies made him the center of attention at every party.","ev":"Xu hướng thích phô trương của anh khiến anh trở thành tâm điểm chú ý tại mỗi bữa tiệc.","k":"exhibitionist, exhibitionistic"},{"t":"furor","p":"noun","d":"sự tức giận","de":"sự giận dữ","e":"The furor over the new policy caused widespread protests across the city.","ev":"Cuộc phẫn nộ về chính sách mới đã gây ra các cuộc biểu tình lan rộng khắp thành phố.","k":"furor"},{"t":"polemical","p":"noun","d":"mang tính luận","de":"mang tính luận chiến","e":"The polemical article sparked controversy and debate in the academic community.","ev":"Bài viết gây tranh cãi đã kích thích sự tranh luận và tranh cãi trong cộng đồng học thuật.","k":"polemical"},{"t":"duplicitous, \nduplicity","p":"adj/noun","d":"lặp lặp, \ntráo đổi","de":"trùng lặp, \nsự dối trá","e":"His duplicitous nature led to many betrayals.","ev":"Bản chất lừa dối của anh ta đã dẫn đến nhiều vụ phản bội.","k":"duplicitous, duplicity"},{"t":"torpor","p":"noun","d":"hôn mê","de":"hôn mê","e":"After a long period of torpor, she finally motivated herself to exercise again.","ev":"Sau một thời gian dài uể oải, cô đã tự thúc đẩy mình tập thể dục trở lại.","k":"torpor"},{"t":"scanty","p":"adj","d":"nó ỏi","de":"ít ỏi","e":"The scanty clothing was not suitable for the cold weather.","ev":"Quần áo mỏng manh không phù hợp cho thời tiết lạnh.","k":"scanty"},{"t":"miserly","p":"adj","d":"keo chinh phục","de":"keo kiệt","e":"His miserly habits kept him from enjoying life to the fullest.","ev":"Thói quen keo kiệt của anh đã ngăn cản anh tận hưởng cuộc sống một cách trọn vẹn.","k":"miserly"},{"t":"cantankerous(ness)","p":"adjective/noun","d":"NGỘ g nút (ness)","de":"gắt gỏng (ness)","e":"The cantankerous old man often argued with his neighbors over trivial matters.","ev":"Người đàn ông khó tính thường cãi nhau với hàng xóm về những vấn đề tầm thường.","k":"cantankerous(ness)"},{"t":"squander","p":"verb","d":"phùng phí","de":"phung phí","e":"Don’t squander your time on trivial matters; focus on what truly matters.","ev":"Đừng lãng phí thời gian vào những điều tầm thường; hãy tập trung vào những gì thực sự quan trọng.","k":"squander"},{"t":"disquiet(ing)","p":"verb/adjective","d":"không yên tĩnh)","de":"không yên)","e":"The disquieting silence in the room suggested that something was wrong.","ev":"Sự im lặng đáng lo ngại trong phòng cho thấy có điều gì đó không ổn.","k":"disquiet(ing)"},{"t":"waning","p":"adj","d":"suy yếu","de":"suy yếu","e":"Her enthusiasm for the project was waning as the deadline approached.","ev":"Sự hào hứng của cô với dự án đang giảm dần khi thời hạn đến gần.","k":"waning"},{"t":"derogatory, \nderogate","p":"adj","d":"xúc phạm, xúc phạm","de":"xúc phạm, \nxúc phạm","e":"The comments were derogatory and hurtful to the community.","ev":"Những bình luận đó đã xúc phạm và gây tổn thương cho cộng đồng.","k":"derogatory, derogate"},{"t":"cacophonous, \ncacophony","p":"adj/noun","d":"tiếng ồn ào, theng âm","de":"ồn ào, \ntạp âm","e":"The cacophonous sounds of the city can be overwhelming at times.","ev":"Âm thanh hỗn tạp của thành phố đôi khi có thể khiến ta choáng ngợp.","k":"cacophonous, cacophony"},{"t":"plasticity","p":"adj","d":"tính dẻo","de":"tính dẻo","e":"The plasticity of the brain allows it to adapt to new experiences throughout life.","ev":"Độ dẻo dai của não cho phép nó thích nghi với những trải nghiệm mới trong suốt cuộc đời.","k":"plasticity"}]},{"n":"Ưu tiên 3 · 2","c":[{"t":"august","p":"adj","d":"tháng tám","de":"tháng tám","e":"The august ceremony was attended by dignitaries from around the world.","ev":"Buổi lễ uy nghi được tham dự bởi các nhân vật quan trọng từ khắp nơi trên thế giới.","k":"august"},{"t":"stark(ness)","p":"noun","d":"(Đích)","de":"(sự khắc nghiệt)","e":"The starkness of the landscape was breathtaking.","ev":"Sự trần trụi của phong cảnh thật đẹp mắt.","k":"stark(ness)"},{"t":"rebuttal","p":"noun","d":"sự bác","de":"sự bác bỏ","e":"The lawyer's rebuttal effectively countered the accusations made against her client.","ev":"Sự phản biện của luật sư đã bác bỏ hiệu quả những cáo buộc chống lại thân chủ của cô.","k":"rebuttal"},{"t":"pacifist","p":"adj","d":"hoà bình chủ nghĩa","de":"người theo chủ nghĩa hoà bình","e":"As a pacifist, she strongly opposed the use of violence in any form.","ev":"Là một người theo chủ nghĩa hòa bình, cô mạnh mẽ phản đối việc sử dụng bạo lực dưới bất kỳ hình thức nào.","k":"pacifist"},{"t":"reprimand","p":"verb","d":"Champion","de":"khiển trách","e":"The manager issued a reprimand to the employee for being late.","ev":"Quản lý đã đưa ra một hình phạt cho nhân viên vì đến muộn.","k":"reprimand"},{"t":"simile","p":"noun","d":"sự so sánh","de":"sự so sánh","e":"The author used a simile to illustrate the character’s feelings, comparing her sadness to a rainstorm.","ev":"Tác giả đã sử dụng phép so sánh để minh họa cảm xúc của nhân vật, so sánh nỗi buồn của cô với cơn bão mưa.","k":"simile"},{"t":"scrutinize, scrutiny","p":"verb/noun","d":"xem xét kỹ lưỡng, xem xét kỹ lưỡng","de":"xem xét kỹ lưỡng, xem xét kỹ lưỡng","e":"She needed to scrutinize the document for any errors before submission.","ev":"Cô ấy cần xem xét kỹ lưỡng tài liệu để tìm bất kỳ lỗi nào trước khi nộp.","k":"scrutinize, scrutiny"},{"t":"slight (verb)","p":"verb","d":"nhẹ (từ)","de":"nhẹ (động từ)","e":"He felt slighted when his contributions were ignored during the meeting.","ev":"Anh cảm thấy bị coi thường khi những đóng góp của mình bị phớt lờ trong cuộc họp.","k":"slight (verb)"},{"t":"demure, demurral","p":"adj/noun","d":"phản đối, phản đối","de":"demurral, demurral","e":"She had a demure smile that belied her confident personality.","ev":"Cô có một nụ cười dịu dàng mà ẩn chứa tính cách tự tin của mình.","k":"demure, demurral"},{"t":"blighted","p":"adj","d":"tàn lụi","de":"tàn lụi","e":"The crops were blighted by the drought.","ev":"Cây trồng đã bị thiệt hại do hạn hán.","k":"blighted"},{"t":"debilitate(d)","p":"verb/adjective","d":"suy nhược(d)","de":"suy nhược(d)","e":"The illness can debilitate even the strongest individuals.","ev":"Căn bệnh này có thể làm suy yếu ngay cả những người mạnh mẽ nhất.","k":"debilitate(d)"},{"t":"ignominy, \nignominious","p":"adj/noun","d":"sự ô nhục, \nô nhục","de":"sự ô nhục, \nô nhục","e":"The ignominy of his actions was hard to bear in front of his peers.","ev":"Sự nhục nhã của hành động của anh thật khó chịu trước mặt các đồng nghiệp.","k":"ignominy, ignominious"},{"t":"diminutive, \ndiminution","p":"adj/noun","d":"bé nhỏ,\nsự suy giảm","de":"nhỏ bé, \nsự suy giảm","e":"The diminutive size of the puppy made it incredibly cute.","ev":"Kích thước nhỏ bé của chú chó con khiến nó trở nên rất dễ thương.","k":"diminutive, diminution"},{"t":"vacuous, vacuity","p":"adj/noun","d":"trống rỗng, trải nghiệm trống trải","de":"trống rỗng, trống trải","e":"The vacuous expression on his face showed he was not paying attention.","ev":"Biểu cảm trống rỗng trên khuôn mặt anh cho thấy anh không chú ý.","k":"vacuous, vacuity"},{"t":"venal(ity)","p":"adj","d":"Mạch (tính)","de":"tĩnh mạch (ity)","e":"His venality was evident when he accepted bribes from several companies.","ev":"Tính tham nhũng của anh rõ ràng khi anh nhận hối lộ từ một số công ty.","k":"venal(ity)"},{"t":"irreverent, \nirreverence","p":"adj/noun","d":"không mong đợi, \nsự bất ngờ","de":"bất kính, \nsự bất kính","e":"His irreverent jokes about serious topics offended many people.","ev":"Những câu đùa không tôn trọng của anh về các chủ đề nghiêm túc đã khiến nhiều người bị xúc phạm.","k":"irreverent, irreverence"},{"t":"ascendancy","p":"noun","d":"uy","de":"uy thế","e":"The party regained ascendancy in the political landscape after the election.","ev":"Đảng đã lấy lại thế thượng phong trong bối cảnh chính trị sau cuộc bầu cử.","k":"ascendancy"},{"t":"finesse","p":"noun/verb","d":"sự lừa","de":"sự khéo léo","e":"He handled the situation with finesse, ensuring a smooth resolution.","ev":"Anh đã xử lý tình huống một cách khéo léo, đảm bảo giải quyết suôn sẻ.","k":"finesse"},{"t":"inscrutable","p":"adj","d":"không thể được","de":"không thể hiểu được","e":"His inscrutable expression made it hard to read him.","ev":"Biểu cảm bí ẩn của anh ta khiến việc đọc vị khó khăn.","k":"inscrutable"},{"t":"prohibitive, \nprohibition","p":"adj/noun","d":"không mong đợi, \nsự mong đợi không hợp lệ","de":"cấm đoán, \nsự cấm đoán","e":"The prohibitive costs of living in the city discourage many from moving there.","ev":"Chi phí sinh hoạt cắt cổ ở thành phố khiến nhiều người không muốn chuyển đến đó.","k":"prohibitive, prohibition"},{"t":"profuse, profusion","p":"noun","d":"dồi dào, dồi dào","de":"dồi dào, dồi dào","e":"She offered profuse apologies for her mistake.","ev":"Cô đã gửi lời xin lỗi dồn dập về sai lầm của mình.","k":"profuse, profusion"},{"t":"byzantine","p":"adj","d":"Byzantine","de":"Byzantine","e":"The byzantine structure of the organization made it hard to navigate.","ev":"Cấu trúc phức tạp của tổ chức khiến việc điều hướng trở nên khó khăn.","k":"byzantine"},{"t":"prevaricator","p":"noun","d":"người xung quanh co","de":"người nói quanh co","e":"A prevaricator can never be trusted.","ev":"Kẻ quanh co không bao giờ có thể được tin cậy.","k":"prevaricator"},{"t":"laud, laudatory","p":"verb","d":"ca, khen","de":"ca ngợi, khen ngợi","e":"He received laudatory reviews for his performance in the play.","ev":"Anh đã nhận được những đánh giá khen ngợi cho màn trình diễn của mình trong vở kịch.","k":"laud, laudatory"},{"t":"barrage","p":"noun","d":"đập phá","de":"đập phá","e":"The barrage of questions overwhelmed her.","ev":"Cơn mưa câu hỏi đã làm cô ấy choáng ngợp.","k":"barrage"}]},{"n":"Ưu tiên 3 · 3","c":[{"t":"philanthropist, \nphilanthropic","p":"adj/noun","d":"nhà từ thiện, \ntừ thiện","de":"nhà từ thiện, \ntừ thiện","e":"The philanthropist donated millions to support education and healthcare initiatives.","ev":"Nhà từ thiện đã quyên góp hàng triệu đô la để hỗ trợ các sáng kiến giáo dục và chăm sóc sức khỏe.","k":"philanthropist, philanthropic"},{"t":"scope","p":"noun","d":"nho vi","de":"phạm vi","e":"The scope of the project includes both research and implementation phases.","ev":"Phạm vi của dự án bao gồm cả giai đoạn nghiên cứu và thực hiện.","k":"scope"},{"t":"disheartening","p":"adj","d":"làm lòng","de":"làm nản lòng","e":"The disheartening news about the project’s funding made the team anxious.","ev":"Tin tức khiến đội ngũ chán nản về việc tài trợ cho dự án đã khiến họ lo lắng.","k":"disheartening"},{"t":"epiphany","p":"noun","d":"sự chồng linh","de":"sự hiển linh","e":"His epiphany about life changed his perspective completely.","ev":"Sự khai sáng về cuộc sống của anh đã thay đổi hoàn toàn quan điểm của anh.","k":"epiphany"},{"t":"bog","p":"noun","d":"đồng tiền","de":"đầm lầy","e":"The heavy rains caused the fields to bog down, making it difficult to plant crops.","ev":"Những trận mưa lớn khiến các cánh đồng lầy lội, làm khó khăn cho việc trồng trọt.","k":"bog"},{"t":"recessive","p":"adj","d":"lặn","de":"lặn","e":"Blue eyes are a recessive trait, meaning they can be masked by dominant traits.","ev":"Mắt xanh là một đặc điểm lặn, có nghĩa là nó có thể bị che khuất bởi các đặc điểm trội.","k":"recessive"},{"t":"sophistry","p":"noun","d":"sự kiện","de":"sự ngụy biện","e":"His argument was nothing more than sophistry.","ev":"Lập luận của anh ta chẳng qua chỉ là lý lẽ ranh mãnh.","k":"sophistry"},{"t":"efface(ment)","p":"noun","d":"hiệu (ment)","de":"hiệu ứng(ment)","e":"The artist's work showed a gradual effacement of earlier styles as she developed her own.","ev":"Công việc của nghệ sĩ cho thấy sự xóa nhòa dần dần các phong cách trước đó khi cô phát triển phong cách riêng.","k":"efface(ment)"},{"t":"castigate","p":"verb","d":"sao","de":"trừng phạt","e":"The teacher castigated the students for their poor performance on the exam.","ev":"Giáo viên đã chỉ trích học sinh vì thành tích kém trong kỳ thi.","k":"castigate"},{"t":"proliferate, \nproliferation","p":"noun","d":"nghe, \nsự tăng sinh","de":"nảy nở, \nsự tăng sinh","e":"The use of social media has proliferated in recent years, changing how we communicate.","ev":"Việc sử dụng mạng xã hội đã gia tăng nhanh chóng trong những năm gần đây, thay đổi cách chúng ta giao tiếp.","k":"proliferate, proliferation"},{"t":"disillusionment","p":"noun","d":"sự thừa","de":"sự vỡ mộng","e":"The disillusionment with the political system led many to lose faith in democracy.","ev":"Sự thất vọng với hệ thống chính trị đã khiến nhiều người mất niềm tin vào nền dân chủ.","k":"disillusionment"},{"t":"fathom (verb)","p":"verb","d":"hiểu được (động từ)","de":"hiểu được (động từ)","e":"It’s hard to fathom the depth of the ocean from the shore.","ev":"Thật khó để hiểu được độ sâu của đại dương từ bờ biển.","k":"fathom (verb)"},{"t":"incriminate","p":"verb","d":"bắt buộc tội","de":"buộc tội","e":"The evidence seemed to incriminate him, making the case against him stronger.","ev":"Bằng chứng dường như buộc tội anh, làm cho vụ án chống lại anh trở nên mạnh mẽ hơn.","k":"incriminate"},{"t":"reap","p":"verb","d":"Nguyên","de":"gặt","e":"If you work hard, you will reap the rewards of your efforts.","ev":"Nếu bạn làm việc chăm chỉ, bạn sẽ gặt hái được thành quả từ nỗ lực của mình.","k":"reap"},{"t":"impudence, \nimpudent","p":"noun/adj","d":"network network, \nrereo","de":"sự ngạo mạn, \ntrơ tráo","e":"His impudence in addressing the teacher shocked the entire class.","ev":"Sự vô lễ của anh khi nói chuyện với giáo viên đã làm cả lớp sốc.","k":"impudence, impudent"},{"t":"temperamental","p":"adjective","d":"thất thường","de":"thất thường","e":"His temperamental nature made it hard for his friends to predict his reactions.","ev":"Tính khí thất thường của anh khiến bạn bè khó đoán được phản ứng của anh.","k":"temperamental"},{"t":"indiscriminate","p":"adj","d":"bãi đậu xe","de":"bừa bãi","e":"His indiscriminate use of resources led to waste and inefficiency.","ev":"Việc anh sử dụng tài nguyên một cách bừa bãi đã dẫn đến lãng phí và thiếu hiệu quả.","k":"indiscriminate"},{"t":"hamper (verb)","p":"verb","d":"(từ)","de":"cản trở (động từ)","e":"Heavy rains can hamper the construction process significantly.","ev":"Mưa lớn có thể cản trở quá trình xây dựng một cách đáng kể.","k":"hamper (verb)"},{"t":"teem, teeming","p":"verb","d":"đông đúc, đông đúc","de":"đông đúc, đông đúc","e":"The lake was teeming with fish during the summer months.","ev":"Hồ đầy cá vào những tháng mùa hè.","k":"teem, teeming"},{"t":"piety, pious","p":"noun/adj","d":"quệ đạo, ngoan đạo","de":"sùng đạo, ngoan đạo","e":"His piety was evident in his daily rituals and charitable acts.","ev":"Tấm lòng sùng đạo của anh rõ ràng qua những nghi lễ hàng ngày và các hành động từ thiện của anh.","k":"piety, pious"},{"t":"eulogy, eulogize","p":"noun","d":"khoa học văn học, văn học","de":"điếu văn, điếu văn","e":"At the funeral, a touching eulogy was delivered in honor of the deceased.","ev":"Tại đám tang, một bài điếu văn xúc động đã được đọc để tôn vinh người đã khuất.","k":"eulogy, eulogize"},{"t":"perquisite","p":"noun","d":"cần","de":"cần thiết","e":"A company car is often considered a perquisite of the job.","ev":"Một chiếc xe công ty thường được coi là một đặc quyền của công việc.","k":"perquisite"},{"t":"parch","p":"adj","d":"phơi bày","de":"phơi","e":"The sun can parch the earth, making it difficult for plants to survive.","ev":"Mặt trời có thể làm khô cằn đất, khiến cây cối khó sống sót.","k":"parch"},{"t":"demonstrative","p":"adjective","d":"biểu tình","de":"biểu tình","e":"He was demonstrative in his affection, often hugging and kissing his friends.","ev":"Anh ấy thể hiện tình cảm một cách rõ ràng, thường ôm và hôn bạn bè.","k":"demonstrative"},{"t":"affected","p":"adj","d":"ảnh hưởng","de":"ảnh hưởng","e":"His affected mannerisms made him seem insincere to others.","ev":"Cách cư xử giả tạo của anh khiến anh có vẻ không chân thành trong mắt người khác.","k":"affected"}]},{"n":"Ưu tiên 3 · 4","c":[{"t":"pedant, pedantic, pedantry","p":"noun","d":"phạm tội, phạm tội, phạm tội","de":"mô phạm, mô phạm, mô phạm","e":"He was criticized for his pedantic approach to teaching, focusing too much on minor details.","ev":"Anh bị chỉ trích vì cách dạy học chú trọng quá nhiều vào những chi tiết nhỏ.","k":"pedant, pedantic, pedantry"},{"t":"provincial","p":"adj","d":"tỉnh","de":"tỉnh","e":"His provincial mindset made it difficult for him to understand broader perspectives.","ev":"Tư duy tỉnh lẻ của anh khiến anh khó hiểu được những quan điểm rộng hơn.","k":"provincial"},{"t":"conciliate, \nconciliatory","p":"v/adj","d":"hòa giải, hòa giải","de":"hòa giải, \nhòa giải","e":"The mediator tried to conciliate both parties during the negotiation.","ev":"Người hòa giải đã cố gắng hòa giải cả hai bên trong quá trình đàm phán.","k":"conciliate, conciliatory"},{"t":"plausible, \nplausibility","p":"adj","d":"hợp lý, tính hợp lý","de":"hợp lý, \ntính hợp lý","e":"The explanation seemed plausible at first glance.","ev":"Giải thích có vẻ hợp lý ngay từ cái nhìn đầu tiên.","k":"plausible, plausibility"},{"t":"indignant","p":"adj","d":"Đám","de":"phẫn nộ","e":"She felt indignant at the unfair treatment she received from her boss.","ev":"Cô cảm thấy phẫn nộ trước sự đối xử bất công mà cô nhận được từ sếp.","k":"indignant"},{"t":"oracle","p":"noun","d":"lời tri","de":"lời tiên tri","e":"The oracle foretold the future.","ev":"Người tiên tri đã dự đoán tương lai.","k":"oracle"},{"t":"egalitarian","p":"adj","d":"bình đẳng","de":"bình đẳng","e":"The country promotes an egalitarian society where everyone has equal rights.","ev":"Quốc gia này thúc đẩy một xã hội bình đẳng nơi mọi người có quyền lợi như nhau.","k":"egalitarian"},{"t":"deference, \ndeferential","p":"noun/adjective","d":"sự quan trọng của tôn giáo, \ncung cấp kính hiển vi","de":"sự tôn trọng, \ncung kính","e":"He showed great deference to his elders during the ceremony.","ev":"Anh đã thể hiện sự tôn trọng lớn đối với những người lớn tuổi hơn trong buổi lễ.","k":"deference, deferential"},{"t":"self-serving","p":"adj","d":"tự phục vụ","de":"tự phục vụ","e":"Her self-serving motives were obvious to everyone in the room.","ev":"Động cơ vị kỷ của cô rõ ràng với mọi người trong phòng.","k":"self-serving"},{"t":"digress(ion)","p":"verb/noun","d":"lạc đề(ion)","de":"lạc đề(ion)","e":"During the presentation, she took a brief digression to share a personal story.","ev":"Trong buổi thuyết trình, cô ấy đã tạm thời lạc đề để chia sẻ một câu chuyện cá nhân.","k":"digress(ion)"},{"t":"epitome, epitomize","p":"noun, verb","d":"điển hình, tự điển hóa","de":"điển hình, điển hình hóa","e":"She is the epitome of grace and elegance, and her performance perfectly epitomized the theme of the ballet.","ev":"Cô ấy là hình mẫu của sự duyên dáng và thanh lịch, và màn trình diễn của cô hoàn toàn tiêu biểu cho chủ đề của buổi ballet.","k":"epitome, epitomize"},{"t":"unwitting","p":"adjective","d":"vô","de":"vô tình","e":"The unwitting participant had no idea what was about to happen.","ev":"Người tham gia không hay biết đã không biết điều gì sắp xảy ra.","k":"unwitting"},{"t":"autocrat, autocratic","p":"noun","d":"chuyên quyền, chuyên quyền","de":"chuyên quyền, chuyên quyền","e":"The autocrat ruled with an iron fist, leaving no room for dissent.","ev":"Nhà độc tài cai trị bằng bàn tay sắt, không để lại chỗ cho sự bất đồng.","k":"autocrat, autocratic"},{"t":"germinate","p":"verb","d":"quả mọng","de":"nảy mầm","e":"The seeds will germinate when the conditions are right.","ev":"Hạt sẽ nảy mầm khi các điều kiện thuận lợi.","k":"germinate"},{"t":"devoid","p":"adj","d":"không có","de":"không có","e":"The area was devoid of wildlife due to extensive urban development.","ev":"Khu vực này hoàn toàn thiếu động vật hoang dã do sự phát triển đô thị rộng rãi.","k":"devoid"},{"t":"idiosyncracy, \nidiosyncratic","p":"noun/adj","d":"khác biệt, \ncó phong cách riêng","de":"sự khác biệt, \ncó phong cách riêng","e":"Her idiosyncrasy of collecting vintage postcards made her unique among her friends.","ev":"Thói quen kỳ quặc của cô trong việc thu thập bưu thiếp cổ điển khiến cô trở nên độc đáo trong số bạn bè.","k":"idiosyncracy, idiosyncratic"},{"t":"charlatan","p":"noun","d":"lang","de":"lang băm","e":"The charlatan promised miraculous results.","ev":"Kẻ lừa đảo hứa hẹn kết quả kỳ diệu.","k":"charlatan"},{"t":"pliable, pliant","p":"adj","d":"dẻo, dễ dàng","de":"dẻo, dễ uốn","e":"The material is pliable and can be easily shaped into different forms.","ev":"Chất liệu này dẻo và có thể dễ dàng tạo hình thành các dạng khác nhau.","k":"pliable, pliant"},{"t":"gargantuan","p":"verb","d":"...","de":"khổng lồ","e":"The gargantuan statue drew visitors from all over the world.","ev":"Bức tượng khổng lồ thu hút du khách từ khắp nơi trên thế giới.","k":"gargantuan"},{"t":"unabashed","p":"adj","d":"không nao núng","de":"không nao núng","e":"She was unabashed about her opinions, expressing them freely at the meeting.","ev":"Cô không hề xấu hổ về ý kiến của mình, tự do bày tỏ chúng trong cuộc họp.","k":"unabashed"},{"t":"virtuoso, virtuosity","p":"noun","d":"thẩm định, thẩm định","de":"sự điêu luyện, sự điêu luyện","e":"The young musician displayed virtuosity beyond his years during the performance.","ev":"Nhạc sĩ trẻ đã thể hiện tài năng vượt trội hơn cả tuổi của mình trong buổi biểu diễn.","k":"virtuoso, virtuosity"},{"t":"stupefy, \nstupefaction","p":"verb/noun","d":"Đêm,\nngạ","de":"choáng váng, \nsửng sốt","e":"The magician's performance left the audience in a state of stupefaction.","ev":"Màn trình diễn của ảo thuật gia đã khiến khán giả rơi vào trạng thái choáng váng.","k":"stupefy, stupefaction"},{"t":"belligerent","p":"adj","d":"trang bị","de":"hiếu chiến","e":"His belligerent attitude caused many conflicts.","ev":"Thái độ hiếu chiến của anh ta đã gây ra nhiều xung đột.","k":"belligerent"},{"t":"listless","p":"adjective","d":"cho phờ","de":"bơ phờ","e":"She felt listless and uninspired after a long week of work.","ev":"Cô cảm thấy uể oải và không có cảm hứng sau một tuần làm việc dài.","k":"listless"},{"t":"discomfited","p":"adjective","d":"không thoải mái","de":"không thoải mái","e":"She felt discomfited by the unexpected question during the interview.","ev":"Cô cảm thấy khó chịu trước câu hỏi bất ngờ trong buổi phỏng vấn.","k":"discomfited"}]},{"n":"Ưu tiên 3 · 5","c":[{"t":"ravenous","p":"noun","d":"háu ăn","de":"háu ăn","e":"After skipping breakfast, he felt ravenous by lunchtime.","ev":"Sau khi bỏ bữa sáng, anh cảm thấy đói cồn cào vào giờ ăn trưa.","k":"ravenous"},{"t":"self-righteous","p":"adj","d":"tự cho là đúng","de":"tự cho mình là đúng","e":"His self-righteous attitude alienated his friends.","ev":"Thái độ tự mãn của anh đã khiến bạn bè xa lánh.","k":"self-righteous"},{"t":"gait","p":"noun","d":"bước đi","de":"dáng đi","e":"She walked with a graceful gait.","ev":"Cô ấy đi với dáng đi uyển chuyển.","k":"gait"},{"t":"provident","p":"adj","d":"quan phòng","de":"quan phòng","e":"She was provident enough to save money for her children’s education.","ev":"Cô đủ khôn ngoan để tiết kiệm tiền cho việc học của con cái.","k":"provident"},{"t":"repugnant","p":"adjective","d":"đáng","de":"đáng ghét","e":"The repugnant behavior of the character in the film made it hard to watch.","ev":"Hành vi ghê tởm của nhân vật trong bộ phim khiến việc xem trở nên khó khăn.","k":"repugnant"},{"t":"satire, satirical, \nsatirize","p":"noun/adjective/verb","d":"châm ngôn, châm ngôn, \ncâu châm ngôn","de":"châm biếm, châm biếm, \nchâm biếm","e":"The book is a satire that critiques societal norms with humor.","ev":"Cuốn sách là một tác phẩm châm biếm chỉ trích các quy tắc xã hội bằng sự hài hước.","k":"satire, satirical, satirize"},{"t":"depreciation, \ndepreciatory","p":"noun","d":"trụ hao, mất giá","de":"khấu hao, \nmất giá","e":"The depreciation of the currency has affected the economy negatively.","ev":"Sự giảm giá của đồng tiền đã ảnh hưởng tiêu cực đến nền kinh tế.","k":"depreciation, depreciatory"},{"t":"totalitarian","p":"noun","d":"toàn trị","de":"toàn trị","e":"The totalitarian regime controlled every aspect of citizens’ lives.","ev":"Chế độ độc tài kiểm soát mọi khía cạnh trong cuộc sống của công dân.","k":"totalitarian"},{"t":"tribulation","p":"noun","d":"nạn nhân","de":"hoạn nạn","e":"They faced many tribulations during their journey but persevered through them all.","ev":"Họ đã phải đối mặt với nhiều thử thách trong suốt hành trình nhưng đã kiên trì vượt qua tất cả.","k":"tribulation"},{"t":"saturate","p":"verb","d":"hòa bình","de":"bão hòa","e":"The sponge will saturate with water if left in it for too long.","ev":"Bọt biển sẽ bão hòa với nước nếu để trong đó quá lâu.","k":"saturate"},{"t":"mitigate, mitigator","p":"verb/noun","d":"giảm độ cứng, giảm độ cứng","de":"giảm nhẹ, giảm nhẹ","e":"We need to find ways to mitigate the risks associated with the project.","ev":"Chúng ta cần tìm cách giảm thiểu những rủi ro liên quan đến dự án.","k":"mitigate, mitigator"},{"t":"sanction","p":"verb","d":"sự kiện","de":"sự trừng phạt","e":"The government decided to sanction the new regulations to improve safety standards.","ev":"Chính phủ quyết định phê chuẩn các quy định mới để cải thiện tiêu chuẩn an toàn.","k":"sanction"},{"t":"lackadaisical","p":"adjective","d":"thiếu quyết định đoán","de":"thiếu quyết đoán","e":"His lackadaisical approach to studying resulted in low grades.","ev":"Cách tiếp cận thiếu quyết tâm của anh đối với việc học đã dẫn đến điểm số thấp.","k":"lackadaisical"},{"t":"ratify","p":"verb","d":"phê chuẩn","de":"phê chuẩn","e":"The treaty must be ratified by both countries before it takes effect.","ev":"Hiệp ước phải được cả hai quốc gia phê chuẩn trước khi có hiệu lực.","k":"ratify"},{"t":"insolence, insolent","p":"noun/adj","d":"xấc xược, xấc xược","de":"xấc xược, xấc xược","e":"The insolent behavior of the student earned him a detention.","ev":"Hành vi hỗn láo của học sinh đã khiến anh bị phạt ở lại lớp.","k":"insolence, insolent"},{"t":"burgeon","p":"verb","d":"đang phát triển","de":"đang phát triển","e":"The plant began to burgeon once the spring rains arrived.","ev":"Cây bắt đầu nảy nở khi những cơn mưa mùa xuân đến.","k":"burgeon"},{"t":"magnanimity, \nmagnanimous","p":"adj/noun","d":"hào hùng, \ncao thượng","de":"sự hào hùng, \ncao thượng","e":"Her magnanimity in forgiving others made her well-respected in the community.","ev":"Tấm lòng rộng lượng của cô trong việc tha thứ cho người khác khiến cô được tôn trọng trong cộng đồng.","k":"magnanimity, magnanimous"},{"t":"heresy, heretic","p":"noun","d":"dị giáo, dị giáo","de":"dị giáo, dị giáo","e":"Accusing him of heresy, the church declared him a heretic and excommunicated him.","ev":"Buộc tội anh dị giáo, nhà thờ tuyên bố anh là người dị giáo và đã tước bỏ quyền giáo hội của anh.","k":"heresy, heretic"},{"t":"fraudulent","p":"adj","d":"lừa đảo","de":"lừa đảo","e":"The fraudulent scheme was uncovered by authorities.","ev":"Kế hoạch gian lận đã bị các cơ quan phát hiện.","k":"fraudulent"},{"t":"rancor(ous)","p":"noun/adjective","d":"(ous)","de":"thù hận (ous)","e":"There was rancor in his voice as he spoke about his former colleague.","ev":"Có sự cay đắng trong giọng nói của anh khi anh nói về người đồng nghiệp cũ.","k":"rancor(ous)"},{"t":"succulent","p":"adj","d":"ngon","de":"ngon","e":"The steak was juicy and succulent.","ev":"Miếng bít tết thật ngon và mọng nước.","k":"succulent"},{"t":"hasten","p":"verb","d":"nhanh","de":"nhanh lên","e":"Please hasten your response.","ev":"Xin vui lòng trả lời nhanh chóng.","k":"hasten"},{"t":"empathetic, \nempathy","p":"adjective/noun","d":"đồng cảm, \ncảm giác sâu sắc","de":"đồng cảm, \nsự đồng cảm","e":"His empathetic nature allowed him to connect with others easily.","ev":"Tính cách đồng cảm của anh giúp anh dễ dàng kết nối với người khác.","k":"empathetic, empathy"},{"t":"futile, futility","p":"adj/n","d":"vô tiện, vô tiện","de":"vô ích, vô ích","e":"Their efforts to resolve the issue seemed futile in the face of such strong opposition.","ev":"Nỗ lực của họ để giải quyết vấn đề có vẻ vô nghĩa trước sự phản đối mạnh mẽ như vậy.","k":"futile, futility"},{"t":"palliate, palliative","p":"noun","d":"làm nóng đi, xoa","de":"làm dịu đi, xoa dịu","e":"They tried to palliate the pain with medication.","ev":"Họ đã cố gắng giảm nhẹ cơn đau bằng thuốc.","k":"palliate, palliative"}]},{"n":"Ưu tiên 3 · 6","c":[{"t":"relinquish","p":"verb","d":"từ","de":"từ bỏ","e":"He decided to relinquish his claim to the inheritance.","ev":"Anh quyết định từ bỏ quyền thừa kế của mình.","k":"relinquish"},{"t":"sanctity","p":"noun","d":"sự thánh","de":"sự thánh thiện","e":"The sanctity of the ancient site was preserved by strict regulations.","ev":"Tính thiêng liêng của địa điểm cổ đại được bảo tồn bởi các quy định nghiêm ngặt.","k":"sanctity"},{"t":"virulent","p":"adj","d":"độc ác","de":"độc ác","e":"The virus was particularly virulent this season.","ev":"Virus này đặc biệt mạnh mẽ trong mùa này.","k":"virulent"},{"t":"lull","p":"noun/verb","d":"ru","de":"ru ngủ","e":"The gentle lull of the waves made him feel relaxed and at peace.","ev":"Âm thanh nhẹ nhàng của sóng khiến anh cảm thấy thư giãn và bình yên.","k":"lull"},{"t":"inert, inertia","p":"adj/noun","d":"nhân, quán tính","de":"trơ, quán tính","e":"The inert materials in the reaction did not contribute to the outcome.","ev":"Các vật liệu bất động trong phản ứng không góp phần vào kết quả.","k":"inert, inertia"},{"t":"regressive","p":"adj","d":"tuổi trẻ","de":"thoái lui","e":"The policy was seen as regressive.","ev":"Chính sách đó được coi là lùi lại.","k":"regressive"},{"t":"spurn","p":"verb","d":"bị làm","de":"bị hắt hủi","e":"She spurned his invitation to the party, preferring to stay home.","ev":"Cô đã từ chối lời mời của anh đến bữa tiệc, thích ở nhà hơn.","k":"spurn"},{"t":"anthropology","p":"noun","d":"nhân học","de":"nhân học","e":"Anthropology provides insights into human behavior and culture.","ev":"Nhân học cung cấp những hiểu biết về hành vi và văn hóa của con người.","k":"anthropology"},{"t":"latent, latency","p":"adj","d":"tiềm ẩn, độ trễ","de":"tiềm ẩn, độ trễ","e":"The scientist studied the latent effects of the drug over several months.","ev":"Nhà khoa học đã nghiên cứu tác động tiềm ẩn của thuốc trong vài tháng.","k":"latent, latency"},{"t":"refutation, refute","p":"noun","d":"sự bác bỏ, bác bỏ","de":"sự bác bỏ, bác bỏ","e":"The refutation of his argument was thorough.","ev":"Sự bác bỏ lập luận của anh ta rất thấu đáo.","k":"refutation, refute"},{"t":"plethora, plethoric","p":"noun","d":"sự sung dào, phong phú","de":"sự dồi dào, phong phú","e":"There was a plethora of options available for consumers in the market.","ev":"Có rất nhiều sự lựa chọn cho người tiêu dùng trên thị trường.","k":"plethora, plethoric"},{"t":"hubris","p":"noun","d":"cơ chế","de":"ngạo mạn","e":"His hubris ultimately led to his downfall.","ev":"Sự kiêu ngạo của anh cuối cùng đã dẫn đến sự sụp đổ của mình.","k":"hubris"},{"t":"encompass","p":"verb","d":"bao gồm","de":"bao gồm","e":"The project aims to encompass a wide range of topics relevant to climate change.","ev":"Dự án nhằm bao quát nhiều chủ đề liên quan đến biến đổi khí hậu.","k":"encompass"},{"t":"prospective","p":"noun","d":"triển lãm","de":"triển vọng","e":"They are prospective clients.","ev":"Họ là những khách hàng tiềm năng.","k":"prospective"},{"t":"reticent, reticence","p":"adjective/noun","d":"sự dè dặt, sự dè dặt","de":"sự dè dặt, sự dè dặt","e":"She was reticent about her personal life, preferring to keep her thoughts private.","ev":"Cô ấy rất kín đáo về cuộc sống cá nhân, thích giữ suy nghĩ của mình trong im lặng.","k":"reticent, reticence"},{"t":"buoyant","p":"adjective","d":"ồ","de":"bồng bềnh","e":"Despite the challenges, she remained buoyant and optimistic about the future.","ev":"Mặc dù gặp nhiều khó khăn, cô vẫn giữ tinh thần phấn chấn và lạc quan về tương lai.","k":"buoyant"},{"t":"deterrent","p":"noun/adjective","d":"7","de":"răn đe","e":"The new law was introduced as a deterrent against reckless driving.","ev":"Luật mới được giới thiệu như một biện pháp răn đe chống lại việc lái xe liều lĩnh.","k":"deterrent"},{"t":"histrionic","p":"adjective","d":"chon","de":"lịch sử","e":"His histrionic behavior during the meeting drew eye rolls from his colleagues.","ev":"Cách cư xử kịch tính của anh ấy trong cuộc họp đã khiến đồng nghiệp phải lắc đầu.","k":"histrionic"},{"t":"incongruity, \nincongruous","p":"noun/adjective","d":"sự không tối thiểu, \nkhông thích hợp","de":"sự không nhất quán, \nkhông thích hợp","e":"The incongruity of wearing a winter coat in summer made everyone laugh.","ev":"Sự không phù hợp của việc mặc áo khoác mùa đông vào mùa hè khiến mọi người buồn cười.","k":"incongruity, incongruous"},{"t":"marred","p":"adj","d":"hoen ố","de":"hoen ố","e":"The painting was marred by water damage.","ev":"Bức tranh bị hư hại bởi nước.","k":"marred"},{"t":"credulity, \ncredulous","p":"noun","d":"hộp thiếc,\nhộp thiếc","de":"hay tin, \ncả tin","e":"His credulity made him an easy target for scams and fraud.","ev":"Sự cả tin của anh khiến anh trở thành mục tiêu dễ dàng cho những vụ lừa đảo.","k":"credulity, credulous"},{"t":"rhetoric(al), \nrhetorician","p":"noun/adjective","d":"hùng(bal), \nnhà hùng biện","de":"hùng biện(al), \nnhà hùng biện","e":"His rhetorical skills captivated the audience during the debate.","ev":"Kỹ năng hùng biện của anh ấy đã thu hút sự chú ý của khán giả trong cuộc tranh luận.","k":"rhetoric(al), rhetorician"},{"t":"folly","p":"noun","d":"sự điên rồ","de":"sự điên rồ","e":"It was sheer folly to invest all her savings in a single venture.","ev":"Đó là sự ngu dốt khi đầu tư tất cả tiền tiết kiệm của cô vào một dự án duy nhất.","k":"folly"},{"t":"elated, elation","p":"adjective/noun","d":"hỗn hợp, hỗn hợp khởi đầu","de":"phấn chấn, phấn khởi","e":"She felt elated after receiving the good news about her promotion.","ev":"Cô cảm thấy hạnh phúc sau khi nhận được tin tốt về việc thăng chức.","k":"elated, elation"},{"t":"contemptible","p":"adj","d":"đáng khinh","de":"đáng khinh","e":"His contemptible behavior during the meeting shocked everyone.","ev":"Hành vi đáng khinh của anh trong cuộc họp đã làm mọi người sốc.","k":"contemptible"}]},{"n":"Ưu tiên 3 · 7","c":[{"t":"exacting","p":"adjective","d":"chính xác","de":"chính xác","e":"The project was exacting and required a lot of attention to detail.","ev":"Dự án này đòi hỏi sự chính xác và cần nhiều sự chú ý đến từng chi tiết.","k":"exacting"},{"t":"Evenhandedness","p":"n.","d":"công bằng","de":"công bằng","e":"strive for evenhandedness, save us from the errors of partisans and zealots.","ev":"phấn đấu cho sự công bằng, cứu chúng ta khỏi sai lầm của những kẻ theo đảng phái và những kẻ cuồng nhiệt.","k":"evenhandedness"},{"t":"distaste","p":"noun","d":"không ưa","de":"không ưa","e":"She felt a deep distaste for dishonesty in any form.","ev":"Cô cảm thấy sự ghê tởm sâu sắc đối với sự không trung thực dưới bất kỳ hình thức nào.","k":"distaste"},{"t":"truculent, \ntruculence","p":"adjective/noun","d":"hung hãn, \nsự hung hãn","de":"hung dữ, \nsự hung hãn","e":"The truculent attitude of the player led to several penalties during the game.","ev":"Thái độ hung hãn của cầu thủ đã dẫn đến nhiều hình phạt trong trận đấu.","k":"truculent, truculence"},{"t":"diffident, diffidence","p":"adjective/noun","d":"khác, khác","de":"khác biệt, khác biệt","e":"Her diffident manner made her hesitant to speak up in meetings.","ev":"Cách cư xử nhút nhát của cô khiến cô do dự khi phát biểu trong các cuộc họp.","k":"diffident, diffidence"},{"t":"automaton","p":"noun","d":"máy tự động","de":"máy tự động","e":"He moved through life like an automaton, going through the motions without passion.","ev":"Anh sống như một người máy, thực hiện mọi việc mà không có đam mê.","k":"automaton"},{"t":"desecration","p":"noun","d":"sự kiện","de":"sự xúc phạm","e":"The desecration of the historic site sparked outrage among the community.","ev":"Hành vi xúc phạm địa điểm lịch sử đã gây ra sự phẫn nộ trong cộng đồng.","k":"desecration"},{"t":"mercenary","p":"noun","d":"Đơn vị đánh","de":"lính đánh thuê","e":"The mercenary soldier fought for whoever paid the highest wage.","ev":"Người lính đánh thuê chiến đấu cho bất cứ ai trả lương cao nhất.","k":"mercenary"},{"t":"dupe","p":"verb","d":"lừa đảo","de":"lừa đảo","e":"Don't let him dupe you with his charm.","ev":"Đừng để anh ta lừa gạt bạn bằng sự quyến rũ của mình.","k":"dupe"},{"t":"slipshod","p":"adj","d":"sự chân","de":"sự trượt chân","e":"She complained that the carpenter's work had been slipshod.","ev":"Cô ấy phàn nàn rằng sản phẩm của người thợ mộc thật cẩu thả","k":"slipshod"},{"t":"exemplar","p":"noun","d":"mẫu","de":"gương mẫu","e":"She serves as an exemplar of hard work and dedication for her colleagues.","ev":"Cô ấy là hình mẫu của sự chăm chỉ và cống hiến cho đồng nghiệp của mình.","k":"exemplar"},{"t":"frugal(ity)","p":"adj","d":"( ) họ","de":"(sự) tiết kiệm","e":"He lived a frugal lifestyle, saving money wherever he could.","ev":"Anh sống một cuộc sống tiết kiệm, tiết kiệm tiền bất cứ khi nào có thể.","k":"frugal(ity)"},{"t":"stock (adjective)","p":"adj","d":"chứng từ (tính từ)","de":"chứng khoán (tính từ)","e":"The stock response from the spokesperson lacked genuine insight into the issue.","ev":"Phản ứng theo mẫu từ người phát ngôn thiếu sự hiểu biết chân thật về vấn đề.","k":"stock (adjective)"},{"t":"prattle","p":"verb/noun","d":"câu chuyện tầm cao","de":"chuyện tầm phào","e":"They engaged in prattle, discussing trivial matters instead of the main topic.","ev":"Họ đã nói nhảm, bàn về những vấn đề tầm thường thay vì chủ đề chính.","k":"prattle"},{"t":"somber","p":"adjective","d":"Mã số","de":"ảm đạm","e":"The somber mood at the funeral reflected the loss felt by everyone.","ev":"Bầu không khí u ám tại tang lễ phản ánh nỗi mất mát mà mọi người đều cảm thấy.","k":"somber"},{"t":"enigma(tic)","p":"noun","d":"bí ẩn(tic)","de":"bí ẩn(tic)","e":"The enigma of her disappearance puzzled everyone.","ev":"Bí ẩn về sự biến mất của cô ấy làm mọi người bối rối.","k":"enigma(tic)"},{"t":"conscientious","p":"adj","d":"tận tâm","de":"tận tâm","e":"She is a conscientious worker who pays attention to every detail.","ev":"Cô là một nhân viên tận tâm, luôn chú ý đến từng chi tiết.","k":"conscientious"},{"t":"steadfast","p":"adj","d":"kiên định","de":"kiên định","e":"She remained steadfast in her beliefs, even when challenged.","ev":"Cô giữ vững niềm tin của mình, ngay cả khi bị thách thức.","k":"steadfast"},{"t":"painstaking","p":"adj","d":"năng lực","de":"siêng năng","e":"Her painstaking attention to detail made her an excellent editor.","ev":"Sự chú ý tỉ mỉ đến từng chi tiết của cô đã làm cho cô trở thành một biên tập viên xuất sắc.","k":"painstaking"},{"t":"boorish, \nboorishness","p":"noun","d":"thô lỗ, \ntình trạng thô lỗ","de":"thô lỗ, \nsự thô lỗ","e":"His boorish behavior at the dinner party embarrassed everyone.","ev":"Hành vi thô lỗ của anh ấy tại bữa tiệc tối đã làm xấu hổ mọi người.","k":"boorish, boorishness"},{"t":"indict(ment)","p":"verb/noun","d":"cáo (ment)","de":"cáo trạng(ment)","e":"The indictment accused him of multiple counts of fraud.","ev":"Cáo trạng buộc tội anh về nhiều tội danh gian lận.","k":"indict(ment)"},{"t":"contempt(uous)","p":"adj","d":"khi (ous)","de":"khinh miệt (ous)","e":"She looked at the critic with a contemptuous expression after the harsh review.","ev":"Cô nhìn người phê bình bằng vẻ mặt khinh bỉ sau bài đánh giá gay gắt.","k":"contempt(uous)"},{"t":"repertory","p":"noun","d":"tiết mục","de":"tiết mục","e":"The repertory theater produces a variety of plays throughout the year.","ev":"Nhà hát lưu trữ sản xuất nhiều vở kịch khác nhau trong suốt cả năm.","k":"repertory"},{"t":"attenuate","p":"verb","d":"giảm","de":"giảm bớt","e":"The new law will attenuate the effects of pollution in the city.","ev":"Luật mới sẽ làm giảm tác động của ô nhiễm trong thành phố.","k":"attenuate"},{"t":"exposé","p":"noun","d":"ra","de":"phơi ra","e":"The exposé revealed the truth behind the scandal.","ev":"Bài báo điều tra tiết lộ sự thật về vụ bê bối.","k":"exposé"}]},{"n":"Ưu tiên 3 · 8","c":[{"t":"discern, discerning","p":"verb","d":"phân biệt, sáng suốt","de":"phân biệt, sáng suốt","e":"She could discern the subtle differences between the two paintings.","ev":"Cô có thể nhận biết những khác biệt tinh tế giữa hai bức tranh.","k":"discern, discerning"},{"t":"peremptory","p":"adj","d":"dự đoán độc lập","de":"độc đoán","e":"The boss's peremptory order left no room for discussion.","ev":"Lệnh hạ lệnh của sếp không để lại chỗ cho cuộc thảo luận.","k":"peremptory"},{"t":"staunch","p":"adj","d":"kiên quyết","de":"kiên quyết","e":"He is a staunch supporter of environmental protection policies.","ev":"Anh là một người ủng hộ vững chắc cho các chính sách bảo vệ môi trường.","k":"staunch"},{"t":"zealot","p":"noun","d":"Động vật hoang dã","de":"cuồng nhiệt","e":"The zealot could not tolerate any views that opposed his beliefs.","ev":"Người cuồng tín không thể chấp nhận bất kỳ quan điểm nào trái ngược với niềm tin của mình.","k":"zealot"},{"t":"opportunist, \nopportunistic","p":"adj/noun","d":"người có cơ sở, \ncơ sở","de":"người cơ hội, \ncơ hội","e":"The opportunist took advantage of the situation to advance his own agenda.","ev":"Kẻ cơ hội đã lợi dụng tình huống để thúc đẩy chương trình của riêng mình.","k":"opportunist, opportunistic"},{"t":"embitter(ed)","p":"adj","d":"cay đắng(ed)","de":"cay đắng(ed)","e":"Years of resentment had embittered him.","ev":"Nhiều năm oán hận đã làm cho anh ta cay đắng.","k":"embitter(ed)"},{"t":"treatise","p":"noun","d":"chuyên gia","de":"chuyên luận","e":"The treatise on philosophy provided a deep analysis of existential questions.","ev":"Luận văn về triết học đã cung cấp một phân tích sâu sắc về các câu hỏi tồn tại.","k":"treatise"},{"t":"lugubrious","d":"Ngập, bi thảm","de":"sầu thảm, bi thảm","e":"a lugubrious face","ev":"một khuôn mặt buồn thảm","k":"lugubrious"},{"t":"solace","p":"noun/verb","d":"sự an","de":"sự an ủi","e":"He found solace in music during difficult times.","ev":"Anh tìm thấy sự an ủi trong âm nhạc trong những lúc khó khăn.","k":"solace"},{"t":"jocular","p":"adjective","d":"vui tính","de":"vui tính","e":"His jocular personality made him the life of the party.","ev":"Tính cách vui vẻ của anh đã khiến anh trở thành tâm điểm của bữa tiệc.","k":"jocular"},{"t":"solicitous(ness)","p":"adj/noun","d":"sự quan tâm","de":"sự quan tâm","e":"She was solicitous about her friend’s well-being after the accident.","ev":"Cô đã rất quan tâm đến sức khỏe của bạn mình sau vụ tai nạn.","k":"solicitous(ness)"},{"t":"compendious","p":"adjective","d":"đầy đủ","de":"đầy đủ","e":"The book provides a compendious overview of modern philosophy in just a few chapters.","ev":"Cuốn sách cung cấp cái nhìn tổng quát ngắn gọn về triết học hiện đại chỉ trong vài chương.","k":"compendious"},{"t":"pronouncement","p":"noun","d":"sự kiện","de":"sự tuyên bố","e":"The pronouncement from the committee shocked everyone in attendance.","ev":"Tuyên bố từ ủy ban khiến mọi người có mặt đều sốc.","k":"pronouncement"},{"t":"depose","p":"verb","d":"hạ sé","de":"hạ bệ","e":"The council decided to depose the corrupt mayor after the investigation.","ev":"Hội đồng quyết định lật đổ thị trưởng tham nhũng sau cuộc điều tra.","k":"depose"},{"t":"wry","p":"adj","d":"Tôi","de":"nhăn nhó","e":"She gave a wry smile when she heard the ironic comment.","ev":"Cô mỉm cười châm biếm khi nghe nhận xét châm biếm.","k":"wry"},{"t":"oversight","p":"noun","d":"giám sát","de":"giám sát","e":"The oversight in the report led to significant errors in the final analysis.","ev":"Sự bỏ sót trong báo cáo đã dẫn đến những sai sót lớn trong phân tích cuối cùng.","k":"oversight"},{"t":"bipartisanship","p":"noun","d":"nhảy","de":"lưỡng đảng","e":"Bipartisanship is essential for passing significant legislation.","ev":"Sự hợp tác giữa hai đảng là cần thiết để thông qua các luật quan trọng.","k":"bipartisanship"},{"t":"obstinate, -acy","p":"adj","d":"cố chấp, -acy","de":"cố chấp, -acy","e":"His obstinate refusal to listen caused a rift in their relationship.","ev":"Việc anh cứng đầu từ chối lắng nghe đã gây ra một cuộc rạn nứt trong mối quan hệ của họ.","k":"obstinate, -acy"},{"t":"pacify","p":"verb","d":"làm đi","de":"làm dịu đi","e":"He tried to pacify the angry crowd with a sincere apology.","ev":"Anh cố gắng làm dịu lòng đám đông giận dữ bằng một lời xin lỗi chân thành.","k":"pacify"},{"t":"demystify","p":"verb","d":"làm sáng","de":"làm sáng tỏ","e":"The goal was to demystify complex theories.","ev":"Mục tiêu là làm rõ những lý thuyết phức tạp.","k":"demystify"},{"t":"irony, ironic","p":"noun","d":"mia mai, mia mai","de":"mỉa mai, mỉa mai","e":"The irony of the situation was not lost on anyone.","ev":"Sự mỉa mai của tình huống không bị bỏ qua với bất kỳ ai.","k":"irony, ironic"},{"t":"rampant","p":"adj","d":"đói","de":"hung hăng","e":"The rampant spread of misinformation is a serious issue in today's society.","ev":"Sự lan truyền tràn lan của thông tin sai lệch là một vấn đề nghiêm trọng trong xã hội ngày nay.","k":"rampant"},{"t":"uncouth","p":"adj","d":"thông qua","de":"thô lỗ","e":"His uncouth behavior at the formal dinner shocked the guests.","ev":"Hành vi thô lỗ của anh tại bữa tối trang trọng đã làm cho các vị khách sốc.","k":"uncouth"},{"t":"estrange, \nestrangement","p":"verb/noun","d":"lạnh lùng, \nlạnh giá","de":"ghẻ lạnh, \nsự ghẻ lạnh","e":"The estrangement between the siblings was painful to witness.","ev":"Sự xa cách giữa các anh chị em thật đau lòng khi chứng kiến.","k":"estrange, estrangement"},{"t":"dauntless","p":"adjective","d":"cảm","de":"dũng cảm","e":"His dauntless spirit inspired others to face their fears.","ev":"Tinh thần không sợ hãi của anh đã truyền cảm hứng cho người khác đối mặt với nỗi sợ hãi của họ.","k":"dauntless"}]},{"n":"Ưu tiên 3 · 9","c":[{"t":"peevish","p":"adjective","d":"Cắn xénh","de":"cáu kỉnh","e":"She was peevish and irritable after missing her morning coffee.","ev":"Cô trở nên cáu kỉnh và khó chịu sau khi bỏ lỡ ly cà phê buổi sáng.","k":"peevish"},{"t":"glutton(ous)","p":"noun/adj","d":"kẻ háu ăn (ous)","de":"kẻ háu ăn (ous)","e":"He was a glutton for punishment.","ev":"Anh ta là người tham ăn; thích chịu đựng khổ sở.","k":"glutton(ous)"},{"t":"precarious","p":"adj","d":"bấp","de":"bấp bênh","e":"The precarious situation required careful handling.","ev":"Tình huống không ổn định đòi hỏi sự xử lý cẩn thận.","k":"precarious"},{"t":"tenacious, tenacity","p":"adj/n","d":"sự mạnh mẽ, sự mạnh mẽ","de":"sự kiên cường, sự kiên cường","e":"Her tenacious efforts to improve her skills eventually paid off.","ev":"Nỗ lực kiên trì của cô để cải thiện kỹ năng cuối cùng đã được đền đáp.","k":"tenacious, tenacity"},{"t":"ineptitude","p":"noun","d":"sự kém chất lượng","de":"sự kém cỏi","e":"His ineptitude in handling the situation caused further complications.","ev":"Sự bất tài của anh trong việc xử lý tình huống đã gây ra những phức tạp thêm.","k":"ineptitude"},{"t":"erudite, erudition","p":"noun","d":"nguyên bác, nguyên bác","de":"uyên bác, uyên bác","e":"The erudite professor captivated the students with his extensive knowledge.","ev":"Giáo sư uyên bác đã thu hút sinh viên bằng kiến thức phong phú của mình.","k":"erudite, erudition"},{"t":"florid(ity)","p":"adjective/noun","d":"hoa mỹ (thành phố)","de":"hoa mỹ (ity)","e":"The author's floridity in writing can make even simple ideas seem extravagant.","ev":"Sự hoa mỹ trong cách viết của tác giả có thể khiến ngay cả những ý tưởng đơn giản cũng trở nên cầu kỳ.","k":"florid(ity)"},{"t":"flummox","p":"verb","d":"thất thường","de":"thất thường","e":"The unexpected question flummoxed him, leaving him speechless.","ev":"Câu hỏi bất ngờ đã khiến anh bối rối, để lại anh trong trạng thái câm lặng.","k":"flummox"},{"t":"foolhardy","p":"adj","d":"sự","de":"sự liều lĩnh","e":"It was foolhardy to attempt such a dangerous climb without proper equipment.","ev":"Thật ngu ngốc khi cố gắng leo núi nguy hiểm như vậy mà không có thiết bị thích hợp.","k":"foolhardy"},{"t":"chagrin","p":"noun","d":"sự thất bại","de":"sự thất vọng","e":"To her chagrin, she realized she had forgotten her friend’s birthday.","ev":"Đến nỗi xấu hổ, cô nhận ra rằng mình đã quên sinh nhật của bạn.","k":"chagrin"},{"t":"embroil(ed)","p":"verb","d":"Ồ (ed)","de":"thêu (ed)","e":"The company became embroiled in a legal dispute over its new product line.","ev":"Công ty đã bị cuốn vào một tranh chấp pháp lý liên quan đến dòng sản phẩm mới.","k":"embroil(ed)"},{"t":"decimate","p":"verb","d":"tàn sát","de":"tàn sát","e":"The disease could decimate the population.","ev":"Bệnh dịch có thể tiêu diệt dân số.","k":"decimate"},{"t":"vindicate, \nvindication","p":"verb/noun","d":"minh oan, \nsự minh oan","de":"minh oan, \nsự minh oan","e":"The evidence helped to vindicate her after the allegations were made.","ev":"Bằng chứng đã giúp biện minh cho cô sau khi có những cáo buộc được đưa ra.","k":"vindicate, vindication"},{"t":"churlish","p":"adj","d":"qu/ phá","de":"quậy phá","e":"His churlish remarks during the meeting alienated his colleagues.","ev":"Những nhận xét thô lỗ của anh trong cuộc họp đã làm xa lánh đồng nghiệp.","k":"churlish"},{"t":"stagnant, \nstagnation","p":"adjective/noun","d":"trì hoãn, \nsự trì hoãn","de":"trì trệ, \nsự trì trệ","e":"The stagnant water in the pond was a breeding ground for mosquitoes.","ev":"Nước đọng trong ao là môi trường sinh sản cho muỗi.","k":"stagnant, stagnation"},{"t":"indeterminate","p":"adj","d":"không xác định","de":"không xác định","e":"The outcome was indeterminate until the last minute.","ev":"Kết quả không xác định cho đến phút cuối.","k":"indeterminate"},{"t":"recluse, reclusive","p":"noun/adjective","d":"ẩn dật, ẩn dật","de":"ẩn dật, ẩn dật","e":"He lived as a recluse, rarely leaving his home or interacting with others.","ev":"Anh sống như một người ẩn dật, hiếm khi rời khỏi nhà hoặc giao tiếp với người khác.","k":"recluse, reclusive"},{"t":"disputatious","p":"adjective","d":"gây tranh cãi","de":"gây tranh cãi","e":"Her disputatious nature often led to arguments with her colleagues.","ev":"Tính cách thích tranh cãi của cô thường dẫn đến những cuộc cãi vã với đồng nghiệp.","k":"disputatious"},{"t":"incubate","p":"verb","d":"u","de":"ủ","e":"The eggs will incubate for about three weeks before hatching.","ev":"Những quả trứng sẽ được ấp trong khoảng ba tuần trước khi nở.","k":"incubate"},{"t":"consternation","p":"noun","d":"sự trẻ","de":"sự sửng sốt","e":"The announcement of layoffs caused consternation among the employees.","ev":"Thông báo về việc cắt giảm nhân sự đã gây ra sự hoang mang trong số nhân viên.","k":"consternation"},{"t":"shroud","p":"adj","d":"tấm vải liệm","de":"tấm vải liệm","e":"The fog acted like a shroud over the city.","ev":"Sương mù bao phủ thành phố như một lớp khăn.","k":"shroud"},{"t":"abhor, abhorrence","p":"verb/noun","d":"rượu vang, rượu vang","de":"ghê tởm, ghê tởm","e":"He abhors cruelty to animals and advocates for their protection.","ev":"Anh ấy ghê tởm sự tàn ác đối với động vật và ủng hộ việc bảo vệ chúng.","k":"abhor, abhorrence"},{"t":"redolent","p":"adj","d":"có mùi thơm","de":"có mùi hôi","e":"The garden was redolent of roses.","ev":"Khu vườn có mùi thơm của hoa hồng.","k":"redolent"},{"t":"luxuriant","p":"adj","d":"um4m","de":"um tùm","e":"The luxuriant gardens were filled with exotic plants and flowers.","ev":"Những khu vườn tươi tốt đầy những loại cây và hoa kỳ lạ.","k":"luxuriant"},{"t":"temporize","p":"verb","d":"tạm thời","de":"tạm thời","e":"They decided to temporize until a decision was made.","ev":"Họ quyết định trì hoãn cho đến khi có quyết định.","k":"temporize"}]},{"n":"Ưu tiên 3 · 10","c":[{"t":"vanquish","p":"verb","d":"đánh","de":"đánh bại","e":"They aimed to vanquish their opponents.","ev":"Họ nhằm mục đích đánh bại đối thủ.","k":"vanquish"},{"t":"laggard","p":"noun/adjective","d":"lạc","de":"lạc hậu","e":"The laggard student finally turned in his assignment after much delay.","ev":"Sinh viên chậm chạp cuối cùng cũng đã nộp bài tập của mình sau nhiều lần trì hoãn.","k":"laggard"},{"t":"notoriety, \nnotorious","p":"noun/adj","d":"tai tiếng, khét tiếng","de":"tai tiếng, \nkhét tiếng","e":"The notoriety of the criminal made headlines across the country.","ev":"Sự nổi tiếng xấu của tội phạm đã khiến các tiêu đề trên toàn quốc.","k":"notoriety, notorious"},{"t":"rectify, rectitude","p":"noun","d":"sửa chữa, đúng đắn","de":"sửa chữa, sự đúng đắn","e":"They tried to rectify the situation.","ev":"Họ đã cố gắng chỉnh sửa tình huống.","k":"rectify, rectitude"},{"t":"ascetic, asceticism","p":"adj/noun","d":"sự đau khổ hạnh phúc","de":"sự khổ hạnh, sự khổ hạnh","e":"The ascetic monk lived a life of simplicity and self-denial.","ev":"Nhà sư khổ hạnh sống một cuộc đời giản dị và từ chối bản thân.","k":"ascetic, asceticism"},{"t":"altruistic, altruism","p":"adj","d":"xin vị tha, xin vị tha","de":"lòng vị tha, lòng vị tha","e":"His altruistic behavior showed a genuine concern for the well-being of others.","ev":"Hành vi vị tha của anh thể hiện sự quan tâm chân thành đến sự phúc lợi của người khác.","k":"altruistic, altruism"},{"t":"reverent","p":"adj","d":"tôn kính","de":"tôn kính","e":"She spoke in a reverent tone when discussing the contributions of the late professor.","ev":"Cô nói với tông giọng kính trọng khi thảo luận về những đóng góp của giáo sư đã qua đời.","k":"reverent"},{"t":"concur","p":"verb","d":"đồng hồ","de":"đồng tình","e":"The committee members concurred that the project should be postponed until further funding is secured.","ev":"Các thành viên trong ủy ban đồng ý rằng dự án nên được hoãn lại cho đến khi có thêm kinh phí.","k":"concur"},{"t":"degradation","p":"noun","d":"suy","de":"suy thoái","e":"The degradation of the environment is a pressing issue for our generation.","ev":"Sự suy thoái của môi trường là một vấn đề cấp bách cho thế hệ của chúng ta.","k":"degradation"},{"t":"aura","p":"noun","d":"hào quang","de":"hào quang","e":"She had an aura of confidence that drew people to her.","ev":"Cô ấy có một hào quang tự tin thu hút mọi người đến với mình.","k":"aura"},{"t":"fanaticism","p":"noun","d":"sự cao tín","de":"sự cuồng tín","e":"Fanaticism can lead to dangerous consequences in any ideology.","ev":"Sự cuồng tín có thể dẫn đến những hậu quả nguy hiểm trong bất kỳ hệ tư tưởng nào.","k":"fanaticism"},{"t":"encumbrance","p":"noun","d":"sự kiện trở","de":"sự cản trở","e":"He considered his debts an encumbrance.","ev":"Anh ta coi nợ nần của mình là một gánh nặng.","k":"encumbrance"},{"t":"faction","p":"noun","d":"phe","de":"phe phái","e":"The faction within the party was pushing for more radical changes.","ev":"Nhóm phái trong đảng đang thúc đẩy những thay đổi quyết liệt hơn.","k":"faction"},{"t":"ungainly","p":"adj","d":"vô duyên","de":"vô duyên","e":"The ungainly teenager tripped over his own feet while walking.","ev":"Cậu thanh niên vụng về đã vấp ngã vì chính đôi chân của mình khi đi bộ.","k":"ungainly"},{"t":"impasse","p":"noun","d":"sự tiếp theo","de":"sự bế tắc","e":"The negotiations reached an impasse, with neither side willing to compromise.","ev":"Các cuộc đàm phán đã đạt đến bế tắc, khi không bên nào sẵn sàng thỏa hiệp.","k":"impasse"},{"t":"sage","p":"noun","d":"Nhân vật","de":"hiền nhân","e":"The sage shared his wisdom with those who sought guidance.","ev":"Nhà hiền triết đã chia sẻ trí tuệ của mình với những người tìm kiếm sự hướng dẫn.","k":"sage"},{"t":"jovial","p":"adjective","d":"vui tính","de":"vui tính","e":"The jovial atmosphere at the family gathering made everyone feel welcome.","ev":"Bầu không khí vui vẻ trong buổi họp mặt gia đình khiến mọi người cảm thấy được chào đón.","k":"jovial"},{"t":"complacency, \ncomplacent","p":"noun/adj","d":"sự tự mãn,\ntự mãn","de":"sự tự mãn, \ntự mãn","e":"His complacency about his performance led to a lack of improvement.","ev":"Sự tự mãn của anh về hiệu suất của mình đã dẫn đến việc thiếu cải thiện.","k":"complacency, complacent"},{"t":"inhibit(ing)","p":"verb","d":"7 chế (ing)","de":"ức chế (ing)","e":"The drug can inhibit the growth of harmful bacteria.","ev":"Thuốc có thể ức chế sự phát triển của vi khuẩn có hại.","k":"inhibit(ing)"},{"t":"patronize","p":"verb","d":"giúp đỡ","de":"bảo trợ","e":"It’s not polite to patronize someone just because you think you know more than they do.","ev":"Không lịch sự khi hạ thấp ai đó chỉ vì bạn nghĩ rằng bạn biết nhiều hơn họ.","k":"patronize"},{"t":"vying","p":"verb","d":"ganh","de":"ganh đua","e":"The two companies are vying for the top position in the market.","ev":"Hai công ty đang cạnh tranh để giành vị trí hàng đầu trên thị trường.","k":"vying"},{"t":"motley","p":"noun","d":"ô","de":"sặc sỡ","e":"The motley crowd at the festival included people of all ages and backgrounds.","ev":"Đám đông đa dạng tại lễ hội bao gồm người thuộc đủ mọi lứa tuổi và nền tảng khác nhau.","k":"motley"},{"t":"urbane","p":"adj","d":"người thành thị","de":"người thành thị","e":"His urbane manner made him popular among his peers at the social event.","ev":"Cách cư xử lịch thiệp của anh khiến anh trở nên nổi bật trong mắt bạn bè tại sự kiện xã hội.","k":"urbane"},{"t":"decorum, decorous","p":"noun","d":"trang lộn, trang lộn","de":"trang nhã, trang nhã","e":"The decorum maintained at the event was impressive, with everyone behaving appropriately.","ev":"Sự lịch thiệp được duy trì tại sự kiện thật ấn tượng, với mọi người cư xử đúng mực.","k":"decorum, decorous"},{"t":"static (adjective)","p":"adjective","d":"(từ)","de":"tĩnh (tính từ)","e":"The static atmosphere in the room made everyone feel uncomfortable.","ev":"Bầu không khí tĩnh lặng trong phòng khiến mọi người cảm thấy không thoải mái.","k":"static (adjective)"}]},{"n":"Ưu tiên 3 · 11","c":[{"t":"insular(ity)","p":"adj/noun","d":"(ity) cách biệt","de":"(ity) cách biệt","e":"His insularity prevented him from understanding the broader implications of the issue.","ev":"Sự tách biệt của anh đã ngăn cản anh hiểu các tác động rộng lớn hơn của vấn đề.","k":"insular(ity)"},{"t":"apathetic, apathy","p":"adj/noun","d":"thờ ơ, thờ ơ","de":"thờ ơ, thờ ơ","e":"His apathetic response to the crisis surprised everyone.","ev":"Phản ứng thờ ơ của anh đối với cuộc khủng hoảng đã làm mọi người bất ngờ.","k":"apathetic, apathy"},{"t":"subversive","p":"adj","d":"đổ mưa","de":"lật đổ","e":"The subversive group aimed to undermine the government’s authority.","ev":"Nhóm nổi loạn nhằm mục đích làm suy yếu quyền lực của chính phủ.","k":"subversive"},{"t":"unruly","p":"adjective","d":"ng ông","de":"ngỗ ngược","e":"The unruly children made it difficult for the teacher to maintain order in the classroom.","ev":"Những đứa trẻ hỗn loạn đã khiến giáo viên khó giữ trật tự trong lớp học.","k":"unruly"},{"t":"encroaching","p":"verb","d":"lạm dụng sử dụng","de":"lấn chiếm","e":"The encroaching fog made it difficult to see the road ahead.","ev":"Sương mù đang đến gần khiến việc nhìn đường phía trước trở nên khó khăn.","k":"encroaching"},{"t":"Prophylactic","p":"adj","d":"phòng, phòng bệnh","de":"phòng ngừa, phòng bệnh","e":"a prophylactic intent","ev":"một ý định phòng ngừa","k":"prophylactic"}]},{"n":"Archaic · 1","c":[{"t":"Dost","d":"Do (second person singular of \"do\").","e":"\"Dost thou love me?\" — Shakespeare, Romeo and Juliet","ev":"\"Anh có yêu em không?\" - Shakespeare, Romeo và Juliet","k":"dost"},{"t":"Whilom","d":"Formerly, once upon a time.","e":"\"In the whilom days of chivalry.\" — Sir Walter Scott, Ivanhoe","ev":"\"Trong những ngày hào hiệp của tinh thần hiệp sĩ.\" — Ngài Walter Scott, Ivanhoe","k":"whilom"},{"t":"Ope","d":"Open.","e":"\"I ope the door to strangers.\" — John Milton, Paradise Lost","ev":"\"Tôi mở cửa cho người lạ.\" - John Milton, Thiên đường đã mất","k":"ope"},{"t":"Sojourn","d":"A temporary stay.","e":"\"During his sojourn in Paris, he met her.\" — Mary Shelley, Frankenstein","ev":"\"Trong thời gian lưu trú ở Paris, anh ấy đã gặp cô ấy.\" — Mary Shelley, Frankenstein","k":"sojourn"},{"t":"Twill","d":"It will.","e":"\"'Twill be a fearful night.\" — Mary Shelley, Frankenstein","ev":"\"'Sẽ là một đêm đáng sợ.\" — Mary Shelley, Frankenstein","k":"twill"},{"t":"Fain","d":"Willingly, eagerly.","e":"\"I would fain die a dry death.\" — Shakespeare, The Tempest","ev":"\"Tôi thà chết một cái chết khô khan.\" - Shakespeare, Cơn bão tố","k":"fain"},{"t":"Whence","d":"From where.","e":"\"Whence came you, sir?\" — Shakespeare, King Lear","ev":"“Ông đến từ đâu vậy, thưa ông?” - Shakespeare, Vua Lear","k":"whence"},{"t":"Oftentimes","d":"Frequently.","e":"\"He oftentimes wrote letters to his beloved.\" — Thomas Hardy, Tess of the d’Urbervilles","ev":"\"Anh ấy thường xuyên viết thư cho người mình yêu.\" — Thomas Hardy, Tess của d’Urbervilles","k":"oftentimes"},{"t":"Herewith","d":"With this.","e":"\"I send you herewith the documents.\" — Traditional Usage","ev":"\"Tôi gửi cho bạn tài liệu này.\" - Cách sử dụng truyền thống","k":"herewith"},{"t":"Forsooth","d":"Truly, in truth.","e":"\"Forsooth, I know not why I am so sad.\" — Shakespeare, The Merchant of Venice","ev":"\"Thật ra, tôi không biết tại sao tôi lại buồn đến thế.\" - Shakespeare, Người lái buôn thành Venice","k":"forsooth"},{"t":"Sooth","d":"Truth, reality.","e":"\"In sooth, I know not why I am so sad.\" — Shakespeare, The Merchant of Venice","ev":"\"Thật nhẹ nhõm, tôi không biết tại sao tôi lại buồn đến thế.\" - Shakespeare, Người lái buôn thành Venice","k":"sooth"},{"t":"Mayhap","d":"Perhaps, maybe.","e":"\"Mayhap it’s better this way.\" — Charlotte Bronte, Jane Eyre","ev":"“Có lẽ thế này tốt hơn.” — Charlotte Bronte, Jane Eyre","k":"mayhap"},{"t":"Ere","d":"Before.","e":"\"Ere the set of sun.\" — Shakespeare, Macbeth","ev":"\"Ere mặt trời lặn.\" — Shakespeare, Macbeth","k":"ere"},{"t":"Wherefore","d":"Why, for what reason.","e":"\"Wherefore art thou Romeo?\" — Shakespeare, Romeo and Juliet","ev":"\"Sao anh lại là Romeo?\" - Shakespeare, Romeo và Juliet","k":"wherefore"},{"t":"Hap","d":"Fortune, luck.","e":"\"By hap and chance he came upon a treasure.\" — Sir Walter Scott, The Monastery","ev":"\"Thật tình cờ, anh ấy đã tìm thấy một kho báu.\" - Ngài Walter Scott, Tu viện","k":"hap"},{"t":"Haply","d":"Perhaps, by chance.","e":"\"Haply for I am black.\" — Shakespeare, Othello","ev":"\"May mắn thay tôi là người da đen.\" - Shakespeare, Othello","k":"haply"},{"t":"Verily","d":"Truly, certainly.","e":"\"Verily, I say unto you.\" — The Bible, Matthew 5:18","ev":"\"Quả thật, tôi nói với bạn.\" - Kinh thánh, Ma-thi-ơ 5:18","k":"verily"},{"t":"Thee","d":"You (object form of 'thou').","e":"\"To love thee better after death.\" — Alfred Lord Tennyson, In Memoriam","ev":"\"Để yêu em tốt hơn sau khi chết.\" - Alfred Lord Tennyson, Tưởng nhớ","k":"thee"},{"t":"’Tis","d":"It is.","e":"\"’Tis the east, and Juliet is the sun.\" — Shakespeare, Romeo and Juliet","ev":"\"'Đây là hướng đông và Juliet là mặt trời.\" - Shakespeare, Romeo và Juliet","k":"'tis"},{"t":"Tarry","d":"Stay, linger.","e":"\"Tarry a little; there is something else.\" — Shakespeare, The Merchant of Venice","ev":"\"Chờ một chút, còn có chuyện khác.\" - Shakespeare, Người lái buôn thành Venice","k":"tarry"},{"t":"Hast","d":"Have or has (second person singular).","e":"\"Thou hast a grim appearance.\" — Shakespeare, Macbeth","ev":"“Ngươi có vẻ ngoài dữ tợn.” — Shakespeare, Macbeth","k":"hast"},{"t":"Thou","d":"You (informal, singular).","e":"\"Thou art more lovely and more temperate.\" — Shakespeare, Sonnet 18","ev":"\"Em đáng yêu hơn và ôn hòa hơn.\" — Shakespeare, Sonnet 18","k":"thou"},{"t":"Hark","d":"Listen, pay attention.","e":"\"Hark! The herald angels sing.\" — Traditional Christmas Carol","ev":"\"Hark! Các thiên thần báo trước đang hát.\" - Ca khúc Giáng sinh truyền thống","k":"hark"},{"t":"Ne’er","d":"Never.","e":"\"Ne’er saw I, never felt, a calm so deep!\" — William Wordsworth, Sonnet","ev":"\"Chưa từng thấy ta, chưa bao giờ cảm nhận được, một sự bình tĩnh sâu sắc như vậy!\" - William Wordsworth, Sonnet","k":"ne'er"},{"t":"Nay","d":"No, indeed not.","e":"\"Nay, I'll not leave thee.\" — Shakespeare, Othello","ev":"\"Không, tôi sẽ không rời xa em.\" - Shakespeare, Othello","k":"nay"}]},{"n":"Archaic · 2","c":[{"t":"Wilt","d":"Will (second person singular form of \"will\").","e":"\"Wilt thou leave me so unsatisfied?\" — Shakespeare, Romeo and Juliet","ev":"“Anh định để tôi không hài lòng đến thế sao?” - Shakespeare, Romeo và Juliet","k":"wilt"},{"t":"Yon/Yonder","d":"Distant, over there.","e":"\"What light through yonder window breaks?\" — Shakespeare, Romeo and Juliet","ev":"“Ánh sáng nào xuyên qua cửa sổ đằng kia?” - Shakespeare, Romeo và Juliet","k":"yon/yonder"},{"t":"Perchance","d":"Perhaps, maybe.","e":"\"Perchance you wonder at this show.\" — Shakespeare, A Midsummer Night's Dream","ev":"\"Có lẽ bạn thắc mắc về buổi biểu diễn này.\" - Shakespeare, Giấc mộng đêm hè","k":"perchance"},{"t":"Forthwith","d":"Immediately, without delay.","e":"\"Forthwith a change was made.\" — Charles Dickens, Great Expectations","ev":"\"Ngay lập tức một sự thay đổi đã được thực hiện.\" - Charles Dickens, Những kỳ vọng lớn lao","k":"forthwith"},{"t":"Thy","d":"Your (possessive form of 'thou').","e":"\"Thy kingdom come, thy will be done.\" — The Bible, Matthew 6:10","ev":"\"Vương quốc của Ngài đến, ý muốn của Ngài sẽ được thực hiện.\" - Kinh thánh, Ma-thi-ơ 6:10","k":"thy"},{"t":"Art","d":"Are (second person singular).","e":"\"Thou art as wise as thou art beautiful.\" — Shakespeare, A Midsummer Night's Dream","ev":"\"Em vừa khôn ngoan vừa xinh đẹp.\" - Shakespeare, Giấc mộng đêm hè","k":"art"},{"t":"Oft","d":"Often.","e":"\"Oft have I sighed to measure.\" — Sir Philip Sidney, Astrophil and Stella","ev":"“Thường tôi đã thở dài để đo.” — Ngài Philip Sidney, Astrophil và Stella","k":"oft"},{"t":"Twas","d":"It was.","e":"\"'Twas the night before Christmas.\" — Clement Clarke Moore, A Visit from St. Nicholas","ev":"\"'Đó là đêm trước lễ Giáng sinh.\" - Clement Clarke Moore, Chuyến viếng thăm từ Thánh Nicholas","k":"twas"},{"t":"Tis","d":"It is.","e":"\"'Tis now the very witching time of night.\" — Shakespeare, Hamlet","ev":"\"Bây giờ là thời điểm ban đêm huyền diệu nhất.\" - Shakespeare, Hamlet","k":"tis"},{"t":"Whatsoever","d":"Whatever.","e":"\"I have no pleasure in whatsoever is bought.\" — Shakespeare, The Merchant of Venice","ev":"\"Tôi không có hứng thú với bất cứ thứ gì được mua.\" - Shakespeare, Người lái buôn thành Venice","k":"whatsoever"},{"t":"Hither","d":"To this place.","e":"\"Come hither, young lad.\" — Shakespeare, King Lear","ev":"“Hãy đến đây, chàng trai trẻ.” - Shakespeare, Vua Lear","k":"hither"},{"t":"O’er","d":"Over.","e":"\"O'er hill and dale.\" — John Keats, Ode to a Nightingale","ev":"\"O'er đồi và dale.\" - John Keats, Ca ngợi chim sơn ca","k":"o'er"},{"t":"Whencever","d":"From wherever.","e":"\"Whencever thou comest, I shall welcome thee.\" — Traditional","ev":"\"Bất cứ khi nào bạn đến, tôi sẽ chào đón bạn.\" - Truyền thống","k":"whencever"},{"t":"Anon","d":"Soon, shortly.","e":"\"I will come to thee anon.\" — Shakespeare, Hamlet","ev":"“Tôi sẽ đến gặp anh vào lúc nào đó.” - Shakespeare, Hamlet","k":"anon"},{"t":"Aught","d":"Anything.","e":"\"Is there aught we can do to help?\" — Shakespeare, Macbeth","ev":"“Chúng tôi có thể giúp gì được không?” — Shakespeare, Macbeth","k":"aught"},{"t":"Whither","d":"To where, to which place.","e":"\"Whither goest thou?\" — John Bunyan, The Pilgrim's Progress","ev":"“Anh đi đâu thế?” — John Bunyan, Hành trình của người hành hương","k":"whither"},{"t":"Anigh","d":"Near.","e":"\"She was well anigh exhausted.\" — Thomas Hardy, Far From the Madding Crowd","ev":"\"Cô ấy đã kiệt sức rồi.\" — Thomas Hardy, Xa khỏi đám đông điên cuồng","k":"anigh"},{"t":"Doth","d":"Does (third-person singular form of 'do').","e":"\"The lady doth protest too much, methinks.\" — Shakespeare, Hamlet","ev":"“Có lẽ quý cô phản đối quá nhiều, tôi nghĩ vậy.” - Shakespeare, Hamlet","k":"doth"},{"t":"Unbeknownst","d":"Without the knowledge of.","e":"\"Unbeknownst to him, the letter was already sent.\" — Jane Austen, Pride and Prejudice","ev":"\"Anh ấy không hề biết rằng bức thư đã được gửi đi.\" - Jane Austen, Kiêu hãnh và định kiến","k":"unbeknownst"},{"t":"Anent","d":"Concerning, about.","e":"\"I shall write anent this matter soon.\" — Traditional Usage","ev":"\"Tôi sẽ viết thư về vấn đề này sớm.\" - Cách sử dụng truyền thống","k":"anent"},{"t":"Betwixt","d":"Between.","e":"\"There is a time betwixt and between.\" — Sir Walter Scott, Ivanhoe","ev":"\"Có một thời gian ở giữa và ở giữa.\" — Ngài Walter Scott, Ivanhoe","k":"betwixt"},{"t":"Ne’er-do-well","d":"A person of bad character, a troublemaker.","e":"\"A band of ne’er-do-wells roamed the town.\" — Charles Dickens, Oliver Twist","ev":"\"Một nhóm người vô dụng lang thang trong thị trấn.\" - Charles Dickens, Oliver Twist","k":"ne'er-do-well"},{"t":"Eftsoons","d":"Soon after.","e":"\"Eftsoons they heard a mighty crashing sound.\" — Edmund Spenser, The Faerie Queene","ev":"\"Eftsoons họ nghe thấy một âm thanh va chạm mạnh.\" — Edmund Spenser, Nữ hoàng thần tiên","k":"eftsoons"},{"t":"Unto","d":"To, until.","e":"\"I say unto you, love your enemies.\" — The Bible, Matthew 5:44","ev":"\"Tôi nói với bạn, hãy yêu kẻ thù của bạn.\" - Kinh thánh, Ma-thi-ơ 5:44","k":"unto"},{"t":"Methinks","d":"It seems to me.","e":"\"Methinks I see these things with parted eye.\" — Shakespeare, A Midsummer Night's Dream","ev":"\"Có vẻ như tôi nhìn những thứ này với con mắt rời rạc.\" - Shakespeare, Giấc mộng đêm hè","k":"methinks"}]},{"n":"Chưa phân loại · 1","c":[{"t":"Caustic","p":"adjective","d":"bitter, biting, acidic","e":"His caustic comments hurt many feelings and created tension in the room.","ev":"Những nhận xét châm biếm của anh đã làm tổn thương nhiều cảm xúc và tạo ra căng thẳng trong phòng.","k":"caustic"},{"t":"Anarchist","p":"noun","d":"one who wants to eliminate all government","e":"An anarchist, Carmine wanted to dissolve every government everywhere.","ev":"Là một kẻ vô chính phủ, Carmine muốn giải thể mọi chính phủ trên khắp nơi.","k":"anarchist"},{"t":"Retain","d":"to keep, to hold on to","e":"She retained her composure even in difficult situations, remaining calm and collected under pressure.","ev":"Cô vẫn giữ được bình tĩnh ngay cả trong những tình huống khó khăn, giữ bình tĩnh và tự chủ trước áp lực.","k":"retain"},{"t":"Fecund","p":"(adj.)","d":"fruitful, fertile","e":"The fecund tree bore enough apples to last us through the entire season.","ev":"Cái cây màu mỡ sinh ra đủ táo để chúng tôi ăn suốt cả mùa.","k":"fecund"},{"t":"Hypothetical","p":"(adj.)","d":"supposed or assumed true, but unproven","e":"Even though it has been celebrated by seven major newspapers, that the drug will be a success when tested in humans is still hypothetical.","ev":"Mặc dù đã được 7 tờ báo lớn tung hô nhưng việc loại thuốc này sẽ thành công khi thử nghiệm trên người vẫn chỉ là giả thuyết.","k":"hypothetical"},{"t":"Anthology","p":"noun","d":"a selected collection of writings, songs, etc.","e":"The new anthology of Bob Dylan songs contains all his greatest hits.","ev":"Tuyển tập mới về các bài hát của Bob Dylan chứa tất cả những bản hit lớn nhất của ông.","k":"anthology"},{"t":"Aquatic","p":"adjective","d":"relating to water","e":"The marine biologist studies aquatic creatures like starfish.","ev":"Nhà sinh vật học biển nghiên cứu các sinh vật dưới nước như sao biển.","k":"aquatic"},{"t":"Threshold","d":"the level or point at which something starts","e":"He crossed the threshold of the house.","ev":"Anh bước qua ngưỡng cửa ngôi nhà.","k":"threshold"},{"t":"Becoming","d":"fitting, attractive","e":"That's a very becoming dress, my dear.","ev":"Đó là một chiếc váy rất hợp đấy, em yêu.","k":"becoming"},{"t":"Sparse","d":"small in number, often spread over a large area; scarce","e":"The vegetation was sparse in the desert, with few plants growing in the harsh conditions.","ev":"Thảm thực vật thưa thớt trên sa mạc, có rất ít loài thực vật phát triển trong điều kiện khắc nghiệt.","k":"sparse"},{"t":"Rapport","p":"noun","d":"mutual understanding and harmony","e":"They quickly developed a strong rapport through their shared interests.","ev":"Họ nhanh chóng phát triển được một mối quan hệ tốt đẹp nhờ những sở thích chung.","k":"rapport"},{"t":"Solidarity","d":"n. the joining of commonalities or common purposes among a group","e":"n. the joining of commonalities or common purposes among a group","ev":"N. sự tham gia của những điểm chung hoặc mục đích chung giữa một nhóm","k":"solidarity"},{"t":"Felicitous","p":"adjective","d":"well suited, apt","e":"His felicitous remarks lightened the mood during the serious discussion.","ev":"Những nhận xét phù hợp của anh đã làm nhẹ bầu không khí trong cuộc thảo luận nghiêm túc.","k":"felicitous"},{"t":"Atypical","p":"adj.","d":"not typical, unusual","e":"Screaming and crying is atypical adult behavior.","ev":"La hét và khóc không phải là hành vi bình thường của người lớn.","k":"atypical"},{"t":"Lavish","p":"(adj.)","d":"given without limits","e":"Because they had worked very hard, the performers appreciated the critic’s lavish praise.","ev":"Bởi vì họ đã làm việc rất chăm chỉ nên các nghệ sĩ biểu diễn đánh giá cao lời khen ngợi không tiếc lời của nhà phê bình.","x":"Loại từ 2: (v.)\nNghĩa 2: to give without limits\nVí dụ 2: Because the performers had worked hard, they deserved the praise that the critic lavished on them.","k":"lavish"},{"t":"Garrulous","p":"(adj.)","d":"talkative, wordy","e":"Some talk show hosts are so garrulous that their guests can’t get a word in edgewise.","ev":"Một số người dẫn chương trình trò chuyện nói nhiều đến mức khách của họ không thể hiểu được lời nào.","k":"garrulous"},{"t":"Endeavor","d":"to try hard to do something","e":"They made a concerted endeavor to improve the situation, working together towards a common goal.","ev":"Họ đã nỗ lực phối hợp để cải thiện tình hình, cùng nhau hướng tới một mục tiêu chung.","k":"endeavor"},{"t":"Bilk","p":"(v.)","d":"cheat, defraud","e":"The lawyer discovered that this firm had bilked several clients out of thousands of dollars.","ev":"Luật sư phát hiện ra rằng công ty này đã lừa đảo một số khách hàng hàng ngàn đô la.","k":"bilk"},{"t":"Attain","p":"verb","d":"to achieve, arrive at","e":"She worked hard to attain her goal of becoming a doctor.","ev":"Cô ấy đã làm việc chăm chỉ để đạt được mục tiêu trở thành bác sĩ.","k":"attain"},{"t":"Effluvia","d":"unpleasant or harmful gases or fumes","e":"The factory emitted noxious effluvia.","ev":"Nhà máy thải ra khí thải độc hại.","k":"effluvia"},{"t":"Displace","d":"to force something or someone out of its usual or original place","e":"The flood displaced many people from their homes.","ev":"Lũ lụt đã khiến nhiều người phải rời bỏ nhà cửa.","k":"displace"},{"t":"Vex","p":"(v.)","d":"to confuse or annoy","e":"My little brother vexes me by poking me in the ribs for hours on end.","ev":"Em trai tôi chọc tức tôi bằng cách chọc vào sườn tôi hàng giờ liền.","k":"vex"},{"t":"Etymology","p":"(n.)","d":"the history of words, their origin and development","e":"From the study of etymology, I know that the word “quixotic” derives from Don Quixote and the word “gaudy” refers to the Spanish architect Gaudí.","ev":"Qua nghiên cứu từ nguyên, tôi biết từ “quixotic” có nguồn gốc từ Don Quixote và từ “gaudy” ám chỉ kiến ​​trúc sư người Tây Ban Nha Gaudí.","k":"etymology"},{"t":"Petulance","p":"(n.)","d":"rudeness, irritability","e":"The Nanny resigned after she could no longer tolerate the child’s petulance.","ev":"Người bảo mẫu đã từ chức sau khi không thể chịu đựng được sự nóng nảy của đứa trẻ nữa.","k":"petulance"},{"t":"Venerable","p":"adj","d":"deserving of respect because of age or achievement","e":"The venerable professor was respected by all his students for his wisdom.","ev":"Giáo sư uy tín được tất cả sinh viên tôn trọng vì trí tuệ của ông.","k":"venerable"}]},{"n":"Chưa phân loại · 2","c":[{"t":"Convivial","p":"adjective","d":"characterized by feasting, drinking, merriment","e":"The party was a convivial gathering filled with laughter and good food.","ev":"Bữa tiệc là một buổi tụ tập vui vẻ đầy tiếng cười và món ăn ngon.","k":"convivial"},{"t":"Asylum","p":"noun","d":"a place of refuge, protection, a sanctuary","e":"(1) The forest served as an asylum from the pressures of city life. (2) After his diagnosis, he was admitted to an asylum.","ev":"(1) Rừng rậm là nơi trú ẩn khỏi áp lực của cuộc sống thành phố. (2) Sau khi được chẩn đoán, ông đã được đưa vào một viện tâm thần.","k":"asylum"},{"t":"Diffident","p":"(adj.)","d":"shy, quiet, modest","e":"While eating dinner with the adults, the diffident youth did not speak for fear of seeming presumptuous.","ev":"Trong khi ăn tối với người lớn, chàng thanh niên rụt rè không nói gì vì sợ có vẻ tự phụ.","k":"diffident"},{"t":"Antagonism","p":"noun","d":"hostility","e":"Superman and Bizarro Superman shared a mutual antagonism, and often fought.","ev":"Superman và Bizarro Superman có sự thù địch lẫn nhau và thường xuyên chiến đấu.","k":"antagonism"},{"t":"Vigilant","p":"adj","d":"watchful, alert","e":"She remained vigilant during the night.","ev":"Cô ấy luôn cảnh giác suốt đêm.","k":"vigilant"},{"t":"Variegated","p":"(adj.)","d":"diversified, distinctly marked","e":"Each wire in the engineering exam was variegated by color so that the students could figure out which one was which.","ev":"Mỗi dây trong kỳ thi kỹ thuật đều có nhiều màu sắc khác nhau để học sinh có thể nhận ra đâu là dây nào.","k":"variegated"},{"t":"Posterity","d":"all future generations of people","e":"He hoped to be remembered by posterity as a great leader.","ev":"Ông hy vọng sẽ được hậu thế ghi nhớ như một nhà lãnh đạo vĩ đại.","k":"posterity"},{"t":"Enfranchise","p":"(v.)","d":"to grant the vote to","e":"The Nineteenth Amendment enfranchised women.","ev":"Bản sửa đổi thứ mười chín đã trao quyền cho phụ nữ.","k":"enfranchise"},{"t":"Verdant","p":"(adj.)","d":"green in tint or color","e":"The verdant leaves on the trees made the world look emerald.","ev":"Những chiếc lá xanh tươi trên cây khiến thế giới trông như màu ngọc lục bảo.","k":"verdant"},{"t":"Vow","p":"v.","d":"to make a firm promise or decision to do something","e":"They vowed (that) they would never forget her kindness.","ev":"Họ thề rằng họ sẽ không bao giờ quên lòng tốt của cô ấy.","k":"vow"},{"t":"Inundate","p":"verb","d":"to flood with abundance","e":"The heavy rains will inundate the fields, causing flooding in the area.","ev":"Những cơn mưa lớn sẽ làm ngập các cánh đồng, gây ra lũ lụt trong khu vực.","k":"inundate"},{"t":"Repulse","p":"(v.)","d":"to disgust","e":"Antisocial Annie tried to repulse people by neglecting to brush her teeth.","ev":"Annie chống đối xã hội đã cố gắng đẩy lùi mọi người bằng cách bỏ bê việc đánh răng.","x":"Nghĩa 2: to push back\nVí dụ 2: With a deft movement of her wrist and a punch to the stomach, Lacy repulsed Jack’s attempt to kiss her.","k":"repulse"},{"t":"Inchoate","p":"(adj.)","d":"unformed or formless, in a beginning stage","e":"The country’s government is still inchoate and, because it has no great tradition, quite unstable.","ev":"Chính phủ nước này vẫn còn non trẻ và vì không có truyền thống tốt đẹp nên khá bất ổn.","k":"inchoate"},{"t":"Cherish","p":"(v.)","d":"to feel or show affection toward something","e":"She continued to cherish her red plaid trousers, even though they had gone out of style and no longer fit her.","ev":"Cô vẫn tiếp tục nâng niu chiếc quần kẻ sọc đỏ của mình, dù chúng đã lỗi thời và không còn vừa với cô nữa.","k":"cherish"},{"t":"Inquisition","d":"interrogation, questioning","e":"The inquisition was a period of religious persecution, with people being tortured and executed for their beliefs.","ev":"Tòa án dị giáo là thời kỳ đàn áp tôn giáo, với những người bị tra tấn và hành quyết vì niềm tin của họ.","k":"inquisition"},{"t":"Paradigm","p":"noun","d":"an example that is a perfect pattern or model","e":"The new paradigm in technology is changing how we communicate.","ev":"Mô hình mới trong công nghệ đang thay đổi cách chúng ta giao tiếp.","k":"paradigm"},{"t":"Amorous","p":"adjective","d":"showing love, particularly sexual","e":"Whenever Albert saw Mariah in her slinky red dress, he felt quite amorous.","ev":"Mỗi khi Albert thấy Mariah trong chiếc đầm đỏ quyến rũ, anh cảm thấy rất say đắm.","k":"amorous"},{"t":"Tact","d":"skillfulness and sensitivity in dealing with others or difficult issues","e":"He handled the delicate situation with tact, choosing his words carefully and avoiding offending anyone.","ev":"Anh ấy xử lý tình huống tế nhị một cách khéo léo, lựa chọn lời nói cẩn thận và tránh làm mất lòng bất cứ ai.","k":"tact"},{"t":"Vestigial","d":"undeveloped, nonfunctional","e":"He had a vestigial tailbone, a remnant from his evolutionary past that served no purpose in humans.","ev":"Anh ta có một chiếc xương cụt tàn tích, tàn tích từ quá khứ tiến hóa của anh ta và không có mục đích gì đối với con người.","k":"vestigial"},{"t":"Oration","p":"(n.)","d":"a speech delivered in a formal or ceremonious manner","e":"The prime minister was visibly shaken when the unruly parliament interrupted his oration about failed domestic policies.","ev":"Thủ tướng rõ ràng đã bị chấn động khi quốc hội ngang ngược cắt ngang bài phát biểu của ông về các chính sách đối nội thất bại.","k":"oration"},{"t":"Adorn","p":"verb","d":"to decorate","e":"We adorned the tree with ornaments for the holiday.","ev":"Chúng tôi đã trang trí cây với những món đồ trang trí cho ngày lễ.","k":"adorn"},{"t":"Duress","p":"(n.)","d":"hardship, threat","e":"It was only under intense duress that he, who was normally against killing, fired his gun.","ev":"Chỉ dưới sự cưỡng ép mãnh liệt, anh ta, người thường chống lại việc giết chóc, mới nổ súng.","k":"duress"},{"t":"Cursory","p":"adj","d":"brief to the point of being superficial","e":"He gave the report a cursory glance before submitting it.","ev":"Anh chỉ liếc qua báo cáo một cách hời hợt trước khi nộp.","k":"cursory"},{"t":"Bashful","p":"adj.","d":"shy, excessively timid","e":"Frankie’s mother told him not to be bashful at the party.","ev":"Mẹ của Frankie bảo cậu đừng ngại ngùng khi tham gia bữa tiệc.","k":"bashful"},{"t":"Incontrovertible","p":"(adj.)","d":"indisputable","e":"Only stubborn Tina would attempt to disprove the incontrovertible laws of physics.","ev":"Chỉ có Tina bướng bỉnh mới cố gắng bác bỏ các định luật vật lý không thể chối cãi.","k":"incontrovertible"}]},{"n":"Chưa phân loại · 3","c":[{"t":"Colloquial","p":"(adj.)","d":"characteristic of informal conversation","e":"Adam’s essay on sexual response in primates was marked down because it contained too many colloquial expressions.","ev":"Bài tiểu luận của Adam về phản ứng tình dục ở loài linh trưởng đã bị đánh dấu vì nó chứa quá nhiều cách diễn đạt thông tục.","k":"colloquial"},{"t":"Mocking","d":"making fun of someone or something in a cruel way","e":"His mocking tone made it clear that he was ridiculing her.","ev":"Giọng điệu chế giễu của anh cho thấy rõ anh đang chế nhạo cô.","k":"mocking"},{"t":"Rebuke","p":"(v.)","d":"to scold, criticize","e":"When the cops showed up at Sarah’s party, they rebuked her for disturbing the peace.","ev":"Khi cảnh sát xuất hiện tại bữa tiệc của Sarah, họ đã khiển trách cô vì đã làm xáo trộn hòa bình.","k":"rebuke"},{"t":"Colossus","p":"(n.)","d":"a gigantic statue or thing","e":"For 56 years, the ancient city of Rhodes featured a colossus standing astride its harbor.","ev":"Trong 56 năm, thành phố cổ Rhodes có một bức tượng khổng lồ đứng trên bến cảng.","k":"colossus"},{"t":"Renown","p":"(n.)","d":"honor, acclaim","e":"The young writer earned international renown by winning the Pulitzer Prize.","ev":"Nhà văn trẻ đã nổi tiếng quốc tế nhờ đoạt giải Pulitzer.","k":"renown"},{"t":"Nomadic","p":"(adj.)","d":"wandering from place to place","e":"In the first six months after college, Jose led a nomadic life, living in New York, California, and Idaho.","ev":"Trong sáu tháng đầu tiên sau đại học, Jose sống cuộc sống du mục, sống ở New York, California và Idaho.","k":"nomadic"},{"t":"Refract","p":"(v.)","d":"to distort, change","e":"The light was refracted as it passed through the prism.","ev":"Ánh sáng bị khúc xạ khi đi qua lăng kính.","k":"refract"},{"t":"Discomfit","p":"(v.)","d":"to thwart, baffle","e":"The normally cheery and playful children’s sudden misery discomfited the teacher.","ev":"Sự đau khổ đột ngột của những đứa trẻ thường vui tươi và vui tươi làm giáo viên cảm thấy khó chịu.","k":"discomfit"},{"t":"Hackneyed","p":"adj","d":"unoriginal, trite","e":"The movie was criticized for its hackneyed plot and clichéd characters.","ev":"Bộ phim bị chỉ trích vì cốt truyện tầm thường và các nhân vật rập khuôn.","k":"hackneyed"},{"t":"Somnolent","p":"(adj.)","d":"sleepy, drowsy","e":"The somnolent student kept falling asleep and waking up with a jerk.","ev":"Cậu sinh viên buồn ngủ cứ ngủ quên và giật mình tỉnh dậy.","k":"somnolent"},{"t":"Convention","p":"noun","d":"an assembly of people","e":"1. The hotel was full because of the cattle ranchers’ convention. 2. The cattle-ranchers have a convention that you take off your boots before entering their houses.","ev":"1. Khách sạn đầy vì hội nghị của những người chăn nuôi gia súc. 2. Có quy tắc là phải bỏ giày trước khi vào nhà họ.","k":"convention"},{"t":"Eloquent","p":"(adj.)","d":"expressive, articulate, moving","e":"The priest gave such an eloquent sermon that most churchgoers were crying.","ev":"Vị linh mục đã giảng một bài giảng hùng hồn đến nỗi hầu hết những người đi nhà thờ đều khóc.","k":"eloquent"},{"t":"Supplemental","d":"added to something else in order to improve it or complete it","e":"The supplemental income helped her make ends meet.","ev":"Thu nhập bổ sung đã giúp cô trang trải cuộc sống.","k":"supplemental"},{"t":"Rescind","p":"verb","d":"to take back, repeal","e":"The organization decided to rescind the policy due to public outcry.","ev":"Tổ chức đã quyết định hủy bỏ chính sách do phản đối từ công chúng.","k":"rescind"},{"t":"Affront","p":"noun","d":"an insult","e":"Bernardo was very touchy, and took any slight as an affront to his honor.","ev":"Bernardo rất nhạy cảm, và coi bất kỳ sự xúc phạm nào là một sự sỉ nhục đối với danh dự của mình.","k":"affront"},{"t":"Mutable","p":"(adj.)","d":"able to change","e":"Because fashion is so mutable, what is trendy today will look outdated in five years.","ev":"Bởi vì thời trang rất dễ thay đổi nên những gì hợp thời trang ngày nay sẽ trở nên lỗi thời sau 5 năm nữa.","k":"mutable"},{"t":"Conduct","d":"v. to control or manage","e":"v. to control or manage","ev":"v. kiểm soát hoặc quản lý","k":"conduct"},{"t":"Pulchritude","p":"(n.)","d":"physical beauty","e":"Several of Shakespeare’s sonnets explore the pulchritude of a lovely young man.","ev":"Một số bài sonnet của Shakespeare khám phá vẻ đẹp tâm hồn của một chàng trai trẻ đáng yêu.","k":"pulchritude"},{"t":"Proffer","d":"to offer advice or an opinion","e":"The scientist proffered a new theory to explain the phenomenon.","ev":"Nhà khoa học đưa ra một lý thuyết mới để giải thích hiện tượng này.","x":"Ví dụ 2: Make a Claim","k":"proffer"},{"t":"Aberration","p":"noun","d":"something that differs from the norm","e":"The sudden change in his behavior was seen as an aberration by his friends.","ev":"Sự thay đổi đột ngột trong hành vi của anh được bạn bè coi là một sự lầm lạc.","k":"aberration"},{"t":"Pariah","p":"(n.)","d":"an outcast","e":"Following the discovery of his plagiarism, Professor Hurley was made a pariah in all academic circles.","ev":"Sau khi bị phát hiện đạo văn, Giáo sư Hurley bị coi là kẻ bị ruồng bỏ trong mọi giới học thuật.","k":"pariah"},{"t":"Rectitude","p":"(n.)","d":"uprightness, extreme morality","e":"The priest’s rectitude gave him the moral authority to counsel his parishioners.","ev":"Sự chính trực của vị linh mục đã cho ông thẩm quyền đạo đức để tư vấn cho giáo dân của mình.","k":"rectitude"},{"t":"Decorous","p":"(adj.)","d":"socially proper, appropriate","e":"The appreciative guest displayed decorous behavior toward his host.","ev":"Vị khách quý đã thể hiện thái độ lịch sự đối với chủ nhà.","k":"decorous"},{"t":"Depravity","p":"noun","d":"wickedness, đồi bại","e":"His depravity shocked everyone at the party.","ev":"Sự suy đồi của anh ta đã khiến mọi người sốc tại bữa tiệc.","k":"depravity"},{"t":"Perturb","d":"to make someone anxious or unsettled; to disturb","e":"The strange noise perturbed her, making her feel uneasy and anxious.","ev":"Tiếng động lạ làm cô bối rối, khiến cô cảm thấy bất an và lo lắng.","k":"perturb"}]},{"n":"Chưa phân loại · 4","c":[{"t":"Vituperate","p":"(v.)","d":"to berate","e":"Jack ran away as soon as his father found out, knowing he would be vituperated for his unseemly behavior.","ev":"Jack đã bỏ chạy ngay khi cha anh phát hiện ra, biết rằng mình sẽ bị khiển trách vì hành vi vô lễ của mình.","k":"vituperate"},{"t":"Transient","p":"adj","d":"passing through briefly; passing into and out of existence","e":"The transient nature of life can be beautiful.","ev":"Bản chất tạm thời của cuộc sống có thể rất đẹp.","k":"transient"},{"t":"Concoct / concoction","p":"(v.)","d":"to fabricate, make up","e":"She concocted the most ridiculous story to explain her absence.","ev":"Cô bịa ra một câu chuyện nực cười nhất để giải thích sự vắng mặt của mình.","k":"concoct / concoction"},{"t":"Reluctance","d":"an unwillingness to do something","e":"She was reluctant to admit her mistake, feeling embarrassed and ashamed.","ev":"Cô không muốn thừa nhận sai lầm của mình, cảm thấy xấu hổ và xấu hổ.","k":"reluctance"},{"t":"Quirk","d":"n. a strange habit","e":"You have to get used to other people's quirks and foibles.","ev":"Bạn phải làm quen với những thói quen và điểm yếu của người khác.","k":"quirk"},{"t":"Anesthesia","p":"noun","d":"loss of sensation","e":"When the nerves in his spine were damaged, Mr. Hollins suffered anesthesia in his legs.","ev":"Khi các dây thần kinh trong cột sống của ông bị tổn thương, ông Hollins đã mất cảm giác ở chân.","k":"anesthesia"},{"t":"Qualitative","d":"adj. involving qualities of something (features and content)","e":"adj. involving qualities of something (features and content)","ev":"tính từ liên quan đến phẩm chất của một cái gì đó (tính năng và nội dung)","k":"qualitative"},{"t":"Prosaic","p":"adjective","d":"plain, lacking liveliness","e":"His writing was often criticized as prosaic and lacking imagination.","ev":"Văn phong của anh ấy thường bị chỉ trích là tầm thường và thiếu sự sáng tạo.","k":"prosaic"},{"t":"Affable","p":"adjective","d":"friendly, amiable","e":"People enjoy being around George because he is so affable.","ev":"Mọi người thích ở bên George vì anh ấy rất thân thiện.","k":"affable"},{"t":"Null","d":"adj. legally void and ineffective","e":"adj. legally void and ineffective","ev":"tính từ về mặt pháp lý vô hiệu và không có hiệu lực","k":"null"},{"t":"Coincide","d":"v. to happen at the same time","e":"Our views coincide on a range of subjects.","ev":"Quan điểm của chúng tôi trùng khớp về nhiều chủ đề.","k":"coincide"},{"t":"Consolidate","d":"1) strengthen 2) combine or unite","e":"The government consolidated its power, centralizing authority and reducing the influence of local leaders.","ev":"Chính phủ củng cố quyền lực, tập trung quyền lực và giảm bớt ảnh hưởng của lãnh đạo địa phương.","k":"consolidate"},{"t":"Adversarial","d":"adj. relating to hostile opposition","e":"adj. relating to hostile opposition","ev":"tính từ liên quan đến sự phản đối thù địch","k":"adversarial"},{"t":"Admonish","p":"verb","d":"to caution, criticize, reprove","e":"Joe’s mother admonished him about eating cookies before dinner.","ev":"Mẹ của Joe đã nhắc nhở anh về việc ăn bánh quy trước bữa tối.","k":"admonish"},{"t":"Reprobate","p":"(adj.)","d":"evil, unprincipled","e":"The reprobate criminal sat sneering in the cell.","ev":"Tên tội phạm đáng ghét ngồi chế nhạo trong phòng giam.","k":"reprobate"},{"t":"Beseech","p":"verb","d":"to beg, plead, implore","e":"The servant beseeched the king for food.","ev":"Người hầu đã cầu xin nhà vua cho thức ăn.","k":"beseech"},{"t":"Solvent","p":"(n.)","d":"a substance that can dissolve other substances","e":"Water is sometimes called the universal solvent because almost all other substances can dissolve into it.","ev":"Nước đôi khi được gọi là dung môi phổ quát vì hầu hết các chất khác đều có thể hòa tan vào nó.","x":"Loại từ 2: (adj.)\nNghĩa 2: able to pay debts\nVí dụ 2: Upon receiving an unexpected check from her aunt, Annabelle found herself suddenly solvent.","k":"solvent"},{"t":"Pious","d":"very religious or spiritual","e":"She was a pious woman who attended church regularly and followed religious teachings.","ev":"Cô ấy là một phụ nữ ngoan đạo, thường xuyên đến nhà thờ và tuân theo những lời dạy tôn giáo.","k":"pious"},{"t":"Radical","d":"1) thorough, complete, extensive 2) fundamental, essential 3) revolutionary, extreme","e":"His radical ideas were met with opposition, as many people found them too extreme and controversial.","ev":"Những ý tưởng cấp tiến của ông vấp phải sự phản đối vì nhiều người cho rằng chúng quá cực đoan và gây tranh cãi.","k":"radical"},{"t":"Chide","p":"verb","d":"to voice disapproval","e":"He chided his friend for being too careless with money.","ev":"Anh đã nhắc nhở bạn mình về việc quá bất cẩn với tiền bạc.","k":"chide"},{"t":"Eclectic","p":"adj","d":"consisting of a diverse variety of elements","e":"The eclectic menu featured dishes from various international cuisines.","ev":"Thực đơn đa dạng có nhiều món ăn từ các nền văn hóa ẩm thực quốc tế khác nhau.","k":"eclectic"},{"t":"Illicit","p":"adj","d":"forbidden, not permitted","e":"The illicit trade in endangered species is a serious global issue.","ev":"Thương mại bất hợp pháp về các loài có nguy cơ tuyệt chủng là một vấn đề toàn cầu nghiêm trọng.","k":"illicit"},{"t":"Punitive","p":"(adj.)","d":"involving punishment","e":"If caught smoking in the boys’ room, the punitive result is immediate expulsion from school.","ev":"Nếu bị bắt quả tang đang hút thuốc trong phòng nam sinh, hình phạt sẽ là đuổi học ngay lập tức.","k":"punitive"},{"t":"Locomotion","d":"n. movement","e":"n. movement","ev":"N. sự chuyển động","k":"locomotion"},{"t":"Duplicity","p":"(n.)","d":"crafty dishonesty","e":"His duplicity involved convincing his employees to let him lower their salaries and increase their stock options, and then to steal the money he saved and run the company into the ground.","ev":"Sự dối trá của anh ta liên quan đến việc thuyết phục nhân viên để anh ta giảm lương và tăng quyền lựa chọn cổ phiếu cho họ, sau đó lấy trộm số tiền anh ta tiết kiệm được và điều hành công ty xuống vực thẳm.","k":"duplicity"}]},{"n":"Chưa phân loại · 5","c":[{"t":"Veranda","d":"a porch or balcony","e":"They enjoyed sitting on the veranda, watching the sunset and enjoying the cool breeze.","ev":"Họ thích thú ngồi trên hiên, ngắm hoàng hôn và tận hưởng làn gió mát.","k":"veranda"},{"t":"Abstain","p":"verb","d":"to freely choose not to commit an action","e":"Angus abstained from wearing the kilt despite pressure.","ev":"Angus đã từ chối mặc chiếc kilt mặc dù bị áp lực.","k":"abstain"},{"t":"Spur","d":"to encourage an activity or development, to cause something to develop faster, thúc đẩy, khích lệ","e":"The competition spurred her to work harder.","ev":"Cuộc thi đã thúc đẩy cô làm việc chăm chỉ hơn.","k":"spur"},{"t":"Iridescent","p":"(adj.)","d":"showing rainbow colors","e":"The bride’s large diamond ring was iridescent in the afternoon sun.","ev":"Chiếc nhẫn kim cương lớn của cô dâu óng ánh trong nắng chiều.","k":"iridescent"},{"t":"Fortitude","p":"noun","d":"strength, guts","e":"He showed great fortitude in facing the challenges of his illness.","ev":"Anh đã thể hiện được sự dũng cảm trong việc đối mặt với những thử thách của bệnh tật.","k":"fortitude"},{"t":"Pithy","p":"(adj.)","d":"concisely meaningful","e":"My father’s long-winded explanation was a stark contrast to his usually pithy statements.","ev":"Lời giải thích dài dòng của cha tôi hoàn toàn trái ngược với những câu nói thường ngày súc tích của ông.","k":"pithy"},{"t":"Proxy","d":"a person authorized to act on behalf of another; substitute","e":"She voted by proxy because she was out of town, authorizing her friend to cast her ballot.","ev":"Cô ấy bỏ phiếu theo ủy quyền vì cô ấy ở ngoài thành phố, ủy quyền cho bạn mình bỏ phiếu.","k":"proxy"},{"t":"Liability","p":"(n.)","d":"something for which one is legally responsible, usually involving a disadvantage or risk","e":"The bungee-jumping tower was a great liability for the owners of the carnival.","ev":"Tháp nhảy bungee là một gánh nặng lớn đối với những người chủ lễ hội.","x":"Nghĩa 2: a handicap, burden\nVí dụ 2: Because she often lost her concentration and didn’t play defense, Marcy was a liability to the team.","k":"liability"},{"t":"Restitution","p":"(n.)","d":"restoration to the rightful owner","e":"Many people feel that descendants of slaves should receive restitution for the sufferings of their ancestors.","ev":"Nhiều người cho rằng con cháu của nô lệ phải được đền bù cho những đau khổ của tổ tiên họ.","k":"restitution"},{"t":"Elegy","p":"(n.)","d":"a speech given in honor of a dead person","e":"At the funeral, the widow gave a moving elegy describing her love for her husband.","ev":"Tại đám tang, người góa phụ đã đọc một bài ca cảm động mô tả tình yêu của bà dành cho chồng.","k":"elegy"},{"t":"Swath","d":"a long strip or area of something","e":"The tornado cut a swath through the forest, leaving a trail of destruction.","ev":"Cơn lốc xoáy cắt ngang khu rừng, để lại dấu vết tàn phá.","k":"swath"},{"t":"Callous","p":"adjective","d":"harsh, cold, unfeeling","e":"His callous remarks about the tragedy upset many people.","ev":"Những nhận xét lạnh lùng của anh về thảm kịch đã khiến nhiều người khó chịu.","k":"callous"},{"t":"Hypocrisy","p":"(n.)","d":"pretending to believe what one does not","e":"Once the politician began passing legislation that contradicted his campaign promises, his hypocrisy became apparent.","ev":"Khi chính trị gia này bắt đầu thông qua những đạo luật đi ngược lại với những lời hứa trong chiến dịch tranh cử của ông, hành vi đạo đức giả của ông đã lộ rõ.","k":"hypocrisy"},{"t":"Marginal","d":"unimportant","e":"The changes were marginal.","ev":"Những thay đổi này rất nhỏ.","x":"Ví dụ 2: general","k":"marginal"},{"t":"Entreat","d":"to ask someone sincerely or anxiously to do something","e":"She entreated him to help her, begging for his assistance.","ev":"Cô cầu xin anh giúp đỡ cô, cầu xin sự giúp đỡ của anh.","k":"entreat"},{"t":"Solipsistic","p":"(adj.)","d":"believing that oneself is all that exists","e":"Colette’s solipsistic attitude completely ignored the plight of the homeless people on the street.","ev":"Thái độ duy ngã của Colette hoàn toàn phớt lờ hoàn cảnh khó khăn của những người vô gia cư trên đường phố.","k":"solipsistic"},{"t":"Entomology","d":"study of insects","e":"Entomology is the study of insects.","ev":"Côn trùng học là nghiên cứu về côn trùng.","x":"Ví dụ 2: Branches of Science","k":"entomology"},{"t":"Authoritarian","d":"enforcing strict obedience to authority","e":"The government was authoritarian and did not tolerate dissent, suppressing freedom of speech and imposing strict controls on the population.","ev":"Chính phủ độc tài và không dung thứ cho những người bất đồng chính kiến, đàn áp quyền tự do ngôn luận và áp đặt các biện pháp kiểm soát chặt chẽ đối với người dân.","k":"authoritarian"},{"t":"Yearn","d":"to have an intense feeling of longing for something","e":"She yearned for a simpler time, longing for the days when life was less complicated and less stressful.","ev":"Cô khao khát một khoảng thời gian đơn giản hơn, khao khát những ngày cuộc sống bớt phức tạp và bớt căng thẳng hơn.","k":"yearn"},{"t":"Resolute","p":"(adj.)","d":"firm, determined","e":"With a resolute glint in her eye, Catherine announced that she was set on going to college in New York City even though she was a little frightened of tall buildings.","ev":"Với ánh mắt kiên quyết, Catherine tuyên bố rằng cô sắp đi học đại học ở thành phố New York mặc dù cô hơi sợ những tòa nhà cao tầng.","k":"resolute"},{"t":"Renunciation","p":"(n.)","d":"to reject","e":"Fiona’s renunciation of red meat resulted in weight loss, but confused those people who thought she’d been a vegetarian for years.","ev":"Việc Fiona từ bỏ thịt đỏ giúp giảm cân nhưng lại khiến những người cho rằng cô đã ăn chay trong nhiều năm bối rối.","k":"renunciation"},{"t":"Philanthropic","p":"(adj.)","d":"charitable, giving","e":"Many people felt that the billionaire’s decision to donate her fortune to house the homeless was the ultimate philanthropic act.","ev":"Nhiều người cảm thấy rằng quyết định quyên góp tài sản của mình để giúp đỡ người vô gia cư là một hành động từ thiện cao cả.","k":"philanthropic"},{"t":"Recapitulate","p":"(v.)","d":"to sum up, repeat","e":"Before the final exam, the teacher recapitulated the semester’s material.","ev":"Trước khi thi cuối kỳ, giáo viên ôn lại tài liệu học kỳ.","k":"recapitulate"},{"t":"Zephyr","p":"(n.) /ˈzef.ɚ/","d":"a gentle breeze","e":"If not for the zephyrs that were blowing and cooling us, our room would’ve been unbearably hot.","ev":"Nếu không có gió zephyr thổi và làm mát chúng tôi, căn phòng của chúng tôi sẽ nóng không chịu nổi.","k":"zephyr"},{"t":"Adequate","d":"sufficient, enough, acceptable","e":"The food was adequate, but not exceptional, leaving us feeling neither satisfied nor disappointed.","ev":"Thức ăn đầy đủ, nhưng không đặc biệt, khiến chúng tôi không cảm thấy hài lòng hay thất vọng.","k":"adequate"}]},{"n":"Chưa phân loại · 6","c":[{"t":"Train","d":"fixate on","e":"train one's eyes on something","ev":"rèn luyện đôi mắt của một người vào một cái gì đó","k":"train"},{"t":"To Temper","d":"to serve as a neutralizing or counterbalancing force to something","e":"He tried to temper his anger, taking deep breaths and calming himself down.","ev":"Anh cố gắng kiềm chế cơn giận bằng cách hít một hơi thật sâu và bình tĩnh lại.","k":"to temper"},{"t":"Artificial","d":"adj. something made; not occurring naturally","e":"adj. something made; not occurring naturally","ev":"tính từ một cái gì đó được thực hiện; không xảy ra một cách tự nhiên","k":"artificial"},{"t":"Excavate","p":"verb","d":"to dig out of the ground and remove","e":"Archaeologists will excavate the site to uncover ancient artifacts.","ev":"Các nhà khảo cổ học sẽ khai thác địa điểm để tìm ra các hiện vật cổ xưa.","k":"excavate"},{"t":"Ballad","p":"noun","d":"a love song","e":"Greta’s boyfriend played her a ballad during their walk.","ev":"Bạn trai của Greta đã chơi cho cô một bài ballad trong khi đi dạo.","k":"ballad"},{"t":"Magnitude","d":"1) the great size or importance of something 2) the extent or degree of something","e":"The magnitude of the disaster was devastating.","ev":"Mức độ nghiêm trọng của thảm họa là tàn khốc.","k":"magnitude"},{"t":"Efficacious","p":"(adj.)","d":"effective","e":"My doctor promised me that the cold medicine was efficacious, but I’m still sniffling.","ev":"Bác sĩ bảo thuốc cảm có tác dụng nhưng tôi vẫn sụt sịt.","k":"efficacious"},{"t":"Usurp","p":"verb","d":"to seize by force, take possession of without right, tiếm quyền","e":"They tried to usurp power from the current leaders of the organization.","ev":"Họ đã cố gắng chiếm đoạt quyền lực từ các nhà lãnh đạo hiện tại của tổ chức.","k":"usurp"},{"t":"Despot","p":"noun","d":"one who has total power and rules brutally","e":"The despot ruled with fear and intimidation, suppressing any opposition.","ev":"Nhà chuyên chế cai trị bằng sự sợ hãi và đe dọa, đàn áp mọi sự phản đối.","k":"despot"},{"t":"Zoology","d":"study of animals","e":"Zoology is the study of animals.","ev":"Động vật học là nghiên cứu về động vật.","x":"Ví dụ 2: Branches of Science","k":"zoology"},{"t":"Envy","d":"n. excessive jealousy","e":"n. excessive jealousy","ev":"N. ghen tuông quá mức","k":"envy"},{"t":"Attribute","p":"(1) verb; (2) noun","d":"to credit, assign","e":"(1) He attributes all of his success to his mother’s encouragement. \n (2) The beetle’s most peculiar attributes include its thorny eyes.","ev":"(1) Anh cho rằng tất cả thành công của mình là nhờ sự khuyến khích của mẹ. \n (2) Một trong những đặc điểm kỳ lạ nhất của con bọ là mắt nhô ra có gai.","k":"attribute"},{"t":"Grapple","d":"to struggle to deal with a difficult problem or situation","e":"She was grappling with a difficult decision.","ev":"Cô đang phải vật lộn với một quyết định khó khăn.","k":"grapple"},{"t":"Depiction","d":"portrayal, illustration","e":"The painting was a vivid depiction of the battle, capturing the intensity and chaos of the scene.","ev":"Bức tranh là sự miêu tả sống động về trận chiến, ghi lại sự khốc liệt và hỗn loạn của khung cảnh.","k":"depiction"},{"t":"Revoke","p":"(v.)","d":"to take back","e":"After missing the curfew set by the court for eight nights in a row, Marcel’s freedom of movement was revoked.","ev":"Sau khi bỏ lỡ lệnh giới nghiêm do tòa án ấn định trong 8 đêm liên tiếp, quyền tự do đi lại của Marcel đã bị thu hồi.","k":"revoke"},{"t":"Presumptuous","p":"adj","d":"disrespectfully bold","e":"It was presumptuous of him to assume he would be invited to the wedding.","ev":"Thật kiêu ngạo khi anh giả định rằng mình sẽ được mời đến đám cưới.","k":"presumptuous"},{"t":"Assertion","d":"n. a strong declaration","e":"n. a strong declaration","ev":"N. một tuyên bố mạnh mẽ","k":"assertion"},{"t":"Emollient","p":"(adj.)","d":"soothing","e":"This emollient cream makes my skin very smooth.","ev":"Loại kem làm mềm này làm cho làn da của tôi rất mịn màng.","k":"emollient"},{"t":"Conflagration","p":"noun","d":"great fire","e":"The conflagration destroyed several homes.","ev":"Ngọn lửa lớn đã phá hủy nhiều ngôi nhà.","k":"conflagration"},{"t":"Capture","d":"v. to trap or take possession of","e":"v. to trap or take possession of","ev":"v. bẫy hoặc chiếm hữu","k":"capture"},{"t":"Morose","p":"adjective","d":"gloomy or sullen","e":"He had a morose expression after receiving the bad news.","ev":"Anh có vẻ ủ rũ sau khi nhận được tin xấu.","k":"morose"},{"t":"Obsequious","p":"(adj.)","d":"excessively compliant or submissive","e":"Mark acted like Janet’s servant, obeying her every request in an obsequious manner.","ev":"Mark hành động như người hầu của Janet, tuân theo mọi yêu cầu của cô một cách khúm núm.","k":"obsequious"},{"t":"Benevolent","p":"noun","d":"marked by goodness or doing good - nhân từ","e":"The benevolent organization provides food and shelter for the homeless.","ev":"Tổ chức nhân đạo cung cấp thực phẩm và chỗ ở cho những người vô gia cư.","k":"benevolent"},{"t":"Accord","p":"verb","d":"an agreement","e":"England and Iceland came to an accord about fishing rights after much negotiation.","ev":"Anh và Iceland đã đạt được thỏa thuận về quyền đánh bắt cá sau nhiều cuộc đàm phán.","k":"accord"},{"t":"Deleterious","p":"adj","d":"harmful","e":"The chemical had deleterious effects on the environment.","ev":"Chất hóa học có tác động có hại đến môi trường.","k":"deleterious"}]},{"n":"Chưa phân loại · 7","c":[{"t":"Irreconcilable","d":"adj. incapable of being in harmony or agreed upon","e":"adj. incapable of being in harmony or agreed upon","ev":"tính từ không có khả năng hòa hợp hoặc đồng ý","k":"irreconcilable"},{"t":"Toady","p":"noun","d":"one who flatters in the hope of gaining favors","e":"The toady followed his wealthy friend everywhere, hoping for financial gain.","ev":"Kẻ nịnh bợ luôn theo chân người bạn giàu có, hy vọng được lợi ích tài chính.","k":"toady"},{"t":"Abscond","p":"verb","d":"to sneak away and hide","e":"In the confusion, the super-spy absconded into the night with the secret plans.","ev":"Trong sự hoang mang, điệp viên siêu hạng đã lẩn trốn vào ban đêm cùng với các kế hoạch bí mật.","k":"abscond"},{"t":"Quaint","p":"(adj.)","d":"charmingly old-fashioned","e":"Hilda was delighted by the quaint bonnets she saw in Amish country.","ev":"Hilda rất thích thú trước những chiếc mũ kỳ lạ mà cô nhìn thấy ở đất nước Amish.","k":"quaint"},{"t":"Florid","p":"(adj.)","d":"flowery, ornate","e":"The writer’s florid prose belongs on a sentimental Hallmark card.","ev":"Văn xuôi hoa mỹ của nhà văn thuộc về một tấm thiệp Hallmark đa cảm.","k":"florid"},{"t":"Culpable","p":"noun/adj","d":"deserving blame","e":"The jury found the defendant culpable of the charges against him.","ev":"Bồi thẩm đoàn đã xác định bị cáo có tội đối với các cáo buộc chống lại anh.","k":"culpable"},{"t":"Expend","d":"to use up, to consume","e":"They expended a lot of energy on the project, working tirelessly to achieve their goals.","ev":"Họ đã dành rất nhiều tâm sức cho dự án, làm việc không mệt mỏi để đạt được mục tiêu của mình.","k":"expend"},{"t":"Credibility","d":"believability, authority","e":"His credibility was questioned after he was caught lying.","ev":"Độ tin cậy của anh ta đã bị nghi ngờ sau khi anh ta bị bắt quả tang nói dối.","k":"credibility"},{"t":"Sophomoric","p":"(adj.)","d":"immature, uninformed","e":"The mature senior rolled her eyes at the sophomoric gross-out humor of the underclassman.","ev":"Người đàn anh trưởng thành trợn mắt trước sự hài hước thô thiển của học sinh lớp dưới.","k":"sophomoric"},{"t":"Abjure","p":"verb","d":"to reject, renounce","e":"The President abjured the evil policies of his predecessor.","ev":"Tổng thống đã từ bỏ các chính sách xấu xa của người tiền nhiệm.","k":"abjure"},{"t":"Apprehend","p":"verb","d":"to seize, arrest","e":"(1) The criminal was apprehended at the scene. (2) The student had trouble apprehending math concepts.","ev":"(1) Tên tội phạm đã bị bắt giữ tại hiện trường. (2) Học sinh gặp khó khăn trong việc hiểu các khái niệm toán học.","k":"apprehend"},{"t":"Incisive","p":"(adj.)","d":"clear, sharp, direct","e":"The discussion wasn’t going anywhere until her incisive comment allowed everyone to see what the true issues were.","ev":"Cuộc thảo luận sẽ không đi đến đâu cho đến khi nhận xét sắc bén của cô ấy cho phép mọi người hiểu được vấn đề thực sự là gì.","k":"incisive"},{"t":"Apocryphal","p":"adjective","d":"fictitious, false, wrong","e":"The stories about my demise were apocryphal, as I am standing before you.","ev":"Những câu chuyện về cái chết của tôi là giả mạo, vì tôi đang đứng trước mặt bạn.","k":"apocryphal"},{"t":"Staid","p":"(adj.)","d":"sedate, serious, self-restrained","e":"The staid butler never changed his expression no matter what happened.","ev":"Người quản gia điềm tĩnh không bao giờ thay đổi nét mặt dù có chuyện gì xảy ra.","k":"staid"},{"t":"Facilitate","d":"to make (an action or process) possible or easier","e":"The new software facilitated communication between employees.","ev":"Phần mềm mới tạo điều kiện thuận lợi cho việc giao tiếp giữa các nhân viên.","k":"facilitate"},{"t":"Egregious","p":"(adj.)","d":"extremely bad","e":"The student who threw sloppy joes across the cafeteria was punished for his egregious behavior.","ev":"Học sinh ném Joes cẩu thả khắp căng tin đã bị trừng phạt vì hành vi nghiêm trọng của mình.","k":"egregious"},{"t":"Wistful","p":"(adj.)","d":"full of yearning; musingly sad, bâng khuâng","e":"Since her pet rabbit died, Edda missed it terribly and sat around wistful all day long.","ev":"Kể từ khi con thỏ cưng của cô chết, Edda nhớ nó vô cùng và ngồi đó tiếc nuối suốt cả ngày.","k":"wistful"},{"t":"Modify","d":"v. to change, alter, or tweak","e":"v. to change, alter, or tweak","ev":"v. thay đổi, thay đổi, điều chỉnh","k":"modify"},{"t":"Ascertain","p":"verb","d":"to perceive, learn","e":"The student ascertained that some plants can survive for weeks without water.","ev":"Học sinh đã nhận ra rằng một số loại cây có thể sống sót nhiều tuần mà không có nước.","k":"ascertain"},{"t":"Surfeit","p":"noun","d":"an overabundant supply or indulgence","e":"After the feast, they were left with a surfeit of food.","ev":"Sau bữa tiệc, họ bị bỏ lại với một lượng thức ăn thừa thãi.","k":"surfeit"},{"t":"Impetuous","p":"adjective","d":"rash; hastily done","e":"Her impetuous decision to quit her job surprised everyone.","ev":"Quyết định bốc đồng của cô để bỏ việc đã khiến mọi người ngạc nhiên.","k":"impetuous"},{"t":"Inimical","p":"(adj.)","d":"hostile, enemylike","e":"I don’t see how I could ever work for a company that was so cold and inimical to me during my interviews.","ev":"Tôi không hiểu làm thế nào tôi có thể làm việc cho một công ty quá lạnh lùng và thù địch với tôi trong các cuộc phỏng vấn.","k":"inimical"},{"t":"Pliable","p":"(adj.)","d":"flexible","e":"Aircraft wings are designed to be somewhat pliable so they do not break in heavy turbulence.","ev":"Cánh máy bay được thiết kế hơi dẻo để không bị gãy khi có chuyển động mạnh.","k":"pliable"},{"t":"Effervescent","p":"(adj.)","d":"bubbly, lively","e":"My friend is so effervescent that she makes everyone smile.","ev":"Bạn tôi sôi nổi đến mức khiến mọi người phải bật cười.","k":"effervescent"},{"t":"Pompous","d":"feeling that one is better or more important than other people","e":"He was a pompous man who often acted superior to others.","ev":"Anh ta là một người đàn ông hào hoa và thường hành động vượt trội so với người khác.","k":"pompous"}]},{"n":"Chưa phân loại · 8","c":[{"t":"Whimsical","p":"(adj.)","d":"fanciful, full of whims","e":"The whimsical little girl liked to pretend that she was an elvin princess.","ev":"Cô bé hay thay đổi thích giả vờ rằng mình là một công chúa yêu tinh.","k":"whimsical"},{"t":"Dissipate","p":"(v.)","d":"to disappear, cause to disappear","e":"The sun finally came out and dissipated the haze.","ev":"Mặt trời cuối cùng cũng ló dạng và xua tan sương mù.","x":"Nghĩa 2: to waste\nVí dụ 2: She dissipated her fortune on a series of bad investments.","k":"dissipate"},{"t":"Attest","d":"to confirm or verify","e":"The witness attested to the defendant's innocence, providing crucial evidence in the trial.","ev":"Nhân chứng đã chứng minh bị cáo vô tội, cung cấp bằng chứng quan trọng cho phiên tòa.","k":"attest"},{"t":"Bourgeois","p":"(n.)","d":"a middle-class person, capitalist","e":"Many businessmen receive criticism for their bourgeois approach to life.","ev":"Nhiều doanh nhân bị chỉ trích vì cách tiếp cận cuộc sống tư sản của họ.","k":"bourgeois"},{"t":"Reminisce","d":"to talk about the past with pleasure","e":"They reminisced about their childhood, sharing stories and memories.","ev":"Họ hồi tưởng về tuổi thơ của mình, chia sẻ những câu chuyện và kỷ niệm.","k":"reminisce"},{"t":"Respite","p":"(n.)","d":"a break, rest","e":"Justin left the pub to gain a brief respite from the smoke and noise.","ev":"Justin rời quán rượu để tránh khói và tiếng ồn một thời gian ngắn.","k":"respite"},{"t":"Amicable","p":"adjective","d":"friendly","e":"The two parties reached an amicable agreement after long negotiations.","ev":"Hai bên đã đạt được thỏa thuận thân thiện sau nhiều cuộc đàm phán dài.","k":"amicable"},{"t":"Abate","p":"verb","d":"to reduce, lessen","e":"The storm will abate by morning, making travel easier.","ev":"Cơn bão sẽ giảm bớt vào buổi sáng, giúp việc di chuyển dễ dàng hơn.","k":"abate"},{"t":"Vapid","p":"adjective","d":"lacking liveliness, dull","e":"The vapid conversation left her feeling bored and uninterested.","ev":"Cuộc trò chuyện nhạt nhẽo đã khiến cô cảm thấy chán nản và không hứng thú.","k":"vapid"},{"t":"Avenue","d":"n. an intangible path or approach to something","e":"n. an intangible path or approach to something","ev":"N. một con đường vô hình hoặc cách tiếp cận một cái gì đó","k":"avenue"},{"t":"Turgid","p":"(adj.)","d":"swollen, excessively embellished in style or language","e":"The haughty writer did not realize how we all really felt about his turgid prose.","ev":"Nhà văn kiêu kỳ đã không nhận ra tất cả chúng ta thực sự cảm thấy thế nào về lối văn xuôi khoa trương của ông.","k":"turgid"},{"t":"Imposition","d":"n. an unnecessary burden","e":"n. an unnecessary burden","ev":"N. gánh nặng không cần thiết","k":"imposition"},{"t":"Hostile","d":"unfriendly, threatening","e":"The environment was hostile to plant life, with harsh conditions and limited resources.","ev":"Môi trường khắc nghiệt đối với đời sống thực vật, với điều kiện khắc nghiệt và nguồn tài nguyên hạn chế.","k":"hostile"},{"t":"Demonstrate","d":"v. to do as an example","e":"v. to do as an example","ev":"v. làm ví dụ","k":"demonstrate"},{"t":"Grandiloquent","d":"using impressive but meaningless language, khoa trương.","e":"He gave a grandiloquent speech.","ev":"Ông đã có một bài phát biểu hoành tráng.","k":"grandiloquent"},{"t":"Officious","p":"adjective","d":"offering one’s services when they are neither wanted nor needed","e":"The officious assistant was always trying to tell others what to do.","ev":"Trợ lý quá tự mãn luôn cố gắng chỉ dẫn người khác phải làm gì.","k":"officious"},{"t":"Mar","d":"làm hỏng, làm xấu","e":"The scratches on the car door mar the otherwise pristine paint job.","ev":"Những vết xước trên cửa xe làm ảnh hưởng đến lớp sơn còn nguyên sơ.","k":"mar"},{"t":"Parsimony","p":"(n.)","d":"frugality, stinginess","e":"Many relatives believed that my aunt’s wealth resulted from her parsimony.","ev":"Nhiều họ hàng tin rằng sự giàu có của dì tôi là nhờ sự tằn tiện của dì.","k":"parsimony"},{"t":"Scurrilous","p":"(adj.)","d":"vulgar, coarse, thô bỉ","e":"When Bruno heard the scurrilous accusation being made about him, he could not believe it because he always tried to be nice to everyone.","ev":"Khi Bruno nghe những lời buộc tội thô tục về mình, anh không thể tin được vì anh luôn cố gắng đối xử tốt với mọi người.","k":"scurrilous"},{"t":"Distinguish","d":"to tell the difference between","e":"He was able to distinguish between the two similar-looking plants by examining their leaves and flowers.","ev":"Ông có thể phân biệt hai loại cây trông giống nhau bằng cách kiểm tra lá và hoa của chúng.","k":"distinguish"},{"t":"Penurious","p":"noun","d":"miserly, stingy","e":"The penurious old man lived in a small, dilapidated house.","ev":"Người đàn ông nghèo khổ sống trong một ngôi nhà nhỏ và xuống cấp.","k":"penurious"},{"t":"Curtail","p":"verb","d":"to lessen, reduce","e":"Since losing his job, he had to curtail his spending.","ev":"Kể từ khi mất việc, anh đã phải cắt giảm chi tiêu.","k":"curtail"},{"t":"Delineate","p":"verb","d":"to describe, outline, shed light on","e":"The report delineates the key differences between the two proposed plans.","ev":"Báo cáo đã phác thảo rõ ràng những khác biệt chính giữa hai kế hoạch đề xuất.","k":"delineate"},{"t":"Stoic","p":"(adj.)","d":"unaffected by passion or feeling","e":"Penelope’s faithfulness to Odysseus required that she be stoic and put off her many suitors.","ev":"Sự chung thủy của Penelope với Odysseus đòi hỏi cô phải khắc kỷ và từ chối nhiều người theo đuổi mình.","k":"stoic"},{"t":"Air","d":"demeanor","e":"to carry yourself with an air of authority","ev":"mang trong mình vẻ uy quyền","k":"air"}]},{"n":"Chưa phân loại · 9","c":[{"t":"Emigration","d":"the act of leaving one's own country","e":"The family decided to emigrate to Australia, seeking a better life and new opportunities.","ev":"Gia đình quyết định di cư sang Úc để tìm kiếm một cuộc sống tốt hơn và những cơ hội mới.","k":"emigration"},{"t":"Arbitrary","p":"adjective","d":"based on factors that appear random","e":"The boy’s decision to choose one college seems arbitrary.","ev":"Quyết định của cậu bé chọn một trường đại học dường như là ngẫu nhiên.","k":"arbitrary"},{"t":"Scandalous","p":"adj.","d":"making people shocked and upset","e":"scandalous stories It's scandalous that we do so little to prevent homelessness.","ev":"những câu chuyện tai tiếng Thật tai tiếng khi chúng ta làm quá ít để ngăn chặn tình trạng vô gia cư.","k":"scandalous"},{"t":"Intrepid","p":"adj","d":"brave in the face of danger","e":"The intrepid explorer ventured into the uncharted territory with confidence.","ev":"Nhà thám hiểm dũng cảm đã mạo hiểm vào lãnh thổ chưa được bản đồ với sự tự tin.","k":"intrepid"},{"t":"Sacrosanct","p":"(adj.)","d":"holy, something that should not be criticized","e":"In the United States, the Constitution is often thought of as a sacrosanct document.","ev":"Ở Hoa Kỳ, Hiến pháp thường được coi là một văn kiện bất khả xâm phạm.","k":"sacrosanct"},{"t":"Hierarchy","p":"(n.)","d":"a system with ranked groups, usually according to social, economic, or professional class","e":"Women found it very difficult to break into the upper ranks of the department’s hierarchy.","ev":"Phụ nữ cảm thấy rất khó để lọt vào các cấp bậc cao hơn trong hệ thống cấp bậc của bộ phận.","k":"hierarchy"},{"t":"Effrontery","p":"(n.)","d":"impudence, nerve, insolence","e":"When I told my aunt that she was boring, my mother scolded me for my effrontery.","ev":"Khi tôi nói với dì rằng dì thật nhàm chán, mẹ tôi đã mắng tôi vì sự vô lễ.","k":"effrontery"},{"t":"Adverse","p":"adjective","d":"antagonistic, unfavorable, dangerous","e":"The hikers abandoned their climb due to adverse conditions.","ev":"Những người đi bộ đã bỏ cuộc do điều kiện bất lợi.","k":"adverse"},{"t":"Verdict","d":"an opinion or judgment","e":"The jury reached a verdict of guilty.","ev":"Bồi thẩm đoàn đã đưa ra phán quyết có tội.","k":"verdict"},{"t":"Submissive","p":"(adj.)","d":"easily yielding to authority","e":"In some cultures, wives are supposed to be submissive and support their husbands in all matters.","ev":"Ở một số nền văn hóa, người vợ phải phục tùng và hỗ trợ chồng trong mọi vấn đề.","k":"submissive"},{"t":"Perish","d":"v. to die; to pass away","e":"v. to die; to pass away","ev":"v. chết; qua đời","k":"perish"},{"t":"Abandon","d":"to leave someone or something without help","e":"He abandoned his family and friends.","ev":"Anh đã bỏ rơi gia đình và bạn bè của mình.","k":"abandon"},{"t":"Dire","p":"adj","d":"adj. hopeless and dangerous or fearful","e":"The situation is dire and requires immediate action.","ev":"Tình huống rất nghiêm trọng và cần hành động ngay lập tức.","k":"dire"},{"t":"Advent","d":"n. the arrival or creation of something (usu. historic)","e":"n. the arrival or creation of something (usu. historic)","ev":"N. sự xuất hiện hoặc tạo ra một cái gì đó (usu. lịch sử)","k":"advent"},{"t":"Judgmental","d":"having an excessively critical point of view; disapproving","e":"She was a judgmental person who often criticized others for their choices and behavior.","ev":"Cô ấy là người thích phán xét và thường chỉ trích người khác về những lựa chọn và hành vi của họ.","k":"judgmental"},{"t":"Temerity","p":"(n.)","d":"audacity, recklessness","e":"Tom and Huck entered the scary cave armed with nothing but their own temerity.","ev":"Tom và Huck bước vào hang động đáng sợ mà không mang theo gì ngoài sự táo bạo của chính họ.","k":"temerity"},{"t":"Allow","d":"v. to permit or consent to","e":"v. to permit or consent to","ev":"v. cho phép hoặc đồng ý","k":"allow"},{"t":"Obstinate","p":"(adj.)","d":"not yielding easily, stubborn","e":"The obstinate child refused to leave the store until his mother bought him a candy bar.","ev":"Cậu bé bướng bỉnh không chịu rời khỏi cửa hàng cho đến khi được mẹ mua cho một thanh kẹo.","k":"obstinate"},{"t":"Abhor","p":"verb","d":"to hate, detest","e":"Oswald began to abhor soccer after constantly injuring himself while playing.","ev":"Oswald bắt đầu ghét bóng đá sau khi liên tục làm mình bị thương khi chơi.","k":"abhor"},{"t":"Raze","p":"verb","d":"to demolish, level","e":"They decided to raze the old building.","ev":"Họ quyết định san bằng tòa nhà cũ.","k":"raze"},{"t":"Brawl","d":"n. an intense, loud fight","e":"n. an intense, loud fight","ev":"N. một cuộc chiến dữ dội, ồn ào","k":"brawl"},{"t":"Teeming","d":"adj. abundantly filled (usu. with living organisms)","e":"adj. abundantly filled (usu. with living organisms)","ev":"tính từ chứa đầy (thông thường với các sinh vật sống)","k":"teeming"},{"t":"Annex","p":"verb","d":"to incorporate territory or space","e":"(1) After defeating them in battle, the Russians annexed Poland. (2) He likes to study in a little annex attached to the library.","ev":"(1) Sau khi đánh bại họ trong trận chiến, người Nga đã sát nhập Ba Lan. (2) Anh thích học trong một phòng phụ nhỏ nối với thư viện.","k":"annex"},{"t":"Degrade","d":"treat with disrespect","e":"The scandal degraded his reputation, tarnishing his image and damaging his career.","ev":"Vụ bê bối đã làm suy giảm danh tiếng, làm hoen ố hình ảnh và hủy hoại sự nghiệp của anh.","k":"degrade"},{"t":"Congeal","p":"verb","d":"to thicken into a solid","e":"The sauce had congealed into a thick paste.","ev":"Nước sốt đã trở thành một hỗn hợp đặc và rắn.","k":"congeal"}]},{"n":"Chưa phân loại · 10","c":[{"t":"Civic","d":"adj. relating to the city or citizens","e":"adj. relating to the city or citizens","ev":"tính từ liên quan đến thành phố hoặc công dân","k":"civic"},{"t":"Reserved","d":"tending to keep feelings or thoughts private; quiet","e":"He was a reserved person who didn't talk much.","ev":"Anh ấy là một người kín đáo và không nói nhiều.","k":"reserved"},{"t":"Pillage","p":"(v.)","d":"to seize or plunder, especially in war","e":"Invading enemy soldiers pillaged the homes scattered along the country’s border.","ev":"Quân giặc xâm lược cướp bóc những ngôi nhà nằm rải rác dọc biên giới đất nước.","k":"pillage"},{"t":"Quagmire","p":"(n.)","d":"a difficult situation","e":"We’d all like to avoid the kind of military quagmire characterized by the Vietnam War.","ev":"Tất cả chúng ta đều muốn tránh loại vũng lầy quân sự đặc trưng của Chiến tranh Việt Nam.","k":"quagmire"},{"t":"Criteria","p":"noun","d":"standards by which something is judged","e":"Among Mrs. Fields’s criteria for good cookies are that they be moist and chewy.","ev":"Một trong những tiêu chí của bà Fields cho bánh quy là phải ẩm và dai.","k":"criteria"},{"t":"Acrimony","p":"noun","d":"bitterness, discord","e":"The acrimony between the two rivals was evident during the debate.","ev":"Sự cay đắng giữa hai đối thủ đã rõ ràng trong suốt cuộc tranh luận.","k":"acrimony"},{"t":"Complement","p":"(v.)","d":"to complete, make perfect","e":"Ann’s scarf complements her blouse beautifully, making her seem fully dressed even though she isn’t wearing a coat.","ev":"Chiếc khăn quàng cổ của Ann làm tôn lên chiếc áo sơ mi của cô ấy một cách đẹp mắt, khiến cô ấy trông như đã ăn mặc chỉnh tề dù không mặc áo khoác.","k":"complement"},{"t":"Propitious","p":"(adj.)","d":"favorable","e":"The dark storm clouds visible on the horizon suggested that the weather would not be propitious for sailing.","ev":"Những đám mây bão đen hiện rõ ở phía chân trời cho thấy thời tiết không thuận lợi cho việc ra khơi.","k":"propitious"},{"t":"Debunk","p":"verb/adjective","d":"to expose the falseness of something","e":"The researcher aimed to debunk the myths surrounding the ancient artifact.","ev":"Nhà nghiên cứu nhằm mục đích vạch trần những huyền thoại xung quanh cổ vật cổ.","k":"debunk"},{"t":"Concise","p":"(adj.)","d":"brief and direct in expression","e":"Gordon did not like to waste time, and his instructions to Brenda were nothing if not concise.","ev":"Gordon không muốn lãng phí thời gian, và những chỉ dẫn của anh dành cho Brenda chẳng là gì nếu không nói là ngắn gọn.","k":"concise"},{"t":"Insurrection","d":"a violent uprising or rebellion","e":"The insurrection was quickly put down by the government, restoring order and stability to the country.","ev":"Cuộc khởi nghĩa nhanh chóng bị chính quyền dập tắt, lập lại trật tự, ổn định cho đất nước.","k":"insurrection"},{"t":"Squalid","d":"extremely dirty, poor, and unpleasant","e":"The slum was a squalid place, with dirty streets and overcrowded housing.","ev":"Khu ổ chuột là một nơi tồi tàn, đường phố bẩn thỉu và nhà ở quá đông đúc.","k":"squalid"},{"t":"Deride","p":"verb","d":"to laugh at mockingly, scorn","e":"They derided his efforts to change the system as naïve.","ev":"Họ chế nhạo nỗ lực của anh để thay đổi hệ thống là ngây thơ.","k":"deride"},{"t":"Tangential","p":"adjective","d":"incidental, peripheral, divergent","e":"His comments were tangential to the main discussion and did not add much value.","ev":"Những nhận xét của anh ấy không liên quan đến cuộc thảo luận chính và không mang lại giá trị gì nhiều.","k":"tangential"},{"t":"Complement (Verb)","d":"to add to (something) in a way that enhances or completes it","e":"The blue curtains complemented the yellow walls, creating a harmonious and inviting atmosphere.","ev":"Những tấm rèm màu xanh bổ sung cho những bức tường màu vàng, tạo ra một bầu không khí hài hòa và lôi cuốn.","k":"complement (verb)"},{"t":"Brevity","d":"concise use of words in writing or speech","e":"The brevity of the speech was appreciated by the audience, who were eager to get on with their day.","ev":"Sự ngắn gọn của bài phát biểu đã được khán giả đánh giá cao, những người đang háo hức bắt đầu ngày làm việc của mình.","k":"brevity"},{"t":"Cadence","p":"(n.)","d":"a rhythm, progression of sound, nhịp","e":"The pianist used the foot pedal to emphasize the cadence of the sonata.","ev":"Nghệ sĩ piano sử dụng bàn đạp chân để nhấn mạnh nhịp điệu của bản sonata.","k":"cadence"},{"t":"Increment","p":"(n.)","d":"an enlargement; the process of increasing","e":"The workmen made the wall longer, increment by increment.","ev":"Những người thợ làm bức tường dài hơn, tăng dần.","k":"increment"},{"t":"Fallacious","p":"adj","d":"incorrect, misleading","e":"His argument was based on fallacious reasoning.","ev":"Lập luận của anh ta dựa trên lý lẽ sai lầm.","k":"fallacious"},{"t":"Abject","p":"adjective","d":"wretched, pitiful","e":"After losing everything, Eloise felt abject.","ev":"Sau khi mất tất cả, Eloise cảm thấy khổ sở.","k":"abject"},{"t":"Counterargument","d":"n. an argument used to criticize or dismantle another argument","e":"n. an argument used to criticize or dismantle another argument","ev":"N. một đối số được sử dụng để chỉ trích hoặc phá bỏ một đối số khác","k":"counterargument"},{"t":"Execrable","p":"(adj.)","d":"loathsome, detestable","e":"Her pudding is so execrable that it makes me sick.","ev":"Món bánh pudding của cô ấy ngon đến mức khiến tôi phát ốm.","k":"execrable"},{"t":"Geriatric","d":"adj. relating to old age","e":"adj. relating to old age","ev":"tính từ liên quan đến tuổi già","k":"geriatric"},{"t":"Efface","p":"(v.)","d":"to wipe out, obliterate, rub away","e":"The husband was so angry at his wife for leaving him that he effaced all evidence of her presence; he threw out pictures of her and gave away all her belongings.","ev":"Người chồng giận vợ vì đã bỏ mình đến mức xóa bỏ mọi bằng chứng về sự hiện diện của cô ấy; anh ta ném ảnh của cô và cho đi tất cả đồ đạc của cô.","k":"efface"},{"t":"Eminent","p":"(adj.)","d":"distinguished, prominent, famous","e":"Mr. Phillips is such an eminent scholar that every professor on campus has come to hear him lecture.","ev":"Ông Phillips là một học giả xuất sắc đến nỗi mọi giáo sư trong trường đều đến nghe ông giảng bài.","x":"Nghĩa 2: conspicuous\nVí dụ 2: There is an eminent stain on that shirt.","k":"eminent"}]},{"n":"Chưa phân loại · 11","c":[{"t":"Tenacity","d":"persistence, determination","e":"Her tenacity allowed her to overcome many obstacles, refusing to give up even when faced with adversity.","ev":"Sự kiên trì giúp cô vượt qua nhiều trở ngại, không bỏ cuộc ngay cả khi gặp nghịch cảnh.","k":"tenacity"},{"t":"Transmute","p":"(v.)","d":"to change or alter in form","e":"Ancient alchemists believed that it was possible to transmute lead into gold.","ev":"Các nhà giả kim cổ đại tin rằng có thể biến chì thành vàng.","k":"transmute"},{"t":"Capitalize","d":"v. to use to your advantage","e":"v. to use to your advantage","ev":"v. tận dụng lợi thế của bạn","k":"capitalize"},{"t":"Abysmal","d":"adj. extremely bad","e":"adj. extremely bad","ev":"tính từ cực kỳ tệ","k":"abysmal"},{"t":"Censure","p":"verb","d":"punish","e":"The senator faced censure for his inappropriate remarks.","ev":"Thượng nghị sĩ đã phải đối mặt với sự chỉ trích vì những nhận xét không thích hợp.","k":"censure"},{"t":"Egocentric","d":"thinking only of oneself; self-centered","e":"He was an egocentric person who only cared about himself and his own needs.","ev":"Anh ấy là một người ích kỷ, chỉ quan tâm đến bản thân và nhu cầu của bản thân.","k":"egocentric"},{"t":"Anathema","p":"noun","d":"a cursed, detested person","e":"I never want to see that murderer. He is an anathema to me.","ev":"Tôi không bao giờ muốn thấy tên sát nhân đó. Hắn là một người tôi ghét bỏ.","k":"anathema"},{"t":"Connive","p":"verb","d":"to plot, scheme","e":"She connived to get me to give up my vacation plans.","ev":"Cô ấy âm thầm lên kế hoạch để thay đổi kế hoạch của tôi.","k":"connive"},{"t":"Prurient","p":"(adj.)","d":"eliciting or possessing an extraordinary interest in sex","e":"David’s mother was shocked by the discovery of prurient reading material hidden beneath her son’s mattress.","ev":"Mẹ của David đã bị sốc khi phát hiện ra tài liệu đọc gây ngứa ngáy được giấu dưới nệm của con trai bà.","k":"prurient"},{"t":"Coerce","p":"(v.)","d":"to make somebody do something by force or threat","e":"The court decided that Vanilla Ice did not have to honor the contract because he had been coerced into signing it.","ev":"Tòa án quyết định Vanilla Ice không cần phải tôn trọng hợp đồng vì anh ta đã bị ép ký.","k":"coerce"},{"t":"Idealistic","d":"unrealistically aiming for perfection","e":"She was an idealistic young woman who believed in making the world a better place, working tirelessly to promote social justice and environmental conservation.","ev":"Cô là một phụ nữ trẻ có lý tưởng, tin tưởng vào việc biến thế giới thành một nơi tốt đẹp hơn, làm việc không mệt mỏi để thúc đẩy công bằng xã hội và bảo tồn môi trường.","k":"idealistic"},{"t":"Neophyte","p":"noun","d":"someone who is young or inexperienced","e":"As a neophyte in the industry, he had much to learn from his experienced colleagues.","ev":"Là một người mới trong ngành, anh có nhiều điều cần học hỏi từ các đồng nghiệp có kinh nghiệm.","k":"neophyte"},{"t":"Amalgamate","p":"verb","d":"to bring together, unite","e":"Because of his charisma, the candidate was able to amalgamate all Democrats and Republicans.","ev":"Nhờ sự quyến rũ của mình, ứng cử viên đã có thể hợp nhất tất cả các đảng viên Dân chủ và Cộng hòa.","k":"amalgamate"},{"t":"Clamor","p":"(n.)","d":"loud noise","e":"Each morning the birds outside my window make such a clamor that they wake me up.","ev":"Mỗi buổi sáng, lũ chim ngoài cửa sổ kêu ầm ĩ đến nỗi chúng đánh thức tôi dậy.","x":"Loại từ 2: (v.)\nNghĩa 2: to loudly insist\nVí dụ 2: Neville’s fans clamored for him to appear on stage, but he had passed out on the floor of his dressing room.","k":"clamor"},{"t":"Fundamental","d":"adj. the most essential or most basic part","e":"adj. the most essential or most basic part","ev":"tính từ phần thiết yếu nhất hoặc cơ bản nhất","k":"fundamental"},{"t":"Sentiment","d":"a view of or attitude towards a situation or event; a general feeling or opinion","e":"Her sentiment was one of sadness and regret, as she reflected on the past and the choices she had made.","ev":"Cảm xúc của cô là buồn bã và hối tiếc khi cô suy ngẫm về quá khứ và những lựa chọn mà cô đã đưa ra.","k":"sentiment"},{"t":"Malleable","p":"adj","d":"easily influenced or controlled by other people","e":"Gold is a malleable metal.","ev":"Vàng là kim loại dễ uốn.","k":"malleable"},{"t":"Audible","p":"adj.","d":"able to be heard","e":"The missing person’s shouts were not audible.","ev":"Những tiếng kêu cứu của người mất tích thì không nghe thấy.","k":"audible"},{"t":"Exarcerbate","d":"to make worse","e":"His comments only served to exacerbate the tension in the room.","ev":"Lời nhận xét của ông chỉ làm tăng thêm sự căng thẳng trong phòng.","k":"exarcerbate"},{"t":"Rhapsodize","p":"(v.)","d":"to engage in excessive enthusiasm","e":"The critic rhapsodized about the movie, calling it an instant classic.","ev":"Nhà phê bình đã ca ngợi bộ phim và gọi nó là một tác phẩm kinh điển ngay lập tức.","k":"rhapsodize"},{"t":"Insinuate","p":"(v.)","d":"to suggest indirectly or subtly","e":"I wish Luke and Spencer would stop insinuating that my perfect report card is the result of anything other than my superior intelligence and good work habits.","ev":"Tôi ước gì Luke và Spencer ngừng bóng gió rằng bảng điểm hoàn hảo của tôi là kết quả của bất cứ điều gì khác ngoài trí thông minh vượt trội và thói quen làm việc tốt của tôi.","k":"insinuate"},{"t":"Refurbish","p":"(v.)","d":"to restore, clean up","e":"The dingy old chair, after being refurbished, commanded the handsome price of $200.","ev":"Chiếc ghế cũ kỹ tồi tàn sau khi được tân trang lại có giá 200 USD.","k":"refurbish"},{"t":"Travesty","p":"(n.)","d":"a grossly inferior imitation","e":"According to the school newspaper’s merciless theater critic, Pacific Coast High’s rendition of the musical Oklahoma was a travesty of the original.","ev":"Theo nhà phê bình sân khấu tàn nhẫn của tờ báo trường học, việc trình diễn vở nhạc kịch Oklahoma của trường Pacific Coast High là một trò hề so với bản gốc.","k":"travesty"},{"t":"Assail","p":"verb","d":"to attack","e":"The critics began to assail the film for its lack of originality.","ev":"Các nhà phê bình bắt đầu chỉ trích bộ phim vì sự thiếu sáng tạo.","k":"assail"},{"t":"Frivolous","p":"(adj.)","d":"of little importance, trifling","e":"Someday, all that anxiety about whether your zit will disappear before the prom will seem totally frivolous.","ev":"Một ngày nào đó, tất cả những lo lắng về việc liệu mụn của bạn có biến mất trước buổi vũ hội sẽ dường như hoàn toàn phù phiếm.","k":"frivolous"}]},{"n":"Chưa phân loại · 12","c":[{"t":"Transgress","p":"(v.)","d":"to violate, go over a limit","e":"The criminal’s actions transgressed morality and human decency.","ev":"Hành động của tội phạm đã vi phạm đạo đức và nhân cách con người.","k":"transgress"},{"t":"Incendiary","p":"(n.)","d":"a person who agitates","e":"If we catch the incendiary who screamed “bomb” in the middle of the soccer match, we’re going to put him in jail.","ev":"Nếu chúng ta bắt được kẻ gây cháy hét lên “bom” giữa trận đấu bóng đá, chúng ta sẽ tống hắn vào tù.","x":"Loại từ 2: (adj.)\nNghĩa 2: inflammatory, causing combustion\nVí dụ 2: Gas and lighter fluid are incendiary materials that should be kept out of hot storage areas.","k":"incendiary"},{"t":"Subtle","d":"not loud, bright, noticeable, or obvious","e":"The changes were subtle, barely noticeable.","ev":"Những thay đổi rất tinh tế, hầu như không đáng chú ý.","k":"subtle"},{"t":"Crux","d":"the essence, the main point","e":"The crux of the matter was whether or not they could afford the house, as financial constraints were the main obstacle.","ev":"Mấu chốt của vấn đề là liệu họ có đủ tiền mua căn nhà hay không, vì trở ngại chính là hạn chế về tài chính.","k":"crux"},{"t":"Prompt","d":"to cause (someone) to take a course of action","e":"The unexpected question prompted her to think carefully before responding, giving her time to gather her thoughts.","ev":"Câu hỏi bất ngờ khiến cô phải suy nghĩ kỹ trước khi trả lời, giúp cô có thời gian tập trung suy nghĩ.","k":"prompt"},{"t":"Retract","p":"(v.)","d":"withdraw","e":"As the media worked itself into a frenzy, the publicist hurriedly retracted his client’s sexist statement.","ev":"Khi giới truyền thông đang phát cuồng, nhà báo đã nhanh chóng rút lại tuyên bố phân biệt giới tính của khách hàng.","k":"retract"},{"t":"Epitome","p":"(n.)","d":"a perfect example, embodiment","e":"My mother, the epitome of good taste, always dresses more elegantly than I do.","ev":"Mẹ tôi, mẫu mực của gu thẩm mỹ tốt, luôn ăn mặc sang trọng hơn tôi.","k":"epitome"},{"t":"Constituent","p":"noun","d":"an essential part","e":"The most important constituent of her perfume is something called ambergris.","ev":"Ambergris là thành phần quan trọng trong nước hoa của cô ấy.","k":"constituent"},{"t":"Forsake","p":"(v.)","d":"to give up, renounce","e":"My New Year’s resolution is to forsake smoking and drinking.","ev":"Quyết tâm trong năm mới của tôi là từ bỏ hút thuốc và uống rượu.","k":"forsake"},{"t":"Raw","d":"adj. unrefined","e":"adj. unrefined","ev":"tính từ chưa tinh chế","k":"raw"},{"t":"Perplex","p":"(v.)","d":"to confuse","e":"Brad was perplexed by his girlfriend’s suddenly distant manner.","ev":"Brad cảm thấy bối rối trước thái độ xa cách đột ngột của bạn gái mình.","k":"perplex"},{"t":"Entrenched","d":"deep rooted","e":"His beliefs were so entrenched that it was nearly impossible to change his mind.","ev":"Niềm tin của anh đã cố thủ đến mức gần như không thể thay đổi được suy nghĩ của anh.","k":"entrenched"},{"t":"Appreciate","d":"to understand a situation and realize that it is important","e":"We appreciate the need for immediate action.","ev":"Chúng tôi đánh giá cao sự cần thiết phải hành động ngay lập tức.","x":"Nghĩa 2: to increase in value\nVí dụ 2: Our house has appreciated in value over the last two years.","k":"appreciate"},{"t":"Destitute","p":"noun","d":"impoverished, utterly lacking","e":"Many families are destitute and struggle to meet their basic needs.","ev":"Nhiều gia đình sống trong cảnh nghèo đói và vật lộn để đáp ứng nhu cầu cơ bản.","k":"destitute"},{"t":"Secrete","d":"v. to produce or release (a substance)","e":"v. to produce or release (a substance)","ev":"v. sản xuất hoặc giải phóng (một chất)","k":"secrete"},{"t":"Fidelity","p":"(n.)","d":"loyalty, devotion","e":"Guard dogs are known for the great fidelity they show toward their masters.","ev":"Chó bảo vệ được biết đến với lòng trung thành tuyệt vời mà chúng thể hiện đối với chủ của mình.","k":"fidelity"},{"t":"Torpid","p":"(adj.)","d":"lethargic, dormant, lacking motion","e":"The torpid whale floated, wallowing in the water for hours.","ev":"Con cá voi lười biếng nổi lên, đắm mình trong nước hàng giờ.","k":"torpid"},{"t":"Soluble","p":"(adj.)","d":"able to dissolve","e":"The plot of the spy film revolved around an untraceable and water-soluble poison.","ev":"Cốt truyện của phim điệp viên xoay quanh một loại chất độc không thể tìm ra và tan trong nước.","k":"soluble"},{"t":"Candid","d":"adj. direct, blunt","e":"adj. direct, blunt","ev":"tính từ trực tiếp, thẳng thừng","k":"candid"},{"t":"Susceptible","p":"adj","d":"easily influenced or harmed by something; vulnerable","e":"Children are often more susceptible to illnesses than adults.","ev":"Trẻ em thường dễ bị bệnh hơn người lớn.","k":"susceptible"},{"t":"Trenchant","p":"(adj.)","d":"effective, articulate, clear-cut","e":"The directions that accompanied my new cell phone were trenchant and easy to follow.","ev":"Những hướng dẫn đi kèm với chiếc điện thoại di động mới của tôi rất rõ ràng và dễ làm theo.","k":"trenchant"},{"t":"Spawn","d":"to produce, generate, or create","e":"The idea spawned a new business venture, leading to the creation of a successful company.","ev":"Ý tưởng này đã tạo ra một dự án kinh doanh mới, dẫn đến việc thành lập một công ty thành công.","k":"spawn"},{"t":"Perspicacity","p":"(adj.)","d":"shrewdness, perceptiveness","e":"The detective was too humble to acknowledge that his perspicacity was the reason for his professional success.","ev":"Vị thám tử quá khiêm tốn để thừa nhận rằng sự sáng suốt là nguyên nhân dẫn đến thành công trong nghề nghiệp của ông.","k":"perspicacity"},{"t":"Libertarian","p":"(adj.)","d":"advocating principles of liberty and free will","e":"The dissatisfied subjects overthrew the monarch and replaced him with a libertarian ruler who respected their democratic principles.","ev":"Những thần dân bất mãn đã lật đổ nhà vua và thay thế ông bằng một nhà cai trị theo chủ nghĩa tự do, người tôn trọng các nguyên tắc dân chủ của họ.","k":"libertarian"},{"t":"Archaic","p":"adjective","d":"of or relating to an earlier period in time, outdated","e":"In some regions, an archaic Chinese dialect is still spoken.","ev":"Ở một số vùng, một phương ngữ tiếng Trung cổ vẫn được nói.","k":"archaic"}]},{"n":"Chưa phân loại · 13","c":[{"t":"Surreptitious","p":"(adj.)","d":"stealthy","e":"The surreptitious CIA agents were able to get in and out of the house without anyone noticing.","ev":"Các đặc vụ CIA lén lút có thể ra vào ngôi nhà mà không ai để ý.","k":"surreptitious"},{"t":"Divisive","p":"adj","d":"causing dissent, discord","e":"The proposal was seen as divisive among the team.","ev":"Đề xuất bị coi là gây chia rẽ trong nhóm.","k":"divisive"},{"t":"Nostalgic","d":"feeling happy and also slightly sad when you think about things that happened in the past","e":"She felt nostalgic when she looked at the old photographs, remembering happier times.","ev":"Cô cảm thấy bồi hồi khi nhìn lại những bức ảnh cũ, nhớ về những khoảng thời gian hạnh phúc hơn.","k":"nostalgic"},{"t":"Debauch","p":"verb","d":"to corrupt by means of sensual, pleasures, trụy lạc","e":"An endless amount of good wine and cheese debauched the traveler.","ev":"Một lượng rượu và phô mai vô tận đã khiến người du lịch sa vào cám dỗ.","k":"debauch"},{"t":"Appalling","p":"adjective","d":"inspiring shock, horror, disgust","e":"The judge found the murderer’s crimes appalling.","ev":"Thẩm phán thấy tội ác của kẻ sát nhân thật kinh khủng.","k":"appalling"},{"t":"Implacable","p":"(adj.)","d":"incapable of being appeased or mitigated","e":"Watch out: once you shun Grandma’s cooking, she is totally implacable.","ev":"Hãy cẩn thận: một khi bạn tránh xa việc nấu ăn của bà, bà sẽ hoàn toàn không thể tha thứ được.","k":"implacable"},{"t":"Foreseeable","d":"adj. capable of being predicted or anticipated","e":"adj. capable of being predicted or anticipated","ev":"tính từ có khả năng được dự đoán hoặc dự đoán","k":"foreseeable"},{"t":"Bear","d":"v. to have as a characteristic","e":"v. to have as a characteristic","ev":"v. có đặc điểm","k":"bear"},{"t":"Extol","p":"verb","d":"to praise, revere","e":"The critics extolled the film for its stunning visuals and compelling story.","ev":"Các nhà phê bình ca ngợi bộ phim vì hình ảnh tuyệt đẹp và cốt truyện hấp dẫn.","k":"extol"},{"t":"Apt","p":"adjective","d":"appropriate or suitable in the circumstances","e":"She has an apt ability to solve complex problems quickly and efficiently.","ev":"Cô ấy có khả năng nhạy bén trong việc giải quyết các vấn đề phức tạp một cách nhanh chóng và hiệu quả.","k":"apt"},{"t":"Savvy","d":"adj. having practical intelligence or knowledge","e":"adj. having practical intelligence or knowledge","ev":"tính từ có trí thông minh hoặc kiến ​​thức thực tế","k":"savvy"},{"t":"Impartiality","d":"n. the equal and objective treatment of opposing views","e":"n. the equal and objective treatment of opposing views","ev":"N. sự đối xử bình đẳng và khách quan của các quan điểm đối lập","k":"impartiality"},{"t":"Alienate","d":"to cause someone to feel isolated or lonely","e":"Her rude comments alienated her from the group, making her feel lonely and isolated.","ev":"Những lời nhận xét thô lỗ của cô khiến cô xa lánh nhóm, khiến cô cảm thấy cô đơn và bị cô lập.","k":"alienate"},{"t":"Predisposed","d":"having a tendency toward","e":"He was predisposed to heart disease.","ev":"Anh ấy dễ mắc bệnh tim.","x":"Ví dụ 2: Science-Related Terms","k":"predisposed"},{"t":"Fiscal","d":"adj. related to (government) money","e":"adj. related to (government) money","ev":"tính từ liên quan đến tiền (chính phủ)","k":"fiscal"},{"t":"Circumlocution","p":"(n.)","d":"indirect and wordy language","e":"The professor’s habit of speaking in circumlocutions made it difficult to follow his lectures.","ev":"Thói quen nói vòng quanh của giáo sư khiến cho việc theo dõi bài giảng của ông trở nên khó khăn.","k":"circumlocution"},{"t":"Compunction","p":"(n.)","d":"distress caused by feeling guilty","e":"He felt compunction for the shabby way he’d treated her.","ev":"Anh cảm thấy ăn năn vì cách cư xử tồi tệ mà anh đã đối xử với cô.","k":"compunction"},{"t":"Blandishment","d":"a flattering remark or action used to persuade someone","e":"She was not swayed by his blandishments.","ev":"Cô không bị lay động bởi những lời tán tỉnh của anh.","k":"blandishment"},{"t":"Resolve","p":"(v.)","d":"to find a solution","e":"Sarah and Emma resolved their differences and shook hands.","ev":"Sarah và Emma giải quyết những khác biệt của họ và bắt tay nhau.","x":"Nghĩa 2: to firmly decide\nVí dụ 2: Lady Macbeth resolved to whip her husband into shape.","k":"resolve"},{"t":"Viscous","p":"adj","d":"not free flowing, syrupy","e":"The syrup was thick and viscous, making it difficult to pour.","ev":"Syrup đặc và sánh, khiến việc rót trở nên khó khăn.","k":"viscous"},{"t":"Anachronistic","p":"adjective","d":"being out of correct chronological order","e":"Saying that the Pyramids were built after the Titanic sank is anachronistic.","ev":"Nói rằng các Kim tự tháp được xây dựng sau khi Titanic chìm là sai thứ tự thời gian.","k":"anachronistic"},{"t":"Arboreal","p":"adjective","d":"of or relating to trees","e":"Leaves and roots are a few arboreal traits.","ev":"Lá và rễ là một vài đặc điểm liên quan đến cây.","k":"arboreal"},{"t":"Allay","p":"verb","d":"to soothe, ease","e":"The chairman of the Federal Reserve gave a speech to allay investors’ fears about an economic downturn.","ev":"Chủ tịch của Cục Dự trữ Liên bang đã có một bài phát biểu để xoa dịu nỗi lo sợ của các nhà đầu tư về một cuộc suy thoái kinh tế.","k":"allay"},{"t":"Taut","d":"adj. pulled tight","e":"adj. pulled tight","ev":"tính từ kéo chặt","k":"taut"},{"t":"Arbiter","p":"noun","d":"one who can resolve a dispute, make a decision","e":"The divorce court judge will serve as the arbiter between the estranged husband and wife.","ev":"Thẩm phán tòa án ly hôn sẽ đóng vai trò làm trọng tài giữa hai vợ chồng ly thân.","k":"arbiter"}]},{"n":"Chưa phân loại · 14","c":[{"t":"Embezzle","p":"(v.)","d":"to steal money by falsifying records","e":"The accountant was fired for embezzling $10,000 of the company’s funds.","ev":"Kế toán viên bị sa thải vì biển thủ 10.000 USD tiền quỹ của công ty.","k":"embezzle"},{"t":"Pertinacious","p":"(adj.)","d":"stubbornly persistent","e":"Harry’s parents were frustrated with his pertinacious insistence that a monster lived in his closet. Then they opened the closet door and were eaten.","ev":"Cha mẹ của Harry rất thất vọng với việc cậu khăng khăng khăng khăng rằng có một con quái vật sống trong tủ quần áo của cậu. Sau đó họ mở cửa tủ và bị ăn thịt.","k":"pertinacious"},{"t":"Vanity","d":"excessive pride in one's own appearance or achievements","e":"His vanity was evident in his constant need for attention and praise, always seeking validation from others.","ev":"Sự phù phiếm của anh ấy thể hiện rõ ở việc anh ấy thường xuyên cần được chú ý và khen ngợi, luôn tìm kiếm sự xác nhận từ người khác.","k":"vanity"},{"t":"Assess","p":"verb","d":"to evaluate","e":"The committee will assess the situation before making a decision.","ev":"Ủy ban sẽ đánh giá tình hình trước khi đưa ra quyết định.","k":"assess"},{"t":"Wallow","p":"(v.)","d":"to roll oneself indolently; to become or remain helpless","e":"My roommate can’t get over her breakup with her boyfriend and now just wallows in self-pity.","ev":"Bạn cùng phòng của tôi không thể vượt qua được cuộc chia tay với bạn trai và giờ chỉ đắm mình trong sự tủi thân.","k":"wallow"},{"t":"Paradox","p":"(n.)","d":"an apparently contradictory statement that is perhaps true","e":"The diplomat refused to acknowledge the paradox that negotiating a peace treaty would demand more resources than waging war.","ev":"Nhà ngoại giao này từ chối thừa nhận nghịch lý rằng việc đàm phán một hiệp ước hòa bình sẽ đòi hỏi nhiều nguồn lực hơn là tiến hành chiến tranh.","k":"paradox"},{"t":"Ostracism","p":"(n.)","d":"exclusion from a group","e":"Beth risked ostracism if her roommates discovered her flatulence.","ev":"Beth có nguy cơ bị tẩy chay nếu bạn cùng phòng phát hiện ra chứng đầy hơi của cô.","k":"ostracism"},{"t":"Attending","d":"accompanying","e":"the benefits attending the new job","ev":"những lợi ích khi tham gia công việc mới","k":"attending"},{"t":"Apathetic","p":"adjective","d":"lacking concern, emotion","e":"Bruno was apathetic about whether he lived under a capitalist or communist regime.","ev":"Bruno không quan tâm đến việc mình sống dưới chế độ tư bản hay cộng sản.","k":"apathetic"},{"t":"Diversification","d":"n. the act of becoming diverse","e":"n. the act of becoming diverse","ev":"N. hành động trở nên đa dạng","k":"diversification"},{"t":"Arrogate","p":"verb","d":"to take without justification","e":"The king arrogated the right to order executions to himself.","ev":"Vị vua đã tự cho mình quyền ra lệnh thi hành án tử.","k":"arrogate"},{"t":"Manifold","p":"(adj.)","d":"diverse, varied","e":"The popularity of Dante’s Inferno is partly due to the fact that the work allows for manifold interpretations.","ev":"Sự nổi tiếng của Inferno của Dante một phần là do tác phẩm cho phép diễn giải theo nhiều cách khác nhau.","k":"manifold"},{"t":"Flabbergasted","p":"(adj.)","d":"astounded","e":"Whenever I read an Agatha Christie mystery novel, I am always flabbergasted when I learn the identity of the murderer.","ev":"Bất cứ khi nào tôi đọc một cuốn tiểu thuyết bí ẩn của Agatha Christie, tôi luôn sửng sốt khi biết danh tính của kẻ sát nhân.","k":"flabbergasted"},{"t":"Covet","p":"verb","d":"to desire enviously","e":"I coveted Moses’s house, wife, and car.","ev":"Tôi thèm muốn nhà, vợ và xe của Moses.","k":"covet"},{"t":"Putrid","p":"(adj.)","d":"rotten, foul","e":"Those rotten eggs smell putrid.","ev":"Những quả trứng thối đó có mùi hôi thối.","k":"putrid"},{"t":"Vociferous","p":"(adj.)","d":"loud, boisterous","e":"I’m tired of his vociferous whining so I’m breaking up with him.","ev":"Tôi chán ngấy việc anh ấy than vãn ầm ĩ nên tôi chia tay anh ấy.","k":"vociferous"},{"t":"Verbose","p":"adjective","d":"wordy, impaired by wordiness","e":"His verbose speech included unnecessary details that bored the audience.","ev":"Bài phát biểu dài dòng của anh ấy bao gồm những chi tiết không cần thiết khiến khán giả chán nản.","k":"verbose"},{"t":"Sovereignty","d":"supreme power or authority","e":"The country regained its sovereignty after years of colonial rule, becoming an independent nation.","ev":"Đất nước giành lại chủ quyền sau nhiều năm bị thuộc địa chi phối, trở thành một quốc gia độc lập.","k":"sovereignty"},{"t":"Oblivious","p":"(adj.)","d":"lacking consciousness or awareness of something","e":"Oblivious to the burning smell emanating from the kitchen, my father did not notice that the rolls in the oven were burned until much too late.","ev":"Không để ý đến mùi khét tỏa ra từ bếp, bố tôi không để ý rằng những ổ bánh cuốn trong lò đã cháy cho đến khi quá muộn.","k":"oblivious"},{"t":"Pellucid","p":"(adj.)","d":"easily intelligible, clear","e":"Wishing his book to be pellucid to the common man, Albert Camus avoided using complicated grammar when composing The Stranger.","ev":"Với mong muốn cuốn sách của mình trở nên rõ ràng đối với người bình thường, Albert Camus tránh sử dụng ngữ pháp phức tạp khi sáng tác Người lạ.","k":"pellucid"},{"t":"Ennui","p":"(n.)","d":"boredom, weariness","e":"I feel such ennui that I don’t look forward to anything, not even my birthday party.","ev":"Tôi cảm thấy chán nản đến mức không mong chờ bất cứ điều gì, kể cả bữa tiệc sinh nhật của mình.","k":"ennui"},{"t":"Competent","d":"having the necessary ability, knowledge, or skill to do something successfully","e":"She was a competent employee, skilled at her job and reliable in her work.","ev":"Cô ấy là một nhân viên có năng lực, có tay nghề cao và đáng tin cậy trong công việc.","k":"competent"},{"t":"Dimissive","d":"khinh thường","e":"She gave a dismissive wave, indicating she wasn’t interested in the suggestion.","ev":"Cô ấy vẫy tay bác bỏ, cho thấy cô ấy không quan tâm đến lời đề nghị này.","k":"dimissive"},{"t":"Prowess","p":"(n.)","d":"extraordinary ability","e":"The musician had never taken a guitar lesson in his life, making his prowess with the instrument even more incredible.","ev":"Người nhạc sĩ chưa bao giờ học guitar trong đời, điều này khiến kỹ năng sử dụng nhạc cụ của anh càng trở nên đáng kinh ngạc hơn.","k":"prowess"},{"t":"Odious","p":"(adj.)","d":"instilling hatred or intense displeasure","e":"Mark was assigned the odious task of cleaning the cat’s litter box.","ev":"Mark được giao nhiệm vụ khó chịu là dọn hộp vệ sinh cho mèo.","k":"odious"}]},{"n":"Chưa phân loại · 15","c":[{"t":"Stark","d":"adj. very plain; devoid of any details or features","e":"adj. very plain; devoid of any details or features","ev":"tính từ rất đơn giản; không có bất kỳ chi tiết hoặc tính năng nào","k":"stark"},{"t":"Procure","p":"verb","d":"to obtain, acquire","e":"He worked hard to procure the necessary materials for the project.","ev":"Anh đã làm việc chăm chỉ để mua được những vật liệu cần thiết cho dự án.","k":"procure"},{"t":"Wanton","p":"(adj.)","d":"undisciplined, lewd, lustful","e":"Vicky’s wanton demeanor often made the frat guys next door very excited.","ev":"Thái độ phóng túng của Vicky thường xuyên khiến các anh chàng nhà bên rất thích thú.","k":"wanton"},{"t":"Impute","p":"(v.)","d":"to ascribe, blame","e":"The CEO imputed the many typos in the letter to his lazy secretary.","ev":"Giám đốc điều hành đã đổ lỗi cho nhiều lỗi chính tả trong bức thư gửi cho cô thư ký lười biếng của mình.","k":"impute"},{"t":"Isotope","d":"alternate form of an element","e":"Carbon-14 is a radioactive isotope of carbon.","ev":"Carbon-14 là đồng vị phóng xạ của carbon.","x":"Ví dụ 2: Science-Related Terms","k":"isotope"},{"t":"Nadir","p":"(n.)","d":"the lowest point of something","e":"My day was boring, but the nadir came when I accidentally spilled a bowl of spaghetti on my head.","ev":"Một ngày của tôi thật nhàm chán, nhưng điều tồi tệ nhất đã đến khi tôi vô tình làm đổ bát mì spaghetti lên đầu.","k":"nadir"},{"t":"Iniquity","p":"(n.)","d":"wickedness or sin","e":"“Your iniquity,” said the priest to the practical jokester, “will be forgiven.”","ev":"“Tội ác của bạn,” vị linh mục nói với người hay đùa, “sẽ được tha thứ.”","k":"iniquity"},{"t":"Meritorious","p":"(adj.)","d":"worthy of esteem or reward","e":"Manfred was given the congressional medal of honor for his meritorious actions.","ev":"Manfred đã được Quốc hội trao tặng Huân chương Danh dự vì những hành động có công của mình.","k":"meritorious"},{"t":"Robust","d":"strong and healthy, durable","e":"He was a robust man with a strong physique and good health.","ev":"Ông là một người đàn ông cường tráng, có thân hình cường tráng và sức khỏe tốt.","k":"robust"},{"t":"Vicarious","p":"adjective","d":"experiencing through another","e":"His vicarious experiences through books allowed him to explore the world without leaving home.","ev":"Những trải nghiệm gián tiếp của anh qua sách cho phép anh khám phá thế giới mà không cần rời khỏi nhà.","k":"vicarious"},{"t":"Multifarious","p":"adj","d":"having great diversity or variety","e":"The market offers a multifarious selection of goods and services.","ev":"Thị trường cung cấp một loạt các hàng hóa và dịch vụ đa dạng.","k":"multifarious"},{"t":"Goad","p":"(v.)","d":"to urge, spur, incite to action","e":"Jim may think he’s not going to fight Billy, but Billy will goad Jim on with insults until he throws a punch.","ev":"Jim có thể nghĩ rằng anh ấy sẽ không chiến đấu với Billy, nhưng Billy sẽ tiếp tục lăng mạ Jim cho đến khi anh ấy tung ra một cú đấm.","k":"goad"},{"t":"Emphatic","d":"adj. very expressive; using emphasis","e":"adj. very expressive; using emphasis","ev":"tính từ rất biểu cảm; sử dụng sự nhấn mạnh","k":"emphatic"},{"t":"Boost","d":"n. an increase or growth","e":"n. an increase or growth","ev":"N. sự gia tăng hoặc tăng trưởng","k":"boost"},{"t":"Dirge","p":"(n.)","d":"a mournful song, especially for a funeral","e":"The bagpipers played a dirge as the casket was carried to the cemetery.","ev":"Những người thổi kèn túi chơi một bản di chúc khi quan tài được khiêng đến nghĩa trang.","k":"dirge"},{"t":"Delegate (Verb)","d":"to assign a task to another person","e":"She delegated the task to her assistant, trusting her to complete it efficiently and effectively.","ev":"Cô giao nhiệm vụ cho trợ lý, tin tưởng cô sẽ hoàn thành công việc một cách hiệu quả và hiệu quả.","k":"delegate (verb)"},{"t":"Dynamic","p":"(adj.)","d":"actively changing","e":"The parents found it hard to keep up with the dynamic music scene with which their children had become very familiar.","ev":"Các bậc cha mẹ khó có thể theo kịp nền âm nhạc sôi động mà con cái họ đã quá quen thuộc.","k":"dynamic"},{"t":"Supercilious","p":"adj","d":"showing contempt or arrogance","e":"The supercilious remarks from the guest made everyone uncomfortable.","ev":"Những lời nhận xét kiêu ngạo của vị khách đã khiến mọi người cảm thấy khó chịu.","k":"supercilious"},{"t":"Pitiable","d":"adj. deserving pity","e":"adj. deserving pity","ev":"tính từ đáng tiếc","k":"pitiable"},{"t":"Rife","p":"(adj.)","d":"abundant","e":"Surprisingly, the famous novelist’s writing was rife with spelling errors.","ev":"Điều đáng ngạc nhiên là bài viết của tiểu thuyết gia nổi tiếng này đầy rẫy lỗi chính tả.","k":"rife"},{"t":"Atrophy","p":"verb","d":"to wither away, decay","e":"If not used, muscles can atrophy over time.","ev":"Nếu không sử dụng, cơ bắp có thể teo lại theo thời gian.","k":"atrophy"},{"t":"Ruminate","p":"(v.)","d":"to contemplate, reflect","e":"Terry liked to ruminate while sitting on the banks of the river, staring pensively into the water.","ev":"Terry thích ngẫm nghĩ khi ngồi bên bờ sông, trầm ngâm nhìn xuống nước.","k":"ruminate"},{"t":"Endow","d":"to provide, to supply","e":"The wealthy philanthropist endowed the university with a large donation.","ev":"Nhà từ thiện giàu có đã tài trợ cho trường đại học một khoản tiền lớn.","k":"endow"},{"t":"Acquisition","d":"something that is bought or obtained, an act of purchase","e":"The acquisition of the new company was a major milestone for the corporation, expanding its market share and increasing its profits.","ev":"Việc mua lại công ty mới là một cột mốc quan trọng đối với tập đoàn, mở rộng thị phần và tăng lợi nhuận.","k":"acquisition"},{"t":"Basic","d":"adj. relating to the foundation or basis of something","e":"adj. relating to the foundation or basis of something","ev":"tính từ liên quan đến nền tảng hoặc cơ sở của một cái gì đó","k":"basic"}]},{"n":"Chưa phân loại · 16","c":[{"t":"Reproach","p":"verb","d":"to scold, disapprove","e":"She looked at him with reproach when he failed to help.","ev":"Cô nhìn anh với ánh mắt trách móc khi anh không giúp đỡ.","k":"reproach"},{"t":"Astute","p":"adjective","d":"very clever, crafty","e":"The astute businessman quickly adapted to the changing market.","ev":"Doanh nhân khôn ngoan đã nhanh chóng thích ứng với thị trường đang thay đổi.","k":"astute"},{"t":"Miser","d":"someone who has a great desire to possess money and hates to spend it, keo kiệt","e":"He was a miser who hoarded money and refused to spend it.","ev":"Anh ta là một người keo kiệt, tích trữ tiền và không chịu tiêu nó.","k":"miser"},{"t":"Abrogate","p":"verb","d":"to abolish, usually by authority","e":"The Bill of Rights ensures the government cannot abrogate our right to free press.","ev":"Luật biểu quyền đảm bảo rằng chính phủ không thể xóa bỏ quyền tự do báo chí của chúng ta.","k":"abrogate"},{"t":"Contentious","p":"noun","d":"having a tendency to quarrel or dispute","e":"The contentious issue sparked a heated debate.","ev":"Vấn đề gây tranh cãi đã kích thích một cuộc tranh luận sôi nổi.","k":"contentious"},{"t":"Evanescent","p":"(adj.)","d":"fleeting, momentary","e":"My joy at getting promoted was evanescent because I discovered that I would have to work much longer hours in a less friendly office.","ev":"Niềm vui được thăng chức của tôi đã tan biến vì tôi phát hiện ra rằng mình sẽ phải làm việc nhiều giờ hơn trong một văn phòng kém thân thiện hơn.","k":"evanescent"},{"t":"Encore","p":"(n.)","d":"the audience’s demand for a repeat performance; also the artist’s performance in response to that demand","e":"At the end of the concert, all the fans yelled, “Encore! Encore!” but the band did not come out to play again.","ev":"Vào cuối buổi hòa nhạc, tất cả người hâm mộ đều hét lên: “Encore! Encore!” nhưng ban nhạc đã không ra chơi nữa.","k":"encore"},{"t":"Reprieve","p":"(n.)","d":"a temporary delay of punishment","e":"Because the governor woke up in a particularly good mood, he granted hundreds of reprieves to prisoners.","ev":"Bởi vì thống đốc tỉnh dậy với tâm trạng đặc biệt tốt nên ông đã ban hành hàng trăm ân xá cho các tù nhân.","k":"reprieve"},{"t":"Impassive","p":"(adj.)","d":"stoic, not susceptible to suffering","e":"Stop being so impassive; it’s healthy to cry every now and then.","ev":"Đừng tỏ ra quá thờ ơ; thỉnh thoảng khóc là điều tốt cho sức khỏe.","k":"impassive"},{"t":"Agile","p":"adjective","d":"quick, nimble","e":"The dogs were too slow to catch the agile rabbit.","ev":"Những chú chó quá chậm để bắt kịp con thỏ nhanh nhẹn.","k":"agile"},{"t":"Emit","d":"v. to discharge, give forth, or release","e":"v. to discharge, give forth, or release","ev":"v. xả, xả, xả","k":"emit"},{"t":"Indefatigable","p":"(adj.)","d":"incapable of defeat, failure, decay","e":"Even after traveling 62 miles, the indefatigable runner kept on moving.","ev":"Ngay cả khi đã đi được 62 dặm, người chạy không mệt mỏi vẫn tiếp tục di chuyển.","k":"indefatigable"},{"t":"Devise","d":"to plan or invent by careful thought","e":"The engineers devised a new plan to improve the efficiency of the system.","ev":"Các kỹ sư đã nghĩ ra một kế hoạch mới để nâng cao hiệu quả của hệ thống.","k":"devise"},{"t":"Recount","d":"to tell someone about something, to give a report of an event","e":"He recounted the story of his childhood, sharing his memories and experiences.","ev":"Anh kể lại câu chuyện thời thơ ấu của mình, chia sẻ những kỷ niệm, trải nghiệm của mình.","k":"recount"},{"t":"Freewheeling","d":"adj. carefree","e":"adj. carefree","ev":"tính từ vô tư","k":"freewheeling"},{"t":"Noxious","p":"adj","d":"harmful, unwholesome","e":"The noxious fumes from the factory were harmful to the local environment.","ev":"Khí độc hại từ nhà máy gây ảnh hưởng xấu đến môi trường địa phương.","k":"noxious"},{"t":"Subsequently","d":"adv. happening later or after something","e":"He was badly injured in the crash and subsequently died.","ev":"Anh ta bị thương nặng trong vụ va chạm và sau đó tử vong.","k":"subsequently"},{"t":"Solicitude","d":"care or concern for someone or something","e":"She showed great solicitude for the sick child, caring for him with tenderness and compassion.","ev":"Mẹ tỏ ra rất quan tâm đến đứa trẻ bị bệnh, chăm sóc nó với sự dịu dàng và cảm thông.","k":"solicitude"},{"t":"Quell","p":"verb","d":"to control or diffuse a potentially explosive situation","e":"The police were called to quell the disturbance at the event.","ev":"Cảnh sát đã được gọi đến để dập tắt sự náo động tại sự kiện.","k":"quell"},{"t":"Inflammatory","d":"arousing angry or violent feelings","e":"His inflammatory remarks sparked a heated debate, inciting anger and resentment among the audience.","ev":"Những nhận xét mang tính kích động của ông đã gây ra một cuộc tranh luận sôi nổi, kích động sự tức giận và phẫn nộ trong khán giả.","k":"inflammatory"},{"t":"Inexorable","p":"(adj.)","d":"incapable of being persuaded or placated","e":"Although I begged for hours, Mom was inexorable and refused to let me stay out all night after the prom.","ev":"Dù tôi van xin hàng giờ nhưng mẹ vẫn không tha và không cho tôi ở ngoài cả đêm sau buổi vũ hội.","k":"inexorable"},{"t":"Capitulate","p":"(v.)","d":"to surrender","e":"The army finally capitulated after fighting a long costly battle.","ev":"Quân đội cuối cùng đã đầu hàng sau một trận chiến tốn kém kéo dài.","k":"capitulate"},{"t":"Meddle","d":"interfere in something that is not one's concern","e":"She was always meddling in other people's business, offering unsolicited advice.","ev":"Cô ấy luôn can thiệp vào công việc của người khác, đưa ra lời khuyên không được yêu cầu.","k":"meddle"},{"t":"Modulate","p":"(v.)","d":"to pass from one state to another, especially in music","e":"The composer wrote a piece that modulated between minor and major keys.","ev":"Nhà soạn nhạc đã viết một đoạn được điều chế giữa phím thứ và phím trưởng.","k":"modulate"},{"t":"Boisterous","p":"(adj.)","d":"loud and full of energy","e":"The candidate won the vote after giving several boisterous speeches on television.","ev":"Ứng cử viên đã giành được phiếu bầu sau khi có nhiều bài phát biểu sôi nổi trên truyền hình.","k":"boisterous"}]},{"n":"Chưa phân loại · 17","c":[{"t":"Cerebral","p":"adj","d":"related to the intellect","e":"The cerebral nature of the discussion made it challenging for some to keep up.","ev":"Tính trí thức của cuộc thảo luận khiến một số người khó theo kịp.","k":"cerebral"},{"t":"Agitate","d":"1) to make someone troubled or nervous 2) to campaign for something in public","e":"The protesters agitated for change, demanding reforms and justice.","ev":"Những người biểu tình kích động đòi thay đổi, đòi cải cách và công lý.","k":"agitate"},{"t":"Antiseptic","p":"adjective","d":"clean, sterile","e":"The antiseptic hospital was very bare, but its cleanliness helped to keep patients healthy.","ev":"Bệnh viện khử trùng rất đơn giản, nhưng sự sạch sẽ của nó đã giúp giữ cho bệnh nhân khỏe mạnh.","k":"antiseptic"},{"t":"Succinct","p":"(adj.)","d":"marked by compact precision","e":"The governor’s succinct speech energized the crowd while the mayor’s rambled on and on.","ev":"Bài phát biểu ngắn gọn của thống đốc đã tiếp thêm sinh lực cho đám đông trong khi thị trưởng cứ huyên thuyên mãi.","k":"succinct"},{"t":"Berate","p":"verb","d":"to scold vehemently","e":"She berated him for being late to the important meeting.","ev":"Cô đã mắng mỏ anh vì đến muộn cuộc họp quan trọng.","k":"berate"},{"t":"Inviolable","p":"(adj.)","d":"secure from assault","e":"Nobody was ever able to break into Batman’s inviolable Batcave.","ev":"Không ai có thể đột nhập vào Batcave bất khả xâm phạm của Batman.","k":"inviolable"},{"t":"Vocation","p":"noun","d":"the work in which someone is employed, profession","e":"Teaching was her true vocation, and she excelled at it.","ev":"Giảng dạy là ơn gọi thực sự của cô, và cô đã xuất sắc trong lĩnh vực này.","k":"vocation"},{"t":"Impregnable","p":"(adj.)","d":"resistant to capture or penetration","e":"Though the invaders used battering rams, catapults, and rain dances, the fortress proved impregnable and resisted all attacks.","ev":"Mặc dù những kẻ xâm lược đã sử dụng máy đập phá, máy phóng và vũ điệu mưa, nhưng pháo đài tỏ ra bất khả xâm phạm và chống lại mọi cuộc tấn công.","k":"impregnable"},{"t":"Mollify","p":"(v.)","d":"to soften in temper","e":"The police officer mollified the angry woman by giving her a warning instead of a ticket.","ev":"Viên cảnh sát đã xoa dịu người phụ nữ đang tức giận bằng cách cảnh cáo cô thay vì phạt tiền.","k":"mollify"},{"t":"Adapt","d":"v. to make suit a new purpose","e":"v. to make suit a new purpose","ev":"v. thực hiện một mục đích mới","k":"adapt"},{"t":"Clandestine","p":"adj","d":"secret","e":"They held a clandestine meeting in the woods.","ev":"Họ tổ chức một cuộc họp bí mật trong rừng.","k":"clandestine"},{"t":"Penultimate","p":"(adj.)","d":"next to last","e":"Having smoked the penultimate cigarette remaining in the pack, Cybil discarded the last cigarette and resolved to quit smoking.","ev":"Hút hết điếu thuốc áp chót còn lại trong bao, Cybil vứt điếu thuốc cuối cùng và quyết tâm bỏ thuốc.","k":"penultimate"},{"t":"Feasible","d":"possible to do easily or conveniently","e":"The plan was feasible, but it would require a lot of effort and resources to implement.","ev":"Kế hoạch này khả thi nhưng đòi hỏi rất nhiều nỗ lực và nguồn lực để thực hiện.","k":"feasible"},{"t":"Conventional","d":"traditional, accepted, mainstream, standard","e":"He had a conventional upbringing and followed traditional values, preferring to stick to what was familiar and comfortable.","ev":"Anh ấy có một nền giáo dục truyền thống và tuân theo các giá trị truyền thống, thích gắn bó với những gì quen thuộc và thoải mái.","k":"conventional"},{"t":"Exult","p":"(v.)","d":"to rejoice","e":"When she found out she won the literature prize, Mary exulted by dancing and singing through the school’s halls.","ev":"Khi biết mình đoạt giải văn học, Mary đã vui mừng nhảy múa và ca hát khắp hội trường của trường.","k":"exult"},{"t":"Diaphanous","p":"(adj.)","d":"light, airy, transparent","e":"Sunlight poured in through the diaphanous curtains, brightening the room.","ev":"Ánh nắng xuyên qua tấm rèm trong mờ, chiếu sáng căn phòng.","k":"diaphanous"},{"t":"Apparent","d":"clearly visible or understood; obvious","e":"It was apparent that she was upset, as her face was flushed and her voice was trembling.","ev":"Rõ ràng là cô ấy đang rất buồn, mặt cô ấy đỏ bừng và giọng nói run rẩy.","k":"apparent"},{"t":"Placid","p":"adjective","d":"calm, peaceful","e":"The placid lake reflected the clear blue sky perfectly.","ev":"Hồ nước yên tĩnh phản chiếu bầu trời xanh trong một cách hoàn hảo.","k":"placid"},{"t":"Severity","d":"the quality of being very unpleasant, unkind, or difficult","e":"The severity of the storm caused widespread damage.","ev":"Mức độ nghiêm trọng của cơn bão đã gây ra thiệt hại trên diện rộng.","k":"severity"},{"t":"Prohibit","d":"v. to command against, to outlaw","e":"v. to command against, to outlaw","ev":"v. ra lệnh chống lại, đặt ra ngoài vòng pháp luật","k":"prohibit"},{"t":"Reinforce","d":"to make stronger","e":"The new evidence reinforced the original theory, providing additional support and credibility.","ev":"Bằng chứng mới đã củng cố lý thuyết ban đầu, cung cấp thêm sự hỗ trợ và độ tin cậy.","k":"reinforce"},{"t":"Compensate","p":"(v.)","d":"to make an appropriate payment for something","e":"Reginald bought Sharona a new dress to compensate her for the one he’d spilled his ice cream on.","ev":"Reginald mua cho Sharona một chiếc váy mới để đền bù cho chiếc váy mà anh đã làm đổ kem lên.","k":"compensate"},{"t":"Ignominious","p":"(adj.)","d":"humiliating, disgracing, ô nhục","e":"It was really ignominious to be kicked out of the dorm for having an illegal gas stove in my room.","ev":"Thật là nhục nhã khi bị đuổi ra khỏi ký túc xá vì trong phòng có bếp ga trái phép.","k":"ignominious"},{"t":"Exalt","p":"(v.)","d":"to glorify, praise","e":"Michael Jordan is the figure in basketball we exalt the most.","ev":"Michael Jordan là nhân vật trong bóng rổ mà chúng tôi đề cao nhất.","k":"exalt"},{"t":"Precipice","p":"(n.) /ˈpres.ə.pɪs/","d":"the face of a cliff, a steep or overhanging place, vách đứng, mỏm đá","e":"The mountain climber hung from a precipice before finding a handhold and pulling himself up.","ev":"Người leo núi treo mình trên vách đá trước khi tìm được chỗ bám và kéo mình lên.","x":"Nghĩa 2: a dangerous situation that could lead to harm or failure\nVí dụ 2: This latest tax increase may push many small companies over the financial precipice.","k":"precipice"}]},{"n":"Chưa phân loại · 18","c":[{"t":"Swarthy","p":"(adj.)","d":"of dark color or complexion","e":"When he got drunk, Robinson’s white skin became rather swarthy.","ev":"Khi say, làn da trắng trẻo của Robinson trở nên khá đen sạm.","k":"swarthy"},{"t":"Umbrage","p":"(n.)","d":"resentment, offense","e":"He called me a lily-livered coward, and I took umbrage at the insult.","ev":"Anh ta gọi tôi là kẻ hèn nhát có lá hoa huệ, và tôi rất tức giận trước lời xúc phạm đó.","k":"umbrage"},{"t":"Tenable","p":"(adj.)","d":"able to be defended or maintained","e":"The department heads tore down the arguments in other people’s theses, but Johari’s work proved to be quite tenable.","ev":"Các trưởng bộ phận đã bác bỏ những lập luận trong luận văn của người khác, nhưng công việc của Johari tỏ ra khá vững chắc.","k":"tenable"},{"t":"Mawkish","p":"(adj.)","d":"characterized by sick sentimentality","e":"Although some nineteenth- century critics viewed Dickens’s writing as mawkish, contemporary readers have found great emotional depth in his works.","ev":"Mặc dù một số nhà phê bình thế kỷ 19 coi tác phẩm của Dickens là ngớ ngẩn, độc giả đương đại đã tìm thấy chiều sâu cảm xúc sâu sắc trong tác phẩm của ông.","k":"mawkish"},{"t":"Cacophony","p":"(n.)","d":"tremendous noise, disharmonious sound","e":"The elementary school orchestra created a cacophony at the recital.","ev":"Dàn nhạc của trường tiểu học đã tạo ra một bản giao hưởng trong buổi biểu diễn.","k":"cacophony"},{"t":"Redress","d":"to correct a wrong","e":"The government promised to redress the grievances of the victims.","ev":"Chính phủ hứa sẽ giải quyết khiếu nại của các nạn nhân.","k":"redress"},{"t":"Notorious","p":"(adj.)","d":"widely and unfavorably known","e":"Jacob was notorious for always arriving late at parties.","ev":"Jacob nổi tiếng là người luôn đến muộn trong các bữa tiệc.","k":"notorious"},{"t":"Harangue","p":"(n.)","d":"a ranting speech","e":"Everyone had heard the teacher’s harangue about gum chewing in class before.","ev":"Mọi người trước đây đã nghe giáo viên giảng về việc nhai kẹo cao su trong lớp.","x":"Loại từ 2: (v.)\nNghĩa 2: to give such a speech\nVí dụ 2: But this time the teacher harangued the class about the importance of brushing your teeth after chewing gum.","k":"harangue"},{"t":"Excel","d":"v. to do something extremely well or to be superior in","e":"v. to do something extremely well or to be superior in","ev":"v. làm điều gì đó cực kỳ tốt hoặc vượt trội trong","k":"excel"},{"t":"Lurid","p":"adj","d":"ghastly, sensational","e":"The movie was filled with lurid details.","ev":"Bộ phim đầy những chi tiết gây sốc.","k":"lurid"},{"t":"Abridge","p":"verb","d":"to cut down, shorten","e":"(1) The publisher abridged the dictionary. (2) Even the abridged version is quite long.","ev":"(1) Nhà xuất bản đã rút gọn từ điển. (2) Ngay cả phiên bản rút gọn cũng khá dài.","k":"abridge"},{"t":"Abnegation","p":"noun","d":"denial of comfort to oneself","e":"The holy man practiced abnegation through simple living.","ev":"Người thánh thiện thực hành sự từ bỏ bằng cách sống đơn giản.","k":"abnegation"},{"t":"Equanimity","p":"noun","d":"composure","e":"She maintained her equanimity during the crisis, making rational decisions.","ev":"Cô giữ được sự điềm tĩnh trong cuộc khủng hoảng, đưa ra những quyết định hợp lý.","k":"equanimity"},{"t":"Intrinsic/ Innate","d":"Inborn, a natural part of","e":"He has an innate talent for music.","ev":"Anh ấy có tài năng bẩm sinh về âm nhạc.","x":"Ví dụ 2: not negative","k":"intrinsic/ innate"},{"t":"Tractable","p":"adj","d":"easily controlled","e":"The dog was surprisingly tractable, following every command without hesitation.","ev":"Chú chó thật bất ngờ khi rất dễ bảo, nghe theo mọi lệnh mà không do dự.","k":"tractable"},{"t":"Allege","p":"verb","d":"to assert, usually without proof","e":"The policeman alleged that Marshall committed the crime, but he was set free after the investigation turned up no evidence.","ev":"Cảnh sát cáo buộc rằng Marshall đã phạm tội, nhưng sau khi điều tra không tìm thấy bằng chứng, Marshall được thả.","k":"allege"},{"t":"Pallid","p":"(adj.)","d":"lacking color","e":"Dr. Van Helsing feared that Lucy’s pallid complexion was due to an unexplained loss of blood.","ev":"Tiến sĩ Van Helsing lo sợ rằng nước da xanh xao của Lucy là do mất máu không rõ nguyên nhân.","k":"pallid"},{"t":"Opine","d":"v. to openly express an opinion","e":"v. to openly express an opinion","ev":"v. bày tỏ quan điểm một cách công khai","k":"opine"},{"t":"Lenient","p":"(adj.)","d":"demonstrating tolerance or gentleness","e":"Because Professor Oglethorpe allowed his students to choose their final grades, the other teachers believed that he was excessively lenient.","ev":"Bởi vì Giáo sư Oglethorpe cho phép học sinh của mình chọn điểm cuối cùng nên các giáo viên khác tin rằng ông đã quá khoan dung.","k":"lenient"},{"t":"Arcane","p":"adj","d":"obscure, secret, known only by a few","e":"The instructions were filled with arcane language.","ev":"Hướng dẫn chứa đầy ngôn ngữ bí ẩn.","k":"arcane"},{"t":"Consecrate","p":"verb","d":"to dedicate something to a holy purpose","e":"Arvin consecrated his spare bedroom as a shrine to Christina.","ev":"Anh đã dành phòng dự trữ làm nơi thờ cúng.","k":"consecrate"},{"t":"Exhilarating","d":"adj. invigorating, stimulating, or exciting","e":"adj. invigorating, stimulating, or exciting","ev":"tính từ tiếp thêm sinh lực, kích thích, hoặc thú vị","k":"exhilarating"},{"t":"Nonchalant","p":"(adj.)","d":"having a lack of concern, indifference","e":"Although deep down she was very angry, Marsha acted in a nonchalant manner when she found out that her best friend had used her clothing without asking.","ev":"Dù trong thâm tâm rất tức giận nhưng Marsha lại hành động thờ ơ khi biết bạn thân đã sử dụng quần áo của mình mà không hỏi ý kiến.","k":"nonchalant"},{"t":"Collateral","p":"(adj.)","d":"secondary","e":"Divorcing my wife had the collateral effect of making me poor, as she was the only one of us with a job or money.","ev":"Việc ly hôn với vợ tôi có tác động phụ là khiến tôi trở nên nghèo khó, vì cô ấy là người duy nhất trong chúng tôi có việc làm hoặc tiền bạc.","x":"Loại từ 2: (n.)\nNghĩa 2: security for a debt\nVí dụ 2: Jacob left his watch as collateral for the $500 loan.","k":"collateral"},{"t":"Compress","p":"(v.)","d":"to apply pressure, squeeze together","e":"Lynn compressed her lips into a frown.","ev":"Lynn mím môi thành một cái cau mày.","k":"compress"}]},{"n":"Chưa phân loại · 19","c":[{"t":"Profuse","p":"(adj.)","d":"plentiful, abundant","e":"The fans were profuse in their cheers for the star basketball player.","ev":"Người hâm mộ đã hết sức cổ vũ cho cầu thủ bóng rổ ngôi sao.","k":"profuse"},{"t":"Terrestrial","p":"(adj.)","d":"relating to the land","e":"Elephants are terrestrial animals.","ev":"Voi là động vật sống trên cạn.","k":"terrestrial"},{"t":"Tantamount","p":"(adj.)","d":"equivalent in value or significance","e":"When it comes to sports, fearing your opponent is tantamount to losing.","ev":"Trong thể thao, sợ hãi đối thủ đồng nghĩa với việc thua cuộc.","k":"tantamount"},{"t":"Avid","d":"passionate about something","e":"She was an avid reader who loved to learn new things, devouring books from all genres.","ev":"Cô là một người ham đọc sách, thích tìm hiểu những điều mới, ngấu nghiến sách thuộc mọi thể loại.","k":"avid"},{"t":"Aggrieved","p":"adjective","d":"distressed, wronged, injured","e":"The foreman mercilessly overworked his aggrieved employees.","ev":"Người giám sát đã làm việc quá sức với các nhân viên bị tổn thương của mình.","k":"aggrieved"},{"t":"Subservient","p":"adj","d":"prepared to obey others, submissive, less important","e":"He took a subservient role in the project, always putting others' needs first.","ev":"Anh đảm nhận một vai trò phụ thuộc trong dự án, luôn đặt nhu cầu của người khác lên hàng đầu.","k":"subservient"},{"t":"Fortuitous","p":"adj","d":"happening by chance, often lucky or fortunate","e":"It was a fortuitous meeting that changed everything.","ev":"Đó là một cuộc gặp gỡ tình cờ đã thay đổi mọi thứ.","k":"fortuitous"},{"t":"Impervious","p":"(adj.)","d":"impenetrable, incapable of being affected","e":"Because of their thick layer of fur, many seals are almost impervious to the cold.","ev":"Vì có lớp lông dày nên nhiều hải cẩu gần như không chịu được cái lạnh.","k":"impervious"},{"t":"Unmitigated","d":"adj. downright, utter, total","e":"adj. downright, utter, total","ev":"tính từ hết sức, hoàn toàn, toàn bộ","k":"unmitigated"},{"t":"Stimulate","d":"to trigger, spark, or activate; to excite","e":"The caffeine stimulated her brain, making her feel more alert and focused.","ev":"Chất caffeine kích thích não cô, khiến cô cảm thấy tỉnh táo và tập trung hơn.","k":"stimulate"},{"t":"Bard","p":"noun","d":"a poet, often a singer as well","e":"Shakespeare is often considered the greatest bard in English history.","ev":"Shakespeare thường được coi là nhà thơ vĩ đại nhất trong lịch sử tiếng Anh.","k":"bard"},{"t":"Patent","p":"(adj.)","d":"readily seen or understood, clear","e":"The reason for Jim’s abdominal pain was made patent after the doctor performed a sonogram.","ev":"Nguyên nhân khiến Jim bị đau bụng đã được xác nhận sau khi bác sĩ thực hiện siêu âm.","k":"patent"},{"t":"Sluggish","d":"slow-moving","e":"The economy was sluggish and jobs were scarce, leading to widespread unemployment and financial hardship.","ev":"Nền kinh tế trì trệ và việc làm khan hiếm, dẫn đến tình trạng thất nghiệp lan rộng và khó khăn về tài chính.","k":"sluggish"},{"t":"Acumen","p":"noun","d":"keen insight","e":"Her business acumen helped her make successful investments.","ev":"Khả năng nhạy bén trong kinh doanh của cô đã giúp cô thực hiện những khoản đầu tư thành công.","k":"acumen"},{"t":"Deter","p":"(v.)","d":"to discourage, prevent from doing","e":"Bob’s description of scary snakes couldn’t deter Marcia from traveling in the rainforests.","ev":"Mô tả của Bob về những con rắn đáng sợ không thể ngăn cản Marcia đi du lịch trong rừng nhiệt đới.","k":"deter"},{"t":"Protean","p":"(adj.)","d":"able to change shape; displaying great variety","e":"Among Nigel’s protean talents was his ability to touch the tip of his nose with his tongue.","ev":"Một trong những tài năng linh hoạt của Nigel là khả năng dùng lưỡi chạm vào chóp mũi của anh ấy.","k":"protean"},{"t":"Repose","p":"(v.)","d":"to rest, lie down","e":"The cat, after eating an entire can of tuna fish, reposed in the sun and took a long nap.","ev":"Con mèo sau khi ăn hết hộp cá ngừ đã nằm phơi nắng và đánh một giấc dài.","k":"repose"},{"t":"Accost","p":"verb","d":"to confront verbally","e":"He was accosted by a stranger asking for directions.","ev":"Anh bị một người lạ tiếp cận và hỏi đường.","k":"accost"},{"t":"Resplendent","p":"(adj.)","d":"shiny, glowing","e":"The partygoers were resplendent in diamonds and fancy dress.","ev":"Những người dự tiệc rực rỡ với những viên kim cương và những bộ váy sang trọng.","k":"resplendent"},{"t":"Formulate","d":"to create or think up","e":"The scientists formulated a new theory to explain the phenomenon, based on extensive research and experimentation.","ev":"Các nhà khoa học đã xây dựng một lý thuyết mới để giải thích hiện tượng này, dựa trên nghiên cứu và thử nghiệm sâu rộng.","k":"formulate"},{"t":"Plight","d":"a dangerous, difficult, or otherwise unfortunate situation","e":"The refugees were in a desperate plight, lacking food, shelter, and medical care.","ev":"Những người tị nạn rơi vào hoàn cảnh tuyệt vọng, thiếu lương thực, nơi ở và chăm sóc y tế.","k":"plight"},{"t":"Stingy","p":"(adj.)","d":"not generous, not inclined to spend or give","e":"Scrooge’s stingy habits did not fit with the generous, giving spirit of Christmas.","ev":"Thói quen keo kiệt của Scrooge không phù hợp với tinh thần hào phóng, cho đi của Giáng sinh.","k":"stingy"},{"t":"Cupidity","p":"noun","d":"greed, strong desire","e":"His cupidity made him enter the abandoned gold mine despite the obvious dangers.","ev":"Sự tham lam khiến anh vào mỏ vàng bỏ hoang mặc dù có nhiều nguy hiểm.","k":"cupidity"},{"t":"Bittersweet","d":"adj. tinged with a feeling of sadness","e":"adj. tinged with a feeling of sadness","ev":"tính từ nhuốm màu cảm giác buồn bã","k":"bittersweet"},{"t":"Antipathy","p":"noun","d":"a strong dislike, repugnance","e":"His antipathy toward the new policy was clear in his comments.","ev":"Sự chống đối của anh đối với chính sách mới đã rõ ràng trong những nhận xét của anh.","k":"antipathy"}]},{"n":"Chưa phân loại · 20","c":[{"t":"Aerial","p":"adjective","d":"somehow related to the air","e":"The fighter planes conducted impressive aerial maneuvers.","ev":"Các máy bay chiến đấu đã thực hiện các động tác trên không ấn tượng.","k":"aerial"},{"t":"Solemn","d":"having or showing serious purpose and determination; formal","e":"The funeral was a solemn occasion, filled with sadness and grief.","ev":"Đám tang là một dịp trang trọng, đầy đau buồn và đau buồn.","k":"solemn"},{"t":"Provoke","d":"to cause a reaction or emotion (usually anger); to trigger","e":"Her rude remarks provoked an angry response, leading to a heated argument and a tense atmosphere.","ev":"Những lời nhận xét thô lỗ của cô đã gây ra phản ứng giận dữ, dẫn đến một cuộc tranh cãi nảy lửa và bầu không khí căng thẳng.","k":"provoke"},{"t":"Stagnate","p":"(v.)","d":"to become or remain inactive, not develop, not flow","e":"With no room for advancement, the waiter’s career stagnated.","ev":"Không có cơ hội thăng tiến, sự nghiệp của người phục vụ bị đình trệ.","k":"stagnate"},{"t":"Conundrum","p":"(n.)","d":"puzzle, problem","e":"Interpreting Jane’s behavior was a constant conundrum.","ev":"Giải thích hành vi của Jane luôn là một câu hỏi hóc búa.","k":"conundrum"},{"t":"Deliberate","p":"(adj.)","d":"intentional, reflecting careful consideration","e":"Though Mary was quite upset, her actions to resolve the dispute were deliberate.","ev":"Mặc dù Mary khá khó chịu nhưng hành động giải quyết tranh chấp của cô là có chủ ý.","k":"deliberate"},{"t":"Desiccated","p":"(adj.)","d":"dried up, dehydrated","e":"The skin of the desiccated mummy looked like old paper.","ev":"Da của xác ướp khô trông giống như tờ giấy cũ.","k":"desiccated"},{"t":"Reclusive","p":"(adj.)","d":"solitary, shunning society","e":"Reclusive authors such as J.D. Salinger do not relish media attention and sometimes even enjoy holing up in remote cabins in the woods.","ev":"Các tác giả ẩn dật như J.D. Salinger không thích sự chú ý của giới truyền thông và đôi khi thậm chí còn thích ẩn náu trong những căn nhà gỗ hẻo lánh trong rừng.","k":"reclusive"},{"t":"Undulate","p":"(v.)","d":"to move in waves","e":"As the storm began to brew, the placid ocean began to undulate to an increasing degree.","ev":"Khi cơn bão bắt đầu nổi lên, đại dương êm đềm bắt đầu nhấp nhô với mức độ ngày càng tăng.","k":"undulate"},{"t":"Dilatory","p":"adj","d":"tending to delay, causing delay","e":"His dilatory tactics annoyed the manager.","ev":"Chiến thuật chậm chạp của anh ta làm phiền quản lý.","k":"dilatory"},{"t":"Ebullient","p":"adjective","d":"extremely lively, enthusiastic","e":"His ebullient personality made him popular among his peers.","ev":"Tính cách sôi nổi của anh đã khiến anh được yêu mến trong nhóm bạn.","k":"ebullient"},{"t":"Relish","p":"(v.)","d":"to enjoy","e":"Pete always relished his bedtime snack.","ev":"Pete luôn thích thú với bữa ăn nhẹ trước khi đi ngủ.","k":"relish"},{"t":"Extensive","d":"large in amount or scale","e":"His knowledge of the subject was extensive, covering a wide range of topics and details.","ev":"Kiến thức của ông về chủ đề này rất sâu rộng, bao gồm nhiều chủ đề và chi tiết.","k":"extensive"},{"t":"Wizened","p":"(adj.)","d":"dry, shrunken, wrinkled","e":"Agatha’s grandmother, Stephanie, had the most wizened countenance, full of leathery wrinkles.","ev":"Bà của Agatha, Stephanie, có khuôn mặt nhăn nheo nhất, đầy nếp nhăn.","k":"wizened"},{"t":"Sanctimonious","p":"adj","d":"giving a hypocritical appearance of piety","e":"She made a sanctimonious speech about ethics.","ev":"Cô ấy đã có một bài phát biểu đạo đức giả về đạo đức.","k":"sanctimonious"},{"t":"Empathy","p":"(n.)","d":"sensitivity to another’s feelings as if they were one’s own","e":"I feel such empathy for my sister when she’s in pain that I cry too.","ev":"Tôi cảm thấy đồng cảm với chị gái mình khi chị ấy đau đớn đến mức tôi cũng khóc.","k":"empathy"},{"t":"Discursive","p":"(adj.)","d":"rambling, lacking order","e":"The professor’s discursive lectures seemed to be about every subject except the one initially described.","ev":"Các bài giảng mang tính diễn ngôn của giáo sư dường như nói về mọi chủ đề ngoại trừ chủ đề được mô tả ban đầu.","k":"discursive"},{"t":"Clout","d":"power and influence (especially in politics or business)","e":"He used his clout to get what he wanted, relying on his influence and connections.","ev":"Anh ta sử dụng quyền lực của mình để đạt được điều mình muốn, dựa vào ảnh hưởng và mối quan hệ của mình.","k":"clout"},{"t":"Prosecute","d":"v. to bring criminal action against someone (in a trial)","e":"v. to bring criminal action against someone (in a trial)","ev":"v. khởi kiện hình sự chống lại ai đó (trong một phiên tòa)","k":"prosecute"},{"t":"Prejudice","d":"a dislike or unfair opinion (of someone) that is not based on reason or actual experience","e":"His prejudice against people of different cultures prevented him from forming meaningful relationships.","ev":"Thành kiến ​​của ông đối với những người thuộc các nền văn hóa khác nhau đã ngăn cản ông hình thành những mối quan hệ có ý nghĩa.","k":"prejudice"},{"t":"Strident","p":"adj","d":"harsh, loud","e":"Her strident voice could be heard above the noise of the crowd.","ev":"Giọng nói chói tai của cô có thể nghe thấy trên tiếng ồn của đám đông.","k":"strident"},{"t":"Malevolent","p":"(adj.)","d":"wanting harm to befall others, xấu bụng","e":"The malevolent old man sat in the park all day, tripping unsuspecting passersby with his cane.","ev":"Ông già độc ác ngồi trong công viên cả ngày, dùng gậy vấp ngã những người qua đường không chút nghi ngờ.","k":"malevolent"},{"t":"Calumny","p":"(n.)","d":"an attempt to spoil someone else’s reputation by spreading lies","e":"The local official’s calumny ended up ruining his opponent’s prospect of winning the election.","ev":"Lời vu khống của quan chức địa phương cuối cùng đã hủy hoại triển vọng giành chiến thắng trong cuộc bầu cử của đối thủ.","k":"calumny"},{"t":"Inefficacious","d":"unable to produce the intended result","e":"The medicine was inefficacious, having no effect on the illness.","ev":"Thuốc không có tác dụng, không có tác dụng chữa bệnh.","k":"inefficacious"},{"t":"Yielding","d":"giving in to or complying with the requests of others, nhân nhượng","e":"she is rarely yielding on such an issue","ev":"cô ấy hiếm khi nhượng bộ trong một vấn đề như vậy","k":"yielding"}]},{"n":"Chưa phân loại · 21","c":[{"t":"Construe","p":"verb","d":"to interpret","e":"He construed her throwing his clothes out the window as a signal that she wanted him to leave.","ev":"Anh đã diễn giải hành động của cô ấy như một dấu hiệu rằng cô ấy muốn anh rời đi.","k":"construe"},{"t":"Rancid","p":"(adj.)","d":"having a terrible taste or smell","e":"Rob was double-dog-dared to eat the rancid egg salad sandwich.","ev":"Rob đã liều lĩnh ăn món bánh sandwich salad trứng ôi thiu.","k":"rancid"},{"t":"Preliminary","d":"occurring before the main event","e":"This is just a preliminary report.","ev":"Đây chỉ là báo cáo sơ bộ.","x":"Ví dụ 2: general","k":"preliminary"},{"t":"Maverick","p":"(n.)","d":"an independent, nonconformist person","e":"Andreas is a real maverick and always does things his own way.","ev":"Andreas là một người lập dị thực sự và luôn làm mọi việc theo cách riêng của mình.","k":"maverick"},{"t":"Anticipate","d":"v. assume to be likely to happen","e":"v. assume to be likely to happen","ev":"v. giả sử có khả năng xảy ra","k":"anticipate"},{"t":"Unprecedented","d":"never done or known before","e":"The storm caused unprecedented damage to the city, destroying homes, businesses, and infrastructure on a massive scale.","ev":"Cơn bão đã gây ra thiệt hại chưa từng có cho thành phố, phá hủy nhà cửa, cơ sở kinh doanh và cơ sở hạ tầng trên quy mô lớn.","k":"unprecedented"},{"t":"Pummel","d":"to hit someone or something repeatedly","e":"The boxer pummeled his opponent, delivering a series of punches.","ev":"Võ sĩ tung ra hàng loạt cú đấm liên tiếp vào đối thủ.","k":"pummel"},{"t":"Curt","p":"adjective","d":"abruptly and rudely short","e":"Her curt reply to my question made me realize that she was upset at me.","ev":"Câu trả lời ngắn gọn của cô khiến tôi nhận ra rằng cô đang bực mình.","k":"curt"},{"t":"Truculent","p":"(adj.)","d":"ready to fight, cruel","e":"This club doesn’t really attract the dangerous types, so why was that bouncer being so truculent?","ev":"Câu lạc bộ này không thực sự thu hút những loại nguy hiểm, vậy tại sao người bảo vệ đó lại hung hãn như vậy?","k":"truculent"},{"t":"Forum","p":"(n.)","d":"a medium for lecture or discussion","e":"Some radio talk-shows provide a good forum for political debate.","ev":"Một số chương trình trò chuyện trên đài phát thanh cung cấp một diễn đàn tốt cho các cuộc tranh luận chính trị.","k":"forum"},{"t":"Panacea","p":"(n.)","d":"a remedy for all ills or difficulties","e":"Doctors wish there was a single panacea for every disease, but sadly there is not.","ev":"Các bác sĩ mong muốn có một loại thuốc chữa bách bệnh cho mọi căn bệnh, nhưng thật đáng buồn là không có.","k":"panacea"},{"t":"Beneficial","d":"having a positive effect","e":"Exercise is beneficial for your health.","ev":"Tập thể dục có lợi cho sức khỏe của bạn.","k":"beneficial"},{"t":"Enthrall","p":"(v.)","d":"to charm, hold spellbound","e":"The sailor’s stories of fighting off sharks and finding ancient treasures enthralled his young son.","ev":"Những câu chuyện về cuộc chiến chống lại cá mập và tìm kiếm kho báu cổ xưa của người thủy thủ đã khiến cậu con trai nhỏ của ông say mê.","k":"enthrall"},{"t":"Choreography","p":"(n.)","d":"the arrangement of dances","e":"The plot of the musical was banal, but the choreography was stunning.","ev":"Cốt truyện của vở nhạc kịch rất tầm thường, nhưng vũ đạo thì tuyệt đẹp.","k":"choreography"},{"t":"Demarcation","p":"(n.)","d":"the marking of boundaries or categories","e":"Different cultures have different demarcations of good and evil.","ev":"Các nền văn hóa khác nhau có những ranh giới khác nhau về thiện và ác.","k":"demarcation"},{"t":"Corpulence","p":"adjective","d":"extreme fatness","e":"Henry’s corpulence did not make him any less attractive to his charming, svelte wife.","ev":"Sự mập mạp của Henry không làm giảm đi sức hấp dẫn của anh với vợ mình.","k":"corpulence"},{"t":"Hallowed","p":"(adj.)","d":"revered, consecrated","e":"In the hallowed corridors of the cathedral, the disturbed professor felt himself to be at peace.","ev":"Trong hành lang thiêng liêng của nhà thờ, vị giáo sư bối rối cảm thấy mình bình yên.","k":"hallowed"},{"t":"Indiscriminately","d":"adv. randomly; with little or no distinction","e":"adv. randomly; with little or no distinction","ev":"lời khuyên. ngẫu nhiên; với rất ít hoặc không có sự khác biệt","k":"indiscriminately"},{"t":"Palette","p":"(adj.)","d":"a range of colors or qualities","e":"The palette of colors utilized in the painting was equaled only by the range of intense emotions the piece evoked.","ev":"Bảng màu được sử dụng trong bức tranh chỉ tương đương với phạm vi cảm xúc mãnh liệt mà tác phẩm gợi lên.","k":"palette"},{"t":"Litigant","p":"(n.)","d":"someone engaged in a lawsuit","e":"When the litigants began screaming at each other, Judge Koch ordered them to be silent.","ev":"Khi các đương sự bắt đầu la hét với nhau, Thẩm phán Koch ra lệnh cho họ im lặng.","k":"litigant"},{"t":"Requisition","p":"(n.)","d":"a demand for goods, usually made by an authority","e":"During the war, the government made a requisition of supplies.","ev":"Trong chiến tranh, chính phủ đã trưng dụng vật tư.","k":"requisition"},{"t":"Audacious","p":"adj.","d":"excessively bold","e":"The security guard was shocked by the fan’s audacious attempt to bribe him.","ev":"Nhân viên bảo vệ đã sốc trước nỗ lực táo bạo của người hâm mộ khi hối lộ anh.","k":"audacious"},{"t":"Impertinent","p":"(adj.)","d":"rude, insolent","e":"Most of your comments are so impertinent that I don’t wish to dignify them with an answer.","ev":"Hầu hết các nhận xét của bạn đều xấc xược đến mức tôi không muốn đánh giá cao họ bằng một câu trả lời.","k":"impertinent"},{"t":"Turpitude","p":"(n.)","d":"depravity, moral corruption, đồi bại, đồi trụy","e":"Sir Marcus’s chivalry often contrasted with the turpitude he exhibited with the ladies at the tavern.","ev":"Tinh thần hiệp sĩ của Ngài Marcus thường tương phản với thái độ sa đọa mà ông thể hiện với các quý cô trong quán rượu.","k":"turpitude"},{"t":"Consonant","p":"adjective","d":"in harmony","e":"The singers’ consonant voices were beautiful.","ev":"Giọng hát của họ hòa quyện một cách hoàn hảo.","k":"consonant"}]},{"n":"Chưa phân loại · 22","c":[{"t":"Cordial","p":"adjective","d":"warm, affectionate, chân thành, thân mật","e":"His cordial greeting melted my anger at once.","ev":"Lời chào thân mật của anh ấy làm tôi nguôi giận ngay lập tức.","k":"cordial"},{"t":"Meander","d":"to follow a route that is not straight or direct","e":"The river meandered through the valley.","ev":"Dòng sông uốn khúc qua thung lũng.","k":"meander"},{"t":"Deplore","p":"(v.)","d":"to feel or express sorrow, disapproval, xót xa, thương hại","e":"We all deplored the miserable working conditions in the factory.","ev":"Tất cả chúng tôi đều tiếc nuối về điều kiện làm việc khốn khổ ở nhà máy.","k":"deplore"},{"t":"Adept","p":"adj","d":"extremely skilled","e":"He is adept at solving complex mathematical problems quickly.","ev":"Anh ấy rất giỏi trong việc giải quyết nhanh chóng các bài toán phức tạp.","k":"adept"},{"t":"Primeval","p":"(adj.)","d":"original, ancient","e":"The first primates to walk on two legs, called Australopithecus, were the primeval descendants of modern man.","ev":"Loài linh trưởng đầu tiên đi bằng hai chân, được gọi là Australopithecus, là hậu duệ nguyên thủy của con người hiện đại.","k":"primeval"},{"t":"Broach","d":"to bring up a difficulty subject for discussion","e":"He hesitated to broach the difficult subject, fearing that it might cause an argument or hurt her feelings.","ev":"Anh lưỡng lự khi đề cập đến chủ đề khó, vì sợ nó có thể gây ra tranh cãi hoặc làm tổn thương cảm xúc của cô.","k":"broach"},{"t":"Deploy","d":"to bring into effective action, dàn quân, triển khai","e":"The army deployed troops to the border to protect the country from invasion.","ev":"Quân đội triển khai quân đến biên giới để bảo vệ đất nước khỏi bị xâm lược.","k":"deploy"},{"t":"Euphoric","p":"(adj.)","d":"elated, uplifted","e":"I was euphoric when I found out that my sister had given birth to twins.","ev":"Tôi vui mừng khôn xiết khi biết tin chị gái mình đã sinh đôi.","k":"euphoric"},{"t":"Vilify","p":"(v.)","d":"to lower in importance, defame","e":"After the Watergate scandal, almost any story written about President Nixon sought to vilify him and criticize his behavior.","ev":"Sau vụ bê bối Watergate, hầu hết mọi câu chuyện viết về Tổng thống Nixon đều tìm cách phỉ báng và chỉ trích hành vi của ông.","k":"vilify"},{"t":"Chaos","p":"(n.)","d":"absolute disorder","e":"Mr. Thornton’s sudden departure for the lavatory plunged his classroom into chaos.","ev":"Việc ông Thornton đột ngột đi vào nhà vệ sinh đã khiến lớp học của ông rơi vào tình trạng hỗn loạn.","k":"chaos"},{"t":"Posit","d":"To suggest or assume something as true","e":"The scientist posited a new theory about the origins of the universe.","ev":"Nhà khoa học đưa ra một lý thuyết mới về nguồn gốc của vũ trụ.","x":"Ví dụ 2: Make a Claim","k":"posit"},{"t":"Contend","d":"1) to deal with someone or something 2) to claim or state a belief confidently","e":"The two teams contended for the championship, battling it out in a thrilling final game.","ev":"Hai đội tranh chức vô địch và chiến đấu trong một trận chung kết gay cấn.","k":"contend"},{"t":"Satiated","d":"adj. satisfied (usu. in hunger)","e":"adj. satisfied (usu. in hunger)","ev":"tính từ hài lòng (thường là đói)","k":"satiated"},{"t":"Privation","p":"(n.)","d":"lacking basic necessities","e":"After decades of rule by an oppressive government that saw nothing wrong with stealing from its citizens, the recent drought only increased the people’s privation.","ev":"Sau nhiều thập kỷ cai trị bởi một chính phủ áp bức không thấy có gì sai trái khi ăn trộm của công dân, đợt hạn hán gần đây chỉ làm tăng thêm tình trạng thiếu thốn của người dân.","k":"privation"},{"t":"Dither","p":"(v.)","d":"to be indecisive","e":"Not wanting to offend either friend, he dithered about which of the two birthday parties he should attend.","ev":"Không muốn làm mất lòng một trong hai người bạn, anh ấy lưỡng lự về việc nên tham dự bữa tiệc sinh nhật nào trong hai bữa tiệc này.","k":"dither"},{"t":"Elucidate","p":"verb","d":"to clarify, explain","e":"The teacher used diagrams to elucidate the complex topic for her students.","ev":"Giáo viên đã sử dụng sơ đồ để làm rõ chủ đề phức tạp cho học sinh của mình.","k":"elucidate"},{"t":"Contusion","p":"noun","d":"bruise, injury","e":"The contusions on his face suggested he’d been in a fight.","ev":"Những vết bầm trên mặt anh cho thấy anh đã tham gia vào một cuộc ẩu đả.","k":"contusion"},{"t":"Prominent","d":"important; famous","e":"He was a prominent figure in the community, respected and admired for his leadership and contributions.","ev":"Ông là một nhân vật nổi bật trong cộng đồng, được kính trọng và ngưỡng mộ vì khả năng lãnh đạo và những đóng góp của mình.","k":"prominent"},{"t":"Hedonist","p":"(n.)","d":"one who believes pleasure should be the primary pursuit of humans","e":"Because he’s such a hedonist, I knew Murray would appreciate the 11 cases of wine I bought him for his birthday.","ev":"Bởi vì anh ấy là người theo chủ nghĩa khoái lạc nên tôi biết Murray sẽ đánh giá cao 11 thùng rượu tôi mua cho anh ấy nhân dịp sinh nhật.","k":"hedonist"},{"t":"Comparable","d":"adj. able to be compared","e":"adj. able to be compared","ev":"tính từ có thể so sánh được","k":"comparable"},{"t":"Volition","d":"the power to make one's own decisions","e":"She acted of her own volition, without being forced or persuaded.","ev":"Cô ấy hành động theo ý muốn của mình, không bị ép buộc hay thuyết phục.","k":"volition"},{"t":"Immure","d":"to imprison someone against their will","e":"The prisoners were immured in their cells, unable to leave or see the outside world.","ev":"Các tù nhân bị giam giữ trong phòng giam, không thể rời đi hay nhìn thấy thế giới bên ngoài.","k":"immure"},{"t":"Coherent","p":"(adj.)","d":"logically consistent, intelligible","e":"Renee could not figure out what Monroe had seen because he was too distraught to deliver a coherent statement.","ev":"Renee không thể hiểu Monroe đã nhìn thấy gì vì anh ấy quá quẫn trí để đưa ra một tuyên bố mạch lạc.","k":"coherent"},{"t":"Endorse","d":"to support","e":"The celebrity endorsed the product, promoting it to her millions of followers.","ev":"Người nổi tiếng đã chứng thực sản phẩm, quảng bá nó tới hàng triệu người theo dõi cô.","k":"endorse"},{"t":"Ostensible","p":"adj","d":"appearing as such, seemingly","e":"His ostensible reason for leaving was unconvincing.","ev":"Lý do bề ngoài của anh ta khi rời đi không thuyết phục.","k":"ostensible"}]},{"n":"Chưa phân loại · 23","c":[{"t":"Plaudits","p":"(n.)","d":"enthusiastic approval, applause","e":"The controversial new film received plaudits from even the harshest critics.","ev":"Bộ phim mới gây tranh cãi đã nhận được sự tán dương từ cả những nhà phê bình gay gắt nhất.","k":"plaudits"},{"t":"Cultivate","p":"verb","d":"to nurture, improve, refine","e":"At the library, she cultivated her interest in spy novels.","ev":"Cô đã nuôi dưỡng sở thích với tiểu thuyết gián điệp tại thư viện.","k":"cultivate"},{"t":"Sovereign","p":"(adj.)","d":"having absolute authority in a certain realm","e":"The sovereign queen, with steely resolve, ordered that the traitorous nobleman be killed.","ev":"Nữ hoàng có chủ quyền, với quyết tâm sắt đá, đã ra lệnh giết chết nhà quý tộc phản bội.","k":"sovereign"},{"t":"Bovine","d":"relating to cows or resembling a cow","e":"He has a bovine expression.","ev":"Anh ấy có một biểu hiện của bò.","k":"bovine"},{"t":"Sagacity","p":"(n.)","d":"shrewdness, soundness of perspective","e":"With remarkable sagacity, the wise old man predicted and thwarted his children’s plan to ship him off to a nursing home.","ev":"Với sự thông minh vượt trội, ông lão thông thái đã đoán trước và cản trở kế hoạch đưa ông vào viện dưỡng lão của các con mình.","k":"sagacity"},{"t":"Incite","d":"v. to encourage or stir up","e":"v. to encourage or stir up","ev":"v. khuyến khích hoặc khuấy động","k":"incite"},{"t":"Excursion","p":"(n.)","d":"a trip or outing","e":"After taking an excursion to the Bronx Zoo, I dreamed about pandas and monkeys.","ev":"Sau khi tham quan Sở thú Bronx, tôi mơ thấy gấu trúc và khỉ.","k":"excursion"},{"t":"Pungent","p":"(adj.)","d":"having a pointed, sharp quality—often used to describe smells","e":"The pungent odor in the classroom made Joseph lose his concentration during the test.","ev":"Mùi hăng trong lớp khiến Joseph mất tập trung trong giờ làm bài.","k":"pungent"},{"t":"Expiate","p":"(v.)","d":"to make amends for, atone","e":"To expiate my selfishness, I gave all my profits to charity.","ev":"Để đền đáp sự ích kỷ của mình, tôi đã dành tất cả lợi nhuận của mình để làm từ thiện.","k":"expiate"},{"t":"Predecessor","d":"someone or something that came before","e":"His predecessor was a respected and admired leader.","ev":"Người tiền nhiệm của ông là một nhà lãnh đạo được kính trọng và ngưỡng mộ.","k":"predecessor"},{"t":"Bereft","p":"adj.","d":"devoid of, without","e":"His family was bereft of food after the tornado.","ev":"Gia đình anh thiếu thốn thực phẩm sau cơn lốc xoáy.","k":"bereft"},{"t":"Fraught","p":"(adj.)","d":"(usually used with “with”) filled or accompanied with","e":"Her glances in his direction were fraught with meaning, though precisely what meaning remained unclear.","ev":"Cái nhìn của cô về phía anh đầy ẩn ý, ​​mặc dù ý nghĩa chính xác vẫn chưa rõ ràng.","k":"fraught"},{"t":"Deprecate","p":"verb","d":"to belittle, depreciate","e":"Many people deprecate the use of slang in formal writing.","ev":"Nhiều người không tán thành việc sử dụng tiếng lóng trong viết chính thức.","k":"deprecate"},{"t":"Emulate","p":"(v.)","d":"to imitate","e":"I idolize Britney Spears so much that I emulate everything she does: I wear her outfits, sing along to her songs, and date a boy named Justin.","ev":"Tôi thần tượng Britney Spears đến mức tôi bắt chước mọi việc cô ấy làm: Tôi mặc trang phục của cô ấy, hát theo các bài hát của cô ấy và hẹn hò với một chàng trai tên Justin.","k":"emulate"},{"t":"Vicissitude","p":"(n.) /vɪˈsɪsɪtuːd/","d":"event that occurs by chance, things happened in life","e":"The vicissitudes of daily life prevent me from predicting what might happen from one day to the next.","ev":"Những thăng trầm của cuộc sống hàng ngày khiến tôi không thể đoán trước được điều gì có thể xảy ra từ ngày này sang ngày khác.","k":"vicissitude"},{"t":"Dreary","d":"adj. sad, gloomy, dull","e":"adj. sad, gloomy, dull","ev":"tính từ buồn, ảm đạm, buồn tẻ","k":"dreary"},{"t":"Mired","d":"stuck in mud","e":"The car was mired in the mud after the heavy rain, requiring a tow truck to get it out.","ev":"Chiếc ô tô bị sa lầy sau trận mưa lớn, phải dùng xe kéo mới đưa ra được.","k":"mired"},{"t":"Derivative","p":"noun/adj","d":"taken directly from a source, unoriginal","e":"His ideas were seen as derivative, lacking originality and depth.","ev":"Những ý tưởng của anh bị coi là không sáng tạo, thiếu tính độc đáo và chiều sâu.","k":"derivative"},{"t":"Establish","d":"v. to enact","e":"v. to enact","ev":"v. ban hành","k":"establish"},{"t":"Exert","d":"to use power or the ability to make something happen","e":"He exerted all his strength to lift the heavy object.","ev":"Anh dùng hết sức lực để nhấc vật nặng lên.","k":"exert"},{"t":"Malediction","p":"(n.)","d":"a curse","e":"When I was arrested for speeding, I screamed maledictions against the policeman and the entire police department.","ev":"Khi bị bắt vì chạy quá tốc độ, tôi đã chửi bới viên cảnh sát và toàn bộ sở cảnh sát.","k":"malediction"},{"t":"Vernacular","d":"everyday informal language, local dialect","e":"He spoke in the vernacular of the region, using local slang and idioms that were unfamiliar to outsiders.","ev":"Ông nói bằng tiếng bản địa của vùng, sử dụng tiếng lóng và thành ngữ địa phương mà người ngoài không quen thuộc.","k":"vernacular"},{"t":"Pinnacle","p":"(n.)","d":"the highest point","e":"Book reviewers declared that the author’s new novel was extraordinary and probably the pinnacle of Western literature.","ev":"Các nhà phê bình sách nhận định cuốn tiểu thuyết mới của tác giả rất phi thường và có lẽ là đỉnh cao của văn học phương Tây.","k":"pinnacle"},{"t":"Pulpit","d":"a raised platform in a church from which the preacher speaks","e":"The preacher stood at the pulpit and delivered a sermon.","ev":"Nhà truyền giáo đứng trên bục giảng và thuyết pháp.","k":"pulpit"},{"t":"Remedial","p":"(adj.)","d":"intended to repair gaps in students’ basic knowledge","e":"After his teacher discovered he couldn’t read, Alex was forced to enroll in remedial English.","ev":"Sau khi giáo viên phát hiện ra cậu không thể đọc, Alex buộc phải đăng ký học thêm tiếng Anh.","k":"remedial"}]},{"n":"Chưa phân loại · 24","c":[{"t":"Onerous","p":"adj","d":"burdensome","e":"The onerous task required a significant amount of time and effort.","ev":"Nhiệm vụ nặng nề yêu cầu một lượng lớn thời gian và công sức.","k":"onerous"},{"t":"Canny","p":"(adj.)","d":"shrewd, careful","e":"The canny runner hung at the back of the pack through much of the race to watch the other runners, and then sprinted past them at the end.","ev":"Người chạy canny đã ở phía sau đoàn trong phần lớn cuộc đua để theo dõi những người chạy khác, và sau đó chạy nhanh vượt qua họ ở cuối.","k":"canny"},{"t":"Gluttony","p":"(n.)","d":"overindulgence in food or drink","e":"Ada’s fried chicken tastes so divine, I don’t know how anyone can call gluttony a sin.","ev":"Món gà rán của Ada có vị thần thánh quá, không biết sao có người có thể gọi thói háu ăn là tội lỗi.","k":"gluttony"},{"t":"Preponderance","p":"(adj.)","d":"superiority in importance or quantity, ưu thế.","e":"Britain’s preponderance of naval might secured the nation’s role as a military power.","ev":"Sự vượt trội về hải quân của Anh có thể đảm bảo vai trò của quốc gia này như một cường quốc quân sự.","k":"preponderance"},{"t":"Surly","p":"adj.","d":"unfriendly; inclined to anger","e":"He gave me a surly look.","ev":"Anh nhìn tôi một cách chắc chắn.","k":"surly"},{"t":"Profligate","p":"(adj.)","d":"dissolute, extravagant","e":"The profligate gambler loved to drink, spend money, steal, cheat, and hang out with prostitutes.","ev":"Kẻ cờ bạc hoang phí thích uống rượu, tiêu tiền, trộm cắp, lừa đảo và giao du với gái mại dâm.","k":"profligate"},{"t":"Discordant","p":"(adj.)","d":"not agreeing, not in harmony with","e":"The girls’ sobs were a discordant sound amid the general laughter that filled the restaurant.","ev":"Tiếng nức nở của các cô gái là một âm thanh trái ngược giữa tiếng cười chung tràn ngập nhà hàng.","k":"discordant"},{"t":"Imprudent","d":"foolish, reckless","e":"It was imprudent to drive so fast in the bad weather, as it increased the risk of an accident.","ev":"Thật là thiếu thận trọng khi lái xe quá nhanh trong thời tiết xấu vì nó làm tăng nguy cơ xảy ra tai nạn.","k":"imprudent"},{"t":"Incredulous","d":"unwilling or unable to believe something","e":"He was incredulous that anyone would believe such a ridiculous story, finding it hard to comprehend how anyone could be so gullible.","ev":"Anh không thể tin được rằng có người lại tin vào một câu chuyện lố bịch như vậy, anh cảm thấy khó hiểu tại sao lại có người cả tin như vậy.","k":"incredulous"},{"t":"Vacuous","p":"(adj.)","d":"lack of content or ideas, stupid","e":"Beyonce realized that the lyrics she had just penned were completely vacuous and tried to add more substance.","ev":"Beyonce nhận ra lời bài hát cô vừa viết hoàn toàn trống rỗng và cố gắng thêm chất lượng vào.","k":"vacuous"},{"t":"Regurgitate","p":"(v.)","d":"to vomit","e":"Feeling sick, Chuck regurgitated his dinner.","ev":"Cảm thấy buồn nôn, Chuck nôn bữa tối của mình ra.","x":"Nghĩa 2: to throw back exactly\nVí dụ 2: Margaret rushed through the test, regurgitating all of the facts she’d memorized an hour earlier.","k":"regurgitate"},{"t":"Chronological","p":"(adj.)","d":"arranged in order of time","e":"Lionel carefully arranged the snapshots of his former girlfriends in chronological order, and then set fire to them.","ev":"Lionel cẩn thận sắp xếp những bức ảnh chụp nhanh của những người bạn gái cũ của mình theo thứ tự thời gian, rồi châm lửa đốt họ.","k":"chronological"},{"t":"Microbial","d":"relating to microscopic organisms","e":"Microbial infections are caused by tiny organisms.","ev":"Nhiễm vi khuẩn là do các sinh vật nhỏ bé gây ra.","x":"Ví dụ 2: Science-Related Terms","k":"microbial"},{"t":"Quandary","p":"(n.)","d":"a perplexed, unresolvable state","e":"Carlos found himself in a quandary: should he choose mint chocolate chip or cookie dough?","ev":"Carlos thấy mình đang ở trong tình thế khó xử: nên chọn sô cô la bạc hà hay bột bánh quy?","k":"quandary"},{"t":"Arid","p":"adjective","d":"excessively dry","e":"Little grows successfully in arid environments.","ev":"Rất ít cây cối phát triển thành công trong môi trường khô cằn.","k":"arid"},{"t":"Arable","p":"adjective","d":"suitable for growing crops","e":"The farmer purchased a plot of arable land for corn.","ev":"Người nông dân đã mua một mảnh đất canh tác để trồng ngô.","k":"arable"},{"t":"Ardor","p":"noun","d":"extreme vigor, energy, enthusiasm","e":"The soldiers conveyed their ardor with impassioned battle cries.","ev":"Các chiến sĩ thể hiện nhiệt huyết của họ bằng những tiếng hò reo trong trận chiến.","k":"ardor"},{"t":"Symbiosis (Adj., Symbiotic)","d":"interaction between two organisms living close together, benefits both","e":"The relationship between the two species is symbiotic.","ev":"Mối quan hệ giữa hai loài là cộng sinh.","x":"Ví dụ 2: Science-Related Terms","k":"symbiosis (adj., symbiotic)"},{"t":"Tremendous","d":"adj. very large, good, or bad in degree or size","e":"adj. very large, good, or bad in degree or size","ev":"tính từ rất lớn, tốt hoặc xấu về mức độ hoặc kích thước","k":"tremendous"},{"t":"Servile","p":"adj","d":"subservient, khúm núm, phục tùng","e":"His servile attitude towards his boss was obvious to everyone in the office.","ev":"Thái độ phục tùng của anh đối với sếp đã rõ ràng với mọi người trong văn phòng.","k":"servile"},{"t":"Innate","p":"adj","d":"inborn, native, inherent","e":"She had an innate ability to understand complex problems quickly.","ev":"Cô có khả năng bẩm sinh để hiểu các vấn đề phức tạp một cách nhanh chóng.","k":"innate"},{"t":"Obstreperous","p":"(adj.)","d":"noisy, unruly","e":"Billy’s obstreperous behavior prompted the librarian to ask him to leave the reading room.","ev":"Hành vi ngang ngược của Billy đã khiến người thủ thư yêu cầu anh rời khỏi phòng đọc.","k":"obstreperous"},{"t":"Apex","d":"n. the highest point of something","e":"n. the highest point of something","ev":"N. điểm cao nhất của một cái gì đó","k":"apex"},{"t":"Urge","d":"n. desire or impulse","e":"n. desire or impulse","ev":"N. mong muốn hoặc sự thúc đẩy","k":"urge"},{"t":"Flaccid","p":"(adj.) /ˈflæs.ɪd/","d":"limp, not firm or strong, mềm nhũn","e":"If a plant is not watered enough, its leaves become droopy and flaccid.","ev":"Nếu cây không được tưới đủ nước, lá sẽ rũ xuống và mềm nhũn.","k":"flaccid"}]},{"n":"Chưa phân loại · 25","c":[{"t":"Antiquated","p":"adjective","d":"old, out of date","e":"That antiquated car has none of the modern features like power windows.","ev":"Chiếc xe cổ đó không có bất kỳ tính năng hiện đại nào như cửa sổ điện.","k":"antiquated"},{"t":"By No Means","d":"not at all","e":"This task is by no means easy, but with determination, we can accomplish it.","ev":"Nhiệm vụ này không hề dễ dàng nhưng với quyết tâm, chúng ta có thể hoàn thành được.","k":"by no means"},{"t":"Instigate","p":"verb","d":"to urge, goad","e":"The manager decided to instigate changes in the company culture to improve morale.","ev":"Người quản lý quyết định khởi xướng thay đổi trong văn hóa công ty để cải thiện tinh thần.","k":"instigate"},{"t":"Sensual","p":"(adj.)","d":"involving sensory gratification, usually related to sex","e":"With a coy smile, the guest on the blind-date show announced that he considered himself a very sensual person.","ev":"Với nụ cười bẽn lẽn, vị khách mời trong chương trình hẹn hò mù quáng tuyên bố rằng anh tự nhận mình là người rất gợi cảm.","k":"sensual"},{"t":"Obeisance","d":"deep respect","e":"The people showed obeisance to the king, bowing and kneeling before him.","ev":"Người dân tỏ lòng tôn kính nhà vua, cúi đầu và quỳ gối trước ông.","k":"obeisance"},{"t":"Tout","p":"verb","d":"to advertise or praise something (often to sell it)","e":"The company touted its new product as a revolutionary innovation.","ev":"Công ty đã quảng bá sản phẩm mới của mình như một đổi mới cách mạng.","k":"tout"},{"t":"Rail","p":"(v.)","d":"to scold, protest","e":"The professor railed against the injustice of the college’s tenure policy.","ev":"Giáo sư lên án sự bất công trong chính sách biên chế của trường đại học.","k":"rail"},{"t":"Arbitration","p":"noun","d":"the process or act of resolving a dispute","e":"The employee sought arbitration when he could not resolve a disagreement with his supervisor.","ev":"Nhân viên đã yêu cầu trọng tài khi không thể giải quyết mâu thuẫn với cấp trên của mình.","k":"arbitration"},{"t":"Munificent","d":"very generous","e":"He made a munificent donation to the charity.","ev":"Anh ấy đã quyên góp rất nhiều cho tổ chức từ thiện.","k":"munificent"},{"t":"Impose","d":"1) to force the acceptance of something 2) to cause inconvenience to someone","e":"The government imposed new taxes on the citizens, increasing the financial burden on households.","ev":"Chính phủ áp đặt các loại thuế mới đối với người dân, làm tăng gánh nặng tài chính cho các hộ gia đình.","k":"impose"},{"t":"Morass","p":"(n.)","d":"a wet swampy bog; figuratively, something that traps and confuses","e":"When Theresa lost her job, she could not get out of her financial morass.","ev":"Khi Theresa mất việc, cô không thể thoát khỏi vũng lầy tài chính của mình.","k":"morass"},{"t":"Mortify","d":"to cause (someone) to feel embarrassed, ashamed, or humiliated","e":"She was mortified when she realized she had made a mistake in front of her boss.","ev":"Cô đau đớn khi nhận ra mình đã phạm sai lầm trước mặt sếp.","k":"mortify"},{"t":"Keen","d":"sharp; highly developed (usually the senses)","e":"She had a keen sense of smell, able to detect even the faintest scent.","ev":"Cô có khứu giác rất nhạy bén, có thể nhận ra ngay cả những mùi hương thoang thoảng nhất.","k":"keen"},{"t":"Interject","p":"(v.)","d":"to insert between other things","e":"During our conversation, the cab driver occasionally interjected his opinion.","ev":"Trong cuộc trò chuyện của chúng tôi, người tài xế taxi thỉnh thoảng xen vào ý kiến ​​của anh ta.","k":"interject"},{"t":"Deft","p":"(adj.)","d":"skillful, capable","e":"Having worked in a bakery for many years, Marcus was a deft bread maker.","ev":"Làm việc nhiều năm ở một tiệm bánh, Marcus là một thợ làm bánh mì khéo léo.","k":"deft"},{"t":"Perfidious","p":"(adj.)","d":"disloyal, unfaithful","e":"After the official was caught selling government secrets to enemy agents, he was executed for his perfidious ways.","ev":"Sau khi quan chức này bị bắt quả tang bán bí mật chính phủ cho đặc vụ của kẻ thù, anh ta đã bị xử tử vì hành vi phản bội của mình.","k":"perfidious"},{"t":"Scathing","p":"adj","d":"sharp, critical, hurtful","e":"The critic wrote a scathing review that damaged the restaurant's reputation.","ev":"Nhà phê bình đã viết một bài đánh giá cay độc làm hỏng danh tiếng của nhà hàng.","k":"scathing"},{"t":"Remembrance","d":"the act of remembering something; a memory","e":"The memorial was a place of remembrance for the victims of the war, honoring their sacrifices and keeping their memory alive.","ev":"Đài tưởng niệm là nơi tưởng nhớ các nạn nhân của chiến tranh, tôn vinh sự hy sinh của họ và lưu giữ ký ức về họ.","k":"remembrance"},{"t":"Injunction","p":"(n.)","d":"an order of official warning","e":"After his house was toilet-papered for the fifth time, the mayor issued an injunction against anyone younger than 21 buying toilet paper.","ev":"Sau khi ngôi nhà của ông được dán giấy vệ sinh lần thứ năm, thị trưởng đã ban hành lệnh cấm bất kỳ ai dưới 21 tuổi mua giấy vệ sinh.","k":"injunction"},{"t":"Quixotic","p":"adj","d":"idealistic, impractical","e":"His quixotic dreams of becoming a famous artist often distracted him from reality.","ev":"Những giấc mơ hão huyền của anh về việc trở thành một nghệ sĩ nổi tiếng thường khiến anh lạc lối khỏi thực tế.","k":"quixotic"},{"t":"Infamy","p":"(n.)","d":"notoriety, extreme ill repute","e":"The infamy of his crime will not lessen as the decades pass.","ev":"Sự ô nhục về tội ác của anh ta sẽ không giảm bớt khi nhiều thập kỷ trôi qua.","k":"infamy"},{"t":"Immerse","p":"(v.)","d":"to absorb, deeply involve, engross","e":"After breaking up with her boyfriend, Nancy decided to immerse herself in her work in order to avoid crying.","ev":"Sau khi chia tay bạn trai, Nancy quyết định vùi đầu vào công việc để tránh khóc.","k":"immerse"},{"t":"Fractious","p":"(adj.)","d":"troublesome or irritable","e":"Although the child insisted he wasn’t tired, his fractious behavior—especially his decision to crush his cheese and crackers all over the floor—convinced everyone present that it was time to put him to bed.","ev":"Mặc dù đứa trẻ khẳng định mình không mệt, nhưng hành vi ngang ngạnh của nó - đặc biệt là quyết định vò nát pho mát và bánh quy giòn khắp sàn - đã thuyết phục mọi người có mặt rằng đã đến lúc phải đưa nó đi ngủ.","k":"fractious"},{"t":"Burnish","p":"(v.)","d":"to polish, shine","e":"His mother asked him to burnish the silverware before setting the table.","ev":"Mẹ anh yêu cầu anh đánh bóng đồ bạc trước khi bày bàn ăn.","k":"burnish"},{"t":"Inversion","d":"n. a reversal","e":"n. a reversal","ev":"N. sự đảo ngược","k":"inversion"}]},{"n":"Chưa phân loại · 26","c":[{"t":"Braggart","d":"a person who boasts about their achievements","e":"He's a real braggart.","ev":"Anh ta đúng là kẻ khoe khoang.","k":"braggart"},{"t":"Censorious","p":"adj","d":"disapproving of or criticizing people","e":"His censorious attitude made it difficult for others to share their opinions.","ev":"Thái độ chỉ trích của anh khiến người khác khó chia sẻ ý kiến của mình.","k":"censorious"},{"t":"Allude","d":"to suggest or call attention to indirectly, to make a reference to something","e":"She alluded to the problem without mentioning it directly, hoping that the other person would understand her meaning.","ev":"Cô ám chỉ vấn đề mà không đề cập trực tiếp đến nó, hy vọng rằng người kia sẽ hiểu ý cô.","k":"allude"},{"t":"Dubious","p":"(adj.)","d":"doubtful, of uncertain quality","e":"Suspicious that he was only trying to get a raise, she found his praise dubious.","ev":"Nghi ngờ rằng anh ta chỉ đang cố gắng tăng lương, cô thấy lời khen ngợi của anh ta thật đáng ngờ.","k":"dubious"},{"t":"Commission","d":"n. the use of payment to request something (e.g., a service or product)","e":"n. the use of payment to request something (e.g., a service or product)","ev":"N. việc sử dụng thanh toán để yêu cầu một cái gì đó (ví dụ: dịch vụ hoặc sản phẩm)","k":"commission"},{"t":"Elaborate","p":"(adj.)","d":"complex, detailed, intricate","e":"Dan always beats me at chess because he develops such an elaborate game plan that I can never predict his next move.","ev":"Dan luôn đánh bại tôi trong môn cờ vua vì anh ấy phát triển một kế hoạch trò chơi phức tạp đến mức tôi không bao giờ có thể đoán trước được bước đi tiếp theo của anh ấy.","k":"elaborate"},{"t":"Consummate (Adj.)","d":"complete or perfect, having a high degree of skill","e":"He was a consummate professional, skilled and experienced in his field.","ev":"Anh ấy là một người có chuyên môn giỏi, có tay nghề cao và giàu kinh nghiệm trong lĩnh vực của mình.","k":"consummate (adj.)"},{"t":"Sophisticated","d":"1) having a lot of worldly experience and knowledge 2) complicated","e":"The restaurant had a sophisticated atmosphere, with elegant decor and attentive service.","ev":"Nhà hàng có bầu không khí tinh tế, trang trí trang nhã và dịch vụ chu đáo.","k":"sophisticated"},{"t":"Agnostic","p":"noun","d":"believing that the existence of God cannot be proven or disproven","e":"Joey’s parents are very religious, but he is agnostic.","ev":"Cha mẹ của Joey rất tôn giáo, nhưng anh thì không chắc chắn về sự tồn tại của Chúa.","k":"agnostic"},{"t":"Exhort","p":"verb","d":"to urge, prod, spur","e":"The coach exhorted his team to give their best effort in the final game.","ev":"Huấn luyện viên đã khuyến khích đội bóng của mình nỗ lực hết sức trong trận đấu cuối cùng.","k":"exhort"},{"t":"Desolate","p":"(adj.)","d":"deserted, dreary, lifeless","e":"She found the desolate landscape quite a contrast to the hustle and bustle of the overcrowded city.","ev":"Cô thấy khung cảnh hoang tàn hoàn toàn trái ngược với sự hối hả và nhộn nhịp của thành phố đông đúc.","k":"desolate"},{"t":"Rigid","d":"stiff, firm, unchangeable","e":"He was a rigid person who was unwilling to change his mind.","ev":"Anh là một người cứng nhắc, không muốn thay đổi quan điểm.","k":"rigid"},{"t":"Deface","p":"(v.)","d":"to ruin or injure something’s appearance","e":"The brothers used eggs and shaving cream to deface their neighbor’s mailbox.","ev":"Hai anh em dùng trứng và kem cạo râu để làm ô uế hộp thư nhà hàng xóm.","k":"deface"},{"t":"Omnipotent","d":"adj. almighty and all powerful","e":"adj. almighty and all powerful","ev":"tính từ toàn năng và mạnh mẽ","k":"omnipotent"},{"t":"Glut","d":"an excess supply of something","e":"The market was glutted with the product, leading to a sharp decline in prices.","ev":"Thị trường tràn ngập sản phẩm, dẫn đến giá giảm mạnh.","k":"glut"},{"t":"Contradict","d":"v. to be in contrast with","e":"v. to be in contrast with","ev":"v. trái ngược với","k":"contradict"},{"t":"Apprehensive","d":"anxious or fearful that something bad or unpleasant will happen","e":"He was apprehensive about the upcoming surgery, fearing the pain and potential complications.","ev":"Anh lo lắng về cuộc phẫu thuật sắp tới, sợ đau đớn và những biến chứng có thể xảy ra.","k":"apprehensive"},{"t":"Luminous","p":"(adj.)","d":"brightly shining","e":"The light of the luminous moon graced the shoulders of the beautiful maiden.","ev":"Ánh trăng sáng chiếu lên đôi vai thiếu nữ xinh đẹp.","k":"luminous"},{"t":"Diligence","d":"n. conscientiousness; the quality of being committed to a task","e":"n. conscientiousness; the quality of being committed to a task","ev":"N. sự tận tâm; chất lượng của sự cam kết với một nhiệm vụ","k":"diligence"},{"t":"Aversion","p":"noun","d":"a particular dislike for something","e":"Ben has an aversion to cold climates due to his Hawaiian roots.","ev":"Vì xuất thân từ Hawaii, Ben rất ghét những vùng khí hậu lạnh.","k":"aversion"},{"t":"Usury","d":"the practice of lending money at unreasonably high interest rates","e":"He was accused of usury.","ev":"Anh ta bị buộc tội cho vay nặng lãi.","k":"usury"},{"t":"Capacious","p":"(adj.)","d":"very spacious","e":"The workers delighted in their new capacious office space.","ev":"Các công nhân vui mừng trong không gian văn phòng rộng rãi mới của họ.","k":"capacious"},{"t":"Ethnography","d":"study of individual cultures","e":"The anthropologist conducted an ethnography of the indigenous tribe.","ev":"Nhà nhân chủng học đã tiến hành nghiên cứu dân tộc học về bộ lạc bản địa.","x":"Ví dụ 2: Social Science","k":"ethnography"},{"t":"Clairvoyant","p":"(adj.)","d":"able to perceive things that normal people cannot","e":"Zelda’s uncanny ability to detect my lies was nothing short of clairvoyant.","ev":"Khả năng kỳ lạ của Zelda trong việc phát hiện những lời nói dối của tôi quả là có khả năng thấu thị.","k":"clairvoyant"},{"t":"Captivate","p":"(v.)","d":"to get the attention of, hold","e":"The fireworks captivated the young boy, who had never seen such things before.","ev":"Pháo hoa đã làm say đắm cậu bé, người chưa bao giờ nhìn thấy những thứ như vậy trước đây.","k":"captivate"}]},{"n":"Chưa phân loại · 27","c":[{"t":"Convey","d":"to make (an idea or feeling) known or understandable to someone; to communicate","e":"The painting conveyed a sense of peace and tranquility.","ev":"Bức tranh mang lại cảm giác bình yên và tĩnh lặng.","k":"convey"},{"t":"Agriculture","p":"noun","d":"farming","e":"It was a huge step in the progress of civilization when tribes began to develop agriculture.","ev":"Đó là một bước lớn trong tiến bộ của nền văn minh khi các bộ tộc bắt đầu phát triển nông nghiệp.","k":"agriculture"},{"t":"Elude","p":"verb","d":"to evade, escape","e":"The thief managed to elude capture.","ev":"Kẻ trộm đã quản lý để thoát khỏi bị bắt.","k":"elude"},{"t":"Adversary","d":"one's opponent or enemy","e":"The two teams were fierce adversaries, competing against each other with great intensity.","ev":"Hai đội là những đối thủ đáng gờm, thi đấu với nhau với cường độ rất cao.","k":"adversary"},{"t":"Populist","d":"người theo chủ nghĩa dân túy (oppose elite group)","e":"The candidate used populist rhetoric to appeal to the common people.","ev":"Ứng cử viên đã sử dụng biện pháp tu từ theo chủ nghĩa dân túy để thu hút người dân bình thường.","k":"populist"},{"t":"Bias","p":"noun","d":"a tendency, inclination, prejudice","e":"The judge’s bias against smokers influenced his decision.","ev":"Thành kiến của thẩm phán đối với người hút thuốc đã ảnh hưởng đến quyết định của ông.","k":"bias"},{"t":"Adulation","p":"noun","d":"extreme praise","e":"Marcy didn’t think the book deserved the adulation it received.","ev":"Marcy không nghĩ rằng cuốn sách xứng đáng với sự ca ngợi mà nó nhận được.","k":"adulation"},{"t":"Tactful","d":"adj. skilled at dealing with people","e":"adj. skilled at dealing with people","ev":"tính từ có kỹ năng ứng xử với mọi người","k":"tactful"},{"t":"Rash","p":"(adj.)","d":"hasty, incautious","e":"It’s best to think things over calmly and thoroughly, rather than make rash decisions.","ev":"Tốt nhất bạn nên suy nghĩ mọi việc một cách bình tĩnh và kỹ lưỡng thay vì đưa ra những quyết định hấp tấp.","k":"rash"},{"t":"Ethereal","p":"(adj.)","d":"heavenly, exceptionally delicate or refined","e":"In her flowing silk gown and lace veil, the bride looked ethereal.","ev":"Trong chiếc váy lụa bồng bềnh và mạng che mặt bằng ren, cô dâu trông thật thanh tao.","k":"ethereal"},{"t":"Artifact","p":"noun","d":"a remaining piece from an extinct culture or place","e":"The scientists searched the cave for artifacts from the ancient Mayan civilization.","ev":"Các nhà khoa học đã tìm kiếm trong hang động để tìm các di tích từ nền văn minh Maya cổ đại.","k":"artifact"},{"t":"Languid","p":"adjective","d":"sluggish from fatigue or weakness","e":"She moved with a languid grace, as if she were floating through the room.","ev":"Cô di chuyển với sự duyên dáng uể oải, như thể đang trôi lơ lửng trong phòng.","k":"languid"},{"t":"Abstract","d":"existing in thought or as an idea but not having a physical or concrete existence; conceptual","e":"The concept was too abstract for me to understand, as it was difficult to visualize or apply to real-life situations.","ev":"Khái niệm này quá trừu tượng đối với tôi để hiểu vì nó khó hình dung hoặc áp dụng vào các tình huống thực tế.","k":"abstract"},{"t":"Objective (Adj.)","d":"fair-minded, not influenced by personal feelings","e":"He tried to be objective in his assessment, avoiding personal bias and considering all the facts.","ev":"Anh cố gắng khách quan trong đánh giá của mình, tránh thiên vị cá nhân và xem xét tất cả sự thật.","k":"objective (adj.)"},{"t":"Taciturn","p":"(adj.)","d":"not inclined to talk","e":"Though Jane never seems to stop talking, her brother is quite taciturn.","ev":"Mặc dù Jane dường như không bao giờ ngừng nói nhưng anh trai cô lại khá ít nói.","k":"taciturn"},{"t":"Inherent","p":"adj","d":"built-in, existing in something as a permanent or essential characteristic","e":"The concept of freedom is inherent in the country's constitution.","ev":"Khái niệm về tự do là vốn có trong hiến pháp của quốc gia.","k":"inherent"},{"t":"Advocate","p":"verb","d":"to argue in favor of something","e":"(1) Arnold advocated for turning left at the stop sign. (2) He was a strong advocate for defense spending.","ev":"(1) Arnold đã ủng hộ việc rẽ trái tại biển báo dừng. (2) Anh là một người ủng hộ mạnh mẽ cho việc tăng cường chi tiêu quốc phòng.","k":"advocate"},{"t":"Viable","d":"capable of working successfully, realistic, doable","e":"The plan was not viable and would not work in practice, as it was based on unrealistic assumptions.","ev":"Kế hoạch này không khả thi và sẽ không áp dụng được trên thực tế vì nó dựa trên những giả định không thực tế.","k":"viable"},{"t":"Bluster","d":"talk intended to seem important or threatening but which is not taken seriously and has little effect","e":"He blustered about his accomplishments, trying to impress others with his supposed greatness.","ev":"Anh ta khoe khoang về thành tích của mình, cố gắng gây ấn tượng với người khác bằng sự vĩ đại được cho là của mình.","k":"bluster"},{"t":"Abide","p":"verb","d":"to put up with","e":"(1) Chuck decided to abide by the decision. (2) The mountains abide despite the weather.","ev":"(1) Chuck quyết định chấp nhận quyết định. (2) Những ngọn núi vẫn tồn tại bất chấp thời tiết.","k":"abide"},{"t":"Jubilant","p":"(adj.)","d":"extremely joyful, happy","e":"The crowd was jubilant when the firefighter carried the woman from the flaming building.","ev":"Đám đông hân hoan khi lính cứu hỏa bế người phụ nữ ra khỏi tòa nhà đang cháy.","k":"jubilant"},{"t":"Dearth","p":"noun","d":"a lack, scarcity","e":"There was a dearth of resources available for the project, hindering its progress.","ev":"Có sự thiếu hụt tài nguyên cho dự án, cản trở tiến trình của nó.","k":"dearth"},{"t":"Adroit","p":"adj","d":"skillful, dexterous","e":"She is adroit at negotiating and often gets the best deals.","ev":"Cô rất khéo léo trong việc đàm phán và thường có được những thỏa thuận tốt nhất.","k":"adroit"},{"t":"Gratuitous","p":"(adj.)","d":"uncalled for, unwarranted","e":"Every morning the guy at the donut shop gives me a gratuitous helping of ketchup packets.","ev":"Mỗi buổi sáng, anh chàng ở cửa hàng bánh rán đưa cho tôi một gói sốt cà chua miễn phí.","k":"gratuitous"},{"t":"Plenitude","p":"(n.)","d":"an abundance","e":"My grandmother was overwhelmed by the plenitude of tomatoes her garden yielded this season.","ev":"Bà tôi choáng ngợp trước lượng cà chua dồi dào mà vườn bà cho thu hoạch trong mùa này.","k":"plenitude"}]},{"n":"Chưa phân loại · 28","c":[{"t":"Materialistic","d":"excessively concerned with material possessions or money","e":"He was a materialistic person who valued possessions and wealth above all else.","ev":"Ông là một người theo chủ nghĩa vật chất, coi trọng của cải và của cải hơn tất cả.","k":"materialistic"},{"t":"Treacherous","d":"adj. dangerous and unstable","e":"adj. dangerous and unstable","ev":"tính từ nguy hiểm và không ổn định","k":"treacherous"},{"t":"Accede","p":"verb","d":"to agree","e":"The teacher acceded to the class's request to play baseball instead of learning grammar.","ev":"Giáo viên đã đồng ý với yêu cầu của lớp để chơi bóng chày thay vì học ngữ pháp.","k":"accede"},{"t":"Reluctantly","d":"adv. somewhat unwillingly","e":"adv. somewhat unwillingly","ev":"lời khuyên. hơi miễn cưỡng","k":"reluctantly"},{"t":"Inarticulate","p":"(adj.)","d":"incapable of expressing oneself clearly through speech","e":"Though he spoke for over an hour, the lecturer was completely inarticulate and the students had no idea what he was talking about.","ev":"Mặc dù ông ấy đã nói hơn một tiếng đồng hồ nhưng giảng viên hoàn toàn không hiểu rõ và sinh viên không hiểu ông ấy đang nói về điều gì.","k":"inarticulate"},{"t":"Obdurate","p":"adj","d":"unyielding to persuasion or moral influences","e":"Despite her pleas, he remained obdurate and refused to change his mind.","ev":"Mặc dù cô đã cầu xin, anh vẫn cứng đầu và từ chối thay đổi quyết định của mình.","k":"obdurate"},{"t":"Ornithology","d":"study of birds","e":"Ornithology is the study of birds.","ev":"Điểu học là nghiên cứu về các loài chim.","x":"Ví dụ 2: Branches of Science","k":"ornithology"},{"t":"Foil","p":"(v.)","d":"to thwart, frustrate, defeat","e":"Inspector Wilkens foiled the thieves by locking them in the bank along with their stolen money.","ev":"Thanh tra Wilkens đã ngăn chặn bọn trộm bằng cách nhốt chúng vào ngân hàng cùng với số tiền trộm được của chúng.","k":"foil"},{"t":"Imperious","p":"adj","d":"commanding, domineering","e":"The imperious tone in her voice made it clear she expected obedience.","ev":"Giọng điệu hống hách của cô khiến mọi người rõ ràng rằng cô mong muốn sự tuân thủ.","k":"imperious"},{"t":"Despondent Jimmy","d":"very sad and discouraged","e":"Despondent Jimmy sat alone on the bench, staring at the sand.","ev":"Jimmy chán nản ngồi một mình trên băng ghế, nhìn chằm chằm vào cát.","k":"despondent jimmy"},{"t":"Delegate","p":"(v.)","d":"to hand over responsibility for something","e":"The dean delegated the task of finding a new professor to a special hiring committee.","ev":"Hiệu trưởng giao nhiệm vụ tìm giáo sư mới cho một ủy ban tuyển dụng đặc biệt.","k":"delegate"},{"t":"Impudent","p":"(adj.)","d":"casually rude, insolent, impertinent","e":"The impudent young man looked the princess up and down and told her she was hot even though she hadn’t asked him.","ev":"Chàng trai xấc xược nhìn công chúa từ trên xuống dưới và nói với cô rằng cô thật nóng bỏng dù cô chưa hỏi ý kiến ​​anh ta.","k":"impudent"},{"t":"Coarse","d":"1) rough, not smooth 2) rude or offensive in manner or speech","e":"His language was coarse and vulgar, often using offensive and inappropriate words.","ev":"Ngôn ngữ của ông thô lỗ và thô tục, thường sử dụng những từ ngữ xúc phạm và không phù hợp.","k":"coarse"},{"t":"Impinge","p":"(v.)","d":"to impact, affect, make an impression","e":"The hail impinged the roof, leaving large dents.","ev":"Mưa đá đập vào mái nhà, để lại những vết lõm lớn.","x":"Nghĩa 2: to encroach, infringe\nVí dụ 2: I apologize for impinging upon you like this, but I really need to use your bathroom. Now.","k":"impinge"},{"t":"Unilateral","d":"adj. one-sided, đơn phương","e":"The party leader has actually declared her support for unilateral nuclear disarmament (= giving up her country's nuclear weapons without first waiting for other countries to do the same).","ev":"Nhà lãnh đạo đảng đã thực sự tuyên bố ủng hộ việc giải trừ vũ khí hạt nhân đơn phương (= từ bỏ vũ khí hạt nhân của đất nước mình mà không chờ đợi các nước khác làm điều tương tự).","k":"unilateral"},{"t":"Ancestral","d":"belonging to or inherited from one's ancestors","e":"The land was ancestral to the tribe, having been passed down through generations.","ev":"Vùng đất này là tổ tiên của bộ tộc, được truyền qua nhiều thế hệ.","k":"ancestral"},{"t":"Potable","p":"(adj.)","d":"suitable for drinking","e":"During sea voyages it is essential that ships carry a supply of potable water because salty ocean water makes anyone who drinks it sick.","ev":"Trong các chuyến đi biển, điều cần thiết là các con tàu phải mang theo nguồn cung cấp nước uống được vì nước biển mặn khiến bất kỳ ai uống phải nước này đều bị bệnh.","k":"potable"},{"t":"Desecrate","p":"(v.)","d":"to violate the sacredness of a thing or place","e":"They feared that the construction of a golf course would desecrate the preserved wilderness.","ev":"Họ lo ngại rằng việc xây dựng một sân gôn sẽ xâm phạm đến vùng hoang dã được bảo tồn.","k":"desecrate"},{"t":"Aggregate","p":"noun","d":"a whole or total","e":"(1) The three branches of the U.S. Government form an aggregate much more powerful than its individual parts. (2) The dictator tried to aggregate as many people into his army as he possibly could.","ev":"(1) Ba nhánh của Chính phủ Hoa Kỳ tạo thành một tổng thể mạnh mẽ hơn nhiều so với từng phần riêng lẻ. (2) Nhà độc tài cố gắng tập hợp càng nhiều người vào quân đội của mình càng tốt.","k":"aggregate"},{"t":"Indulge","d":"nuông chiều, say mê","e":"She decided to indulge in a piece of chocolate after a long day at work.","ev":"Cô quyết định thưởng thức một miếng sô cô la sau một ngày dài làm việc.","k":"indulge"},{"t":"Frankly","d":"adv. directly, clearly","e":"She spoke very frankly about her experiences.","ev":"Cô ấy đã nói rất thẳng thắn về những trải nghiệm của mình.","k":"frankly"},{"t":"Trite","p":"adj","d":"not original, overused","e":"His jokes quickly became trite and lost their appeal.","ev":"Những câu đùa của anh nhanh chóng trở nên tầm thường và mất đi sức hấp dẫn.","k":"trite"},{"t":"Pathology","p":"(n.)","d":"a social/mental problem, bệnh lý học","e":"Dr. Hastings had difficulty identifying the precise nature of Brian’s pathology.","ev":"Tiến sĩ Hastings gặp khó khăn trong việc xác định bản chất chính xác bệnh lý của Brian.","k":"pathology"},{"t":"Saccharine","p":"(adj.)","d":"sickeningly sweet","e":"Tom’s saccharine manner, although intended to make him popular, actually repelled his classmates.","ev":"Phong cách đường mật của Tom, mặc dù nhằm mục đích khiến anh ấy nổi tiếng, nhưng thực sự đã khiến các bạn cùng lớp của anh ấy khó chịu.","k":"saccharine"},{"t":"Constructive","d":"helpful and useful","e":"His criticism was constructive.","ev":"Những lời chỉ trích của ông mang tính xây dựng.","k":"constructive"}]},{"n":"Chưa phân loại · 29","c":[{"t":"Serendipity","p":"noun","d":"luck, finding good things without looking for them","e":"Their encounter was a stroke of serendipity.","ev":"Cuộc gặp gỡ của họ là một sự tình cờ may mắn.","k":"serendipity"},{"t":"Archetypal","p":"adjective","d":"the most representative or typical example of something","e":"Some believe George Washington was the archetypal politician.","ev":"Một số người cho rằng George Washington là hình mẫu điển hình của một chính trị gia.","k":"archetypal"},{"t":"Animated","p":"adjective","d":"lively","e":"When he talks about drama, which is his true passion, he becomes very animated.","ev":"Khi anh nói về kịch, niềm đam mê thực sự của mình, anh trở nên rất sinh động.","k":"animated"},{"t":"Reconsideration","d":"n. thinking again about a previously made choice","e":"n. thinking again about a previously made choice","ev":"N. suy nghĩ lại về sự lựa chọn trước đó","k":"reconsideration"},{"t":"Alias","p":"noun","d":"a false name or identity","e":"He snuck past the guards by using an alias and fake ID.","ev":"Anh đã lén lút vượt qua các lính gác bằng cách sử dụng một tên giả và giấy tờ giả.","k":"alias"},{"t":"Inept","p":"(adj.)","d":"not suitable or capable, unqualified","e":"She proved how inept she was when she forgot three orders and spilled a beer in a customer’s lap.","ev":"Cô đã chứng tỏ mình kém cỏi như thế nào khi quên ba đơn hàng và làm đổ bia vào lòng khách hàng.","k":"inept"},{"t":"Magnanimous","p":"(adj.)","d":"noble, generous","e":"Although I had already broken most of her dishes, Jacqueline was magnanimous enough to continue letting me use them.","ev":"Mặc dù tôi đã làm vỡ hầu hết bát đĩa của cô ấy nhưng Jacqueline vẫn rất rộng lượng khi tiếp tục cho tôi dùng chúng.","k":"magnanimous"},{"t":"Platitude","p":"(n.)","d":"an uninspired remark, cliché","e":"After reading over her paper, Helene concluded that what she thought were profound insights were actually just platitudes.","ev":"Sau khi đọc qua bài báo của mình, Helene kết luận rằng những gì cô nghĩ là những hiểu biết sâu sắc thực ra chỉ là những điều vô nghĩa.","k":"platitude"},{"t":"Omnipotence","d":"having unlimited or great power","e":"The gods were believed to have omnipotence over the world, controlling the weather, causing natural disasters, and determining the fate of individuals.","ev":"Các vị thần được cho là có quyền toàn năng trên thế giới, kiểm soát thời tiết, gây ra thiên tai và quyết định số phận của mỗi cá nhân.","k":"omnipotence"},{"t":"Upheaval","d":"a sudden change or disruption, chaos","e":"The social upheaval caused widespread unrest, with protests and riots breaking out in cities across the country.","ev":"Biến động xã hội gây ra tình trạng bất ổn lan rộng, với các cuộc biểu tình và bạo loạn nổ ra ở các thành phố trên khắp đất nước.","k":"upheaval"},{"t":"Apprehension","p":"n.","d":"worry about the future, or a fear that something unpleasant is going to happen","e":"It's normal to feel a little apprehension before starting a new job.","ev":"Việc cảm thấy hơi e ngại trước khi bắt đầu một công việc mới là điều bình thường.","k":"apprehension"},{"t":"Flourish","d":"v. to prosper, grow, or make fast progress","e":"v. to prosper, grow, or make fast progress","ev":"v. thịnh vượng, phát triển hoặc tiến bộ nhanh chóng","k":"flourish"},{"t":"Simple","d":"adj. easy; not complex","e":"adj. easy; not complex","ev":"tính từ dễ; không phức tạp","k":"simple"},{"t":"Truncate","p":"(v.)","d":"to shorten by cutting off","e":"After winning the derby, the jockey truncated the long speech he had planned and thanked only his mom and his horse.","ev":"Sau khi giành chiến thắng trong trận derby, tay đua ngựa đã cắt ngắn bài phát biểu dài mà anh ta đã dự định và chỉ cảm ơn mẹ và con ngựa của mình.","k":"truncate"},{"t":"Tranquil","p":"(adj.)","d":"calm","e":"There is a time of night when nothing moves and everything is tranquil.","ev":"Có một thời điểm trong đêm không có gì chuyển động và mọi thứ đều yên tĩnh.","k":"tranquil"},{"t":"Unctuous","p":"(adj.)","d":"smooth or greasy in texture, appearance, manner","e":"The unctuous receptionist seemed untrustworthy, as if she was only being helpful because she thought we might give her a big tip.","ev":"Cô tiếp tân khó tính có vẻ không đáng tin cậy, như thể cô ấy chỉ giúp ích vì cô ấy nghĩ chúng tôi có thể cho cô ấy một khoản tiền boa lớn.","k":"unctuous"},{"t":"Prepossessing","p":"(adj.)","d":"occupying the mind to the exclusion of other thoughts or feelings","e":"His prepossessing appearance made it impossible for me to think of anything else.","ev":"Vẻ ngoài quyến rũ của anh khiến tôi không thể nghĩ được điều gì khác.","k":"prepossessing"},{"t":"Supple","d":"bending or able to be bent easily; not stiff; flexible","e":"Her body was supple and flexible, allowing her to perform acrobatic feats.","ev":"Cơ thể cô dẻo dai và linh hoạt, cho phép cô thực hiện những động tác nhào lộn.","k":"supple"},{"t":"Obtuse","p":"(adj.)","d":"lacking quickness of sensibility or intellect","e":"Political opponents warned that the prime minister’s obtuse approach to foreign policy would embroil the nation in mindless war.","ev":"Các đối thủ chính trị cảnh báo rằng cách tiếp cận thiếu suy nghĩ của thủ tướng đối với chính sách đối ngoại sẽ lôi kéo đất nước vào một cuộc chiến tranh vô tâm.","k":"obtuse"},{"t":"Amend","d":"to revise, to make changes","e":"The government amended the law to address the new issue.","ev":"Chính phủ đã sửa đổi luật để giải quyết vấn đề mới.","k":"amend"},{"t":"Linchpin","p":"(n.)","d":"something that holds separate parts together, or a person or thing vital to an enterprise or organization.","e":"The linchpin in the prosecution’s case was the hair from the defendant’s head, which was found at the scene of the crime.","ev":"Mấu chốt trong vụ án của bên công tố là sợi tóc trên đầu bị cáo, được tìm thấy tại hiện trường vụ án.","k":"linchpin"},{"t":"Grandiose","p":"adj","d":"on a magnificent or exaggerated scale","e":"His grandiose plans for the project were met with skepticism from the team.","ev":"Những kế hoạch phức tạp của anh cho dự án đã gặp sự hoài nghi từ đội ngũ.","k":"grandiose"},{"t":"Flagrant","p":"adjective","d":"offensive, egregious","e":"The athlete's flagrant violation of the rules led to his disqualification.","ev":"Việc vi phạm rõ ràng của vận động viên đã dẫn đến việc anh bị loại.","k":"flagrant"},{"t":"Medley","p":"(n.)","d":"a mixture of differing things","e":"Susannah’s wardrobe contained an astonishing medley of colors, from olive green to fluorescent pink.","ev":"Tủ quần áo của Susannah có sự pha trộn màu sắc đáng kinh ngạc, từ xanh ô liu đến hồng huỳnh quang.","k":"medley"},{"t":"Conducive","d":"providing the right conditions for something to happen or exist; to help bring about","e":"The warm weather was conducive to outdoor activities.","ev":"Thời tiết ấm áp thuận lợi cho các hoạt động ngoài trời.","k":"conducive"}]},{"n":"Chưa phân loại · 30","c":[{"t":"Desolation","d":"a state of complete emptiness or destruction","e":"The war left the country in a state of desolation, with destroyed cities and displaced people.","ev":"Chiến tranh khiến đất nước rơi vào tình trạng hoang tàn, với các thành phố bị phá hủy và người dân phải di dời.","k":"desolation"},{"t":"Gourmand","p":"(n.)","d":"someone fond of eating and drinking","e":"My parents, who used to eat little more than crackers and salad, have become real gourmands in their old age.","ev":"Cha mẹ tôi, những người từng ăn ít hơn bánh quy giòn và salad, đã trở thành những người sành ăn thực sự khi về già.","k":"gourmand"},{"t":"Sinister","d":"adj. ominous, evil","e":"adj. ominous, evil","ev":"tính từ đáng ngại, xấu xa","k":"sinister"},{"t":"Polemic","p":"(n.)","d":"an aggressive argument against a specific opinion, bút chiến","e":"My brother launched into a polemic against my arguments that capitalism was an unjust economic system.","ev":"Anh trai tôi bắt đầu bút chiến chống lại lập luận của tôi rằng chủ nghĩa tư bản là một hệ thống kinh tế bất công.","k":"polemic"},{"t":"Frugal","p":"(adj.)","d":"thrifty, economical","e":"Richard is so frugal that his diet consists almost exclusively of catfish and chicken liver—the two most inexpensive foods in the store.","ev":"Richard tiết kiệm đến mức chế độ ăn uống của anh hầu như chỉ bao gồm cá da trơn và gan gà - hai loại thực phẩm rẻ tiền nhất trong cửa hàng.","k":"frugal"},{"t":"Disdain","p":"(v.)","d":"to scorn, hold in low esteem","e":"Insecure about their jobs, the older employees disdained the recently hired ones, who were young and capable.","ev":"Không an tâm về công việc của mình, những nhân viên lớn tuổi coi thường những người mới được thuê, còn trẻ và có năng lực.","x":"Loại từ 2: (n.)\nNghĩa 2: scorn, low esteem\nVí dụ 2: After learning of his immoral actions, Justine held Lawrence in disdain.","k":"disdain"},{"t":"Accordingly","d":"adv. in accordance with","e":"adv. in accordance with","ev":"lời khuyên. phù hợp với","k":"accordingly"},{"t":"Condolence","p":"noun","d":"an expression of sympathy in sorrow","e":"Brian lamely offered his condolences on the loss of his sister’s roommate’s cat.","ev":"Brian đã bày tỏ sự cảm thông về cái chết của một con mèo.","k":"condolence"},{"t":"To Stress","d":"to emphasize","e":"She was stressed about her upcoming exam, feeling overwhelmed and anxious about the pressure to succeed.","ev":"Cô căng thẳng về kỳ thi sắp tới, cảm thấy choáng ngợp và lo lắng trước áp lực phải thành công.","k":"to stress"},{"t":"Flatter","d":"to praise someone in order to please him or her","e":"He flattered her by complimenting her appearance.","ev":"Anh tâng bốc cô bằng cách khen ngợi vẻ ngoài của cô.","k":"flatter"},{"t":"Maudlin","p":"adjective","d":"weakly sentimental","e":"She became maudlin after a few drinks, reminiscing about her high school days.","ev":"Cô trở nên sướt mướt sau vài ly, nhớ lại những ngày ở trường trung học.","k":"maudlin"},{"t":"Seminal","p":"(adj.)","d":"original, important, creating a field","e":"Stephen Greenblatt’s essays on Shakespeare proved to be seminal, because they initiated the critical school of New Historicism.","ev":"Các bài tiểu luận của Stephen Greenblatt về Shakespeare tỏ ra có sức ảnh hưởng lớn vì chúng đã khởi xướng trường phái phê phán Chủ nghĩa Lịch sử Mới.","k":"seminal"},{"t":"Continuum","d":"a continuous sequence; a range","e":"Time is a continuum, flowing smoothly from one moment to the next.","ev":"Thời gian là một dòng chảy liên tục, trôi chảy từ khoảnh khắc này sang khoảnh khắc tiếp theo.","k":"continuum"},{"t":"Discern/ Discerning","d":"To recognize or distinguish; perceptive","e":"She has a discerning taste in wine.","ev":"Cô ấy có sở thích sành điệu về rượu vang.","x":"Ví dụ 2: not negative","k":"discern/ discerning"},{"t":"Objection","d":"a reason for disagreeing","e":"She raised an objection to the proposal, arguing that it was unfair and discriminatory.","ev":"Cô đã phản đối đề xuất này, cho rằng nó không công bằng và mang tính phân biệt đối xử.","k":"objection"},{"t":"Compel","d":"to force someone to do something","e":"The law compelled him to testify, forcing him to provide evidence in the court case.","ev":"Luật pháp bắt buộc anh ta phải làm chứng, buộc anh ta phải cung cấp bằng chứng trước tòa.","k":"compel"},{"t":"Deceive","d":"to trick or mislead someone","e":"She tried to deceive him into believing her story, lying to him in order to manipulate him.","ev":"Cô cố gắng lừa anh tin vào câu chuyện của cô, nói dối anh để thao túng anh.","k":"deceive"},{"t":"Modicum","p":"noun","d":"a small amount of something","e":"She only had a modicum of experience, but she was eager to learn more.","ev":"Cô chỉ có một chút kinh nghiệm, nhưng cô rất háo hức để học hỏi thêm.","k":"modicum"},{"t":"Clinical","d":"adj. emotionally unattached (usu. used in medical or scientific setting)","e":"adj. emotionally unattached (usu. used in medical or scientific setting)","ev":"tính từ không bị ràng buộc về mặt cảm xúc (thường được sử dụng trong môi trường y tế hoặc khoa học)","k":"clinical"},{"t":"Trounce","d":"to defeat someone easily and completely","e":"Our team trounced their opponents.","ev":"Đội của chúng tôi đã đánh bại đối thủ của họ.","k":"trounce"},{"t":"Exonerate","p":"(v.)","d":"to free from guilt or blame, exculpate","e":"The true thief’s confession exonerated the man who had been held in custody for the crime.","ev":"Lời thú tội của tên trộm thực sự đã minh oan cho người đàn ông từng bị giam giữ vì tội ác này.","k":"exonerate"},{"t":"Quotidian","p":"(adj.)","d":"daily","e":"Ambika’s quotidian routines include drinking two cups of coffee in the morning.","ev":"Thói quen thường ngày của Ambika bao gồm uống hai tách cà phê vào buổi sáng.","k":"quotidian"},{"t":"Frenetic","p":"(adj.)","d":"frenzied, hectic, frantic","e":"In the hours between night and morning, the frenetic pace of city life slows to a lull.","ev":"Trong khoảng thời gian từ đêm đến sáng, nhịp sống hối hả của thành phố chậm lại đến mức tạm lắng.","k":"frenetic"},{"t":"Garish","p":"adj","d":"gaudy, in bad taste","e":"The room was decorated in garish colors.","ev":"Căn phòng được trang trí bằng màu sắc lòe loẹt.","k":"garish"},{"t":"Secular","d":"having no religious or spiritual basis","e":"The government was secular and did not favor any particular religion, ensuring that all citizens were treated equally.","ev":"Chính phủ là thế tục và không ủng hộ bất kỳ tôn giáo cụ thể nào, đảm bảo rằng mọi công dân đều được đối xử bình đẳng.","k":"secular"}]},{"n":"Chưa phân loại · 31","c":[{"t":"Inclination","p":"(n.)","d":"a tendency, propensity","e":"Sarah has an inclination to see every foreign film she hears about, even when she’s sure that she won’t like it.","ev":"Sarah có xu hướng xem mọi bộ phim nước ngoài mà cô ấy nghe nói đến, ngay cả khi cô ấy chắc chắn rằng mình sẽ không thích nó.","k":"inclination"},{"t":"Commodious","p":"(adj.)","d":"roomy","e":"Holden invited the three women to join him in the back seat of the taxicab, assuring them that the car was quite commodious.","ev":"Holden mời ba người phụ nữ ngồi cùng anh ta ở ghế sau của chiếc taxi, đảm bảo với họ rằng chiếc xe khá rộng rãi.","k":"commodious"},{"t":"Sobriety","p":"(n.) /səˈbraɪ.ə.t̬i/","d":"sedate, calm, điềm tĩnh","e":"Jason believed that maintaining his sobriety in times of crisis was the key to success in life.","ev":"Jason tin rằng việc duy trì trạng thái tỉnh táo trong thời kỳ khủng hoảng là chìa khóa thành công trong cuộc sống.","k":"sobriety"},{"t":"Defer","p":"(v.)","d":"to postpone something; to yield to another’s wisdom, chiều theo","e":"Ron deferred to Diane, the expert on musical instruments, when he was asked about buying a piano.","ev":"Ron đã nói với Diane, chuyên gia về nhạc cụ, khi được hỏi về việc mua một cây đàn piano.","k":"defer"},{"t":"Capricious","p":"adjective","d":"subject to whim, fickle","e":"Her capricious nature made it difficult to predict her reactions.","ev":"Tính cách thất thường của cô khiến việc dự đoán phản ứng của cô trở nên khó khăn.","k":"capricious"},{"t":"Torrid","p":"(adj.)","d":"giving off intense heat, passionate","e":"I didn’t want to witness the neighbor’s torrid affair through the window.","ev":"Tôi không muốn chứng kiến ​​cảnh nóng bỏng của người hàng xóm qua cửa sổ.","k":"torrid"},{"t":"Principle","d":"n. basic truth, assumption, or rule","e":"n. basic truth, assumption, or rule","ev":"N. sự thật, giả định hoặc quy tắc cơ bản","k":"principle"},{"t":"Culmination","p":"noun","d":"the climax toward which something progresses","e":"The culmination of the couple’s argument was the decision to divorce.","ev":"Đỉnh điểm của cuộc tranh cãi của cặp đôi là quyết định ly hôn.","k":"culmination"},{"t":"Tacit","p":"(adj.)","d":"expressed without words","e":"I interpreted my parents’ refusal to talk as a tacit acceptance of my request.","ev":"Tôi hiểu việc bố mẹ từ chối nói chuyện là sự ngầm chấp nhận yêu cầu của tôi.","k":"tacit"},{"t":"Actuate","d":"1) to cause (a machine or device) to operate 2) to cause (someone) to act in a particular way","e":"The desire for revenge actuated her actions.","ev":"Mong muốn trả thù đã thúc đẩy hành động của cô.","k":"actuate"},{"t":"Novel","d":"new or unusual in an interesting way","e":"The novel was a best-seller, praised for its originality and creativity.","ev":"Cuốn tiểu thuyết là cuốn sách bán chạy nhất, được ca ngợi vì sự độc đáo và sáng tạo.","k":"novel"},{"t":"Judicious","p":"adj","d":"having or exercising sound judgment, sáng suốt","e":"His judicious decision helped the company avoid a major crisis.","ev":"Quyết định khôn ngoan của anh đã giúp công ty tránh được một cuộc khủng hoảng lớn.","k":"judicious"},{"t":"Approbation","p":"noun","d":"praise","e":"The crowd welcomed the heroes with approbation.","ev":"Đám đông đã chào đón các anh hùng với sự ca ngợi.","k":"approbation"},{"t":"Conform","d":"to behave according to an expectation or rule","e":"She had to conform to the company's dress code, wearing a suit to work.","ev":"Cô phải tuân thủ quy định về trang phục của công ty, mặc vest đi làm.","k":"conform"},{"t":"Speculative","p":"(adj.)","d":"not based in fact","e":"Sadly, Tessa was convicted on merely speculative evidence.","ev":"Đáng buồn thay, Tessa bị kết án chỉ dựa trên bằng chứng suy đoán.","k":"speculative"},{"t":"Lithe","p":"adj","d":"graceful, flexible, supple","e":"The dancer moved with a lithe grace that captivated the audience.","ev":"Vũ công di chuyển với sự duyên dáng mềm mại đã thu hút khán giả.","k":"lithe"},{"t":"Petty","d":"1) of little importance 2) caring too much about trivial matters","e":"He was a petty person who held grudges and got upset over trivial matters.","ev":"Anh ta là một người nhỏ mọn, hay oán giận và khó chịu vì những vấn đề tầm thường.","k":"petty"},{"t":"Subjugate","p":"(v.)","d":"to bring under control, subdue","e":"The invading force captured and subjugated the natives of that place.","ev":"Thế lực xâm lược đã bắt và khuất phục người dân bản xứ nơi đó.","k":"subjugate"},{"t":"Secluded","d":"hard to reach, hidden away","e":"The secluded cabin provided a peaceful retreat from the hustle and bustle of the city.","ev":"Cabin hẻo lánh mang đến một nơi trú ẩn yên bình khỏi sự hối hả và nhộn nhịp của thành phố.","k":"secluded"},{"t":"Anxiety","p":"noun","d":"intense uneasiness","e":"When he heard about the car crash, he felt anxiety because he knew his girlfriend was driving on that road.","ev":"Khi anh nghe về vụ tai nạn xe hơi, anh cảm thấy lo lắng vì biết bạn gái mình đang lái xe trên con đường đó.","k":"anxiety"},{"t":"Fatuous","p":"(adj.)","d":"silly, foolish","e":"He considers himself a serious poet, but in truth, he only writes fatuous limericks.","ev":"Anh ta tự coi mình là một nhà thơ nghiêm túc, nhưng thực ra anh ta chỉ viết những câu thơ châm biếm ngu ngốc.","k":"fatuous"},{"t":"Content","d":"satisfied","e":"She was content with her simple life, finding joy in the small things.","ev":"Cô hài lòng với cuộc sống giản dị của mình, tìm thấy niềm vui từ những điều nhỏ nhặt.","k":"content"},{"t":"Extant","p":"(adj.)","d":"existing, not destroyed or lost","e":"My mother’s extant love letters to my father are in the attic trunk.","ev":"Những bức thư tình còn sót lại của mẹ tôi gửi cho bố tôi nằm trong cốp gác mái.","k":"extant"},{"t":"Sedentary","p":"(adj.)","d":"sitting, settled","e":"The sedentary cat did little but loll in the sun.","ev":"Con mèo ít vận động không làm gì nhiều ngoài việc nằm dài dưới nắng.","k":"sedentary"},{"t":"Phlegmatic","p":"(adj.)","d":"uninterested, unresponsive","e":"Monique feared her dog was ill after the animal’s phlegmatic response to his favorite chew toy.","ev":"Monique lo sợ con chó của cô bị ốm sau phản ứng đờ đẫn của con vật với món đồ chơi nhai yêu thích của nó.","k":"phlegmatic"}]},{"n":"Chưa phân loại · 32","c":[{"t":"Sneer","d":"to make a facial expression that shows disapproval or disrespect","e":"He sneered at her suggestion, implying that it was stupid.","ev":"Anh chế nhạo lời đề nghị của cô, ngụ ý rằng nó thật ngu ngốc.","k":"sneer"},{"t":"Merely","d":"only; just","e":"He was merely trying to help, not to criticize, as he genuinely wanted to offer his assistance.","ev":"Anh ấy chỉ cố gắng giúp đỡ chứ không phải chỉ trích vì anh ấy thực sự muốn đề nghị giúp đỡ.","k":"merely"},{"t":"Boast","d":"to brag, to show off","e":"He boasted about his athletic abilities, exaggerating his achievements and trying to impress others.","ev":"Anh ta khoe khoang về khả năng thể thao của mình, phóng đại thành tích của mình và cố gắng gây ấn tượng với người khác.","k":"boast"},{"t":"Pert","p":"(adj.)","d":"flippant, bold","e":"My parents forgave Sandra’s pert humor at the dinner table because it had been so long since they had last seen her.","ev":"Cha mẹ tôi đã tha thứ cho sự hài hước ngang tàng của Sandra trên bàn ăn tối vì đã quá lâu rồi họ chưa gặp lại cô ấy.","k":"pert"},{"t":"Accretion","p":"noun","d":"slow growth in size or amount","e":"Stalactites form through the accretion of minerals in caves.","ev":"Thạch nhũ hình thành qua sự tích lũy khoáng chất trong các hang động.","k":"accretion"},{"t":"Subordinate","d":"having a lower or less important position","e":"She was subordinate to her boss, following his orders and respecting his authority.","ev":"Cô phục tùng sếp, tuân theo mệnh lệnh của ông và tôn trọng quyền lực của ông.","k":"subordinate"},{"t":"Antecedent","p":"noun","d":"something that came before","e":"The great tradition of Western culture had its antecedent in the culture of Ancient Greece.","ev":"Truyền thống vĩ đại của văn hóa phương Tây có nguồn gốc từ nền văn hóa Hy Lạp cổ đại.","k":"antecedent"},{"t":"Disposed","d":"inclined","e":"She seems favourably disposed towards the idea.","ev":"Cô ấy có vẻ có thiện cảm với ý tưởng này.","k":"disposed"},{"t":"Winsome","p":"(adj.)","d":"charming, pleasing","e":"After such a long, frustrating day, I was grateful for Chris’s winsome attitude and childish naivete.","ev":"Sau một ngày dài chán nản như vậy, tôi biết ơn thái độ lôi cuốn và sự ngây thơ trẻ con của Chris.","k":"winsome"},{"t":"Assiduous","p":"adjective","d":"hard-working, diligent","e":"His assiduous efforts in studying paid off with high grades.","ev":"Nỗ lực chăm chỉ của anh trong việc học đã được đền đáp bằng điểm số cao.","k":"assiduous"},{"t":"Irksome","d":"irritating, annoying","e":"The irksome noise from the neighbor's house made it difficult to concentrate, driving her to distraction.","ev":"Tiếng ồn khó chịu từ nhà hàng xóm khiến cô khó tập trung, khiến cô mất tập trung.","k":"irksome"},{"t":"Disclose","p":"(v.)","d":"to reveal, make public","e":"The CEO disclosed to the press that the company would have to fire several employees.","ev":"Giám đốc điều hành tiết lộ với báo chí rằng công ty sẽ phải sa thải một số nhân viên.","k":"disclose"},{"t":"Utopia","p":"(n.)","d":"an imaginary and remote place of perfection","e":"Everyone in the world wants to live in a utopia, but no one can agree how to go about building one.","ev":"Mọi người trên thế giới đều muốn sống trong một điều không tưởng, nhưng không ai có thể thống nhất được cách thức xây dựng điều đó.","k":"utopia"},{"t":"Cognizant","p":"(adj.)","d":"aware, mindful","e":"Jake avoided speaking to women in bars because he was cognizant of the fact that drinking impairs his judgment.","ev":"Jake tránh nói chuyện với phụ nữ trong quán bar vì anh nhận thức được thực tế rằng việc uống rượu làm suy giảm khả năng phán đoán của anh.","k":"cognizant"},{"t":"Unwieldy","d":"difficult to carry or move","e":"The box was too unwieldy to carry, being heavy and awkward to maneuver.","ev":"Chiếc hộp quá khó để mang theo, nặng và khó điều khiển.","k":"unwieldy"},{"t":"Naive","d":"showing a lack of experience, wisdom, or judgment","e":"He was naive and trusting, easily believing the promises of others and falling victim to scams.","ev":"Anh ngây thơ và cả tin, dễ tin vào lời hứa của người khác và trở thành nạn nhân của những trò lừa đảo.","k":"naive"},{"t":"Sensuous","p":"(adj.)","d":"involving sensory gratification","e":"Paul found drinking Coke, with all the little bubbles bursting on his tongue, a very sensuous experience.","ev":"Paul thấy uống Coke với những bong bóng nhỏ sủi bọt trên lưỡi, một trải nghiệm rất khoái cảm.","k":"sensuous"},{"t":"Refine","d":"to improve something by making small changes","e":"The oil was refined into gasoline.","ev":"Dầu đã được tinh chế thành xăng.","k":"refine"},{"t":"Flout","p":"(v.)","d":"to disregard or disobey openly","e":"I flouted the school’s dress code by wearing a tie-dyed tank top and a pair of cut-off jeans.","ev":"Tôi vi phạm quy định về trang phục của trường bằng cách mặc một chiếc áo ba lỗ nhuộm màu cà vạt và một chiếc quần jean rách.","k":"flout"},{"t":"Antithesis","p":"noun","d":"the absolute opposite","e":"Your values, which hold war in high esteem, are the antithesis of my pacifist beliefs.","ev":"Giá trị của bạn, coi trọng chiến tranh, hoàn toàn trái ngược với niềm tin hòa bình của tôi.","k":"antithesis"},{"t":"Proliferate","d":"increase or grow rapidly","e":"The weeds proliferated in the garden, growing rapidly and spreading uncontrollably.","ev":"Cỏ dại mọc tràn lan trong vườn, mọc nhanh và lây lan không kiểm soát.","k":"proliferate"},{"t":"Insipid","p":"adjective","d":"dull, boring","e":"The soup was insipid, lacking flavor and excitement.","ev":"Món súp nhạt nhẽo, thiếu hương vị và sự thú vị.","k":"insipid"},{"t":"Abdicate","p":"verb","d":"to give up a position, usually one of leadership","e":"When he realized the revolutionaries would win, the king abdicated his throne.","ev":"Khi nhận ra rằng những người cách mạng sẽ thắng, nhà vua đã từ bỏ ngai vàng.","k":"abdicate"},{"t":"Burden","d":"a difficulty, problem, or responsibility","e":"The heavy burden of responsibility weighed heavily on her, causing her to feel overwhelmed and stressed.","ev":"Gánh nặng trách nhiệm đè nặng lên cô khiến cô cảm thấy choáng ngợp và căng thẳng.","k":"burden"},{"t":"Dormant","p":"adjective","d":"sleeping, temporarily inactive","e":"The seeds remained dormant until the spring rains woke them up.","ev":"Hạt giống vẫn nằm im cho đến khi mưa xuân đánh thức chúng.","k":"dormant"}]},{"n":"Chưa phân loại · 33","c":[{"t":"Cobbler","p":"(n.)","d":"a person who makes or repairs shoes","e":"I had my neighborhood cobbler replace my worn-out leather soles with new ones.","ev":"Tôi đã nhờ người thợ giày hàng xóm thay những chiếc đế da cũ kỹ của mình bằng những chiếc đế mới.","k":"cobbler"},{"t":"Ferocity","d":"n. viciousness, violence","e":"n. viciousness, violence","ev":"N. sự hung ác, bạo lực","k":"ferocity"},{"t":"Insatiable","p":"(adj.)","d":"incapable of being satisfied","e":"My insatiable appetite for melons can be a real problem in the winter.","ev":"Sự thèm ăn dưa vô độ của tôi có thể là một vấn đề thực sự trong mùa đông.","k":"insatiable"},{"t":"Evoke","p":"verb","d":"to bring to mind","e":"The song evoked memories of her childhood and made her nostalgic.","ev":"Bài hát gợi lại những kỷ niệm về thời thơ ấu của cô và khiến cô cảm thấy hoài niệm.","k":"evoke"},{"t":"Auspicious","p":"adj","d":"favorable, indicative of good things","e":"The signs were auspicious for a successful outcome.","ev":"Các dấu hiệu rất thuận lợi cho một kết quả thành công.","k":"auspicious"},{"t":"Articulate","d":"having the ability to speak fluently and persuasively","e":"She was an articulate speaker, able to express her ideas clearly and persuasively.","ev":"Cô ấy là một diễn giả lưu loát, có khả năng diễn đạt ý tưởng của mình một cách rõ ràng và thuyết phục.","k":"articulate"},{"t":"Vitriolic","p":"(adj.)","d":"having a caustic quality","e":"When angry, the woman would spew vitriolic insults.","ev":"Khi tức giận, người phụ nữ sẽ phun ra những lời lăng mạ cay nghiệt.","k":"vitriolic"},{"t":"Disheartened","p":"(adj.)","d":"feeling a loss of spirit or morale","e":"The team was disheartened after losing in the finals of the tournament.","ev":"Toàn đội thất vọng sau khi thua ở trận chung kết của giải đấu.","k":"disheartened"},{"t":"Chastise","p":"verb","d":"to criticize severely","e":"She chastised her son for not completing his homework.","ev":"Cô đã khiển trách con trai vì không hoàn thành bài tập về nhà.","k":"chastise"},{"t":"Analgesic","p":"noun","d":"something that reduces pain","e":"Put this analgesic on the wound so that the poor man feels a little better.","ev":"Đặt thuốc giảm đau này lên vết thương để người đàn ông tội nghiệp cảm thấy dễ chịu hơn một chút.","k":"analgesic"},{"t":"Vitality","d":"life, energy, and strength","e":"The young man exuded vitality, full of energy and enthusiasm.","ev":"Chàng trai toát lên sức sống, tràn đầy năng lượng và nhiệt huyết.","k":"vitality"},{"t":"Paternal","d":"behaving or feeling as a father does toward his child","e":"He had a paternal relationship with his employees, treating them like family.","ev":"Ông có mối quan hệ như cha con với nhân viên của mình, đối xử với họ như gia đình.","k":"paternal"},{"t":"Wane","p":"(v.)","d":"to decrease in size, dwindle","e":"Don’t be so afraid of his wrath because his influence with the president is already beginning to wane.","ev":"Đừng quá sợ hãi trước cơn thịnh nộ của ông ấy vì ảnh hưởng của ông ấy với tổng thống đã bắt đầu suy yếu.","k":"wane"},{"t":"Taxonomy","d":"classification system","e":"The taxonomy of plants is based on their physical characteristics.","ev":"Việc phân loại thực vật dựa trên đặc điểm vật lý của chúng.","x":"Ví dụ 2: Science-Related Terms","k":"taxonomy"},{"t":"Hiatus","p":"(n.)","d":"a break or gap in duration or continuity","e":"The hiatus in service should last two or three months—until the cable lines are repaired .","ev":"Thời gian gián đoạn dịch vụ sẽ kéo dài hai hoặc ba tháng—cho đến khi đường cáp được sửa chữa.","k":"hiatus"},{"t":"Peculiar","d":"adj. strange, bizarre","e":"adj. strange, bizarre","ev":"tính từ kỳ lạ, kỳ quái","k":"peculiar"},{"t":"Catalog","p":"(v.)","d":"to list, enter into a list","e":"The judge cataloged the victim’s injuries before calculating how much money he would award.","ev":"Thẩm phán đã liệt kê các vết thương của nạn nhân trước khi tính toán số tiền mà anh ta sẽ thưởng.","x":"Loại từ 2: (n.)\nNghĩa 2: a list or collection\nVí dụ 2: We received a catalog from J. Crew that displayed all of their new items.","k":"catalog"},{"t":"Abet","p":"verb","d":"to aid, help, encourage","e":"The spy succeeded only because a friend on the inside abetted him.","ev":"Điệp viên thành công chỉ nhờ có một người bạn bên trong hỗ trợ.","k":"abet"},{"t":"Authenticity","d":"n. the quality of being real and true instead of fake and contrived","e":"n. the quality of being real and true instead of fake and contrived","ev":"N. chất lượng của sự thật và sự thật thay vì giả tạo và giả tạo","k":"authenticity"},{"t":"Sustain","d":"to strengthen or support; to keep alive","e":"The bridge could not sustain the weight of the truck.","ev":"Cây cầu không thể chịu được trọng lượng của xe tải.","k":"sustain"},{"t":"Hardy","p":"adjective","d":"robust, capable of surviving through adverse conditions","e":"The hardy plants thrived in the harsh environment.","ev":"Những cây cối bền bỉ đã phát triển mạnh mẽ trong môi trường khắc nghiệt.","k":"hardy"},{"t":"Puerile","p":"(adj.)","d":"juvenile, immature","e":"The judge demanded order after the lawyer’s puerile attempt to object by stomping his feet on the courtroom floor.","ev":"Thẩm phán yêu cầu trật tự sau khi luật sư cố gắng phản đối bằng cách dậm chân xuống sàn phòng xử án.","k":"puerile"},{"t":"Crescendo","p":"noun","d":"a steady increase in intensity or volume","e":"The crescendo of the brass instruments gave the piece a patriotic feel.","ev":"Sự tăng dần của nhạc cụ đồng cho bản nhạc cảm giác yêu nước.","k":"crescendo"},{"t":"Meretricious","d":"attractive in a cheap and showy way","e":"The decorations were meretricious and tacky.","ev":"Các đồ trang trí chỉ đơn giản và rườm rà.","k":"meretricious"},{"t":"Contemplate","d":"to think about for a long time","e":"She contemplated the meaning of life, pondering deep philosophical questions and searching for answers.","ev":"Cô suy ngẫm về ý nghĩa của cuộc sống, cân nhắc những câu hỏi triết học sâu sắc và tìm kiếm câu trả lời.","k":"contemplate"}]},{"n":"Chưa phân loại · 34","c":[{"t":"Legerdemain","p":"(n.)","d":"deception, slight-of-hand","e":"Smuggling the French plants through customs by claiming that they were fake was a remarkable bit of legerdemain.","ev":"Việc buôn lậu các loại cây của Pháp thông qua hải quan bằng cách tuyên bố rằng chúng là hàng giả là một hành vi lừa đảo đáng chú ý.","k":"legerdemain"},{"t":"Vexing","d":"annoying, irritating","e":"The vexing problem kept her up at night, preventing her from getting a good rest.","ev":"Vấn đề khó chịu đó khiến cô mất ngủ cả đêm, khiến cô không thể nghỉ ngơi thoải mái.","k":"vexing"},{"t":"Constitute","d":"to be the parts that form something","e":"The five books constitute the Bible.","ev":"Năm cuốn sách tạo thành Kinh Thánh.","k":"constitute"},{"t":"Emend","p":"(v.)","d":"to correct or revise a written text","e":"If my sentence is incorrect, the editor will emend what I have written.","ev":"Nếu câu của tôi sai, người biên tập sẽ sửa lại những gì tôi đã viết.","k":"emend"},{"t":"Knell","p":"(n.)","d":"the solemn sound of a bell, often indicating a death","e":"Echoing throughout our village, the funeral knell made the stormy day even more grim.","ev":"Tiếng chuông tang lễ vang vọng khắp làng chúng tôi khiến ngày giông bão càng trở nên nghiệt ngã hơn.","k":"knell"},{"t":"Atone","p":"verb","d":"to repent, make amends","e":"She wanted to atone for her past mistakes by helping others.","ev":"Cô ấy muốn chuộc lỗi cho những sai lầm trong quá khứ bằng cách giúp đỡ người khác.","k":"atone"},{"t":"Querulous","p":"(adj.)","d":"whiny, complaining","e":"If deprived of his pacifier, young Brendan becomes querulous.","ev":"Nếu bị tước mất núm vú giả, cậu bé Brendan sẽ trở nên cáu kỉnh.","k":"querulous"},{"t":"Tremulous","p":"(adj.)","d":"fearful","e":"I always feel a trifle tremulous when walking through a graveyard.","ev":"Tôi luôn cảm thấy hơi run khi đi qua nghĩa địa.","k":"tremulous"},{"t":"Inveterate","p":"(adj.)","d":"stubbornly established by habit","e":"I’m the first to admit that I’m an inveterate coffee drinker—I drink four cups a day.","ev":"Tôi là người đầu tiên thừa nhận rằng tôi là người nghiện cà phê – tôi uống bốn cốc mỗi ngày.","k":"inveterate"},{"t":"Figurative","p":"(adj.)","d":"symbolic","e":"Using figurative language, Jane likened the storm to an angry bull.","ev":"Sử dụng ngôn ngữ tượng hình, Jane ví cơn bão như một con bò đực đang giận dữ.","k":"figurative"},{"t":"Render","d":"to cause someone or something to be in a particular state","e":"He rendered assistance to the injured man.","ev":"Anh ta đã giúp đỡ người đàn ông bị thương.","k":"render"},{"t":"Zenith","p":"(n.)","d":"the highest point, culminating point","e":"I was too nice to tell Nelly that she had reached the absolute zenith of her career with that one hit of hers.","ev":"Tôi thật tử tế khi nói với Nelly rằng cô ấy đã đạt đến đỉnh cao tuyệt đối trong sự nghiệp chỉ với một bản hit của cô ấy.","k":"zenith"},{"t":"Implicit","p":"(adj.)","d":"understood but not outwardly obvious, implied","e":"I know Professor Smith didn’t actually say not to write from personal experience, but I think such a message was implicit in her instruction to use scholarly sources.","ev":"Tôi biết Giáo sư Smith thực sự không nói rằng đừng viết từ kinh nghiệm cá nhân, nhưng tôi nghĩ thông điệp như vậy đã ẩn chứa trong hướng dẫn của cô ấy về việc sử dụng các nguồn học thuật.","k":"implicit"},{"t":"Insurgent","p":"(n.)","d":"one who rebels","e":"The insurgent snuck into and defaced a different classroom each night until the administration agreed to meet his demands.","ev":"Kẻ nổi dậy lẻn vào và phá hoại một lớp học khác nhau mỗi đêm cho đến khi chính quyền đồng ý đáp ứng yêu cầu của hắn.","k":"insurgent"},{"t":"Clergy","p":"(n.)","d":"members of Christian holy orders","e":"Though the villagers viewed the church rectory as quaint and charming, the clergy who lived there regarded it as a mildewy and dusty place that aggravated their allergies.","ev":"Mặc dù dân làng coi nhà xứ của nhà thờ là một nơi cổ kính và quyến rũ, nhưng các giáo sĩ sống ở đó lại coi đây là một nơi ẩm mốc và bụi bặm khiến bệnh dị ứng của họ càng trầm trọng hơn.","k":"clergy"},{"t":"Pejorative","p":"(adj.)","d":"derogatory, uncomplimentary","e":"The evening’s headline news covered an international scandal caused by a pejorative statement the famous senator had made in reference to a foreign leader.","ev":"Bản tin tiêu đề buổi tối đưa tin về một vụ bê bối quốc tế gây ra bởi một tuyên bố mang tính miệt thị mà thượng nghị sĩ nổi tiếng đã đưa ra khi đề cập đến một nhà lãnh đạo nước ngoài.","k":"pejorative"},{"t":"Disaffected","p":"(adj.)","d":"rebellious, resentful of authority","e":"Dismayed by Bobby’s poor behavior, the parents sent their disaffected son to a military academy to be disciplined.","ev":"Thất vọng trước hành vi kém cỏi của Bobby, cha mẹ cậu đã gửi đứa con trai bất mãn của mình đến học viện quân sự để kỷ luật.","k":"disaffected"},{"t":"Complacency","p":"(n.)","d":"self-satisfied ignorance of danger","e":"Colin tried to shock his friends out of their complacency by painting a frightening picture of what might happen to them.","ev":"Colin cố gắng làm cho bạn bè của mình bị sốc vì sự tự mãn của họ bằng cách vẽ ra một bức tranh đáng sợ về những gì có thể xảy ra với họ.","k":"complacency"},{"t":"Parody","p":"noun/verb","d":"a satirical imitation","e":"The comedian’s parody of the politician had everyone laughing.","ev":"Màn parodie của diễn viên hài về chính trị gia đã khiến mọi người cười ngả nghiêng.","k":"parody"},{"t":"Counterproductive","d":"adj. Having the opposite of the desired effect","e":"The response to the disaster was unsuccessful and perhaps even counterproductive","ev":"Việc ứng phó với thảm họa đã không thành công và thậm chí có thể phản tác dụng","k":"counterproductive"},{"t":"Coronation","p":"noun","d":"the act of crowning","e":"The new king’s coronation occurred the day after his father’s death.","ev":"Lễ đăng quang của nhà vua mới diễn ra một ngày sau khi cha ông qua đời.","k":"coronation"},{"t":"Serene","p":"(adj.)","d":"calm, untroubled","e":"Louise stood in front of the Mona Lisa, puzzling over the famous woman’s serene smile.","ev":"Louise đứng trước bức Mona Lisa, bối rối trước nụ cười thanh thản của người phụ nữ nổi tiếng.","k":"serene"},{"t":"Calibrate","p":"(v.)","d":"to set, standardize","e":"The mechanic calibrated the car’s transmission to make the motor run most efficiently.","ev":"Người thợ đã hiệu chỉnh hộp số của ô tô để động cơ hoạt động hiệu quả nhất.","k":"calibrate"},{"t":"Decry","p":"(v.)","d":"to criticize openly","e":"The kind video rental clerk decried the policy of charging customers late fees.","ev":"Người nhân viên cho thuê video tốt bụng đã chê bai chính sách tính phí trễ hạn của khách hàng.","k":"decry"},{"t":"Camaraderie","p":"(n.)","d":"brotherhood, jovial unity","e":"Camaraderie among employees usually leads to success in business.","ev":"Tình bạn giữa các nhân viên thường dẫn đến thành công trong kinh doanh.","k":"camaraderie"}]},{"n":"Chưa phân loại · 35","c":[{"t":"Pressing","d":"urgent or needing to be dealt with immediately","e":"The pressing need for food and water led to a humanitarian crisis.","ev":"Nhu cầu cấp thiết về lương thực và nước uống đã dẫn đến một cuộc khủng hoảng nhân đạo.","k":"pressing"},{"t":"Disparity","d":"a great difference","e":"There was a wide disparity between the rich and the poor in the country, with some people living in luxury while others struggled to survive.","ev":"Có sự chênh lệch lớn giữa người giàu và người nghèo trong nước, một số người sống xa hoa trong khi những người khác phải vật lộn để tồn tại.","k":"disparity"},{"t":"Artisan","p":"noun","d":"a craftsman","e":"The artisan uses wood to create beautiful furniture.","ev":"Người thợ thủ công sử dụng gỗ để tạo ra đồ nội thất đẹp.","k":"artisan"},{"t":"Cosmopolitan","p":"adj","d":"sophisticated, worldly","e":"The cosmopolitan city attracts people from all over the world.","ev":"Thành phố quốc tế thu hút người từ khắp nơi trên thế giới.","k":"cosmopolitan"},{"t":"Combustion","p":"(n.)","d":"the act or process of burning","e":"The unexpected combustion of the prosecution’s evidence forced the judge to dismiss the case against Ramirez.","ev":"Việc đốt bằng chứng bất ngờ của bên công tố đã buộc thẩm phán phải bác bỏ vụ kiện chống lại Ramirez.","k":"combustion"},{"t":"Compelling","p":"(adj.)","d":"forceful, demanding attention","e":"Eliot’s speech was so compelling that Lenore accepted his proposal on the spot.","ev":"Bài phát biểu của Eliot thuyết phục đến nỗi Lenore đã chấp nhận lời đề nghị của anh ngay tại chỗ.","k":"compelling"},{"t":"Ecstatic","p":"(adj.)","d":"intensely and overpoweringly happy","e":"The couple was ecstatic when they learned that they had won the lottery.","ev":"Cặp đôi vui mừng khi biết mình trúng số độc đắc.","k":"ecstatic"},{"t":"Effectual","d":"successful in producing the intended results","e":"The medicine was effectual in treating the disease.","ev":"Thuốc đã có tác dụng điều trị bệnh.","k":"effectual"},{"t":"Retention","d":"n. the act of keeping something","e":"n. the act of keeping something","ev":"N. hành động giữ một cái gì đó","k":"retention"},{"t":"Amenable","p":"adjective","d":"willing, compliant","e":"He is amenable to new ideas and always open to suggestions.","ev":"Anh ấy dễ tiếp thu các ý tưởng mới và luôn sẵn sàng lắng nghe những gợi ý.","k":"amenable"},{"t":"Currency","d":"acceptance, approval (idea)","e":"The idea that computer use enhances students’ motivation has gained currency in recent years.","ev":"Ý tưởng cho rằng việc sử dụng máy tính giúp nâng cao động lực của học sinh đã trở nên phổ biến trong những năm gần đây.","k":"currency"},{"t":"Grievous","p":"(adj.)","d":"injurious, hurtful; serious or grave in nature","e":"Electrocuting the inmate without being sure of his guilt would be a truly grievous mistake.","ev":"Giật điện tù nhân mà không chắc chắn về tội lỗi của mình sẽ là một sai lầm thực sự nghiêm trọng.","k":"grievous"},{"t":"Tumult","d":"confusion or disorder","e":"The city was in a state of tumult after the riots, with widespread destruction and violence.","ev":"Thành phố rơi vào tình trạng hỗn loạn sau cuộc bạo loạn, với sự tàn phá và bạo lực lan rộng.","k":"tumult"},{"t":"Malicious","d":"intending to cause harm; evil","e":"His malicious intent was clear, as he deliberately tried to harm others.","ev":"Ý định xấu xa của anh ta rất rõ ràng, khi anh ta cố tình làm hại người khác.","k":"malicious"},{"t":"Enervate","p":"(v.)","d":"to weaken, exhaust","e":"Writing these sentences enervates me so much that I will have to take a nap after I finish.","ev":"Viết những dòng này khiến tôi mệt mỏi đến mức tôi sẽ phải chợp mắt một lát sau khi viết xong.","k":"enervate"},{"t":"Innuendo","p":"noun","d":"an insinuation","e":"His remarks were filled with innuendo, suggesting more than he actually said.","ev":"Những nhận xét của anh ấy đầy bóng gió, ám chỉ nhiều hơn những gì anh thực sự nói.","k":"innuendo"},{"t":"Edict","p":"(n.)","d":"an order, decree","e":"The ruler issued an edict requiring all of his subjects to bow down before him.","ev":"Người cai trị đã ban hành một sắc lệnh yêu cầu tất cả thần dân của mình phải cúi đầu trước anh ta.","k":"edict"},{"t":"Confluence","p":"noun","d":"a situation in which two things join or come together","e":"The confluence of different cultures enriched the community.","ev":"Sự giao thoa của các nền văn hóa khác nhau đã làm phong phú cộng đồng.","k":"confluence"},{"t":"Circumscribed","p":"(adj.)","d":"marked off, bounded","e":"The children were permitted to play tag only within a carefully circumscribed area of the lawn.","ev":"Trẻ em chỉ được phép chơi đuổi bắt trong khu vực được giới hạn cẩn thận trên bãi cỏ.","k":"circumscribed"},{"t":"Ambivalent","p":"adjective","d":"having mixed feeling","e":"My feelings about Calvin are ambivalent because he is a loyal friend, but also a cruel thief.","ev":"Cảm xúc của tôi về Calvin là mâu thuẫn vì anh ấy là một người bạn trung thành, nhưng cũng là một kẻ trộm độc ác.","k":"ambivalent"},{"t":"Discredit","d":"Disprove, unlikely to appear as a correct answer.","e":"The scandal discredited the politician.","ev":"Vụ bê bối đã làm mất uy tín của chính trị gia.","x":"Ví dụ 2: Weaken, disprove","k":"discredit"},{"t":"Blight","p":"(n.)","d":"a plague, disease","e":"The potato blight destroyed the harvest and bankrupted many families.","ev":"Bệnh bạc lá khoai tây đã phá hủy mùa màng và khiến nhiều gia đình phá sản.","x":"Nghĩa 2: something that destroys hope\nVí dụ 2: His bad morale is a blight upon this entire operation.","k":"blight"},{"t":"Raucous","p":"adjective","d":"loud, boisterous","e":"The raucous laughter from the party next door kept him awake all night.","ev":"Tiếng cười ồn ào từ bữa tiệc bên cạnh đã khiến anh không ngủ được suốt đêm.","k":"raucous"},{"t":"Implicate","p":"(v.)","d":"to involve in an incriminating way, incriminate","e":"Even though Tom wasn’t present at the time of the shooting, he was implicated by the evidence suggesting that he had supplied the shooters with guns.","ev":"Mặc dù Tom không có mặt vào thời điểm xảy ra vụ nổ súng, nhưng anh ta vẫn bị liên lụy bởi bằng chứng cho thấy anh ta đã cung cấp súng cho những kẻ xả súng.","k":"implicate"},{"t":"Cajole","p":"verb","d":"to urge, coax","e":"He tried to cajole his friend into going to the party by promising a free dinner.","ev":"Anh ấy đã cố gắng nịnh nọt bạn mình đi dự tiệc bằng cách hứa sẽ đãi bữa tối miễn phí.","k":"cajole"}]},{"n":"Chưa phân loại · 36","c":[{"t":"Sycophant","p":"noun","d":"one who flatters for self-gain","e":"The sycophant always flatters his boss to gain favor.","ev":"Kẻ nịnh hót luôn tâng bốc sếp của mình để chiếm được cảm tình.","k":"sycophant"},{"t":"Impecunious","p":"(adj.)","d":"poor","e":"“I fear he’s too impecunious to take me out tonight,” the bratty girl whined.","ev":"“Tôi sợ anh ấy quá thiếu tiền để đưa tôi đi chơi tối nay,” cô gái nhỏ nhắn rên rỉ.","k":"impecunious"},{"t":"Accolade","p":"noun","d":"high praise, special distinction","e":"Everyone offered accolades to Sam after he won the Nobel Prize.","ev":"Mọi người đã gửi lời khen ngợi đến Sam sau khi anh ấy giành giải Nobel.","k":"accolade"},{"t":"Concomitant","p":"adjective","d":"accompanying in a subordinate fashion","e":"His dislike of hard work carried with it a concomitant lack of funds.","ev":"Sự lười biếng của anh ấy dẫn đến việc thiếu tiền như một hệ quả.","k":"concomitant"},{"t":"Replete","p":"(adj.)","d":"full, abundant","e":"The unedited version was replete with naughty words.","ev":"Phiên bản chưa chỉnh sửa chứa đầy những từ ngữ nghịch ngợm.","k":"replete"},{"t":"Erudite","p":"(adj.)","d":"learned","e":"My Latin teacher is such an erudite scholar that he has translated some of the most difficult and abstruse ancient poetry.","ev":"Giáo viên tiếng Latinh của tôi là một học giả uyên bác đến mức ông đã dịch một số bài thơ cổ khó và sâu sắc nhất.","k":"erudite"},{"t":"Timorous","p":"(adj.)","d":"timid, fearful","e":"When dealing with the unknown, timorous Tallulah almost always broke into tears.","ev":"Khi đối mặt với những điều chưa biết, Tallulah nhút nhát hầu như luôn bật khóc.","k":"timorous"},{"t":"Dabble","d":"to try an activity in a casual way","e":"He dabbled in painting, trying it out as a hobby but not taking it too seriously.","ev":"Anh theo đuổi hội họa, thử vẽ như một sở thích nhưng không quá coi trọng nó.","k":"dabble"},{"t":"Brazen","p":"(adj.)","d":"excessively bold, brash","e":"Critics condemned the novelist’s brazen attempt to plagiarize Hemingway’s story.","ev":"Các nhà phê bình lên án nỗ lực trắng trợn của tiểu thuyết gia này nhằm đạo văn câu chuyện của Hemingway.","k":"brazen"},{"t":"Stupefy","p":"(v.)","d":"to astonish, make insensible","e":"Veronica’s audacity and ungratefulness stupefied her best friend, Heather.","ev":"Sự táo bạo và vô ơn của Veronica đã khiến người bạn thân nhất của cô, Heather, choáng váng.","k":"stupefy"},{"t":"Exasperate","p":"(v.)","d":"to irritate, irk","e":"George’s endless complaints exasperated his roomate.","ev":"Những lời phàn nàn bất tận của George khiến bạn cùng phòng của anh bực tức.","k":"exasperate"},{"t":"Enamor","p":"(v.)","d":"to fill with love, fascinate, usually used in passive form followed by “of” or “with”","e":"I grew enamored of that boy when he quoted my favorite love poem.","ev":"Tôi càng say mê chàng trai đó khi anh ấy trích dẫn bài thơ tình yêu thích của tôi.","k":"enamor"},{"t":"Sinuous","p":"(adj.)","d":"lithe, serpentine","e":"With the sinuous movements of her arms, the dancer mimicked the motion of a snake.","ev":"Với những chuyển động uốn lượn của cánh tay, vũ công bắt chước chuyển động của một con rắn.","k":"sinuous"},{"t":"Annihilate","d":"v. to destroy or cause devastating destruction","e":"v. to destroy or cause devastating destruction","ev":"v. phá hủy hoặc gây ra sự tàn phá nặng nề","k":"annihilate"},{"t":"Fluctuate","d":"to rise and fall irregularly","e":"The stock market fluctuated wildly throughout the day, causing many investors to lose money.","ev":"Thị trường chứng khoán biến động dữ dội suốt cả ngày khiến nhiều nhà đầu tư thua lỗ.","k":"fluctuate"},{"t":"Divine","p":"(adj.)","d":"godly, exceedingly wonderful","e":"Terribly fond of desserts, she found the rich chocolate cake to be divine.","ev":"Cực kỳ thích món tráng miệng, cô thấy chiếc bánh sô cô la béo ngậy thật thần thánh.","k":"divine"},{"t":"Credulity","p":"noun","d":"readiness to believe","e":"His credulity made him an easy target for con men.","ev":"Sự cả tin của anh khiến anh dễ trở thành mục tiêu của kẻ lừa đảo.","k":"credulity"},{"t":"Utilitarian","p":"(adj.)","d":"relating to or aiming at usefulness","e":"The beautiful, fragile vase couldn’t hold flowers or serve any other utilitarian purpose.","ev":"Chiếc bình đẹp đẽ, dễ vỡ không thể đựng hoa hay phục vụ bất kỳ mục đích thực dụng nào khác.","k":"utilitarian"},{"t":"Probity","p":"(n.)","d":"virtue, integrity","e":"Because he was never viewed as a man of great probity, no one was surprised by Mr. Samson’s immoral behavior.","ev":"Vì ông chưa bao giờ được coi là người có đạo đức cao nên không ai ngạc nhiên trước hành vi vô đạo đức của ông Samson.","k":"probity"},{"t":"Oblique","p":"(adj.)","d":"diverging from a straight line or course, nghiêng, quanh co","e":"Martin’s oblique language confused those who listened to him.","ev":"Ngôn ngữ xiên xẹo của Martin khiến những người nghe anh bối rối.","k":"oblique"},{"t":"Ruse","p":"(n.)","d":"a trick","e":"Oliver concocted an elaborate ruse for sneaking out of the house to meet his girlfriend while simultaneously giving his mother the impression that he was asleep in bed.","ev":"Oliver đã bày ra một mưu mẹo tinh vi để lẻn ra khỏi nhà để gặp bạn gái đồng thời khiến mẹ anh có ấn tượng rằng anh đang ngủ trên giường.","k":"ruse"},{"t":"Grandiloquence","p":"(n.)","d":"lofty, pompous language","e":"The student thought her grandiloquence would make her sound smart, but neither the class nor the teacher bought it.","ev":"Cô sinh viên nghĩ rằng tài hùng biện của cô sẽ khiến cô có vẻ thông minh, nhưng cả lớp và giáo viên đều không tin điều đó.","k":"grandiloquence"},{"t":"Tirade","p":"noun","d":"a long speech marked by harsh or biting language","e":"His tirade against the government lasted for over an hour.","ev":"Bài chỉ trích chính phủ của anh kéo dài hơn một giờ.","k":"tirade"},{"t":"Blandish","p":"(v.)","d":"to coax by using flattery","e":"Rachel’s assistant tried to blandish her into accepting the deal.","ev":"Trợ lý của Rachel cố thuyết phục cô chấp nhận thỏa thuận.","k":"blandish"},{"t":"Inevitable","d":"unavoidable","e":"It was inevitable that the old building would eventually collapse, as its foundation was crumbling and it could no longer support its weight.","ev":"Việc tòa nhà cũ cuối cùng sẽ sụp đổ là điều không thể tránh khỏi vì nền móng của nó đã sụp đổ và nó không còn có thể chịu được sức nặng của mình nữa.","k":"inevitable"}]},{"n":"Chưa phân loại · 37","c":[{"t":"Eschew","p":"(v.)","d":"to shun, avoid","e":"George hates the color green so much that he eschews all green food.","ev":"George ghét màu xanh lá cây đến mức anh ấy tránh tất cả các loại thực phẩm có màu xanh lá cây.","k":"eschew"},{"t":"Genial","p":"adjective","d":"friendly, affable","e":"His genial smile made everyone feel welcome at the party.","ev":"Nụ cười thân thiện của anh khiến mọi người cảm thấy được chào đón tại bữa tiệc.","k":"genial"},{"t":"Mores","p":"(n.)","d":"the moral attitudes and fixed customs of a group of people.","e":"Mores change over time; many things that were tolerated in 1975 are no longer seen as being socially acceptable.","ev":"Mores thay đổi theo thời gian; nhiều điều được dung thứ vào năm 1975 không còn được xã hội chấp nhận nữa.","k":"mores"},{"t":"Limpid","p":"(adj.)","d":"clear, transparent","e":"Mr. Johnson’s limpid writing style greatly pleased readers who disliked complicated novels.","ev":"Phong cách viết trong trẻo của ông Johnson làm hài lòng rất nhiều độc giả không thích những cuốn tiểu thuyết phức tạp.","k":"limpid"},{"t":"Sufficient","d":"adj. enough; just meeting a requirement","e":"adj. enough; just meeting a requirement","ev":"tính từ đủ; chỉ cần đáp ứng một yêu cầu","k":"sufficient"},{"t":"Compliment","p":"(n.)","d":"an expression of esteem or approval","e":"I blushed crimson when Emma gave me a compliment on my new haircut.","ev":"Tôi đỏ mặt khi Emma khen kiểu tóc mới của tôi.","k":"compliment"},{"t":"Expurgate","p":"(v.)","d":"to remove offensive or incorrect parts, usually of a book","e":"The history editors expurgated from the text all disparaging and inflammatory comments about the Republican Party.","ev":"Các biên tập viên lịch sử đã loại bỏ khỏi văn bản tất cả những bình luận chê bai và kích động về Đảng Cộng hòa.","k":"expurgate"},{"t":"Covert","p":"adjective","d":"secretly engaged in","e":"Nerwin waged a covert campaign against his enemies, while outwardly appearing to remain friendly.","ev":"Nerwin đã thực hiện một chiến dịch bí mật chống lại kẻ thù.","k":"covert"},{"t":"Conceive","d":"to form or create a plan or idea","e":"She conceived of a new business idea, imagining a product that would revolutionize the industry.","ev":"Cô hình thành một ý tưởng kinh doanh mới, hình dung ra một sản phẩm có thể cách mạng hóa ngành công nghiệp này.","k":"conceive"},{"t":"Amiable","p":"adjective","d":"friendly","e":"She has an amiable personality, making her easy to get along with.","ev":"Cô ấy có tính cách thân thiện, khiến mọi người dễ dàng hòa hợp với cô.","k":"amiable"},{"t":"Complacent","d":"overly satisfied or pleased with oneself","e":"She was complacent with her job, satisfied with her current situation and not seeking change.","ev":"Cô tự mãn với công việc của mình, hài lòng với tình hình hiện tại và không tìm kiếm sự thay đổi.","k":"complacent"},{"t":"Caucus","p":"(n.)","d":"a meeting usually held by people working toward the same goal","e":"The ironworkers held a caucus to determine how much of a pay increase they would request.","ev":"Những người thợ sắt đã tổ chức một cuộc họp kín để xác định xem họ sẽ yêu cầu tăng lương bao nhiêu.","k":"caucus"},{"t":"Irascible","p":"(adj.)","d":"easily angered","e":"At the smallest provocation, my irascible cat will begin scratching and clawing.","ev":"Khi bị khiêu khích dù là nhỏ nhất, con mèo nóng nảy của tôi sẽ bắt đầu cào và cào.","k":"irascible"},{"t":"Indolent","p":"adjective","d":"lazy","e":"His indolent attitude towards work led to poor performance.","ev":"Thái độ lười biếng của anh đối với công việc đã dẫn đến hiệu suất kém.","k":"indolent"},{"t":"Cleave","p":"(v.)","d":"to divide into parts","e":"Following the scandalous disgrace of their leader, the entire political party cleaved into warring factions.","ev":"Sau sự ô nhục đầy tai tiếng của người lãnh đạo của họ, toàn bộ đảng chính trị đã chia rẽ thành các phe phái tham chiến.","x":"Nghĩa 2: to stick together firmly\nVí dụ 2: After resolving their marital problems, Junior and Rosa cleaved to one another all the more tightly.","k":"cleave"},{"t":"Dispel","p":"verb","d":"to drive away, scatter","e":"She hoped to dispel the rumors by providing clear evidence.","ev":"Cô hy vọng có thể làm tan biến những tin đồn bằng cách cung cấp bằng chứng rõ ràng.","k":"dispel"},{"t":"Confer","d":"give, grant","e":"moves were made to confer an honorary degree on her","ev":"những động thái đã được thực hiện để trao bằng danh dự cho cô ấy","x":"Nghĩa 2: Exchange ideas\nVí dụ 2: The two leaders conferred about the crisis.","k":"confer"},{"t":"Feral","p":"(adj.)","d":"wild, savage","e":"That beast looks so feral that I would fear being alone with it.","ev":"Con thú đó trông hoang dã đến mức tôi sợ phải ở một mình với nó.","k":"feral"},{"t":"Noisome","p":"(adj.)","d":"unpleasant, offensive, especially to the sense of smell","e":"Nobody would enter the stalls until the horse’s noisome leavings were taken away.","ev":"Không ai được vào chuồng cho đến khi những thứ ồn ào của con ngựa được dọn đi.","k":"noisome"},{"t":"Penitent","p":"(adj.)","d":"remorseful, regretful","e":"The jury’s verdict may have been more lenient if the criminal had appeared penitent for his gruesome crimes.","ev":"Phán quyết của bồi thẩm đoàn có thể sẽ khoan dung hơn nếu tên tội phạm tỏ ra sám hối vì những tội ác khủng khiếp của mình.","k":"penitent"},{"t":"Sheer","d":"1) not mixed with anything else; pure or complete 2) very large","e":"The sheer cliffs were almost vertical.","ev":"Những vách đá dựng đứng gần như thẳng đứng.","k":"sheer"},{"t":"Annul","p":"verb","d":"to make void or invalid","e":"Congress sought to annul the law after its catastrophic effects became evident.","ev":"Quốc hội đã tìm cách hủy bỏ luật này sau khi các tác động thảm khốc của nó trở nên rõ ràng.","k":"annul"},{"t":"Timid","d":"easily frightened; shy","e":"She was timid and shy, afraid to speak in public.","ev":"Cô là người rụt rè, nhút nhát, ngại nói trước đám đông.","k":"timid"},{"t":"Buffet","p":"(v.)","d":"to strike with force","e":"The strong winds buffeted the ships, threatening to capsize them.","ev":"Những cơn gió mạnh đập vào các con tàu, có nguy cơ lật úp chúng.","x":"Loại từ 2: (n.)\nNghĩa 2: an arrangement of food set out on a table\nVí dụ 2: Rather than sitting around a table, the guests took food from our buffet and ate standing up.","k":"buffet"},{"t":"Wayward","p":"adj","d":"difficult to control or predict because of unusual behavior","e":"The wayward child often disobeyed his parents’ rules.","ev":"Đứa trẻ bướng bỉnh thường không tuân theo các quy tắc của cha mẹ.","k":"wayward"}]},{"n":"Chưa phân loại · 38","c":[{"t":"Optimistic","d":"hopeful and confident about the future","e":"Despite the challenges, she remained optimistic about the future, believing that things would eventually get better.","ev":"Bất chấp những thách thức, cô vẫn lạc quan về tương lai, tin rằng mọi thứ cuối cùng sẽ tốt hơn.","k":"optimistic"},{"t":"Interminable","p":"(adj.)","d":"without possibility of end","e":"The fact that biology lectures came just before lunch made them seem interminable.","ev":"Việc các bài giảng sinh học diễn ra ngay trước bữa trưa khiến chúng dường như kéo dài vô tận.","k":"interminable"},{"t":"Stronghold","d":"a place that is strongly defended, a fortress","e":"The castle was a stronghold of the enemy, a fortified position that was difficult to conquer.","ev":"Lâu đài là thành trì của kẻ thù, một vị trí kiên cố khó chinh phục.","k":"stronghold"},{"t":"Cunning","p":"adjective","d":"sly, clever at being deceitful","e":"The general devised a cunning plan to surprise the enemy.","ev":"Tướng đã nghĩ ra một kế hoạch xảo quyệt để bất ngờ kẻ thù.","k":"cunning"},{"t":"Vindictive","p":"adj","d":"vengeful","e":"His vindictive nature made it hard to trust him.","ev":"Bản chất trả thù của anh ta khiến việc tin tưởng khó khăn.","k":"vindictive"},{"t":"Integral","p":"(adj.)","d":"necessary for completeness","e":"Without the integral ingredient of flour, you wouldn’t be able to make bread.","ev":"Nếu không có thành phần không thể thiếu là bột mì thì bạn sẽ không thể làm được bánh mì.","k":"integral"},{"t":"Conduit","p":"noun","d":"a pipe or channel through which something passes","e":"The water flowed through the conduit into the container.","ev":"Nước chảy qua ống dẫn vào một khu vực khác.","k":"conduit"},{"t":"Readily","d":"adv. right away and without difficulty","e":"He readily agreed to help.","ev":"Anh ấy sẵn sàng đồng ý giúp đỡ.","k":"readily"},{"t":"Revere","p":"(v.)","d":"to esteem, show deference, venerate","e":"The doctor saved countless lives with his combination of expertise and kindness and became universally revered.","ev":"Vị bác sĩ đã cứu sống vô số người bằng sự kết hợp giữa chuyên môn và lòng tốt của mình và được mọi người tôn kính.","k":"revere"},{"t":"Galvanizing","d":"adj. thrilling, exciting, stimulating","e":"adj. thrilling, exciting, stimulating","ev":"tính từ hồi hộp, sôi động, kích thích","k":"galvanizing"},{"t":"Amenity","p":"noun","d":"an item that increases comfort","e":"Bill Gates’s house is stocked with so many amenities, he never has to do anything for himself.","ev":"Nhà của Bill Gates có rất nhiều tiện nghi, ông không bao giờ phải làm gì cho chính mình.","k":"amenity"},{"t":"Defile","p":"(v.)","d":"to make unclean, impure","e":"She defiled the calm of the religious building by playing her banjo.","ev":"Cô ấy đã làm ô uế sự yên tĩnh của tòa nhà tôn giáo bằng cách chơi đàn banjo của mình.","k":"defile"},{"t":"Dialect","p":"(n.)","d":"a variation of a language","e":"In the country’s remote, mountainous regions, the inhabitants spoke a dialect that the country’s other inhabitants had difficulty understanding.","ev":"Ở những vùng miền núi xa xôi của đất nước, người dân nói một phương ngữ mà những cư dân khác của đất nước khó hiểu.","k":"dialect"},{"t":"Avenge","p":"verb","d":"to seek revenge","e":"The victims strive to avenge themselves against their robbers.","ev":"Các nạn nhân cố gắng báo thù những kẻ cướp của mình.","k":"avenge"},{"t":"Remiss","p":"(adj.)","d":"negligent, failing to take care","e":"The burglar gained entrance because the security guard, remiss in his duties, forgot to lock the door.","ev":"Tên trộm vào được vì nhân viên bảo vệ lơ là nhiệm vụ của mình, quên khóa cửa.","k":"remiss"},{"t":"Detrimental","d":"harmful, damaging","e":"Smoking is detrimental to your health, increasing the risk of lung cancer, heart disease, and other serious illnesses.","ev":"Hút thuốc có hại cho sức khỏe của bạn, làm tăng nguy cơ ung thư phổi, bệnh tim và các bệnh nghiêm trọng khác.","k":"detrimental"},{"t":"Contrite","p":"adjective","d":"penitent, eager to be forgiven","e":"Blake’s contrite behavior made it impossible to stay angry at him.","ev":"Hành động ăn năn của anh khiến mọi người dễ dàng tha thứ cho anh.","k":"contrite"},{"t":"Incorrigible","p":"(adj.)","d":"incapable of correction, delinquent","e":"You can buy Grandma nicotine gum all you want, but I think that after sixty-five years of smoking she’s incorrigible.","ev":"Bạn có thể mua kẹo cao su nicotin của bà bao nhiêu tùy thích, nhưng tôi nghĩ rằng sau sáu mươi lăm năm hút thuốc, bà không thể sửa chữa được.","k":"incorrigible"},{"t":"Incessant","p":"(adj.)","d":"unending","e":"We wanted to go outside and play, but the incessant rain kept us indoors for two days.","ev":"Chúng tôi muốn ra ngoài chơi nhưng trời mưa dai dẳng nên chúng tôi phải ở trong nhà suốt hai ngày.","k":"incessant"},{"t":"Plaudit","d":"praise or applause","e":"She received a plaudit for her performance.","ev":"Cô đã nhận được lời khen ngợi cho màn trình diễn của mình.","k":"plaudit"},{"t":"Encumber","p":"(v.)","d":"to weigh down, burden","e":"At the airport, my friend was encumbered by her luggage, so I offered to carry two of her bags.","ev":"Đến sân bay, bạn tôi bị vướng hành lý nên tôi đề nghị xách hộ cho cô ấy hai túi xách.","k":"encumber"},{"t":"Precedent","d":"n. an example or subject from earlier in time","e":"n. an example or subject from earlier in time","ev":"N. một ví dụ hoặc chủ đề từ trước đó trong thời gian","k":"precedent"},{"t":"Salve","p":"(n.)","d":"a soothing balm","e":"After Tony applied a salve to his brilliant red sunburn, he soon felt a little better.","ev":"Sau khi Tony bôi thuốc lên vết cháy nắng đỏ rực của mình, anh ấy nhanh chóng cảm thấy dễ chịu hơn một chút.","k":"salve"},{"t":"Repentant","p":"(adj.)","d":"penitent, sorry","e":"The repentant Dennis apologized profusely for breaking his mother’s vase.","ev":"Dennis ăn năn xin lỗi rối rít vì đã làm vỡ chiếc bình của mẹ mình.","k":"repentant"},{"t":"Tyranny","d":"cruel and abusive government or rule","e":"The people revolted against the tyranny of the dictator, demanding freedom and democracy.","ev":"Nhân dân nổi dậy chống lại sự bạo ngược của kẻ độc tài, đòi tự do và dân chủ.","k":"tyranny"}]},{"n":"Chưa phân loại · 39","c":[{"t":"Infusion","p":"(n.)","d":"an injection of one substance into another; the permeation of one substance by another","e":"The infusion of Eastern religion into Western philosophy created interesting new schools of thought.","ev":"Sự truyền bá tôn giáo phương Đông vào triết học phương Tây đã tạo ra những trường phái tư tưởng mới thú vị.","k":"infusion"},{"t":"Gregarious","p":"(adj.)","d":"drawn to the company of others, sociable","e":"Well, if you’re not gregarious, I don’t know why you would want to go to a singles party!","ev":"Chà, nếu bạn không thích giao du, tôi không biết tại sao bạn lại muốn đi dự một bữa tiệc độc thân!","k":"gregarious"},{"t":"Sporadic","p":"adj","d":"scattered, irregular, unpredictable","e":"The rain was sporadic throughout the day.","ev":"Cơn mưa xảy ra rải rác suốt cả ngày.","k":"sporadic"},{"t":"Reputable","p":"(adj.)","d":"of good reputation","e":"After the most reputable critic in the industry gave the novel a glowing review, sales took off.","ev":"Sau khi nhà phê bình có uy tín nhất trong ngành đánh giá cuốn tiểu thuyết một cách rực rỡ, doanh số bán hàng đã tăng vọt.","k":"reputable"},{"t":"Altercation","p":"noun","d":"a dispute, fight","e":"Jason and Lionel blamed one another for the car accident, leading to an altercation.","ev":"Jason và Lionel đã đổ lỗi cho nhau về vụ tai nạn xe hơi, dẫn đến một cuộc tranh cãi.","k":"altercation"},{"t":"Quarrel","d":"an angry argument or disagreement","e":"They quarreled over the division of the inheritance, arguing heatedly about who should receive the most money.","ev":"Họ cãi nhau về việc phân chia tài sản thừa kế, tranh cãi nảy lửa xem ai sẽ nhận được nhiều tiền nhất.","k":"quarrel"},{"t":"Obsolete","p":"(adj.)","d":"no longer used, out of date","e":"With the inventions of tape decks and CDs, which both have better sound and are easier to use, eight-track players are now entirely obsolete.","ev":"Với những phát minh về băng từ và đĩa CD, cả hai đều có âm thanh tốt hơn và dễ sử dụng hơn, máy nghe nhạc 8 rãnh giờ đây đã hoàn toàn lỗi thời.","k":"obsolete"},{"t":"Nascent","p":"(adj.)","d":"in the process of being born or coming into existence","e":"Unfortunately, my brilliant paper was only in its nascent form on the morning that it was due.","ev":"Thật không may, bài báo tuyệt vời của tôi chỉ mới ở dạng non trẻ vào buổi sáng mà nó đến hạn.","k":"nascent"},{"t":"Ascetic","p":"adjective","d":"practicing restraint as a means of self-discipline, usually religious","e":"The ascetic monk lived a life devoid of worldly pleasures.","ev":"Thầy tu khổ hạnh sống một cuộc đời không có những thú vui trần thế.","k":"ascetic"},{"t":"Petulant","p":"adjective","d":"adj. cranky, pouty, irritable","e":"The petulant child threw a tantrum when he didn’t get his way.","ev":"Đứa trẻ cáu kỉnh đã ăn vạ khi không được như ý muốn.","k":"petulant"},{"t":"Sentinel","d":"a guard whose job is to stand and keep watch","e":"The guard stood sentinel at the gate, watching for intruders.","ev":"Người bảo vệ đứng canh gác ở cổng, canh chừng những kẻ đột nhập.","k":"sentinel"},{"t":"Metamorphose","p":"(v.)","d":"to change into a completely different form or type","e":"The awkward boy I knew had metamorphosed into a tall, confident man.","ev":"Cậu bé vụng về mà tôi biết đã biến thành một người đàn ông cao lớn, tự tin.","k":"metamorphose"},{"t":"Alacrity","p":"noun","d":"eagerness, speed","e":"She accepted the challenge with alacrity, eager to prove herself.","ev":"Cô chấp nhận thử thách một cách nhanh chóng, háo hức để chứng tỏ bản thân.","k":"alacrity"},{"t":"Reform","d":"to make changes in something in order to improve it","e":"The government implemented economic reforms.","ev":"Chính phủ thực hiện cải cách kinh tế.","k":"reform"},{"t":"Diffuse","p":"adj","d":"to scatter, thin out, break up","e":"The light from the lamp began to diffuse throughout the room.","ev":"Ánh sáng từ đèn bắt đầu lan tỏa khắp phòng.","k":"diffuse"},{"t":"Brusque","p":"(adj.)","d":"short, abrupt, dismissive","e":"The captain’s brusque manner offended the passengers.","ev":"Thái độ cộc cằn của cơ trưởng đã xúc phạm hành khách.","k":"brusque"},{"t":"Ribald","p":"(adj.)","d":"coarsely, crudely humorous","e":"While some giggled at the ribald joke involving a parson’s daughter, most sighed and rolled their eyes.","ev":"Trong khi một số cười khúc khích trước trò đùa tục tĩu liên quan đến con gái của một mục sư, thì hầu hết đều thở dài và đảo mắt.","k":"ribald"},{"t":"Implement","p":"(n.)","d":"an instrument, utensil, tool","e":"Do you have a knife or some other sort of implement that I could use to pry the lid off of this jar?","ev":"Bạn có dao hoặc dụng cụ nào khác mà tôi có thể dùng để cạy nắp lọ này không?","x":"Loại từ 2: (v.)\nNghĩa 2: to put into effect, to institute\nVí dụ 2: After the first town curfew failed to stop the graffiti problem, the mayor implemented a new policy to use security cameras to catch perpetrators in the act.","k":"implement"},{"t":"Disavow","p":"(v.)","d":"to deny knowledge of or responsibility for","e":"Not wanting others to criticize her, she disavowed any involvement in the company’s hiring scandal.","ev":"Không muốn người khác chỉ trích mình, cô phủ nhận mọi liên quan đến vụ bê bối tuyển dụng của công ty.","k":"disavow"},{"t":"Ramify","d":"v. to split into two or more branches","e":"v. to split into two or more branches","ev":"v. chia thành hai hoặc nhiều nhánh","k":"ramify"},{"t":"Distend","p":"(v.)","d":"to swell out","e":"Years of drinking beer caused his stomach to distend.","ev":"Nhiều năm uống bia khiến bụng ông chướng lên.","k":"distend"},{"t":"Salutation","p":"(n.)","d":"a greeting","e":"Andrew regularly began letters with the bizarre salutation “Ahoy ahoy.”","ev":"Andrew thường xuyên bắt đầu các bức thư bằng lời chào kỳ quái “Ahoy ahoy.”","k":"salutation"},{"t":"Nocturnal","p":"(adj.)","d":"relating to or occurring during the night","e":"Jackie was a nocturnal person; she would study until dawn and sleep until the evening.","ev":"Jackie là người sống về đêm; cô ấy sẽ học đến sáng và ngủ đến tối.","k":"nocturnal"},{"t":"Nondescript","p":"(adj.)","d":"lacking a distinctive character","e":"I was surprised when I saw the movie star in person because she looked nondescript.","ev":"Tôi đã rất ngạc nhiên khi tận mắt nhìn thấy ngôi sao điện ảnh này vì cô ấy trông không có gì nổi bật.","k":"nondescript"},{"t":"Renovate","p":"(v.)","d":"restore, return to original state","e":"The renovated antique candelabra looked as good as new.","ev":"Chiếc chân nến cổ đã được tân trang lại trông vẫn đẹp như mới.","x":"Nghĩa 2: to enlarge and make prettier, especially a house\nVí dụ 2: After getting renovated, the house was twice as big and much more attractive.","k":"renovate"}]},{"n":"Chưa phân loại · 40","c":[{"t":"Cumulative","p":"adjective","d":"increasing, building upon itself","e":"The cumulative effect of hours spent in the sun was a deep tan.","ev":"Tác động dồn lại của việc ở dưới nắng nhiều giờ là làn da rám nắng.","k":"cumulative"},{"t":"Veracity","p":"(n.)","d":"truthfulness, accuracy","e":"With several agencies regulating the reports, it was difficult for Latifah to argue against its veracity.","ev":"Với một số cơ quan quản lý các báo cáo, Latifah khó có thể phản đối tính xác thực của nó.","k":"veracity"},{"t":"Consummate","p":"verb","d":"to complete a deal; to be perfect, to complete a marriage ceremony through sexual intercourse","e":"Erica and Donald consummated their agreement in the executive boardroom.","ev":"Họ đã hoàn tất thỏa thuận của mình trong một không gian riêng tư.","k":"consummate"},{"t":"Intact","d":"complete and in the original state; not damaged","e":"The vase was still intact, despite the fall.","ev":"Chiếc bình vẫn còn nguyên vẹn dù đã bị rơi.","k":"intact"},{"t":"Kudos","p":"(n.)","d":"praise for an achievement","e":"After the performance, the reviewers gave the opera singer kudos for a job well done.","ev":"Sau màn trình diễn, những người đánh giá đã khen ngợi ca sĩ opera vì đã hoàn thành tốt công việc.","k":"kudos"},{"t":"Stolid","p":"(adj.)","d":"expressing little sensibility, unemotional","e":"Charles’s stolid reaction to his wife’s funeral differed from the passion he showed at the time of her death.","ev":"Phản ứng lạnh lùng của Charles trước đám tang của vợ mình khác với niềm đam mê mà anh thể hiện vào thời điểm cô qua đời.","k":"stolid"},{"t":"Surrogate","p":"(n.)","d":"one acting in place of another","e":"The surrogate carried the child to term for its biological parents.","ev":"Người đại diện đã bế đứa trẻ đến gặp cha mẹ ruột của nó.","k":"surrogate"},{"t":"Carp","p":"(v.)","d":"to annoy, pester","e":"The husband divorced his wife after listening to her carping voice for decades.","ev":"Người chồng ly dị vợ sau hàng chục năm nghe giọng chửi bới của vợ.","k":"carp"},{"t":"Maelstrom","p":"(n.)","d":"a destructive whirlpool which rapidly sucks in objects","e":"Little did the explorers know that as they turned the next bend of the calm river a vicious maelstrom would catch their boat.","ev":"Các nhà thám hiểm không hề biết rằng khi họ rẽ sang khúc cua tiếp theo của con sông êm đềm, một cơn lốc dữ dội sẽ cuốn lấy thuyền của họ.","k":"maelstrom"},{"t":"Monotony","d":"boredom, dullness, lack of variety","e":"The monotony of his daily routine made him feel bored and unfulfilled, longing for excitement and variety.","ev":"Sự đơn điệu của thói quen hàng ngày khiến anh cảm thấy buồn chán và không thỏa mãn, khao khát sự phấn khích và đa dạng.","k":"monotony"},{"t":"Carouse","p":"(v.)","d":"to party, celebrate","e":"We caroused all night after getting married.","ev":"Chúng tôi say sưa suốt đêm sau khi kết hôn.","k":"carouse"},{"t":"Enact","d":"to make law, to put into practice (a belief, idea, or suggestion)","e":"The government enacted a new law to address the problem, hoping to improve the situation.","ev":"Chính phủ đã ban hành một đạo luật mới để giải quyết vấn đề này với hy vọng cải thiện được tình hình.","k":"enact"},{"t":"Bane","p":"noun","d":"a burden","e":"Advanced physics is the bane of many students’ lives.","ev":"Vật lý nâng cao là gánh nặng của nhiều sinh viên.","k":"bane"},{"t":"Disgruntled","p":"(adj.)","d":"upset, not content","e":"The child believed that his parents had unjustly grounded him, and remained disgruntled for a week.","ev":"Đứa trẻ tin rằng cha mẹ đã trừng phạt mình một cách oan uổng và bất bình suốt một tuần.","k":"disgruntled"},{"t":"Fetter","p":"(v.)","d":"to chain, restrain","e":"The dog was fettered to the parking meter.","ev":"Con chó bị xích vào đồng hồ đỗ xe.","k":"fetter"},{"t":"Versatility","d":"ability to adapt to many different functions or activities","e":"Her versatility allowed her to adapt to different situations and challenges.","ev":"Tính linh hoạt của cô cho phép cô thích ứng với các tình huống và thử thách khác nhau.","k":"versatility"},{"t":"Objectivity","d":"n. judgment based on observations instead of emotions or opinions","e":"n. judgment based on observations instead of emotions or opinions","ev":"N. phán đoán dựa trên quan sát thay vì cảm xúc hoặc ý kiến","k":"objectivity"},{"t":"Pacific","p":"(adj.)","d":"soothing","e":"The chemistry professor’s pacific demeanor helped the class remain calm after the experiment exploded.","ev":"Phong thái hòa bình của giáo sư hóa học đã giúp cả lớp giữ bình tĩnh sau khi thí nghiệm bùng nổ.","k":"pacific"},{"t":"Dilemma","d":"a situation in which a difficult choice has to be made between 2 or more alternatives","e":"He was faced with a difficult dilemma, having to choose between two undesirable options.","ev":"Anh phải đối mặt với một tình thế tiến thoái lưỡng nan, phải lựa chọn giữa hai phương án không mong muốn.","k":"dilemma"},{"t":"Paragon","p":"(n.)","d":"a model of excellence or perfection","e":"The mythical Helen of Troy was considered a paragon of female beauty.","ev":"Helen huyền thoại của thành Troy được coi là hình mẫu về vẻ đẹp phụ nữ.","k":"paragon"},{"t":"Want (For)","d":"lack","e":"The community was in want for basic supplies after the disaster struck.","ev":"Cộng đồng đang cần nguồn cung cấp cơ bản sau khi thảm họa xảy ra.","k":"want (for)"},{"t":"Temperance","p":"(n.)","d":"moderation in action or thought","e":"Maintaining temperance will ensure that you are able to think rationally and objectively.","ev":"Duy trì sự điều độ sẽ đảm bảo rằng bạn có thể suy nghĩ hợp lý và khách quan.","k":"temperance"},{"t":"Entail","p":"(v.)","d":"to include as a necessary step","e":"Building a new fence entails tearing down the old one.","ev":"Xây dựng một hàng rào mới đòi hỏi phải phá bỏ cái cũ.","k":"entail"},{"t":"Furtive","p":"adj","d":"secretive, sly","e":"She cast a furtive glance at the document.","ev":"Cô ấy liếc nhìn một cách vụng trộm vào tài liệu.","k":"furtive"},{"t":"Surmount","d":"v. to get on top of or overcome","e":"v. to get on top of or overcome","ev":"v. vượt lên trên hoặc vượt qua","k":"surmount"}]},{"n":"Chưa phân loại · 41","c":[{"t":"Decrepit","d":"1) weak, disabled 2) in a run-down state, decayed","e":"The old house was decrepit and in need of repair, with peeling paint, broken windows, and a crumbling roof.","ev":"Ngôi nhà cũ đã xuống cấp và cần được sửa chữa, lớp sơn bong tróc, cửa sổ vỡ và mái nhà xiêu vẹo.","k":"decrepit"},{"t":"Notion","d":"a belief or idea","e":"He had a vague notion of what he wanted to do, but he wasn't sure of the details.","ev":"Anh ấy có một khái niệm mơ hồ về những gì anh ấy muốn làm, nhưng anh ấy không chắc chắn về chi tiết.","k":"notion"},{"t":"Abase","p":"verb","d":"to humiliate, degrade","e":"After being overthrown and abased, the deposed leader bowed down to his conqueror.","ev":"Sau khi bị lật đổ và bị hạ thấp, nhà lãnh đạo bị truất quyền đã quỳ xuống trước kẻ chinh phục.","k":"abase"},{"t":"Commensurate","p":"(adj.)","d":"corresponding in size or amount","e":"Ahab selected a very long roll and proceeded to prepare a tuna salad sandwich commensurate with his enormous appetite.","ev":"A-háp chọn một ổ bánh mì thật dài và bắt đầu chuẩn bị món bánh kẹp salad cá ngừ tương xứng với khẩu vị khổng lồ của mình.","k":"commensurate"},{"t":"Aspersion","p":"noun","d":"a curse, expression of ill-will","e":"The politicians cast aspersions on each other's character.","ev":"Các chính trị gia đã chỉ trích lẫn nhau về phẩm chất.","k":"aspersion"},{"t":"Commendation","p":"(n.)","d":"a notice of approval or recognition","e":"Jared received a commendation from Linda, his supervisor, for his stellar performance.","ev":"Jared đã nhận được lời khen ngợi từ Linda, người giám sát của anh ấy vì thành tích xuất sắc của anh ấy.","k":"commendation"},{"t":"Convoke","d":"to summon, to call together","e":"The president convoked a meeting of the cabinet to discuss the crisis.","ev":"Tổng thống triệu tập một cuộc họp nội các để thảo luận về cuộc khủng hoảng.","k":"convoke"},{"t":"Consign","p":"verb","d":"to give something over to another’s care","e":"Unwillingly, he consigned his mother to a nursing home.","ev":"Anh đã phải gửi mẹ vào trại dưỡng lão.","k":"consign"},{"t":"Demagogue","p":"(n.)","d":"a leader who appeals to a people’s prejudices","e":"The demagogue strengthened his hold over his people by blaming immigrants for the lack of jobs.","ev":"Nhà mị dân đã củng cố quyền lực của mình đối với người dân của mình bằng cách đổ lỗi cho người nhập cư về tình trạng thiếu việc làm.","k":"demagogue"},{"t":"Suffrage","d":"the right to vote","e":"Women's suffrage was a major milestone in the fight for equality, granting women the right to vote and participate in the political process.","ev":"Quyền bầu cử của phụ nữ là một cột mốc quan trọng trong cuộc đấu tranh vì bình đẳng, trao cho phụ nữ quyền bầu cử và tham gia vào tiến trình chính trị.","k":"suffrage"},{"t":"Inquisitor","p":"(n.)","d":"one who inquires, especially in a hostile manner","e":"The inquisitor was instructed to knock on every door in town in order to find the fugitive.","ev":"Người điều tra được chỉ thị gõ cửa từng nhà trong thị trấn để tìm ra kẻ chạy trốn.","k":"inquisitor"},{"t":"Trifling","p":"adj","d":"unimportant, insignificant","e":"He dismissed the issue as trifling and not worth his time.","ev":"Anh coi thường vấn đề là không đáng kể và không xứng đáng với thời gian của mình.","k":"trifling"},{"t":"Ornate","p":"(adj.)","d":"highly elaborate, excessively decorated","e":"The ornate styling of the new model of luxury car could not compensate for the poor quality of its motor.","ev":"Kiểu dáng trang trí công phu của mẫu xe sang mới không thể bù đắp cho chất lượng kém của động cơ.","k":"ornate"},{"t":"Harrowing","p":"(adj.)","d":"greatly distressing, vexing","e":"The car crash was a harrowing experience, but I have a feeling that the increase in my insurance premiums will be even more upsetting.","ev":"Vụ tai nạn ô tô là một trải nghiệm đau buồn, nhưng tôi có cảm giác rằng việc tăng phí bảo hiểm của tôi sẽ còn khó chịu hơn nữa.","k":"harrowing"},{"t":"Mediation","d":"the process by which someone tries to end a disagreement by helping the two sides to talk about and agree on a solution","e":"The mediator helped the two parties reach a settlement through mediation.","ev":"Hòa giải viên đã giúp hai bên đạt được giải pháp thông qua hòa giải.","k":"mediation"},{"t":"Munificence","p":"(n.)","d":"generosity in giving","e":"The royal family’s munificence made everyone else in their country rich.","ev":"Sự hào phóng của gia đình hoàng gia đã khiến mọi người khác ở đất nước họ trở nên giàu có.","k":"munificence"},{"t":"Proscribe","p":"(v.)","d":"to condemn, outlaw","e":"The town council voted to proscribe the sale of alcohol on weekends.","ev":"Hội đồng thị trấn đã bỏ phiếu cấm bán rượu vào cuối tuần.","k":"proscribe"},{"t":"Conciliatory","p":"(adj.)","d":"friendly, agreeable","e":"I took Amanda’s invitation to dinner as a very conciliatory gesture.","ev":"Tôi coi lời mời đi ăn tối của Amanda như một cử chỉ mang tính hòa giải.","k":"conciliatory"},{"t":"Dissemble","p":"(v.)","d":"to conceal, fake","e":"Not wanting to appear heartlessly greedy, she dissembled and hid her intention to sell her ailing father’s stamp collection.","ev":"Không muốn tỏ ra tham lam nhẫn tâm, cô đã nói dối và giấu ý định bán bộ sưu tập tem của người cha ốm yếu.","k":"dissemble"},{"t":"Acerbic","p":"adjective","d":"biting, bitter in tone or taste","e":"Jill’s acerbic comments hurt her friends' feelings.","ev":"Những nhận xét châm chọc của Jill đã làm tổn thương cảm xúc của bạn bè.","k":"acerbic"},{"t":"Labyrinthine","d":"complicated or confusing","e":"The old city was a labyrinthine maze of narrow streets, making it difficult to navigate and easy to get lost.","ev":"Thành phố cổ là một mê cung mê cung với những con đường chật hẹp, khiến việc di chuyển trở nên khó khăn và dễ bị lạc.","k":"labyrinthine"},{"t":"Premise","d":"an idea or theory on which a statement or action is based; an assumption","e":"The premise of the story was unrealistic and unbelievable.","ev":"Tiền đề của câu chuyện là không thực tế và khó tin.","k":"premise"},{"t":"Hegemony","p":"(n.)","d":"domination over others","e":"Britain’s hegemony over its colonies was threatened once nationalist sentiment began to spread around the world.","ev":"Quyền bá chủ của Anh đối với các thuộc địa của mình bị đe dọa khi tình cảm dân tộc chủ nghĩa bắt đầu lan rộng khắp thế giới.","k":"hegemony"},{"t":"Epistolary","p":"(adj.)","d":"relating to or contained in letters","e":"Some people call me “Auntie’s boy,” because my aunt and I have such a close epistolary relationship that we write each other every day.","ev":"Một số người gọi tôi là “cậu bé của dì” vì tôi và dì có mối quan hệ thư từ thân thiết đến mức chúng tôi viết thư cho nhau hàng ngày.","k":"epistolary"},{"t":"Heinous","p":"(adj.)","d":"shockingly wicked, repugnant","e":"The killings were made all the more heinous by the fact that the murderer first tortured his victims for three days.","ev":"Các vụ giết người càng trở nên tàn khốc hơn bởi thực tế là kẻ sát nhân lần đầu tiên tra tấn nạn nhân của hắn trong ba ngày.","k":"heinous"}]},{"n":"Chưa phân loại · 42","c":[{"t":"Virtuoso","p":"(n.)","d":"one who excels in an art; a highly skilled musical performer","e":"Even though Lydia has studied piano for many years, she’s only average at it. She’s no virtuoso, that’s for sure.","ev":"Mặc dù Lydia đã học piano trong nhiều năm nhưng cô ấy chỉ ở mức trung bình. Cô ấy không phải là người tài giỏi, đó là điều chắc chắn.","k":"virtuoso"},{"t":"Tortuous","p":"(adj.)","d":"winding","e":"The scary thing about driving in mountains are the narrow, tortuous roads.","ev":"Điều đáng sợ khi lái xe trên núi là những con đường hẹp, quanh co.","k":"tortuous"},{"t":"Disrepute","p":"(n.)","d":"a state of being held in low regard","e":"The officer fell into disrepute after it was learned that he had disobeyed the orders he had given to his own soldiers.","ev":"Viên sĩ quan rơi vào tình trạng ô nhục sau khi biết rằng anh ta đã không tuân theo mệnh lệnh mà anh ta đã đưa ra cho binh lính của mình.","k":"disrepute"},{"t":"Demeanor","d":"manner, attitude, appearance","e":"His demeanor suggested that he was nervous, as he was fidgeting and avoiding eye contact.","ev":"Thái độ của anh ấy cho thấy anh ấy đang lo lắng vì anh ấy bồn chồn và tránh giao tiếp bằng mắt.","k":"demeanor"},{"t":"Insolent","p":"(adj.)","d":"rude, arrogant, overbearing","e":"That celebrity is so insolent, making fun of his fans right to their faces.","ev":"Tên nổi tiếng đó thật xấc xược, trêu chọc thẳng vào mặt người hâm mộ của mình.","k":"insolent"},{"t":"Solitude","d":"the state or situation of being alone","e":"She enjoyed solitude, spending time alone and reflecting on her thoughts.","ev":"Cô thích sự cô độc, dành thời gian một mình và suy ngẫm về những suy nghĩ của mình.","k":"solitude"},{"t":"Collusion","p":"(n.)","d":"secret agreement, conspiracy","e":"The three law students worked in collusion to steal the final exam.","ev":"Ba sinh viên luật thông đồng để trộm bài thi cuối kỳ.","k":"collusion"},{"t":"Enfeeble","d":"to make someone or something very weak","e":"The illness enfeebled her, making her weak and unable to do much.","ev":"Căn bệnh khiến cô yếu đi, khiến cô yếu ớt và không thể làm được gì nhiều.","k":"enfeeble"},{"t":"Persecute","d":"v. to cause suffering to","e":"v. to cause suffering to","ev":"v. gây đau khổ cho","k":"persecute"},{"t":"Hapless","p":"(adj.)","d":"unlucky","e":"My poor, hapless family never seems to pick a sunny week to go on vacation.","ev":"Gia đình nghèo khó, bất hạnh của tôi dường như không bao giờ chọn một tuần nắng đẹp để đi nghỉ.","k":"hapless"},{"t":"Moderate","p":"(adj.)","d":"not extreme","e":"Luckily, the restaurant we chose had moderate prices; none of us have any money.","ev":"May mắn thay, nhà hàng chúng tôi chọn có giá vừa phải; không ai trong chúng tôi có tiền.","x":"Loại từ 2: (n.)\nNghĩa 2: one who expresses moderate opinions\nVí dụ 2: Because he found both the liberal and conservative proposals too excessive, Mr. Park sided with the moderates.","k":"moderate"},{"t":"Revel","p":"(v.)","d":"to enjoy intensely","e":"Theodore reveled in his new status as Big Man on Campus.","ev":"Theodore say sưa với địa vị mới của mình là Người đàn ông lớn trong khuôn viên trường.","k":"revel"},{"t":"Maxim","p":"(n.)","d":"a common saying expressing a principle of conduct","e":"Miss Manners’s etiquette maxims are both entertaining and instructional.","ev":"Những câu châm ngôn về nghi thức của Miss Manners vừa mang tính giải trí vừa mang tính hướng dẫn.","k":"maxim"},{"t":"Adumbrate","p":"verb","d":"to sketch out in a vague way","e":"The coach adumbrated a game plan, but it was unclear to the players.","ev":"Huấn luyện viên đã phác thảo một kế hoạch, nhưng nó không rõ ràng với các cầu thủ.","k":"adumbrate"},{"t":"Obfuscate","p":"(v.)","d":"to make something less clear and harder to understand, especially intentionally","e":"The detective did want to answer the newspaperman’s questions, so he obfuscated the truth.","ev":"Vị thám tử muốn trả lời các câu hỏi của người phóng viên nên đã che giấu sự thật.","k":"obfuscate"},{"t":"Affluent","p":"adjective","d":"rich, wealthy","e":"Mrs. Grebelski was affluent, owning a huge house, three cars, and an island near Maine.","ev":"Bà Grebelski giàu có, sở hữu một ngôi nhà lớn, ba chiếc xe và một hòn đảo gần Maine.","k":"affluent"},{"t":"Aloof","p":"adjective","d":"reserved, distant","e":"The scientist could seem aloof, as if he didn’t care about his friends, but he was just thinking about quantum mechanics.","ev":"Nhà khoa học có thể có vẻ xa cách, như thể ông không quan tâm đến bạn bè, nhưng thực ra ông chỉ đang suy nghĩ về cơ học lượng tử.","k":"aloof"},{"t":"Inoculate","p":"(v.)","d":"to introduce a microorganism, serum, or vaccine into an organism in order to increase immunity to illness; to vaccinate","e":"I’ve feared needles ever since I was inoculated against 37 diseases at age one; but I have also never been sick.","ev":"Tôi đã sợ kim tiêm kể từ khi tôi được tiêm chủng ngừa 37 căn bệnh khi mới một tuổi; nhưng tôi cũng chưa bao giờ bị bệnh.","k":"inoculate"},{"t":"Bazaar","d":"a market selling a large variety of goods","e":"The bazaar was filled with colorful stalls selling handmade goods, creating a vibrant and bustling atmosphere.","ev":"Khu chợ tràn ngập những gian hàng đầy màu sắc bán đồ thủ công, tạo nên không khí sôi động, nhộn nhịp.","k":"bazaar"},{"t":"Indomitable","p":"adj","d":"not capable of being conquered","e":"Her indomitable spirit helped her overcome numerous obstacles in life.","ev":"Tinh thần bất khuất của cô đã giúp cô vượt qua nhiều trở ngại trong cuộc sống.","k":"indomitable"},{"t":"Sullen","d":"silent and unpleasant; depressed; gloomy","e":"He was sullen and withdrawn, refusing to talk to anyone.","ev":"Anh ta ủ rũ và thu mình lại, không chịu nói chuyện với bất cứ ai.","k":"sullen"},{"t":"Dismay","d":"a feeling of shock and unhappiness","e":"The news filled her with dismay, causing her to feel disappointed and discouraged.","ev":"Tin tức khiến cô mất tinh thần, khiến cô cảm thấy thất vọng và chán nản.","k":"dismay"},{"t":"Exemplify","d":"to be a typical example of something","e":"His actions exemplified the values of honesty and integrity.","ev":"Hành động của anh thể hiện giá trị của sự trung thực và liêm chính.","k":"exemplify"},{"t":"Compliant","p":"(adj.)","d":"ready to adapt oneself to another’s wishes","e":"Sue had very strong opinions about what to do on a first date, and Ted was absolutely compliant.","ev":"Sue có quan điểm rất mạnh mẽ về những việc cần làm trong buổi hẹn hò đầu tiên và Ted hoàn toàn tuân theo.","k":"compliant"},{"t":"Solicitous","p":"(adj.)","d":"concerned, attentive","e":"Jim, laid up in bed with a nasty virus, enjoyed the solicitous attentions of his mother, who brought him soup and extra blankets.","ev":"Jim, nằm trên giường với một loại virus khó chịu, rất thích sự quan tâm ân cần của mẹ anh, người mang súp và thêm chăn cho anh.","k":"solicitous"}]},{"n":"Chưa phân loại · 43","c":[{"t":"Upbraid","p":"(v.)","d":"to criticize or scold severely","e":"The last thing Lindsay wanted was for Lisa to upbraid her again about missing the rent payment.","ev":"Điều cuối cùng Lindsay muốn là Lisa lại khiển trách cô về việc không trả được tiền thuê nhà.","k":"upbraid"},{"t":"Viability","d":"n. ability to be done in a practical or useful way","e":"n. ability to be done in a practical or useful way","ev":"N. khả năng được thực hiện một cách thiết thực hoặc hữu ích","k":"viability"},{"t":"Reprove","p":"(v.)","d":"to scold, rebuke","e":"Lara reproved her son for sticking each and every one of his fingers into the strawberry pie.","ev":"Lara khiển trách con trai vì nhét từng ngón tay của nó vào chiếc bánh dâu.","k":"reprove"},{"t":"Potentate","p":"(n.)","d":"one who has great power, a ruler","e":"All the villagers stood along the town’s main road to observe as the potentate’s procession headed towards the capital.","ev":"Tất cả dân làng đứng dọc theo con đường chính của thị trấn để quan sát đoàn rước của kẻ thống trị tiến về thủ đô.","k":"potentate"},{"t":"Analogous","p":"adjective","d":"similar to, so that an analogy can be drawn","e":"The bone structure of whales and fish is quite analogous, even though they are unrelated.","ev":"Cấu trúc xương của cá voi và cá rất tương tự, mặc dù chúng không có quan hệ di truyền.","k":"analogous"},{"t":"Embrace","d":"to welcome with open arms, to accept or support willingly","e":"She embraced the opportunity to travel, eagerly anticipating new experiences and adventures.","ev":"Cô nắm lấy cơ hội đi du lịch, háo hức mong đợi những trải nghiệm và cuộc phiêu lưu mới.","k":"embrace"},{"t":"Cavort","p":"(v.)","d":"to leap about, behave boisterously","e":"The adults ate their dinners on the patio, while the children cavorted around the pool.","ev":"Người lớn ăn tối ngoài hiên, trong khi bọn trẻ nô đùa quanh hồ bơi.","k":"cavort"},{"t":"Congenial","p":"adjective","d":"pleasantly agreeable","e":"The congenial atmosphere at the gathering made everyone feel comfortable.","ev":"Bầu không khí thân thiện trong buổi gặp gỡ khiến mọi người cảm thấy thoải mái.","k":"congenial"},{"t":"Diminish","d":"v. to become smaller in scope or degree","e":"v. to become smaller in scope or degree","ev":"v. trở nên nhỏ hơn về phạm vi hoặc mức độ","k":"diminish"},{"t":"Largess","p":"(n.)","d":"the generous giving of lavish gifts","e":"My boss demonstrated great largess by giving me a new car.","ev":"Sếp của tôi đã thể hiện sự hào phóng bằng cách tặng tôi một chiếc ô tô mới.","k":"largess"},{"t":"Reservoir","p":"(n.)","d":"reserves, large supply","e":"Igor the Indomitable had quite a reservoir of strengh and could lift ten tons, even after running 700 miles, jumping over three mountains, and swimming across an ocean.","ev":"Igor Bất khuất có khá nhiều sức mạnh và có thể nâng được 10 tấn, ngay cả sau khi chạy 700 dặm, nhảy qua ba ngọn núi và bơi qua đại dương.","x":"Nghĩa 2: a body of water used for storing water\nVí dụ 2: After graduation, the more rebellious members of the senior class jumped into the town reservoir used for drinking water.","k":"reservoir"},{"t":"Largesse","d":"generosity in giving money or gifts","e":"He distributed largesse among the poor.","ev":"Ông phân phát rộng rãi cho người nghèo.","k":"largesse"},{"t":"Invoke","p":"verb","d":"to call on or refer to something, cầu khẩn","e":"She tried to invoke the spirit of teamwork in her colleagues during the project.","ev":"Cô cố gắng khơi dậy tinh thần đồng đội trong các đồng nghiệp của mình trong suốt dự án.","k":"invoke"},{"t":"Anonymous","p":"adjective","d":"being unknown, unrecognized","e":"Mary received a love poem from an anonymous admirer.","ev":"Mary nhận được một bài thơ tình từ một người hâm mộ ẩn danh.","k":"anonymous"},{"t":"Adhere","p":"verb","d":"to stick to something","e":"(1) We adhered the poster to the wall. (2) He adhered to his religious beliefs without question.","ev":"(1) Chúng tôi đã dán áp phích lên tường. (2) Anh ta tuân thủ các tín ngưỡng tôn giáo của mình mà không cần nghi ngờ.","k":"adhere"},{"t":"Contravene","p":"verb","d":"to contradict, oppose, violate","e":"Edwidge contravened his landlady’s rule against overnight guests.","ev":"Anh đã vi phạm quy định của bà chủ nhà về khách qua đêm.","k":"contravene"},{"t":"Vivacious","p":"(adj.)","d":"lively, sprightly","e":"The vivacious clown makes all of the children laugh and giggle with his friendly antics.","ev":"Chú hề hoạt bát khiến tất cả trẻ em cười khúc khích với những trò hề thân thiện của mình.","k":"vivacious"},{"t":"Licentious","p":"(adj.)","d":"displaying a lack of moral or legal restraints","e":"Marilee has always been fascinated by the licentious private lives of politicians.","ev":"Marilee luôn bị cuốn hút bởi đời sống riêng tư phóng túng của các chính trị gia.","k":"licentious"},{"t":"Emote","p":"(v.)","d":"to express emotion","e":"The director told the actor he had to emote, or else the audience would have no idea what his character was going through.","ev":"Đạo diễn nói với nam diễn viên rằng anh phải thể hiện cảm xúc, nếu không khán giả sẽ không biết nhân vật của anh đang trải qua điều gì.","k":"emote"},{"t":"Doctrine","p":"noun","d":"a belief or set of beliefs","e":"The doctrine of equality is fundamental to the nation's constitution.","ev":"Học thuyết về bình đẳng là nền tảng của hiến pháp quốc gia.","k":"doctrine"},{"t":"Derelict","p":"(adj.)","d":"abandoned, run-down","e":"Even though it was dangerous, the children enjoyed going to the deserted lot and playing in the derelict house.","ev":"Dù nguy hiểm nhưng các em rất thích ra bãi đất hoang và chơi đùa trong ngôi nhà bỏ hoang.","k":"derelict"},{"t":"Obstinacy","d":"stubbornness, unwilling to change","e":"Her obstinacy made it difficult to convince her, as she refused to budge on her position and listen to reason.","ev":"Sự cố chấp của cô khiến việc thuyết phục cô trở nên khó khăn, vì cô không chịu nhượng bộ quan điểm của mình và lắng nghe lý lẽ.","k":"obstinacy"},{"t":"Irrational","d":"not logical or reasonable","e":"His fear of spiders was irrational, as they posed no real threat to him.","ev":"Nỗi sợ nhện của anh là vô lý, vì chúng không gây ra mối đe dọa thực sự nào cho anh.","k":"irrational"},{"t":"Yoke","p":"(v.)","d":"to join, link","e":"We yoked together the logs by tying a string around them.","ev":"Chúng tôi buộc các khúc gỗ lại với nhau bằng cách buộc một sợi dây quanh chúng.","k":"yoke"},{"t":"Feasibility","d":"n. the practicality or possibility of something","e":"n. the practicality or possibility of something","ev":"N. tính thực tế hoặc khả năng của một cái gì đó","k":"feasibility"}]},{"n":"Chưa phân loại · 44","c":[{"t":"Mimic","d":"to imitate or copy (someone's actions or words)","e":"She could mimic the voices of famous people, entertaining her friends with her impressions.","ev":"Cô ấy có thể bắt chước giọng nói của những người nổi tiếng, chiêu đãi bạn bè bằng những ấn tượng của mình.","k":"mimic"},{"t":"Implication","d":"1) a conclusion that can be drawn from something 2) a consequence or result","e":"The implication of his statement was that she was lying, even though he didn't explicitly say so.","ev":"Hàm ý trong câu nói của anh là cô đang nói dối, mặc dù anh không nói rõ ràng như vậy.","k":"implication"},{"t":"Confidant","p":"noun","d":"a person entrusted with secrets","e":"Shortly after we met, she became my chief confidant.","ev":"Cô ấy được tin tưởng giữ những bí mật cá nhân.","k":"confidant"},{"t":"Relegate","p":"verb","d":"to assign to the proper place","e":"She was relegated to a lesser role after the merger.","ev":"Cô đã bị hạ xuống một vai trò thấp hơn sau khi sáp nhập.","k":"relegate"},{"t":"Explicate","d":"explain in great detail","e":"The teacher explicated the difficult concept.","ev":"Giáo viên giải thích khái niệm khó.","x":"Ví dụ 2: Explain","k":"explicate"},{"t":"Conception","d":"1) origin or beginning 2) an idea or concept","e":"Her conception of the project was innovative and original.","ev":"Quan niệm của cô về dự án rất sáng tạo và độc đáo.","k":"conception"},{"t":"Inhibit","p":"(v.)","d":"to prevent, restrain, stop","e":"When I told you I needed the car last night, I certainly never meant to inhibit you from going out.","ev":"Khi tôi nói với bạn rằng tôi cần xe tối qua, tôi chắc chắn không bao giờ có ý ngăn cản bạn ra ngoài.","k":"inhibit"},{"t":"Contradiction","d":"a combination of statements or ideas that are opposed to one another; inconsistency","e":"His statement was a contradiction to what he had said earlier, creating confusion and disbelief.","ev":"Tuyên bố của ông mâu thuẫn với những gì ông đã nói trước đó, tạo ra sự nhầm lẫn và hoài nghi.","k":"contradiction"},{"t":"Confinement","d":"imprisonment, captivity","e":"The prisoners were kept in strict confinement, with limited freedom and constant surveillance.","ev":"Các tù nhân bị giam giữ nghiêm ngặt, với quyền tự do hạn chế và bị giám sát liên tục.","k":"confinement"},{"t":"Unadorned","d":"adj. undecorated, plain","e":"adj. undecorated, plain","ev":"tính từ không trang trí, đơn giản","k":"unadorned"},{"t":"Juvenile","d":"young, childish, immature","e":"Her behavior was juvenile, childish and immature.","ev":"Hành vi của cô ấy còn non nớt, trẻ con và non nớt.","k":"juvenile"},{"t":"Defamatory","p":"(adj.)","d":"harmful toward another’s reputation","e":"The defamatory gossip spreading about the actor made the public less willing to see the actor’s new movie.","ev":"Những lời đồn thổi phỉ báng nam diễn viên lan truyền khiến công chúng không mấy mặn mà với việc xem phim mới của nam diễn viên.","k":"defamatory"},{"t":"Diminutive","p":"(adj.)","d":"small or miniature","e":"The bullies, tall and strong, picked on the diminutive child.","ev":"Những kẻ bắt nạt, cao lớn và khỏe mạnh, bắt nạt đứa trẻ nhỏ bé.","k":"diminutive"},{"t":"Canvas","p":"(n.)","d":"a piece of cloth on which an artist paints","e":"Picasso liked to work on canvas rather than on bare cement.","ev":"Picasso thích vẽ trên vải hơn là trên xi măng trần.","x":"Loại từ 2: (v.)\nNghĩa 2: to cover, inspect\nVí dụ 2: We canvassed the neighborhood looking for clues.","k":"canvas"},{"t":"Larceny","p":"(n.)","d":"obtaining another’s property by theft or trickery","e":"When my car was not where I had left it, I realized that I was a victim of larceny.","ev":"Khi chiếc xe của tôi không còn ở nơi tôi đã để lại, tôi nhận ra mình là nạn nhân của một vụ trộm cắp.","k":"larceny"},{"t":"Perilous","d":"dangerous","e":"The journey was perilous, with many dangers and obstacles along the way.","ev":"Cuộc hành trình đầy nguy hiểm, với nhiều nguy hiểm và chướng ngại vật trên đường đi.","k":"perilous"},{"t":"Pathos","p":"(n.)","d":"the power of a person, situation, piece of writing, or work of art to cause feelings of sadness, especially because people feel sympathy, tính chất cảm động","e":"There's a pathos in his performance which he never lets slide into sentimentality.","ev":"Có một điểm yếu trong màn trình diễn của anh ấy mà anh ấy không bao giờ để nó rơi vào tình cảm.","k":"pathos"},{"t":"Oust","d":"v. to remove or force out of (usu. a position or office)","e":"v. to remove or force out of (usu. a position or office)","ev":"v. loại bỏ hoặc buộc phải rời khỏi (sử dụng một vị trí hoặc chức vụ)","k":"oust"},{"t":"Partisan","p":"noun","d":"a follower, adherent","e":"The partisan debates in the media often create division among the public.","ev":"Những cuộc tranh luận theo phe phái trong truyền thông thường tạo ra sự chia rẽ trong công chúng.","k":"partisan"},{"t":"Solicitation","d":"a request for money, information, or help","e":"He was arrested for solicitation of prostitution.","ev":"Anh ta bị bắt vì tội mời chào mại dâm.","k":"solicitation"},{"t":"Indifference","d":"lack of interest and concern","e":"Her indifference to the suffering of others was shocking, as she seemed completely unmoved by their pain.","ev":"Sự thờ ơ của cô trước nỗi đau khổ của người khác thật đáng kinh ngạc, vì cô dường như hoàn toàn không lay động trước nỗi đau của họ.","k":"indifference"},{"t":"Novice","p":"(n.)","d":"a beginner, someone without training or experience","e":"Because we were all novices at yoga, our instructor decided to begin with the basics.","ev":"Bởi vì tất cả chúng tôi đều là người mới tập yoga nên người hướng dẫn của chúng tôi quyết định bắt đầu với những điều cơ bản.","k":"novice"},{"t":"Zealous","p":"(adj.)","d":"fervent, filled with eagerness in pursuit of something","e":"If he were any more zealous about getting his promotion, he’d practically live at the office.","ev":"Nếu anh ấy nhiệt tình hơn nữa trong việc được thăng chức thì gần như anh ấy sẽ sống ở văn phòng.","k":"zealous"},{"t":"Invective","p":"(n.)","d":"an angry verbal attack","e":"My mother’s irrational invective against the way I dress only made me decide to dye my hair green.","ev":"Sự chỉ trích vô lý của mẹ đối với cách ăn mặc của tôi chỉ khiến tôi quyết định nhuộm tóc màu xanh lá cây.","k":"invective"},{"t":"Scatterbrained","d":"disorganized, forgetful","e":"She was a scatterbrained person who often forgot things and was easily distracted.","ev":"Cô là một người đãng trí, thường xuyên quên đồ và dễ bị phân tâm.","k":"scatterbrained"}]},{"n":"Chưa phân loại · 45","c":[{"t":"Congregation","p":"noun","d":"a gathering of people, especially for religious services","e":"The priest told the congregation that he would be retiring.","ev":"Cộng đồng đã tụ họp để nghe thông báo tôn giáo.","k":"congregation"},{"t":"Blemish","p":"(n.)","d":"an imperfection, flaw","e":"The dealer agreed to lower the price because of the many blemishes on the surface of the wooden furniture.","ev":"Người bán đồng ý giảm giá vì bề mặt đồ gỗ có nhiều vết xước.","k":"blemish"},{"t":"Onset","d":"n. the beginning or early stages","e":"n. the beginning or early stages","ev":"N. giai đoạn đầu hoặc giai đoạn đầu","k":"onset"},{"t":"Avarice","p":"noun","d":"excessive greed","e":"Avarice often leads to unethical behavior in business.","ev":"Lòng tham thường dẫn đến hành vi phi đạo đức trong kinh doanh.","k":"avarice"},{"t":"Forbearance","p":"(n.)","d":"patience, restraint, toleration","e":"The doctor showed great forbearance in calming down the angry patient who shouted insults at him.","ev":"Bác sĩ đã thể hiện sự nhẫn nại tuyệt vời trong việc xoa dịu bệnh nhân đang giận dữ hét lên những lời lăng mạ ông.","k":"forbearance"},{"t":"Effulgent","p":"(adj.) /ɪˈfʌl.dʒənt/","d":"shining brightly","e":"The golden palace was effulgent.","ev":"Cung điện vàng rực rỡ.","k":"effulgent"},{"t":"Demure","p":"(adj.)","d":"quiet, modest, reserved","e":"Though everyone else at the party was dancing and going crazy, she remained demure.","ev":"Mặc dù mọi người khác trong bữa tiệc đều đang nhảy múa và phát điên nhưng cô ấy vẫn rất nghiêm túc.","k":"demure"},{"t":"Exigent","p":"(adj.)","d":"urgent, critical","e":"The patient has an exigent need for medication, or else he will lose his sight.","ev":"Bệnh nhân cần thuốc cấp thiết, nếu không sẽ bị mất thị lực.","k":"exigent"},{"t":"Abstruse","p":"adj","d":"hard to comprehend","e":"The professor's lecture on quantum mechanics was so abstruse that many students left feeling confused.","ev":"Bài giảng của giáo sư về cơ học lượng tử quá trừu tượng đến nỗi nhiều sinh viên ra về với cảm giác bối rối.","k":"abstruse"},{"t":"Upshot","d":"the final result of a situation","e":"The upshot of the meeting was that they agreed to work together.","ev":"Kết quả của cuộc gặp là họ đã đồng ý làm việc cùng nhau.","k":"upshot"},{"t":"Concord","p":"noun","d":"harmonious agreement","e":"Julie and Harold began the evening with a disagreement but ended it in a state of perfect concord.","ev":"Họ đã giải quyết xung đột và tìm thấy sự đồng thuận.","k":"concord"},{"t":"Impartial","d":"able to judge something fairly","e":"The judge must be impartial, treating all parties fairly and without bias.","ev":"Thẩm phán phải vô tư, đối xử công bằng và không thiên vị với tất cả các bên.","k":"impartial"},{"t":"Docile","p":"(adj.)","d":"easily taught or trained","e":"She successfully taught the docile puppy several tricks.","ev":"Cô đã dạy thành công cho chú chó con ngoan ngoãn một số thủ thuật.","k":"docile"},{"t":"Embellish","p":"(v.)","d":"to decorate, adorn","e":"My mom embellished the living room by adding lace curtains.","ev":"Mẹ tôi tô điểm phòng khách bằng cách thêm rèm ren.","x":"Nghĩa 2: to add details to, enhance\nVí dụ 2: When Harry told me that he had “done stuff” on his vacation, I asked him to embellish upon his account.","k":"embellish"},{"t":"Dominion","d":"1) control over a country or people 2) the land that belongs to a ruler","e":"The empire exercised dominion over a vast territory.","ev":"Đế chế thực hiện quyền thống trị trên một lãnh thổ rộng lớn.","k":"dominion"},{"t":"Sublime","p":"(adj.)","d":"lofty, grand, exalted","e":"The homeless man sadly pondered his former wealth and once sublime existence.","ev":"Người đàn ông vô gia cư buồn bã suy ngẫm về sự giàu có trước đây và sự tồn tại cao cả một thời của mình.","k":"sublime"},{"t":"Elated","p":"(adj.)","d":"overjoyed, thrilled","e":"When she found out she had won the lottery, the writer was elated.","ev":"Khi biết mình trúng số, người viết đã rất phấn khởi.","k":"elated"},{"t":"Calamity","p":"(n.)","d":"an event with disastrous consequences","e":"The earthquake in San Francisco was a calamity worse than any other natural disaster in history.","ev":"Trận động đất ở San Francisco là một thảm họa tồi tệ hơn bất kỳ thảm họa thiên nhiên nào khác trong lịch sử.","k":"calamity"},{"t":"Pernicious","p":"(adj.)","d":"extremely destructive or harmful","e":"The new government feared that the Communist sympathizers would have a pernicious influence on the nation’s stability.","ev":"Chính phủ mới lo ngại rằng những người có cảm tình với Cộng sản sẽ có ảnh hưởng xấu đến sự ổn định của đất nước.","k":"pernicious"},{"t":"Antediluvian","p":"adj","d":"ancient","e":"His ideas were antediluvian and outdated.","ev":"Ý tưởng của anh ta cổ xưa và lạc hậu.","k":"antediluvian"},{"t":"Misgiving","d":"a feeling of doubt, uncertainty, or worry about a future event","e":"He had misgivings about the plan, doubting its success.","ev":"Anh ta có những nghi ngờ về kế hoạch, nghi ngờ sự thành công của nó.","k":"misgiving"},{"t":"Skeptical","d":"having doubts","e":"He was skeptical about the claims made in the advertisement, questioning whether the product would actually work as promised.","ev":"Ông hoài nghi về những tuyên bố trong quảng cáo, đặt câu hỏi liệu sản phẩm có thực sự hoạt động như đã hứa hay không.","k":"skeptical"},{"t":"Incomprehensible","d":"not able to be understood","e":"The instructions were incomprehensible, making it difficult to follow them.","ev":"Các hướng dẫn không thể hiểu được, gây khó khăn cho việc thực hiện theo chúng.","k":"incomprehensible"},{"t":"Didactic","p":"adj","d":"intended to instruct","e":"The didactic nature of the lecture made it both informative and engaging.","ev":"Tính giáo dục của bài giảng khiến nó vừa cung cấp thông tin vừa hấp dẫn.","k":"didactic"},{"t":"Semaphore","p":"(n.)","d":"a visual signal","e":"Anne and Diana communicated with a semaphore involving candles and window shades.","ev":"Anne và Diana giao tiếp bằng một tín hiệu liên quan đến nến và rèm cửa sổ.","k":"semaphore"}]},{"n":"Chưa phân loại · 46","c":[{"t":"Ingenuous","p":"adj","d":"not devious; innocent and candid","e":"She has an ingenuous charm that makes her very likable.","ev":"Cô ấy có một sức hấp dẫn ngây thơ khiến cô rất được yêu mến.","k":"ingenuous"},{"t":"Insidious","p":"(adj.)","d":"appealing but imperceptibly harmful, seductive","e":"Lisa’s insidious chocolate cake tastes so good but makes you feel so sick later on!","ev":"Chiếc bánh sô cô la quỷ quyệt của Lisa có vị rất ngon nhưng về sau lại khiến bạn phát ngán!","k":"insidious"},{"t":"Ambitious","d":"adj. having a powerful desire for success or achievement","e":"adj. having a powerful desire for success or achievement","ev":"tính từ có một mong muốn mạnh mẽ để thành công hoặc đạt được thành tích","k":"ambitious"},{"t":"Unjust","d":"adj. unfair; not justified","e":"adj. unfair; not justified","ev":"tính từ không công bằng; không hợp lý","k":"unjust"},{"t":"Expunge","p":"(v.)","d":"to obliterate, eradicate","e":"Fearful of an IRS investigation, Paul tried to expunge all incriminating evidence from his tax files.","ev":"Lo sợ bị IRS điều tra, Paul đã cố gắng xóa bỏ mọi bằng chứng buộc tội khỏi hồ sơ thuế của mình.","k":"expunge"},{"t":"Facile","p":"adj","d":"easy, requiring little effort","e":"His facile understanding of the topic impressed everyone in the meeting.","ev":"Sự hiểu biết dễ dàng của anh về chủ đề đã gây ấn tượng với mọi người trong cuộc họp.","k":"facile"},{"t":"Coup","p":"noun","d":"a brilliant, unexpected act","e":"Alexander pulled off an amazing coup when he got a date with Cynthia by purposely getting hit by her car. 2. In their coup attempt, the army officers stormed the Parliament and took all the legislators hostage.","ev":"Alexander đã thực hiện một cú sốc khi hẹn hò với Cynthia. 2. Trong cuộc đảo chính, các sĩ quan quân đội đã tấn công Quốc hội.","k":"coup"},{"t":"Punctilious","p":"adj","d":"eager to follow rules or conventions","e":"She was punctilious about following the rules, ensuring everything was done correctly.","ev":"Cô rất chú ý đến việc tuân theo các quy tắc, đảm bảo mọi thứ đều được thực hiện chính xác.","k":"punctilious"},{"t":"Emaciated","p":"(adj.)","d":"very thin, enfeebled looking","e":"My sister eats a lot of pastries and chocolate but still looks emaciated.","ev":"Chị tôi ăn rất nhiều bánh ngọt và sôcôla nhưng trông vẫn hốc hác.","k":"emaciated"},{"t":"Boon","p":"(n.)","d":"a gift or blessing","e":"The good weather has been a boon for many businesses located near the beach.","ev":"Thời tiết tốt là một lợi thế cho nhiều doanh nghiệp nằm gần bãi biển.","k":"boon"},{"t":"Allocate","p":"verb","d":"to distribute, set aside","e":"The committee will allocate funds to support local charities.","ev":"Ủy ban sẽ phân bổ quỹ để hỗ trợ các tổ chức từ thiện địa phương.","k":"allocate"},{"t":"Accommodating","p":"adjective","d":"helpful, obliging, polite","e":"Arnold, Mark, and Zebulon were accommodating to each other despite their small apartment.","ev":"Arnold, Mark và Zebulon đã hỗ trợ lẫn nhau mặc dù căn hộ của họ nhỏ.","k":"accommodating"},{"t":"Abduct","p":"verb","d":"to kidnap, take by force","e":"The evildoers abducted the fairy princess from her happy home.","ev":"Những kẻ xấu đã bắt cóc công chúa tiên từ ngôi nhà hạnh phúc của cô.","k":"abduct"},{"t":"Appropriate","p":"adjective","d":"to take, make use of","e":"The government appropriated the farmer’s land without justification.","ev":"Chính phủ đã chiếm đoạt đất của nông dân mà không có lý do chính đáng.","k":"appropriate"},{"t":"Aggrandize","p":"verb","d":"to increase or make greater","e":"Joseph always dropped the names of the famous people his father knew as a way to aggrandize his personal stature.","ev":"Joseph thường nhắc đến tên của những người nổi tiếng mà cha anh biết như một cách để nâng cao vị thế cá nhân của mình.","k":"aggrandize"},{"t":"Dismal","d":"depressing, gloomy","e":"The weather was dismal, with gray skies and constant drizzle.","ev":"Thời tiết thật ảm đạm, bầu trời xám xịt và mưa phùn liên tục.","k":"dismal"},{"t":"Ineffable","p":"adjective","d":"unspeakable, incapable of being expressed through words","e":"The beauty of the sunset was ineffable; no words could capture its essence.","ev":"Vẻ đẹp của hoàng hôn thật không thể diễn tả; không có từ nào có thể diễn tả được bản chất của nó.","k":"ineffable"},{"t":"Clemency","p":"(n.)","d":"mercy","e":"After he forgot their anniversary, Martin could only beg Maria for clemency.","ev":"Sau khi quên mất ngày kỷ niệm của họ, Martin chỉ có thể cầu xin Maria sự khoan hồng.","k":"clemency"},{"t":"Perusal","p":"(n.)","d":"a careful examination, review","e":"The actor agreed to accept the role after a two-month perusal of the movie script.","ev":"Nam diễn viên đồng ý nhận vai sau hai tháng xem qua kịch bản phim.","k":"perusal"},{"t":"Esteem","d":"respect and admiration for someone","e":"She was held in high esteem by her colleagues.","ev":"Cô được đồng nghiệp đánh giá cao.","k":"esteem"},{"t":"Cloying","p":"(adj.)","d":"sickeningly sweet","e":"Though Ronald was physically attractive, Maud found his constant compliments and solicitous remarks cloying.","ev":"Mặc dù Ronald có vẻ ngoài hấp dẫn nhưng Maud nhận thấy những lời khen ngợi liên tục và những nhận xét ân cần của anh ấy thật giả tạo.","k":"cloying"},{"t":"Manifest","p":"(adj.)","d":"perceptible, obvious","e":"When I wrote the wrong sum on the chalkboard, my mistake was so manifest that the entire class burst into laughter.","ev":"Khi tôi viết sai số lên bảng, lỗi của tôi lộ rõ ​​đến mức cả lớp bật cười.","x":"Loại từ 2: (v.)\nNghĩa 2: to show plainly\nVí dụ 2: His illness first manifested itself with particularly violent hiccups.","k":"manifest"},{"t":"Indignation","p":"(n.)","d":"anger sparked by something unjust or unfair","e":"I resigned from the sorority because of my indignation at its hazing of new members.","ev":"Tôi đã từ chức khỏi hội nữ sinh vì sự phẫn nộ trước việc hội này coi thường các thành viên mới.","k":"indignation"},{"t":"Scorn","d":"contempt, the feeling that someone or something is worthless","e":"He scorned the idea of giving up, regarding it as weak and cowardly.","ev":"Anh khinh miệt ý định bỏ cuộc, coi đó là sự yếu đuối và hèn nhát.","k":"scorn"},{"t":"Idolatrous","p":"(adj.)","d":"excessively worshipping one object or person","e":"Xena’s idolatrous fawning over the band—following them on tour, starting their fan club, filming their documentary—is really beginning to get on my nerves.","ev":"Sự tôn sùng thần tượng của Xena đối với ban nhạc — theo họ trong chuyến lưu diễn, thành lập câu lạc bộ người hâm mộ, quay phim tài liệu của họ — thực sự bắt đầu khiến tôi lo lắng.","k":"idolatrous"}]},{"n":"Chưa phân loại · 47","c":[{"t":"Fastidious","p":"adj","d":"meticulous, demanding, having high and often unattainable standards","e":"She is fastidious about cleanliness and organizes everything meticulously.","ev":"Cô rất cầu toàn về sự sạch sẽ và sắp xếp mọi thứ một cách tỉ mỉ.","k":"fastidious"},{"t":"Unilaterally","d":"used to indicate that something is done by only one person or group, without the agreement of others","e":"The decision was made unilaterally by the government, without consulting the public or seeking their input.","ev":"Quyết định này được chính phủ đơn phương đưa ra mà không hỏi ý kiến ​​​​công chúng hoặc hỏi ý kiến ​​​​của họ.","k":"unilaterally"},{"t":"Behemoth","p":"noun","d":"something of tremendous power or size","e":"The new aircraft carrier is among the behemoths added to the fleet.","ev":"Tàu sân bay mới là một trong những “quái vật” được thêm vào đội hình.","k":"behemoth"},{"t":"Acute","p":"adjective","d":"sharp, severe","e":"(1) Arnold could not walk due to acute pain. (2) Libby’s acute mind quickly solved the trick.","ev":"(1) Arnold không thể đi vì cơn đau dữ dội. (2) Trí thông minh nhạy bén của Libby đã nhanh chóng giải quyết được mẹo.","k":"acute"},{"t":"Veneer","p":"(n.)","d":"a superficial or deceptively attractive appearance, façade","e":"Thanks to her Chanel makeup, Shannen was able to maintain a veneer of perfection that hid the flaws underneath.","ev":"Nhờ trang điểm Chanel, Shannen đã có thể duy trì vẻ ngoài hoàn hảo để che đi những khuyết điểm bên dưới.","k":"veneer"},{"t":"Acquiesce","p":"verb","d":"to agree without protesting","e":"Mr. Correlli acquiesced to his wife’s demand to come in for dinner.","ev":"Ông Correlli đã chấp nhận yêu cầu của vợ về việc vào ăn tối.","k":"acquiesce"},{"t":"Vital","d":"adj. urgently necessary","e":"adj. urgently necessary","ev":"tính từ cần thiết khẩn cấp","k":"vital"},{"t":"Transparent","d":"adj. see-through; so thin that light can shine through","e":"adj. see-through; so thin that light can shine through","ev":"tính từ nhìn xuyên qua; mỏng đến mức ánh sáng có thể chiếu xuyên qua","k":"transparent"},{"t":"Unveil","d":"v. to make visible; to reveal","e":"v. to make visible; to reveal","ev":"v. làm cho có thể nhìn thấy được; tiết lộ","k":"unveil"},{"t":"Redoubtable","p":"(adj.)","d":"formidable","e":"The fortress looked redoubtable set against a stormy sky.","ev":"Pháo đài trông đáng tin cậy trên nền trời giông bão.","x":"Nghĩa 2: commanding respect\nVí dụ 2: The audience greeted the redoubtable speaker with a standing ovation.","k":"redoubtable"},{"t":"Aspire","p":"verb","d":"to long for, aim toward","e":"She aspires to become a successful artist one day.","ev":"Cô khao khát trở thành một nghệ sĩ thành công trong một ngày không xa.","k":"aspire"},{"t":"Dispatch","p":"(v.)","d":"to send off to accomplish a duty","e":"The carpenter dispatched his assistant to fetch wood.","ev":"Người thợ mộc sai người giúp việc đi lấy gỗ.","k":"dispatch"},{"t":"Innovate","p":"(v.)","d":"to do something in an unprecedented way","e":"Because of the stiff competition, the company knew it needed to pour a lot of energy into innovating new and better products.","ev":"Do sự cạnh tranh gay gắt, công ty biết rằng cần phải đổ nhiều sức lực vào việc đổi mới các sản phẩm mới và tốt hơn.","k":"innovate"},{"t":"Indigent","p":"(adj.)","d":"very poor, impoverished","e":"I would rather donate money to help the indigent population than to the park sculpture fund.","ev":"Tôi thà quyên góp tiền để giúp đỡ người nghèo hơn là quỹ điêu khắc công viên.","k":"indigent"},{"t":"Decree","d":"an official order or command","e":"The king issued a decree that banned alcohol, imposing a strict prohibition on the consumption of alcoholic beverages.","ev":"Nhà vua ban hành sắc lệnh cấm rượu, áp đặt lệnh cấm nghiêm ngặt đối với việc tiêu thụ đồ uống có cồn.","k":"decree"},{"t":"Confide","d":"v. to share something secretive with someone","e":"v. to share something secretive with someone","ev":"v. chia sẻ điều gì đó bí mật với ai đó","k":"confide"},{"t":"Bequeath","p":"verb","d":"to pass on, give","e":"She decided to bequeath her entire estate to her favorite charity.","ev":"Cô quyết định để lại toàn bộ tài sản của mình cho tổ chức từ thiện mà cô yêu thích.","k":"bequeath"},{"t":"Dissent","p":"(v.)","d":"to disagree","e":"The principal argued that the child should repeat the fourth grade, but the unhappy parents dissented.","ev":"Hiệu trưởng cho rằng đứa trẻ nên học lại lớp bốn, nhưng các bậc phụ huynh không hài lòng không đồng ý.","x":"Loại từ 2: (n.)\nNghĩa 2: the act of disagreeing\nVí dụ 2: Unconvinced that the defendant was guilty, the last juror voiced his dissent with the rest of the jury.","k":"dissent"},{"t":"Quantitative","d":"adj. involving quantities (numbers and amounts)","e":"adj. involving quantities (numbers and amounts)","ev":"tính từ liên quan đến số lượng (số lượng và số lượng)","k":"quantitative"},{"t":"Enchantment","d":"magic, charm, fascination","e":"The forest was filled with an air of enchantment, with its towering trees, sparkling streams, and magical creatures.","ev":"Khu rừng tràn ngập bầu không khí mê hoặc, với những cây cao chót vót, những dòng suối lấp lánh và những sinh vật huyền diệu.","k":"enchantment"},{"t":"Melodramatic","d":"exaggerated, sensationalized, or overemotional","e":"Her behavior was melodramatic, exaggerated and overly emotional.","ev":"Hành vi của cô ấy khoa trương, cường điệu và quá xúc động.","k":"melodramatic"},{"t":"Predilection","p":"(n.)","d":"a preference or inclination for something","e":"Francois has a predilection for eating scrambled eggs with ketchup, though I prefer to eat eggs without any condiments.","ev":"Francois có sở thích ăn trứng bác với sốt cà chua, mặc dù tôi thích ăn trứng không kèm gia vị hơn.","k":"predilection"},{"t":"Controversial","d":"adj. highly debatable and causing contention","e":"adj. highly debatable and causing contention","ev":"tính từ gây nhiều tranh cãi và gây tranh cãi","k":"controversial"},{"t":"Iconoclast","p":"(n.)","d":"one who attacks common beliefs or institutions","e":"Jane goes to one protest after another, but she seems to be an iconoclast rather than an activist with a progressive agenda.","ev":"Jane tham gia hết cuộc biểu tình này đến cuộc biểu tình khác, nhưng cô ấy dường như là một người bài trừ biểu tượng hơn là một nhà hoạt động có chương trình nghị sự tiến bộ.","k":"iconoclast"},{"t":"Paleontology","d":"study of fossils","e":"Paleontology is the study of fossils.","ev":"Cổ sinh vật học là nghiên cứu về hóa thạch.","x":"Ví dụ 2: Branches of Science","k":"paleontology"}]},{"n":"Chưa phân loại · 48","c":[{"t":"Inane","p":"adj","d":"silly and meaningless","e":"The inane comments during the meeting only distracted everyone from the main issue.","ev":"Những bình luận vô nghĩa trong cuộc họp chỉ khiến mọi người phân tâm khỏi vấn đề chính.","k":"inane"},{"t":"Prudence","p":"(n.)","d":"cautious, circumspect","e":"After losing a fortune in a stock market crash, my father vowed to practice greater prudence in future investments.","ev":"Sau khi thua lỗ trong một vụ sụp đổ của thị trường chứng khoán, cha tôi thề sẽ thận trọng hơn trong các khoản đầu tư trong tương lai.","k":"prudence"},{"t":"Lethargic","p":"(adj.)","d":"in a state of sluggishness or apathy","e":"When Jean Claude explained to his boss that he was lethargic and didn’t feel like working that day, the boss fired him.","ev":"Khi Jean Claude giải thích với sếp rằng ngày hôm đó anh ta thờ ơ và không muốn làm việc, ông chủ đã sa thải anh ta.","k":"lethargic"},{"t":"Scintillating","p":"adjective","d":"sparkling","e":"The scintillating conversation at dinner made the evening enjoyable.","ev":"Cuộc trò chuyện sáng tạo trong bữa tối đã làm cho buổi tối trở nên thú vị.","k":"scintillating"},{"t":"Intimation","p":"(n.)","d":"an indirect suggestion","e":"Mr. Brinford’s intimation that he would soon pass away occurred when he began to discuss how to distribute his belongings among his children.","ev":"Việc ông Brinford báo trước rằng ông sắp qua đời xảy ra khi ông bắt đầu thảo luận về cách phân chia tài sản của mình cho các con.","k":"intimation"},{"t":"Pittance","p":"(n.)","d":"a very small amount, especially relating to money","e":"Josh complained that he was paid a pittance for the great amount of work he did at the firm.","ev":"Josh phàn nàn rằng anh được trả một khoản tiền rất nhỏ cho khối lượng công việc khổng lồ mà anh đã làm ở công ty.","k":"pittance"},{"t":"Absolution","p":"noun","d":"freedom from blame, guilt, sin","e":"The jury gave Angela absolution with a verdict of not guilty.","ev":"Bồi thẩm đoàn đã cho Angela sự giải thoát với phán quyết không có tội.","k":"absolution"},{"t":"Phenomenon","d":"a noteworthy occurrence or situation","e":"The aurora borealis is a natural phenomenon that occurs when charged particles from the sun interact with the Earth's atmosphere.","ev":"Cực quang là một hiện tượng tự nhiên xảy ra khi các hạt tích điện từ mặt trời tương tác với bầu khí quyển Trái đất.","k":"phenomenon"},{"t":"Conformist","p":"noun","d":"one who behaves the same as others","e":"Julian was such a conformist that he had to wait and see if his friends would do something before he would commit.","ev":"Anh chỉ hành động sau khi thấy người khác làm gì.","k":"conformist"},{"t":"Laceration","p":"(n.)","d":"a cut, tear","e":"Because he fell off his bike into a rosebush, the paperboy’s skin was covered with lacerations.","ev":"Vì ngã xe đạp vào bụi hoa hồng nên da của cậu bé bán báo đầy những vết rách.","k":"laceration"},{"t":"Temperament","d":"a person's nature, character, or frame of mind","e":"He had a fiery temperament and was easily angered, often lashing out at others without thinking.","ev":"Anh ta có tính khí nóng nảy và dễ nổi giận, thường xuyên đả kích người khác mà không cần suy nghĩ.","k":"temperament"},{"t":"Fetid","p":"(adj.)","d":"having a foul odor","e":"I can tell from the fetid smell in your refrigerator that your milk has spoiled.","ev":"Qua mùi hôi trong tủ lạnh tôi có thể biết sữa của bạn đã hỏng.","k":"fetid"},{"t":"Potent","d":"powerful, persuasive, or effective","e":"The drug was a potent painkiller.","ev":"Thuốc là một loại thuốc giảm đau mạnh.","k":"potent"},{"t":"Fervent","p":"(adj.)","d":"ardent, passionate, deep","e":"The fervent protestors chained themselves to the building and shouted all night long.","ev":"Những người biểu tình nhiệt thành đã xích mình vào tòa nhà và la hét suốt đêm.","k":"fervent"},{"t":"Negligent","p":"(adj.)","d":"habitually careless, neglectful","e":"Jessie’s grandfather called me a negligent fool after I left the door to his apartment unlocked even though there had been a recent string of robberies.","ev":"Ông của Jessie gọi tôi là kẻ ngu ngốc cẩu thả sau khi tôi để cửa căn hộ của ông không khóa mặc dù gần đây đã xảy ra một loạt vụ cướp.","k":"negligent"},{"t":"Constrain","p":"verb","d":"to forcibly restrict","e":"His belief in nonviolence constrained him from taking revenge on his attackers.","ev":"Nguyên tắc của anh đã ngăn cản anh trả thù.","k":"constrain"},{"t":"Preoccupied With","d":"obsessed with something","e":"She was preoccupied with her work and didn't have time for anything else, completely absorbed in her tasks.","ev":"Cô ấy bận rộn với công việc của mình và không có thời gian cho bất cứ điều gì khác, hoàn toàn mải mê với công việc của mình.","k":"preoccupied with"},{"t":"Nominal","p":"(adj.)","d":"trifling, insignificant","e":"Because he was moving the following week and needed to get rid of his furniture more than he needed money, Jordan sold everything for a nominal fee.","ev":"Vì tuần sau anh sẽ chuyển đi và cần thanh lý đồ đạc nhiều hơn là cần tiền nên Jordan đã bán mọi thứ với một khoản phí tượng trưng.","k":"nominal"},{"t":"Guile","p":"(n.)","d":"deceitful, cunning, sly behavior","e":"Because of his great guile, the politician was able to survive scandal after scandal.","ev":"Nhờ mưu mẹo lớn của mình, chính trị gia này đã có thể sống sót sau hết vụ bê bối này đến vụ bê bối khác.","k":"guile"},{"t":"Complicit","p":"(adj.)","d":"being an accomplice in a wrongful act","e":"By keeping her daughter’s affair a secret, Maddie became complicit in it.","ev":"Bằng cách giữ bí mật chuyện ngoại tình của con gái, Maddie đã trở thành đồng lõa trong đó.","k":"complicit"},{"t":"Distinct","d":"clearly separate and different","e":"The two languages were distinct, with different grammar, vocabulary, and pronunciation.","ev":"Hai ngôn ngữ này khác biệt, có ngữ pháp, từ vựng và cách phát âm khác nhau.","k":"distinct"},{"t":"Lament","d":"to express sadness and regret about something","e":"She lamented the loss of her friend, expressing her sadness and grief.","ev":"Cô than thở về sự ra đi của người bạn, bày tỏ nỗi buồn và sự đau buồn.","k":"lament"},{"t":"Fathom","p":"(v.)","d":"to understand, comprehend","e":"I cannot fathom why you like that crabby and mean-spirited neighbor of ours.","ev":"Tôi không thể hiểu tại sao bạn lại thích người hàng xóm cáu kỉnh và xấu tính của chúng ta.","k":"fathom"},{"t":"Provision","d":"1) a condition or requirement in a legal document, điều khoản 2) the act of providing services or resources","e":"The government made provisions for disaster relief, ensuring that aid would be available to those affected.","ev":"Chính phủ đưa ra các quy định về cứu trợ thiên tai, đảm bảo rằng viện trợ sẽ được cung cấp cho những người bị ảnh hưởng.","k":"provision"},{"t":"Dissuade","p":"(v.)","d":"to persuade someone not to do something","e":"Worried that he would catch a cold, she tried to dissuade him from going out on winter nights.","ev":"Lo lắng anh sẽ bị cảm lạnh, cô cố gắng khuyên anh đừng ra ngoài vào những đêm đông.","k":"dissuade"}]},{"n":"Chưa phân loại · 49","c":[{"t":"Immutable","p":"(adj.)","d":"not changeable","e":"The laws of physics are immutable and constant.","ev":"Các định luật vật lý là bất biến và bất biến.","k":"immutable"},{"t":"Accessible","p":"adjective","d":"obtainable, reachable","e":"After studying hard, Marlena found her Ivy-League college goal was accessible.","ev":"Sau khi học chăm chỉ, Marlena nhận ra rằng mục tiêu vào đại học Ivy-League của cô là có thể đạt được.","k":"accessible"},{"t":"Opulent","p":"(adj.)","d":"characterized by rich abundance verging on ostentation, xa hoa","e":"The opulent furnishings of the dictator’s private compound contrasted harshly with the meager accommodations of her subjects.","ev":"Nội thất sang trọng trong khu nhà riêng của nhà độc tài tương phản gay gắt với chỗ ở ít ỏi của thần dân của bà.","k":"opulent"},{"t":"Progenitor","d":"originator, creator, founder","e":"He was the progenitor of a new dynasty, founding a powerful and influential family.","ev":"Ông là người sáng lập ra một triều đại mới, thành lập nên một gia tộc hùng mạnh và có thế lực.","k":"progenitor"},{"t":"Prospect","d":"the possibility or likelihood of some future event occurring","e":"The prospect of a vacation excited her, filling her with anticipation and joy.","ev":"Viễn cảnh về một kỳ nghỉ làm cô phấn khích, tràn ngập sự mong chờ và niềm vui.","k":"prospect"},{"t":"Perfunctory","p":"adjective","d":"showing little interest or enthusiasm","e":"His perfunctory response to the question showed his lack of interest.","ev":"Phản ứng hời hợt của anh đối với câu hỏi cho thấy sự thiếu quan tâm của anh.","k":"perfunctory"},{"t":"Esoteric","p":"adj","d":"understood by only a select few","e":"The esoteric nature of the topic made it difficult for outsiders to understand.","ev":"Tính chất bí truyền của chủ đề khiến người ngoài khó hiểu.","k":"esoteric"},{"t":"Anecdote","p":"noun","d":"a short, humorous account","e":"After dinner, Marlon told an anecdote about the time he got his nose stuck in a toaster.","ev":"Sau bữa tối, Marlon đã kể một câu chuyện hài hước về lần anh bị mũi kẹt vào máy nướng bánh.","k":"anecdote"},{"t":"Practical","d":"likely to succeed or be effective in real circumstances, relating to actual experience rather than knowledge only","e":"She was a practical person who focused on solving problems and achieving results.","ev":"Cô ấy là một người thực tế, tập trung vào việc giải quyết vấn đề và đạt được kết quả.","k":"practical"},{"t":"Condone","p":"verb","d":"to pardon, deliberately overlook","e":"He refused to condone his brother’s crime.","ev":"Anh không tha thứ hay biện hộ cho hành động sai trái của em trai.","k":"condone"},{"t":"Arrant Purposelessness","d":"complete and total","e":"The project felt like an exercise in arrant purposelessness, with no clear goal or outcome.","ev":"Dự án giống như một bài tập vô mục đích, không có mục tiêu hay kết quả rõ ràng.","k":"arrant purposelessness"},{"t":"Dissonance","p":"(n.)","d":"lack of harmony or consistency","e":"Though the president of the company often spoke of the company as reliant solely upon its workers, her decision to increase her own salary rather than reward her employees revealed a striking dissonance between her alleged beliefs and her actions.","ev":"Mặc dù chủ tịch công ty thường nói rằng công ty chỉ phụ thuộc hoàn toàn vào công nhân, nhưng quyết định tăng lương thay vì khen thưởng nhân viên của bà đã bộc lộ sự bất hòa rõ rệt giữa niềm tin được cho là và hành động của bà.","k":"dissonance"},{"t":"Deference","d":"respect","e":"She showed deference to her elders, respecting their wisdom and experience.","ev":"Cô tỏ ra tôn trọng người lớn tuổi, tôn trọng sự khôn ngoan và kinh nghiệm của họ.","k":"deference"},{"t":"Plausible","p":"(adj.)","d":"believable, reasonable","e":"He studied all the data and then came up with a plausible theory that took all factors into account.","ev":"Ông nghiên cứu tất cả dữ liệu và sau đó đưa ra một lý thuyết hợp lý có tính đến tất cả các yếu tố.","k":"plausible"},{"t":"Expedient","p":"adjective/noun","d":"advisable, advantageous, serving one’s self-interest","e":"It was expedient for the manager to make a quick decision to avoid further delays.","ev":"Việc đưa ra quyết định nhanh chóng là điều cần thiết cho người quản lý để tránh trì hoãn thêm.","k":"expedient"},{"t":"Cogent","p":"(adj.)","d":"intellectually convincing","e":"Irene’s arguments in favor of abstinence were so cogent that I could not resist them.","ev":"Những lập luận ủng hộ việc kiêng khem của Irene thuyết phục đến mức tôi không thể cưỡng lại được.","k":"cogent"},{"t":"Debase","p":"verb","d":"to lower the quality or esteem of something","e":"The large raise that he gave himself debased his motives for running the charity.","ev":"Sự tăng lương lớn mà anh tự thưởng làm giảm giá trị của động cơ của anh khi điều hành quỹ từ thiện.","k":"debase"},{"t":"Inure","p":"(v.)","d":"to cause someone or something to become accustomed to a situation","e":"Twenty years in the salt mines inured the man to the discomforts of dirt and grime.","ev":"Hai mươi năm làm việc trong các mỏ muối đã khiến người đàn ông này phải chịu đựng sự khó chịu của bụi bẩn.","k":"inure"},{"t":"Plethora","p":"(n.)","d":"an abundance, excess","e":"The wedding banquet included a plethora of oysters piled almost three feet high.","ev":"Tiệc cưới bao gồm rất nhiều hàu chất cao gần 3 feet.","k":"plethora"},{"t":"Balk","p":"verb","d":"to stop, block abruptly","e":"Edna’s boss balked at her request for a raise.","ev":"Sếp của Edna đã từ chối yêu cầu tăng lương của cô.","k":"balk"},{"t":"Terse","d":"using few words","e":"He gave a terse reply.","ev":"Anh trả lời ngắn gọn.","k":"terse"},{"t":"Sparingly","d":"adv. insufficiently, meagerly, or in a restricted manner","e":"adv. insufficiently, meagerly, or in a restricted manner","ev":"lời khuyên. không đầy đủ, ít ỏi, hoặc một cách hạn chế","k":"sparingly"},{"t":"Exculpate","p":"(v.)","d":"to free from guilt or blame, exonerate","e":"My discovery of the ring behind the dresser exculpated me from the charge of having stolen it.","ev":"Việc tôi phát hiện ra chiếc nhẫn phía sau tủ quần áo đã giúp tôi thoát khỏi tội danh ăn trộm nó.","k":"exculpate"},{"t":"Mull Over","d":"To think about something carefully","e":"The student mulled over the essay prompt for several minutes before beginning to write.","ev":"Học sinh nghiền ngẫm lời nhắc bài luận trong vài phút trước khi bắt đầu viết.","x":"Ví dụ 2: Think about","k":"mull over"},{"t":"Incantation","d":"a series of words said as a magic spell or charm","e":"The witch chanted an incantation, hoping to summon a demon.","ev":"Mụ phù thủy niệm một câu thần chú với hy vọng triệu hồi được một con quỷ.","k":"incantation"}]},{"n":"Chưa phân loại · 50","c":[{"t":"Empirical","p":"(adj.)","d":"based on observation or experience","e":"The scientist gathered empirical data on the growth rate of dandelions by studying the dandelions behind his house.","ev":"Nhà khoa học đã thu thập dữ liệu thực nghiệm về tốc độ sinh trưởng của bồ công anh bằng cách nghiên cứu những cây bồ công anh phía sau nhà mình.","x":"Nghĩa 2: capable of being proved or disproved by experiment\nVí dụ 2: That all cats hate getting wet is an empirical statement: I can test it by bathing my cat, Trinket.","k":"empirical"},{"t":"Tome","p":"(n.)","d":"a large book","e":"In college, I used to carry around an anatomy book that was the heaviest tome in my bag.","ev":"Ở trường đại học, tôi thường mang theo một cuốn sách giải phẫu, cuốn sách nặng nhất trong cặp của mình.","k":"tome"},{"t":"Anguish","p":"noun","d":"extreme sadness, torment","e":"Angelos suffered terrible anguish when he learned that Buffy had died.","ev":"Angelos đã chịu đựng nỗi đau khổ khủng khiếp khi biết rằng Buffy đã chết.","k":"anguish"},{"t":"Proclaim","d":"to announce officially or publicly","e":"The king proclaimed himself emperor.","ev":"Nhà vua tự xưng là hoàng đế.","k":"proclaim"},{"t":"Forlorn","p":"adjective","d":"lonely, abandoned, hopeless","e":"She sat forlorn on the bench, waiting for someone who never arrived.","ev":"Cô ngồi đơn độc trên ghế, chờ đợi một người không bao giờ đến.","k":"forlorn"},{"t":"Portent","p":"(n.)","d":"an omen","e":"When a black cat crossed my sister’s path while she was walking to school, she took it as a portent that she would do badly on her spelling test.","ev":"Khi một con mèo đen băng qua đường nơi chị tôi đang đi bộ đến trường, chị ấy coi đó là điềm báo rằng chị ấy sẽ làm bài kiểm tra chính tả kém.","k":"portent"},{"t":"Reverence","d":"deep respect for someone or something","e":"The people showed great reverence for their leader, treating him with respect and admiration.","ev":"Người dân tỏ ra hết sức tôn kính người lãnh đạo của họ, đối xử với ông bằng sự tôn trọng và ngưỡng mộ.","k":"reverence"},{"t":"Trepidation","p":"noun","d":"fear, apprehension","e":"She felt a sense of trepidation before her big presentation.","ev":"Cô cảm thấy lo lắng trước bài thuyết trình lớn của mình.","k":"trepidation"},{"t":"Diligent","p":"(adj.)","d":"showing care in doing one’s work","e":"The diligent researcher made sure to check her measurements multiple times.","ev":"Nhà nghiên cứu siêng năng đã đảm bảo kiểm tra số đo của cô ấy nhiều lần.","k":"diligent"},{"t":"Wrath","p":"noun","d":"vengeful anger, punishment","e":"The villagers expressed their wrath when they learned about the unfair treatment.","ev":"Người dân đã bày tỏ sự giận dữ khi biết về sự đối xử bất công.","k":"wrath"},{"t":"Battery","p":"(1) noun; (2) noun","d":"a device that supplies power","e":"(1) Most cars run on a battery and gasoline. \n (2) He was accused of assault and battery.","ev":"(1) Hầu hết các xe ô tô chạy bằng ắc quy và xăng. \n (2) Anh bị cáo buộc tấn công và đánh đập.","k":"battery"},{"t":"Chronicle","p":"(n.)","d":"a written history","e":"The library featured the newly updated chronicle of World War II.","ev":"Thư viện có biên niên sử mới được cập nhật về Thế chiến thứ hai.","x":"Loại từ 2: (v.)\nNghĩa 2: to write a history\nVí dụ 2: Albert’s diary chronicled the day-to-day growth of his obsession with Cynthia.","k":"chronicle"},{"t":"Interlocutor","p":"(n.)","d":"someone who participates in a dialogue or conversation","e":"When the officials could not come to an agreement over the correct cover of the flags, the prime minister acted as an interlocutor.","ev":"Khi các quan chức không thể đi đến thống nhất về cách che phủ chính xác các lá cờ, thủ tướng đóng vai trò là người đối thoại.","k":"interlocutor"},{"t":"Haughty","p":"(adj.)","d":"disdainfully proud","e":"The superstar’s haughty dismissal of her costars will backfire on her someday.","ev":"Việc siêu sao ngạo mạn sa thải bạn diễn của mình sẽ phản tác dụng vào một ngày nào đó.","k":"haughty"},{"t":"Observe","d":"obey","e":"People must observe the law. Nobody should be an exception.","ev":"Người dân phải tuân thủ pháp luật. Không ai có thể là một ngoại lệ.","k":"observe"},{"t":"Precocious","p":"adj","d":"advanced, developing ahead of time","e":"The precocious child amazed everyone with her advanced vocabulary.","ev":"Cô bé thông minh khiến mọi người kinh ngạc với vốn từ vựng phát triển vượt trội.","k":"precocious"},{"t":"Mandate","p":"(n.)","d":"an authoritative command","e":"In the Old Testament, God mandates that no one should steal.","ev":"Trong Cựu Ước, Thiên Chúa truyền lệnh không ai được trộm cắp.","k":"mandate"},{"t":"Enumerate","p":"verb","d":"v. to specify or count","e":"The speaker began to enumerate the reasons for the project's success.","ev":"Người nói đã bắt đầu liệt kê những lý do cho sự thành công của dự án.","k":"enumerate"},{"t":"Wily","p":"(adj.)","d":"crafty, sly","e":"Though they were not the strongest of the Thundercats, wily Kit and Kat were definitely the most clever and full of tricks.","ev":"Mặc dù họ không phải là những người mạnh nhất trong nhóm Thundercats nhưng Kit và Kat quỷ quyệt chắc chắn là những người thông minh và đầy thủ đoạn nhất.","k":"wily"},{"t":"Vigorous","d":"strong, healthy, and full of energy","e":"She was a vigorous athlete, training hard and competing at a high level.","ev":"Cô là một vận động viên mạnh mẽ, tập luyện chăm chỉ và thi đấu ở trình độ cao.","k":"vigorous"},{"t":"Circuitous","p":"adj","d":"roundabout","e":"Their route was circuitous, taking much longer.","ev":"Tuyến đường của họ quanh co, mất nhiều thời gian hơn.","k":"circuitous"},{"t":"Vehemently","p":"(adv.)","d":"marked by intense force or emotion","e":"The candidate vehemently opposed cutting back on Social Security funding.","ev":"Ứng cử viên kịch liệt phản đối việc cắt giảm nguồn tài trợ An sinh xã hội.","k":"vehemently"},{"t":"Dour","p":"(adj.)","d":"stern, joyless","e":"The children feared their dour neighbor because the old man would take their toys if he believed they were being too loud.","ev":"Bọn trẻ sợ người hàng xóm khắc nghiệt của chúng vì ông già sẽ lấy đồ chơi của chúng nếu ông tin rằng chúng quá ồn ào.","k":"dour"},{"t":"Bombastic","p":"adjective","d":"excessively confident, pompous, khoa trương","e":"The politician's bombastic rhetoric failed to convince the voters.","ev":"Lời hùng biện phô trương của chính trị gia đã không thuyết phục được cử tri.","k":"bombastic"},{"t":"Foment","d":"v. to stir up","e":"v. to stir up","ev":"v. khuấy động","k":"foment"}]},{"n":"Chưa phân loại · 51","c":[{"t":"Confection","p":"noun","d":"a sweet, fancy food","e":"We went to the mall food court and purchased a delicious confection.","ev":"Họ đã mua một món tráng miệng ngon tại khu ẩm thực.","k":"confection"},{"t":"Aisle","p":"noun","d":"a passageway between rows of seats","e":"Once we got inside the stadium we walked down the aisle to our seats.","ev":"Khi chúng tôi vào trong sân vận động, chúng tôi đi xuống lối đi đến chỗ ngồi của mình.","k":"aisle"},{"t":"Consolation","p":"noun","d":"an act of comforting, sự an ủi","e":"Darren found Alexandra’s presence to be a consolation for his suffering.","ev":"Sự có mặt của cô ấy giúp anh cảm thấy tốt hơn trong những lúc khó khăn.","k":"consolation"},{"t":"Paramount","p":"(adj.)","d":"greatest in importance, rank, character","e":"It was paramount that the bomb squad disconnect the blue wire before removing the fuse.","ev":"Điều quan trọng nhất là đội phá bom phải ngắt dây màu xanh trước khi tháo cầu chì.","k":"paramount"},{"t":"Poignant","p":"(adj.)","d":"deeply affecting, moving","e":"My teacher actually cried after reading to us the poignant final chapter of the novel.","ev":"Thầy tôi thực sự đã khóc sau khi đọc cho chúng tôi nghe chương cuối đầy cảm động của cuốn tiểu thuyết.","k":"poignant"},{"t":"Pretense","p":"(n.)","d":"an appearance or action intended to deceive","e":"Though he actually wanted to use his parents’ car to go on a date, Nick borrowed his parents’ car under the pretense of attending a group study session.","ev":"Mặc dù thực sự muốn sử dụng xe của bố mẹ để đi hẹn hò nhưng Nick đã mượn xe của bố mẹ với lý do tham gia một buổi học nhóm.","k":"pretense"},{"t":"Coagulate","p":"(v.)","d":"to thicken, clot","e":"The top layer of the pudding had coagulated into a thick skin.","ev":"Lớp trên cùng của bánh pudding đã đông lại thành một lớp da dày.","k":"coagulate"},{"t":"Demur","d":"to raise doubts or to protest","e":"She demurred when asked to speak in public, feeling shy and hesitant to share her thoughts.","ev":"Cô ngần ngại khi được yêu cầu phát biểu trước đám đông, cảm thấy ngại ngùng và ngần ngại chia sẻ suy nghĩ của mình.","k":"demur"},{"t":"Enigmatic","p":"(adj.)","d":"mystifying, cryptic","e":"That man wearing the dark suit and dark glasses is so enigmatic that no one even knows his name.","ev":"Người đàn ông mặc bộ vest đen và đeo kính đen đó bí ẩn đến mức không ai biết tên anh ta.","k":"enigmatic"},{"t":"Abort","p":"verb","d":"to give up on a half-finished project or effort","e":"The men had to abort their plan to jump rope around the world after running out of food.","ev":"Những người đàn ông phải từ bỏ kế hoạch nhảy dây vòng quanh thế giới sau khi hết thức ăn.","k":"abort"},{"t":"Mendacious","p":"(adj.)","d":"having a lying, false character","e":"The mendacious content of the tabloid magazines is at least entertaining.","ev":"Nội dung dối trá của các tạp chí lá cải ít nhất cũng mang tính giải trí.","k":"mendacious"},{"t":"Convulsion","d":"a sudden, violent, irregular movement of the body","e":"The earthquake caused a convulsion of the earth, shaking buildings and causing widespread damage.","ev":"Trận động đất đã gây ra sự rung chuyển của mặt đất, làm rung chuyển các tòa nhà và gây ra thiệt hại trên diện rộng.","k":"convulsion"},{"t":"Recollection","d":"a memory; the act of remembering","e":"Her recollection of the event was hazy, as she couldn't remember all the details clearly.","ev":"Ký ức của cô về sự kiện này rất mơ hồ vì cô không thể nhớ rõ ràng mọi chi tiết.","k":"recollection"},{"t":"Laudatory","p":"(adj.)","d":"expressing admiration or praise","e":"Such laudatory comments are unusual from someone who is usually so reserved in his opinions.","ev":"Những lời nhận xét khen ngợi như vậy thật bất thường đối với một người thường rất dè dặt trong quan điểm của mình.","k":"laudatory"},{"t":"Lucid","p":"adjective","d":"clear, easily understandable","e":"Her explanation was so lucid that everyone understood the complex concept immediately.","ev":"Giải thích của cô ấy rõ ràng đến nỗi mọi người ngay lập tức hiểu được khái niệm phức tạp.","k":"lucid"},{"t":"Fickle","p":"(adj.)","d":"shifting in character, inconstant","e":"In Greek dramas, the fickle gods help Achilles one day, and then harm him the next.","ev":"Trong các bộ phim truyền hình Hy Lạp, các vị thần hay thay đổi giúp đỡ Achilles một ngày và sau đó làm hại anh ta vào ngày hôm sau.","k":"fickle"},{"t":"Inimitable","d":"Unique, one-of-a-kind","e":"His style is inimitable.","ev":"Phong cách của anh ấy là không thể bắt chước được.","x":"Ví dụ 2: not negative","k":"inimitable"},{"t":"Modest","d":"1) humble, not showy 2) not large in size or amount","e":"She was a modest person who never boasted about her achievements.","ev":"Cô là người khiêm tốn, không bao giờ khoe khoang về thành tích của mình.","k":"modest"},{"t":"Incumbent","p":"(n.)","d":"one who holds an office","e":"The incumbent senator is already serving his fifth term.","ev":"Thượng nghị sĩ đương nhiệm đã phục vụ nhiệm kỳ thứ năm của mình.","x":"Loại từ 2: (adj.)\nNghĩa 2: obligatory\nVí dụ 2: It is incumbent upon this organization to offer aid to all who seek it.","k":"incumbent"},{"t":"Enmity","p":"(n.)","d":"ill will, hatred, hostility","e":"Mark and Andy have clearly not forgiven each other, because the enmity between them is obvious to anyone in their presence.","ev":"Mark và Andy rõ ràng đã không tha thứ cho nhau, bởi vì sự thù hận giữa họ là điều hiển nhiên đối với bất kỳ ai có mặt họ.","k":"enmity"},{"t":"Oscillate","p":"(v.)","d":"to sway from one side to the other","e":"My uncle oscillated between buying a station wagon to transport his family and buying a sports car to satisfy his boyhood fantasies.","ev":"Chú tôi dao động giữa việc mua một chiếc xe ga để chở gia đình và mua một chiếc ô tô thể thao để thỏa mãn những tưởng tượng thời niên thiếu của mình.","k":"oscillate"},{"t":"Demean","p":"(v.)","d":"to lower the status or stature of something","e":"She refused to demean her secretary by making him order her lunch.","ev":"Cô từ chối hạ thấp thư ký của mình bằng cách bắt anh ta gọi bữa trưa cho cô.","k":"demean"},{"t":"Vestige","p":"(n.)","d":"a mark or trace of something lost or vanished","e":"Do you know if the Mexican tortilla is a vestige of some form of Aztec corn-based flat bread?","ev":"Bạn có biết liệu bánh tortilla của Mexico có phải là vết tích của một dạng bánh mì dẹt làm từ ngô của người Aztec không?","k":"vestige"},{"t":"Devious","p":"(adj.)","d":"not straightforward, deceitful","e":"Not wanting to be punished, the devious girl blamed the broken vase on the cat.","ev":"Không muốn bị trừng phạt, cô gái ranh mãnh đổ lỗi chiếc bình vỡ cho con mèo.","k":"devious"},{"t":"Rancor","p":"(n.)","d":"deep, bitter resentment","e":"When Eileen challenged me to a fight, I could see the rancor in her eyes.","ev":"Khi Eileen thách đấu với tôi, tôi có thể nhìn thấy sự hận thù trong mắt cô ấy.","k":"rancor"}]},{"n":"Chưa phân loại · 52","c":[{"t":"Forage","p":"(v.)","d":"to graze, rummage for food","e":"When we got lost on our hiking trip, we foraged for berries and nuts in order to survive.","ev":"Khi chúng tôi bị lạc trong chuyến đi bộ đường dài, chúng tôi đã đi tìm quả mọng và các loại hạt để tồn tại.","k":"forage"},{"t":"Incarnate","p":"(adj.)","d":"existing in the flesh, embodied","e":"In the church pageant, I play the role of greed incarnate.","ev":"Trong cuộc thi ở nhà thờ, tôi đóng vai hiện thân của lòng tham.","x":"Loại từ 2: (v.)\nNghĩa 2: to give human form to\nVí dụ 2: The alien evaded detection by incarnating himself in a human form.","k":"incarnate"},{"t":"Espouse","p":"(v.) /esˈpaʊz/","d":"to take up as a cause, support theo (phong trào, thuyết)","e":"I love animals so much that I espouse animal rights.","ev":"Tôi yêu động vật đến mức tôi tán thành quyền động vật.","k":"espouse"},{"t":"Congruity","p":"noun","d":"the quality of being in agreement","e":"Bill and Veronica achieved a perfect congruity of opinion.","ev":"Họ hoàn toàn đồng ý với nhau.","k":"congruity"},{"t":"Dread","d":"to fear, be afraid of","e":"The thought of public speaking filled her with dread, causing her heart to race and her palms to sweat.","ev":"Ý nghĩ phải nói trước công chúng khiến cô sợ hãi, khiến tim cô đập nhanh và lòng bàn tay đổ mồ hôi.","k":"dread"},{"t":"Beguile","p":"verb","d":"to trick, deceive","e":"The thief beguiled his partners into surrendering their money.","ev":"Kẻ trộm đã lừa dối các đồng phạm giao nộp tiền của họ.","k":"beguile"},{"t":"Corrosive","p":"adjective","d":"having the tendency to erode or eat away, ăn mòn","e":"The effect of the chemical was highly corrosive.","ev":"Hóa chất này có tác động ăn mòn rất mạnh.","k":"corrosive"},{"t":"Irreverence","p":"(n.)","d":"disrespect","e":"The irreverence displayed by the band that marched through the chapel disturbed many churchgoers.","ev":"Sự bất kính của ban nhạc diễu hành qua nhà nguyện đã khiến nhiều người đi nhà thờ lo lắng.","k":"irreverence"}]}]});
